(1, 1, 'Nepal ko Bhugol ra Itihas', 'nepal-ko-bhugol-ra-itihas-1', NULL, 1, 1, '2026-08-29 08:42:03', '2026-08-29 08:42:03'),
(2, 1, 'Bigyan ra Prabidhi (Science & Technology)', 'bigyan-ra-prabidhi-science-technology-1', NULL, 2, 1, '2026-08-29 08:42:03', '2026-08-29 08:42:03'),
(3, 2, 'Karyalaya Byawastha ra Karyabidhi', 'karyalaya-byawastha-ra-karyabidhi-2', NULL, 1, 1, '2026-08-29 08:42:03', '2026-08-29 08:42:03'),
(185, 140, '1. General Awareness Foundations for Section Officer', '1-general-awareness-foundations-for-section-officer-140', 'In-depth exam-oriented study notes structured with concept breakdowns, comparative tables, and facts.', 1, 1, '2026-09-02 11:54:52', '2026-09-02 11:54:52'),
(186, 141, '1. Verbal, Quantitative & Analytical Reasoning', '1-verbal-quantitative-analytical-reasoning-141', 'Systematic methodology, shortcuts, and problem-solving rules.', 1, 1, '2026-09-02 11:54:52', '2026-09-02 11:54:52'),
(188, 143, '1. State, Federalism, Public Administration & Policy Governance', '1-state-federalism-public-administration-policy-governance-143', 'Comprehensive governance concepts and administrative frameworks.', 1, 1, '2026-09-02 11:54:52', '2026-09-02 11:54:52'),
(189, 144, '1. Socio-Economic, Environmental & Geopolitical Issues', '1-socio-economic-environmental-geopolitical-issues-144', 'In-depth contemporary national and global development challenges.', 1, 1, '2026-09-02 11:54:52', '2026-09-02 11:54:52'),
(190, 145, '1. Civil Service Law, Administrative Jurisprudence & Office Procedures', '1-civil-service-law-administrative-jurisprudence-office-procedures-145', 'Statutory laws and practical administrative management for civil servants.', 1, 1, '2026-09-02 11:54:52', '2026-09-02 11:54:52'),
(191, 146, '1. Geography, Climate & Natural Resources of Nepal', '1-geography-climate-natural-resources-of-nepal-146', 'Physical topography, altitudinal ecological zones, river systems, climate classifications, and natural wealth of Nepal.', 1, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(192, 146, '2. Socio-Economic Development & Periodic Planning', '2-socio-economic-development-periodic-planning-146', 'Social systems, cultural heritage, national periodic planning, and drivers of economic development.', 2, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(193, 146, '3. Energy Resources, Hydropower & NEA Overview', '3-energy-resources-hydropower-nea-overview-146', 'Water, solar, and wind energy potential, hydropower development, NEA mandate, and private sector IPPs.', 3, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(194, 146, '4. Environment, Climate Change & Sustainable Development', '4-environment-climate-change-sustainable-development-146', 'SDGs, demographic trends, environmental protection measures, pollution control, and climate change management in Nepal.', 4, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(195, 146, '5. National Affairs, Federalism & Democratic Governance', '5-national-affairs-federalism-democratic-governance-146', 'Current events, federal governance architecture, democracy, social inclusion, and GK assessment.', 5, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(196, 147, '1. Fundamental Features & Preliminary Provisions', '1-fundamental-features-preliminary-provisions-147', 'Promulgation, core constitutional characteristics, preliminary articles, and citizenship provisions.', 1, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(197, 147, '2. Fundamental Rights, Duties & State Policies', '2-fundamental-rights-duties-state-policies-147', 'Comprehensive breakdown of 31 Fundamental Rights, Citizen Duties, Directive Principles, and State Policies.', 2, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(198, 147, '3. Constitutional Organs & Federal Schedules', '3-constitutional-organs-federal-schedules-147', 'Constitutional bodies, anti-corruption, audit oversight, PSC, election commission, human rights, and Schedules 1-9.', 3, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(199, 148, '1. Numerical Ability & Business Mathematics', '1-numerical-ability-business-mathematics-148', 'Unitary method, percentages, fractions, averages, profit & loss, discount, and simple interest calculations.', 1, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(200, 148, '2. Computer Literacy & Office Applications', '2-computer-literacy-office-applications-148', 'Computer components, Word processing, Spreadsheets (Excel), Presentations (PowerPoint), Email & Internet.', 2, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(201, 149, '1. Fundamental Concepts of Accounting', '1-fundamental-concepts-of-accounting-149', 'Bookkeeping, Double Entry principles, Accounting terminology, Accounting Equation, Capital vs Revenue, and Cash vs Accrual.', 1, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(202, 149, '2. Accounting Records, Reconciliation & Depreciation', '2-accounting-records-reconciliation-depreciation-149', 'Cash Book, Petty Cash Fund (Imprest), Bank Reconciliation, Subsidiary Ledgers, and Depreciation calculation.', 2, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(203, 149, '3. Financial Statements & Cost Accounting', '3-financial-statements-cost-accounting-149', 'Trial balance, NEA financial reporting & consolidation, Profit & Loss, Balance Sheet, Cost concepts, and inventory valuation (FIFO, LIFO, Weighted Average).', 3, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(204, 149, '4. Internal Control, Banking & Auditing Procedures', '4-internal-control-banking-auditing-procedures-149', 'Internal control, internal audit, statutory audit, bank guarantees, letters of credit (LC), and assessment quiz.', 4, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(205, 150, '1. NEA Statutory Framework & Administration', '1-nea-statutory-framework-administration-150', 'NEA Act 2041, Employee Service Regulations, Financial Administration, budget, advances, and Beruju settlement.', 1, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(206, 150, '2. Electricity Theft Control, Distribution & Tariff Rules', '2-electricity-theft-control-distribution-tariff-rules-150', 'Electricity Leakage Control Rules 2059, Distribution Bylaws 2078, meter reading, locked premise billing, and tariff collection.', 2, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53'),
(207, 150, '3. Tax Laws, Retirement Funds & Anti-Corruption', '3-tax-laws-retirement-funds-anti-corruption-150', 'EPF, CIT, Income Tax Act 2058 (TDS provisions), Prevention of Corruption Act 2059, and Final Assessment Quiz.', 3, 1, '2026-09-02 11:54:53', '2026-09-02 11:54:53');

