INSERT INTO `courses` (`id`, `title`, `slug`, `description`, `syllabus_pdf`, `thumbnail`, `level`, `is_published`, `created_at`, `updated_at`, `trending_score`) VALUES
(1, 'Kharidar Tayari', 'kharidar-tayari', 'Complete preparation course for Kharidar (Non-Gazetted Second Class) position under Nepal Public Service Commission. Covers General Knowledge, IQ & Aptitude, Office Management, and Job Knowledge with objective and subjective exam preparation.', 'courses/syllabus/Kharidar Syllabus.pdf', 'course-thumbnails/01M18FVD47T77TN568HT702AJ5.jpg', 'beginner', 1, '2026-08-29 08:42:03', '2026-09-02 22:28:30', 26.725639770717),
(2, 'Nayab Subba Tayari', 'nayab-subba-tayari', 'Comprehensive Nayab Subba (Non-Gazetted First Class) preparation covering General Knowledge, Intelligence Quotient, General Administration, and Accounting. Designed for the integrated examination system of Lok Sewa Aayog.', 'courses/syllabus/Nayab Subba Syllabus.pdf', 'course-thumbnails/01M18FY1HJGT73TVVDGKSMK6VQ.jpg', 'intermediate', 1, '2026-08-29 08:42:03', '2026-09-02 22:28:30', 34.948913546322),
(3, 'Section Officer Tayari (Gazetted Third Class)', 'section-officer-tayari', 'Comprehensive preparation course for Section Officer (Gazetted Third Class - Administration, Foreign Affairs, Audit, and Parliament Services) under the Public Service Commission (Lok Sewa Aayog) Integrated & Unified Examination System. Complete English curriculum covering Stage I (General Awareness, Aptitude Test & Reasoning, English Language Competence) and Stage II (Governance Systems, Contemporary Issues, and Service-Related Administration & Law).', 'courses/syllabus/01M1GVG10VDPVBNQMDA2YDK6RB.pdf', 'course-thumbnails/01M18FZRMP2H3N5T3CX61JRD9S.jpg', 'advanced', 1, '2026-08-29 08:42:03', '2026-09-02 22:28:30', 34.948913546322),
(4, 'NRB Officer Tayari', 'nrb-officer-tayari', 'Nepal Rastra Bank Officer (Third Class) exam preparation covering Macroeconomics, Microeconomics, Nepalese Banking System, Financial Accounting, and Banking Operations. Focus on monetary policy, fiscal policy, and central banking functions.', 'storage/docs/Loksewa_Student_User_Manual.pdf', 'course-thumbnails/01M18G0T0GSTDYC58G8FKZ120P.jpg', 'advanced', 1, '2026-08-29 08:42:03', '2026-09-02 22:28:30', 26.725639770717),
(5, 'NRB Assistant Director Tayari', 'nrb-assistant-director-tayari', 'Premium preparation course for NRB Assistant Director position covering Banking Law & Regulations, Monetary Policy Tools, Corporate Governance, Capital Adequacy, Foreign Exchange Regulation, and advanced macroeconomic analysis.', 'storage/docs/Loksewa_Student_User_Manual.pdf', 'course-thumbnails/01M18G1RY0J106PPD2KX2B0BF5.jpg', 'advanced', 1, '2026-08-29 08:42:03', '2026-09-02 22:28:30', 16.44654755121),
(7, 'Computer Sip Pariksha', 'computer-sip-pariksha', 'Practical computer skill test preparation covering MS Word, MS Excel, MS PowerPoint, Email & Internet usage, Nepali Unicode typing, and data entry. Required for all Loksewa positions as part of the final examination stage.', 'storage/docs/Loksewa_Student_User_Manual.pdf', 'course-thumbnails/01M18G9505CSZHDENPZ0SNJNWA.jpeg', 'beginner', 1, '2026-08-29 08:42:03', '2026-09-02 22:28:30', 14.390729107309),
(9, 'Nepal Telecom Tayari', 'nepal-telecom-tayari', 'Complete preparation course for Nepal Telecom', 'storage/docs/Loksewa_Student_User_Manual.pdf', 'course-thumbnails/01M18G5XDCDYVTDM9741Q223EX.jpg', 'beginner', 1, '2026-08-29 23:07:23', '2026-08-30 00:51:56', 0),
(13, 'Nepal Electricity Authority (NEA) - Level 4 Administration & Accounting', 'nea-level-4', 'Complete preparation course for Nepal Electricity Authority (NEA) Level-4 Administration & Accounting Internal and Open Competitive Examination. Comprehensive curriculum in English covering Paper I (General Knowledge, Constitution of Nepal, General Mathematics & Computer) and Paper II (Accounting, Financial Reporting, Costing, Auditing, NEA Act 2041, Employee Bylaws, Financial Rules, Electricity Theft Control, Tax, and Corruption Prevention).', 'courses/syllabus/01M1HEVVM34CWG7B9196YE1MXV.pdf', 'course-thumbnails/01M1HF09AQXHBQ6XGJQDRS2TE6.jpg', 'intermediate', 1, '2026-09-02 10:35:35', '2026-09-02 22:28:30', 87.818139645822);

