INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'Physical Geography of Nepal', 'physical-geography-of-nepal-1', '<h3>Physical Divisions of Nepal</h3><p>Nepal is divided into three main ecological regions based on altitude and terrain:</p><ul><li><strong>Himalayan Region (Himal):</strong> Covers approximately 15% of total land area, lies above 4,877m altitude. Contains 8 of the world\'s 14 peaks above 8,000m including Mount Everest (Sagarmatha, 8,848.86m). Key features: permanent snow, glaciers, high-altitude lakes (Tilicho, Rara). Sparse human settlement. Districts include Solukhumbu, Dolpa, Humla, Mustang.</li><li><strong>Hilly Region (Pahad):</strong> Covers approximately 68% of total land area. Altitude ranges from 610m to 4,877m. Contains the Mahabharat range, Chure hills, and fertile inter-mountain valleys like Kathmandu Valley, Pokhara Valley, and Dang Valley. Most populated region with major urban centers.</li><li><strong>Terai Region (Madhesh):</strong> Covers approximately 17% of total land area. Flat alluvial plains along the southern border with India. Known as the granary of Nepal — produces majority of rice, wheat, sugarcane. Major cities: Biratnagar, Birgunj, Janakpur, Nepalgunj, Dhangadhi.</li></ul><h3>Major Rivers</h3><p>Nepal has three major river systems, all tributaries of the Ganges:</p><ol><li><strong>Koshi River System:</strong> Largest by volume. Seven tributaries (Saptakoshi). Origin in Tibet and eastern Nepal Himalayas.</li><li><strong>Gandaki River System:</strong> Contains the Kaligandaki — one of the deepest gorges in the world. Seven tributaries including Trishuli, Marsyangdi, Seti.</li><li><strong>Karnali River System:</strong> Longest river in Nepal (507km). Originates near Lake Mansarovar in Tibet. Western Nepal\'s lifeline.</li></ol>', NULL, 'lessons/pdfs/Geography of Nepal_compressed.pdf', '[{\"question\":\"Which is the highest mountain peak in the world located in Nepal?\",\"options\":[\"Mount K2\",\"Mount Everest\",\"Kangchenjunga\",\"Lhotse\"],\"option_0\":\"Mount K2\",\"option_1\":\"Mount Everest\",\"option_2\":\"Kangchenjunga\",\"option_3\":\"Lhotse\",\"answer\":1,\"hint\":\"Known locally as Sagarmatha and in Tibetan as Chomolungma.\",\"explanation\":\"Mount Everest (Sagarmatha) is the highest peak in the world at 8848.86 meters, situated in the Mahalangur range of Solukhumbu district.\"},{\"question\":\"Which river of Nepal is historically known in India as the \\\"Sorrow of Bihar\\\"?\",\"options\":[\"Gandaki River\",\"Karnali River\",\"Koshi River\",\"Mahakali River\"],\"option_0\":\"Gandaki River\",\"option_1\":\"Karnali River\",\"option_2\":\"Koshi River\",\"option_3\":\"Mahakali River\",\"answer\":2,\"hint\":\"It frequently changes its course and causes severe monsoon flooding in northern Bihar, India.\",\"explanation\":\"The Koshi River is known as the \\\"Sorrow of Bihar\\\" because of annual catastrophic flooding and silt deposition caused by shifts in its meandering channel.\"},{\"question\":\"What is the longest river in Nepal within Nepalese territorial borders?\",\"options\":[\"Koshi River\",\"Gandaki River\",\"Karnali River\",\"Trishuli River\"],\"option_0\":\"Koshi River\",\"option_1\":\"Gandaki River\",\"option_2\":\"Karnali River\",\"option_3\":\"Trishuli River\",\"answer\":2,\"hint\":\"Originates from the Mansarovar basin in Tibet and measures 507 km within Nepal.\",\"explanation\":\"Karnali is the longest river in Nepal, measuring 507 km within Nepalese territory before flowing into India as the Ghaghara.\"},{\"question\":\"Which is the deepest river in Nepal with the highest water discharge capacity?\",\"options\":[\"Karnali River\",\"Gandaki River\",\"Koshi River\",\"Bheri River\"],\"option_0\":\"Karnali River\",\"option_1\":\"Gandaki River\",\"option_2\":\"Koshi River\",\"option_3\":\"Bheri River\",\"answer\":1,\"hint\":\"Formed by seven major tributaries including Kali Gandaki, Trishuli, and Marsyangdi.\",\"explanation\":\"Gandaki (Narayani) is the deepest river in Nepal with deep gorges carved by the Kali Gandaki between Annapurna and Dhaulagiri.\"},{\"question\":\"Which is the largest lake in Nepal by surface area?\",\"options\":[\"Shey Phoksundo Lake\",\"Fewa Lake\",\"Rara Lake\",\"Tilicho Lake\"],\"option_0\":\"Shey Phoksundo Lake\",\"option_1\":\"Fewa Lake\",\"option_2\":\"Rara Lake\",\"option_3\":\"Tilicho Lake\",\"answer\":2,\"hint\":\"Located in Mugu District at an altitude of 2,990 meters, praised as the Queen of Lakes.\",\"explanation\":\"Rara Lake in Mugu district is the largest freshwater lake in Nepal with a surface area of 10.8 sq km.\"},{\"question\":\"Which is the deepest lake in Nepal?\",\"options\":[\"Rara Lake\",\"Shey Phoksundo Lake\",\"Gosaikunda Lake\",\"Begnas Lake\"],\"option_0\":\"Rara Lake\",\"option_1\":\"Shey Phoksundo Lake\",\"option_2\":\"Gosaikunda Lake\",\"option_3\":\"Begnas Lake\",\"answer\":1,\"hint\":\"An oligotrophic alpine lake situated in Dolpa district at 3,611 m altitude, famous for its turquoise blue water.\",\"explanation\":\"Shey Phoksundo Lake in Dolpa is the deepest lake in Nepal with a maximum depth of approximately 145 meters.\"},{\"question\":\"Nepal Standard Time is determined based on which meridian passing through Gaurishankar Himal?\",\"options\":[\"80 degrees 15 minutes East Longitude\",\"84 degrees 00 minutes East Longitude\",\"86 degrees 15 minutes East Longitude\",\"88 degrees 00 minutes East Longitude\"],\"option_0\":\"80 degrees 15 minutes East Longitude\",\"option_1\":\"84 degrees 00 minutes East Longitude\",\"option_2\":\"86 degrees 15 minutes East Longitude\",\"option_3\":\"88 degrees 00 minutes East Longitude\",\"answer\":2,\"hint\":\"Introduced on Baisakh 1, 2042 BS, making Nepal 5 hours and 45 minutes ahead of GMT.\",\"explanation\":\"Nepal Standard Time is based on the 86\\u00b015\' East longitude meridian intersecting Mount Gaurishankar (7,134 m), exactly GMT +5:45.\"},{\"question\":\"Which district of Nepal is known as the district across the Himalayas receiving the lowest average annual rainfall?\",\"options\":[\"Mustang\",\"Solukhumbu\",\"Sindhupalchok\",\"Ramechhap\"],\"option_0\":\"Mustang\",\"option_1\":\"Solukhumbu\",\"option_2\":\"Sindhupalchok\",\"option_3\":\"Ramechhap\",\"answer\":0,\"hint\":\"Lies in the rain-shadow area north of the Annapurna and Dhaulagiri mountain ranges.\",\"explanation\":\"Mustang lies in the trans-Himalayan rain-shadow zone and receives the lowest annual rainfall in Nepal (approx. <250 mm\\/year).\"},{\"question\":\"Which place in Nepal records the highest average annual rainfall?\",\"options\":[\"Dhangadhi\",\"Lumle\",\"Biratnagar\",\"Janakpur\"],\"option_0\":\"Dhangadhi\",\"option_1\":\"Lumle\",\"option_2\":\"Biratnagar\",\"option_3\":\"Janakpur\",\"answer\":1,\"hint\":\"Located near Pokhara valley south of the Annapurna mountain barrier.\",\"explanation\":\"Lumle in Kaski district receives the highest annual rainfall in Nepal, often exceeding 5,000 mm annually (Cherrapunji of Nepal).\"},{\"question\":\"Which was the first National Park established in Nepal?\",\"options\":[\"Sagarmatha National Park\",\"Chitwan National Park\",\"Bardia National Park\",\"Langtang National Park\"],\"option_0\":\"Sagarmatha National Park\",\"option_1\":\"Chitwan National Park\",\"option_2\":\"Bardia National Park\",\"option_3\":\"Langtang National Park\",\"answer\":1,\"hint\":\"Famous habitat of the One-horned Rhinoceros and Royal Bengal Tiger in the inner Terai.\",\"explanation\":\"Chitwan National Park was established in 1973 AD (2030 BS) as Nepal\\u2019s first national park and designated a UNESCO World Heritage Site in 1984.\"}]', 'text', 1, 15, 1, '2026-08-29 08:42:03', '2026-09-02 12:19:39'),
(2, 1, 1, 'General Information of Universe', 'history-of-modern-nepal-1', 'Focus mainly on Planets, Satellite etc\n', NULL, 'lessons/pdfs/General-Information-about-Universe-Loksewa-PDF_compressed.pdf', '[{\"question\":\"Which is the closest star to the planet Earth?\",\"options\":[\"Proxima Centauri\",\"The Sun\",\"Sirius\",\"Alpha Centauri\"],\"option_0\":\"Proxima Centauri\",\"option_1\":\"The Sun\",\"option_2\":\"Sirius\",\"option_3\":\"Alpha Centauri\",\"answer\":1,\"hint\":\"The center of our Solar System located approximately 149.6 million km from Earth.\",\"explanation\":\"The Sun is the closest star to Earth; light from the Sun takes approximately 8 minutes and 20 seconds to reach Earth.\"},{\"question\":\"Which planet in the Solar System is closest to the Sun?\",\"options\":[\"Venus\",\"Mercury\",\"Mars\",\"Earth\"],\"option_0\":\"Venus\",\"option_1\":\"Mercury\",\"option_2\":\"Mars\",\"option_3\":\"Earth\",\"answer\":1,\"hint\":\"The smallest planet in the solar system with an orbital period of just 88 Earth days.\",\"explanation\":\"Mercury is the innermost and smallest planet in our Solar System, orbiting closest to the Sun.\"},{\"question\":\"Which planet is known as both the Morning Star and Evening Star and is the hottest planet in the Solar System?\",\"options\":[\"Mercury\",\"Venus\",\"Mars\",\"Jupiter\"],\"option_0\":\"Mercury\",\"option_1\":\"Venus\",\"option_2\":\"Mars\",\"option_3\":\"Jupiter\",\"answer\":1,\"hint\":\"Dense carbon dioxide atmosphere creates an extreme runaway greenhouse effect.\",\"explanation\":\"Venus is the brightest natural object in night skies after the Moon and the hottest planet (~465\\u00b0C) due to dense CO2 atmosphere.\"},{\"question\":\"Which planet in the Solar System is known as the Red Planet?\",\"options\":[\"Mercury\",\"Mars\",\"Jupiter\",\"Saturn\"],\"option_0\":\"Mercury\",\"option_1\":\"Mars\",\"option_2\":\"Jupiter\",\"option_3\":\"Saturn\",\"answer\":1,\"hint\":\"Its surface contains abundant iron oxide giving it a reddish appearance.\",\"explanation\":\"Mars is called the Red Planet because widespread iron oxide on its surface imparts a distinct reddish tint.\"},{\"question\":\"Which is the largest planet in our Solar System?\",\"options\":[\"Saturn\",\"Jupiter\",\"Neptune\",\"Uranus\"],\"option_0\":\"Saturn\",\"option_1\":\"Jupiter\",\"option_2\":\"Neptune\",\"option_3\":\"Uranus\",\"answer\":1,\"hint\":\"A gas giant with the famous Great Red Spot storm, having a mass more than double all other planets combined.\",\"explanation\":\"Jupiter is the largest planet in the Solar System with a diameter of ~142,984 km and over 90 known moons.\"},{\"question\":\"Which planet in our Solar System is famously surrounded by prominent, bright planetary rings made of ice and dust?\",\"options\":[\"Jupiter\",\"Saturn\",\"Uranus\",\"Neptune\"],\"option_0\":\"Jupiter\",\"option_1\":\"Saturn\",\"option_2\":\"Uranus\",\"option_3\":\"Neptune\",\"answer\":1,\"hint\":\"The second largest planet in the Solar System, with Titan as its largest moon.\",\"explanation\":\"Saturn is renowned for its spectacular and complex ring system composed predominantly of water ice and rocky debris.\"},{\"question\":\"What is the name of the barred spiral galaxy containing our Solar System?\",\"options\":[\"Andromeda Galaxy\",\"Milky Way Galaxy\",\"Triangulum Galaxy\",\"Whirlpool Galaxy\"],\"option_0\":\"Andromeda Galaxy\",\"option_1\":\"Milky Way Galaxy\",\"option_2\":\"Triangulum Galaxy\",\"option_3\":\"Whirlpool Galaxy\",\"answer\":1,\"hint\":\"A spiral galaxy containing 100 to 400 billion stars.\",\"explanation\":\"Our Solar System is located in the Orion Arm of the Milky Way galaxy.\"},{\"question\":\"What is the speed of light in a vacuum?\",\"options\":[\"150,000 km\\/s\",\"300,000 km\\/s\",\"500,000 km\\/s\",\"3,000 km\\/s\"],\"option_0\":\"150,000 km\\/s\",\"option_1\":\"300,000 km\\/s\",\"option_2\":\"500,000 km\\/s\",\"option_3\":\"3,000 km\\/s\",\"answer\":1,\"hint\":\"Fundamental physical constant denoted by the letter c.\",\"explanation\":\"Light travels at approximately 299,792 km\\/s (~300,000 km\\/second) in a vacuum.\"},{\"question\":\"Which celestial object was reclassified from a major planet to a Dwarf Planet by the IAU in 2006?\",\"options\":[\"Ceres\",\"Pluto\",\"Eris\",\"Makemake\"],\"option_0\":\"Ceres\",\"option_1\":\"Pluto\",\"option_2\":\"Eris\",\"option_3\":\"Makemake\",\"answer\":1,\"hint\":\"Discovered in 1930 by Clyde Tombaugh in the Kuiper Belt.\",\"explanation\":\"Pluto was reclassified as a dwarf planet by the IAU in August 2006 because it had not cleared the neighborhood around its orbit.\"},{\"question\":\"What was the world first artificial satellite launched into Earth orbit by the Soviet Union in 1957?\",\"options\":[\"Explorer 1\",\"Sputnik 1\",\"Vostok 1\",\"Apollo 11\"],\"option_0\":\"Explorer 1\",\"option_1\":\"Sputnik 1\",\"option_2\":\"Vostok 1\",\"option_3\":\"Apollo 11\",\"answer\":1,\"hint\":\"Marked the beginning of the human Space Age on October 4, 1957.\",\"explanation\":\"Sputnik 1 was the first artificial satellite placed in orbit by the USSR on 4 October 1957, initiating the global Space Race.\"}]', 'text', 3, 15, 1, '2026-08-29 08:42:03', '2026-09-02 12:19:39'),
(3, 1, 1, 'History of Nepal', 'geography-history-quiz-1', '[\n    {\n        \"question\": \"Who is the first prime minister of Nepal?\",\n        \"options\": [\n            \"Niraj Paudel\",\n            \"Bhimsen Thapa\",\n            \"Hemraj Pathak\",\n            \"Jana Bahadur\"\n        ],\n        \"answer\": 1,\n        \"hint\": \"ABc\",\n        \"explanation\": \"abc\"\n    }\n]', NULL, 'lessons/pdfs/HIstory of Nepal.pdf', '[{\"question\":\"Who was the first Prime Minister (Mukhtiyar) of unified Nepal?\",\"options\":[\"Jung Bahadur Rana\",\"Bhimsen Thapa\",\"Damodar Pande\",\"Ranganath Poudel\"],\"option_0\":\"Jung Bahadur Rana\",\"option_1\":\"Bhimsen Thapa\",\"option_2\":\"Damodar Pande\",\"option_3\":\"Ranganath Poudel\",\"answer\":1,\"hint\":\"Served as Mukhtiyar from 1806 to 1837 AD and built the iconic Dharahara tower.\",\"explanation\":\"Bhimsen Thapa was the first Prime Minister (Mukhtiyar) of Nepal, serving from 1806 to 1837 AD during the reigns of King Girvan Yuddha and King Rajendra.\"},{\"question\":\"Who was the first King of the ancient Kirat Dynasty in Nepal according to historical chronicles?\",\"options\":[\"King Mandev\",\"King Yalambar\",\"King Gasti\",\"King Nimish\"],\"option_0\":\"King Mandev\",\"option_1\":\"King Yalambar\",\"option_2\":\"King Gasti\",\"option_3\":\"King Nimish\",\"answer\":1,\"hint\":\"Defeated the Abhir\\/Mahispal dynasty to establish Kirati rule in the Kathmandu valley.\",\"explanation\":\"King Yalambar was the founder and first king of the Kirat dynasty in Nepal, ruling from Shankhamul\\/Gokarna.\"},{\"question\":\"Which Licchavi King issued the first historical inscribed copper coins (Manaank) in Nepal?\",\"options\":[\"King Amshuverma\",\"King Mandev I\",\"King Gunakamadev\",\"King Shivadev\"],\"option_0\":\"King Amshuverma\",\"option_1\":\"King Mandev I\",\"option_2\":\"King Gunakamadev\",\"option_3\":\"King Shivadev\",\"answer\":1,\"hint\":\"Installed the earliest dated stone pillar inscription at Changu Narayan temple in 464 AD.\",\"explanation\":\"King Mandev I (464-505 AD) is the first authenticated historical king of Nepal who minted Manaank coins and erected the Changu Narayan inscription.\"},{\"question\":\"The Sugauli Treaty between Nepal and the British East India Company was ratified in which year?\",\"options\":[\"1814 AD\",\"1816 AD\",\"1846 AD\",\"1857 AD\"],\"option_0\":\"1814 AD\",\"option_1\":\"1816 AD\",\"option_2\":\"1846 AD\",\"option_3\":\"1857 AD\",\"answer\":1,\"hint\":\"Concluded the Anglo-Nepalese War (1814\\u20131816) fixing the Mechi and Mahakali boundary rivers.\",\"explanation\":\"The Sugauli Treaty was signed in December 1815 and officially ratified on 4 March 1816, establishing the modern borders of Nepal.\"},{\"question\":\"The 104-year Rana autocratic rule in Nepal began following which historical massacre in Kathmandu?\",\"options\":[\"Bhandarkhal Massacre\",\"Kot Massacre\",\"Alau Massacre\",\"38 Saal Massacre\"],\"option_0\":\"Bhandarkhal Massacre\",\"option_1\":\"Kot Massacre\",\"option_2\":\"Alau Massacre\",\"option_3\":\"38 Saal Massacre\",\"answer\":1,\"hint\":\"Occurred at the royal armory courtyard in Kathmandu on Ashwin 2, 1903 BS.\",\"explanation\":\"The Kot Massacre occurred on 14 September 1846 (1903 Ashwin 2 BS), eliminating major noble courtiers and elevating Jung Bahadur Rana to power.\"},{\"question\":\"Who established the first modern educational institution of Nepal, Durbar High School?\",\"options\":[\"Prithvi Narayan Shah\",\"Jung Bahadur Rana\",\"Bir Shumsher\",\"Dev Shumsher\"],\"option_0\":\"Prithvi Narayan Shah\",\"option_1\":\"Jung Bahadur Rana\",\"option_2\":\"Bir Shumsher\",\"option_3\":\"Dev Shumsher\",\"answer\":1,\"hint\":\"Established in 1910 BS following his historic diplomatic tour to Great Britain and France.\",\"explanation\":\"Jung Bahadur Rana founded Durbar High School inside the royal palace in 1910 BS (1853 AD) upon returning from Europe.\"},{\"question\":\"Which King of Gorkha initiated the Great Unification Campaign of Nepal?\",\"options\":[\"King Dravya Shah\",\"King Prithvi Narayan Shah\",\"King Pratap Singh Shah\",\"King Bahadur Shah\"],\"option_0\":\"King Dravya Shah\",\"option_1\":\"King Prithvi Narayan Shah\",\"option_2\":\"King Pratap Singh Shah\",\"option_3\":\"King Bahadur Shah\",\"answer\":1,\"hint\":\"Conquered Nuwakot in 1801 BS and later unified Kathmandu, Patan, and Bhaktapur into a single nation.\",\"explanation\":\"King Prithvi Narayan Shah of Gorkha began the unification of Nepal by annexing Nuwakot in 1744 AD and establishing Kathmandu as the capital in 1769 AD.\"},{\"question\":\"On which historic date was the Rana regime overthrown and Democracy declared in Nepal?\",\"options\":[\"Falgun 7, 2007 BS\",\"Chaitra 1, 2015 BS\",\"Chaitra 26, 2046 BS\",\"Jestha 15, 2065 BS\"],\"option_0\":\"Falgun 7, 2007 BS\",\"option_1\":\"Chaitra 1, 2015 BS\",\"option_2\":\"Chaitra 26, 2046 BS\",\"option_3\":\"Jestha 15, 2065 BS\",\"answer\":0,\"hint\":\"King Tribhuvan announced the end of Rana rule over state radio; celebrated as National Democracy Day.\",\"explanation\":\"Democracy was declared in Nepal on 7th Falgun 2007 BS (18 February 1951) by King Tribhuvan after the successful tripartite revolution.\"},{\"question\":\"Who was the first elected Prime Minister of Nepal following the general election of 2015 BS?\",\"options\":[\"Matrika Prasad Koirala\",\"Bishweshwar Prasad Koirala\",\"Tanka Prasad Acharya\",\"Kirti Nidhi Bista\"],\"option_0\":\"Matrika Prasad Koirala\",\"option_1\":\"Bishweshwar Prasad Koirala\",\"option_2\":\"Tanka Prasad Acharya\",\"option_3\":\"Kirti Nidhi Bista\",\"answer\":1,\"hint\":\"Leader of the Nepali Congress party that won a two-thirds majority in 2015 BS.\",\"explanation\":\"B.P. Koirala became the first democratically elected Prime Minister of Nepal on 13 Jestha 2016 BS (1959 AD).\"},{\"question\":\"The Constitution of Nepal currently in force was promulgated by the Constituent Assembly on which date?\",\"options\":[\"Mangsir 4, 2070 BS\",\"Ashwin 3, 2072 BS\",\"Magh 1, 2074 BS\",\"Jestha 15, 2065 BS\"],\"option_0\":\"Mangsir 4, 2070 BS\",\"option_1\":\"Ashwin 3, 2072 BS\",\"option_2\":\"Magh 1, 2074 BS\",\"option_3\":\"Jestha 15, 2065 BS\",\"answer\":1,\"hint\":\"Celebrated annually across Nepal as National Constitution Day.\",\"explanation\":\"The historic federal democratic Constitution of Nepal was promulgated by the second Constituent Assembly on 3rd Ashwin 2072 BS (20 September 2015).\"}]', 'quiz', 4, 15, 1, '2026-08-29 08:42:03', '2026-09-02 12:19:39'),
(4, 1, 2, 'Geography of World', 'basic-science-for-kharidar-2', '<h3>Physics Fundamentals</h3><p>Key concepts frequently tested in Loksewa exams:</p><ul><li><strong>Newton\'s Laws of Motion:</strong> First law (inertia), Second law (F=ma), Third law (action-reaction)</li><li><strong>Energy:</strong> Kinetic energy, Potential energy, Conservation of energy. Nepal\'s hydropower potential of 83,000 MW (economically feasible: 42,000 MW)</li><li><strong>Light:</strong> Reflection, refraction, dispersion, total internal reflection</li></ul><h3>Biology Basics</h3><ul><li>Cell structure: Nucleus, mitochondria, chloroplast, cell membrane</li><li>Blood groups: A, B, AB, O and Rh factor</li><li>Vitamins and deficiency diseases: A (night blindness), B1 (beriberi), C (scurvy), D (rickets)</li></ul><h3>Nepal\'s IT Development</h3><ul><li>NTC established 1913 BS for telecommunications</li><li>Internet introduced to Nepal in 1994</li><li>E-governance initiatives: Nagarik App, MeroKitta, online tax filing</li></ul>', NULL, 'lessons/pdfs/01M1GG34XZX29EA3AWDWHPPXXE.pdf', '[{\"question\":\"Which is the largest continent in the world by both surface area and total population?\",\"options\":[\"Africa\",\"Asia\",\"North America\",\"Europe\"],\"option_0\":\"Africa\",\"option_1\":\"Asia\",\"option_2\":\"North America\",\"option_3\":\"Europe\",\"answer\":1,\"hint\":\"Covers nearly 30% of Earth\\u2019s land area and is home to about 60% of the world\\u2019s population.\",\"explanation\":\"Asia is the largest and most populous continent, spanning over 44.5 million square kilometers.\"},{\"question\":\"Which is the longest river in the world?\",\"options\":[\"Amazon River\",\"Nile River\",\"Yangtze River\",\"Mississippi River\"],\"option_0\":\"Amazon River\",\"option_1\":\"Nile River\",\"option_2\":\"Yangtze River\",\"option_3\":\"Mississippi River\",\"answer\":1,\"hint\":\"Flows northward through eleven countries in northeastern Africa into the Mediterranean Sea.\",\"explanation\":\"The Nile River in Africa is the longest river in the world with an estimated length of 6,650 km.\"},{\"question\":\"Which is the largest and deepest ocean on Earth?\",\"options\":[\"Atlantic Ocean\",\"Pacific Ocean\",\"Indian Ocean\",\"Arctic Ocean\"],\"option_0\":\"Atlantic Ocean\",\"option_1\":\"Pacific Ocean\",\"option_2\":\"Indian Ocean\",\"option_3\":\"Arctic Ocean\",\"answer\":1,\"hint\":\"Covers more than 30% of the Earth\\u2019s surface, larger than all land masses combined.\",\"explanation\":\"The Pacific Ocean is the largest and deepest ocean basin, containing the deepest oceanic point on Earth (Mariana Trench).\"},{\"question\":\"What is the deepest trench in the world oceans located in the western Pacific Ocean?\",\"options\":[\"Java Trench\",\"Mariana Trench\",\"Puerto Rico Trench\",\"Sunda Trench\"],\"option_0\":\"Java Trench\",\"option_1\":\"Mariana Trench\",\"option_2\":\"Puerto Rico Trench\",\"option_3\":\"Sunda Trench\",\"answer\":1,\"hint\":\"Its lowest section, Challenger Deep, descends nearly 11 kilometers below sea level.\",\"explanation\":\"The Mariana Trench (Challenger Deep) is the deepest oceanic trench on Earth with a depth of approximately 11,034 meters.\"},{\"question\":\"Which is the largest hot desert in the world?\",\"options\":[\"Gobi Desert\",\"Sahara Desert\",\"Kalahari Desert\",\"Thar Desert\"],\"option_0\":\"Gobi Desert\",\"option_1\":\"Sahara Desert\",\"option_2\":\"Kalahari Desert\",\"option_3\":\"Thar Desert\",\"answer\":1,\"hint\":\"Spans over 9 million square kilometers across North Africa.\",\"explanation\":\"The Sahara Desert in North Africa is the world\\u2019s largest subtropical hot desert, covering roughly the size of the United States.\"},{\"question\":\"Which is the world largest freshwater lake by surface area?\",\"options\":[\"Lake Baikal\",\"Lake Superior\",\"Lake Victoria\",\"Caspian Sea\"],\"option_0\":\"Lake Baikal\",\"option_1\":\"Lake Superior\",\"option_2\":\"Lake Victoria\",\"option_3\":\"Caspian Sea\",\"answer\":1,\"hint\":\"One of the Great Lakes shared between the United States and Canada.\",\"explanation\":\"Lake Superior is the world\\u2019s largest freshwater lake by surface area (approx. 82,100 sq km).\"},{\"question\":\"Which is the deepest freshwater lake in the world located in Siberia, Russia?\",\"options\":[\"Lake Tanganyika\",\"Lake Baikal\",\"Lake Malawi\",\"Lake Huron\"],\"option_0\":\"Lake Tanganyika\",\"option_1\":\"Lake Baikal\",\"option_2\":\"Lake Malawi\",\"option_3\":\"Lake Huron\",\"answer\":1,\"hint\":\"Contains 20% of the world\\u2019s unfrozen surface fresh water.\",\"explanation\":\"Lake Baikal in Russia is the deepest lake in the world with a maximum depth of 1,642 meters (5,387 feet).\"},{\"question\":\"Which strait separates Asia from North America connecting the Arctic Ocean with the Bering Sea?\",\"options\":[\"Strait of Gibraltar\",\"Bering Strait\",\"Strait of Malacca\",\"Bosphorus Strait\"],\"option_0\":\"Strait of Gibraltar\",\"option_1\":\"Bering Strait\",\"option_2\":\"Strait of Malacca\",\"option_3\":\"Bosphorus Strait\",\"answer\":1,\"hint\":\"Lies between Cape Dezhnev in Russia and Cape Prince of Wales in Alaska.\",\"explanation\":\"The Bering Strait connects the Chukchi Sea (Arctic Ocean) with the Bering Sea (Pacific Ocean), separating Russia from Alaska.\"},{\"question\":\"Which is the longest continental mountain range in the world?\",\"options\":[\"Himalayas\",\"Andes Mountain Range\",\"Rocky Mountains\",\"Alps\"],\"option_0\":\"Himalayas\",\"option_1\":\"Andes Mountain Range\",\"option_2\":\"Rocky Mountains\",\"option_3\":\"Alps\",\"answer\":1,\"hint\":\"Runs along the entire western coast of South America through seven countries.\",\"explanation\":\"The Andes is the longest continental mountain range in the world, extending about 7,000 km along western South America.\"},{\"question\":\"Which country in the world is known as the Land of the Midnight Sun?\",\"options\":[\"Japan\",\"Norway\",\"Canada\",\"New Zealand\"],\"option_0\":\"Japan\",\"option_1\":\"Norway\",\"option_2\":\"Canada\",\"option_3\":\"New Zealand\",\"answer\":1,\"hint\":\"During summer months north of the Arctic Circle, the sun never sets below the horizon.\",\"explanation\":\"Norway is called the Land of the Midnight Sun because northern regions experience continuous daylight during summer.\"}]', 'text', 2, 15, 1, '2026-08-29 08:42:03', '2026-09-02 12:19:39'),
(70, 1, NULL, 'History of World', 'history-of-world', 'focus on history', NULL, 'lessons/pdfs/History-of-World-GK-PDF-Notes_compressed.pdf', '[{\"question\":\"The French Revolution began in which year with the storming of the Bastille prison?\",\"options\":[\"1776 AD\",\"1789 AD\",\"1804 AD\",\"1815 AD\"],\"option_0\":\"1776 AD\",\"option_1\":\"1789 AD\",\"option_2\":\"1804 AD\",\"option_3\":\"1815 AD\",\"answer\":1,\"hint\":\"Adopted the famous motto: Liberty, Equality, Fraternity.\",\"explanation\":\"The French Revolution commenced on 14 July 1789 with the storming of the Bastille in Paris, overturning absolute feudal monarchy.\"},{\"question\":\"In which country did the Industrial Revolution first begin in the mid-18th century?\",\"options\":[\"France\",\"Great Britain\",\"Germany\",\"United States\"],\"option_0\":\"France\",\"option_1\":\"Great Britain\",\"option_2\":\"Germany\",\"option_3\":\"United States\",\"answer\":1,\"hint\":\"Pioneered through mechanized textile manufacturing, steam engines, and coal mining.\",\"explanation\":\"The Industrial Revolution originated in Great Britain around 1760 due to inventions like James Watt\\u2019s steam engine and access to capital and coal.\"},{\"question\":\"The American Declaration of Independence from British rule was officially adopted on which date?\",\"options\":[\"July 4, 1776 AD\",\"August 15, 1783 AD\",\"January 1, 1789 AD\",\"December 25, 1775 AD\"],\"option_0\":\"July 4, 1776 AD\",\"option_1\":\"August 15, 1783 AD\",\"option_2\":\"January 1, 1789 AD\",\"option_3\":\"December 25, 1775 AD\",\"answer\":0,\"hint\":\"Drafted by Thomas Jefferson and signed in Philadelphia; celebrated as US Independence Day.\",\"explanation\":\"The 13 American colonies declared independence from Great Britain on July 4, 1776 in Philadelphia.\"},{\"question\":\"What was the duration of the First World War?\",\"options\":[\"1912 to 1916 AD\",\"1914 to 1918 AD\",\"1939 to 1945 AD\",\"1905 to 1911 AD\"],\"option_0\":\"1912 to 1916 AD\",\"option_1\":\"1914 to 1918 AD\",\"option_2\":\"1939 to 1945 AD\",\"option_3\":\"1905 to 1911 AD\",\"answer\":1,\"hint\":\"Triggered by the assassination of Archduke Franz Ferdinand of Austria in Sarajevo in June 1914.\",\"explanation\":\"World War I lasted from 28 July 1914 to 11 November 1918, ending with the signing of the Treaty of Versailles in 1919.\"},{\"question\":\"World War II began in September 1939 with Germany invasion of which country?\",\"options\":[\"France\",\"Poland\",\"Soviet Union\",\"Austria\"],\"option_0\":\"France\",\"option_1\":\"Poland\",\"option_2\":\"Soviet Union\",\"option_3\":\"Austria\",\"answer\":1,\"hint\":\"Led Great Britain and France to declare war on Nazi Germany two days later.\",\"explanation\":\"World War II commenced on September 1, 1939 when Adolf Hitler\\u2019s Nazi Germany launched a blitzkrieg invasion of Poland.\"},{\"question\":\"The Russian Bolshevik Revolution in 1917 was led by which revolutionary leader?\",\"options\":[\"Joseph Stalin\",\"Vladimir Lenin\",\"Leon Trotsky\",\"Karl Marx\"],\"option_0\":\"Joseph Stalin\",\"option_1\":\"Vladimir Lenin\",\"option_2\":\"Leon Trotsky\",\"option_3\":\"Karl Marx\",\"answer\":1,\"hint\":\"Overthrew Tsar Nicholas II and the provisional government to establish the Soviet Union.\",\"explanation\":\"Vladimir Lenin led the Bolsheviks during the October Revolution in November 1917, establishing the world\\u2019s first socialist state.\"},{\"question\":\"On which two Japanese cities did the United States drop atomic bombs in August 1945?\",\"options\":[\"Tokyo and Kyoto\",\"Hiroshima and Nagasaki\",\"Osaka and Yokohama\",\"Sapporo and Kobe\"],\"option_0\":\"Tokyo and Kyoto\",\"option_1\":\"Hiroshima and Nagasaki\",\"option_2\":\"Osaka and Yokohama\",\"option_3\":\"Sapporo and Kobe\",\"answer\":1,\"hint\":\"Little Boy was dropped on August 6 and Fat Man on August 9, 1945.\",\"explanation\":\"The US detonated atomic bombs over Hiroshima on 6 August 1945 and Nagasaki on 9 August 1945, leading to Japan\\u2019s surrender.\"},{\"question\":\"In which year was the United Nations officially founded in San Francisco?\",\"options\":[\"1919 AD\",\"1945 AD\",\"1948 AD\",\"1955 AD\"],\"option_0\":\"1919 AD\",\"option_1\":\"1945 AD\",\"option_2\":\"1948 AD\",\"option_3\":\"1955 AD\",\"answer\":1,\"hint\":\"Charter signed by 51 original member states on October 24, 1945.\",\"explanation\":\"The United Nations was officially established on 24 October 1945 when the UN Charter was ratified by the permanent Security Council members and majority signatories.\"},{\"question\":\"The historic fall of the Berlin Wall occurred in which year?\",\"options\":[\"1985 AD\",\"1989 AD\",\"1991 AD\",\"1995 AD\"],\"option_0\":\"1985 AD\",\"option_1\":\"1989 AD\",\"option_2\":\"1991 AD\",\"option_3\":\"1995 AD\",\"answer\":1,\"hint\":\"Paved the way for German reunification in 1990 and the dissolution of the Soviet Union.\",\"explanation\":\"The Berlin Wall fell on 9 November 1989, uniting East and West Germany and marking the symbolic end of the Cold War.\"},{\"question\":\"The Magna Carta, the foundational charter limiting royal power and establishing rule of law, was signed in England in:\",\"options\":[\"1066 AD\",\"1215 AD\",\"1492 AD\",\"1688 AD\"],\"option_0\":\"1066 AD\",\"option_1\":\"1215 AD\",\"option_2\":\"1492 AD\",\"option_3\":\"1688 AD\",\"answer\":1,\"hint\":\"Granted by King John of England at Runnymede.\",\"explanation\":\"King John of England granted the Magna Carta on 15 June 1215, establishing the legal principle that everyone, including the monarch, is subject to the law.\"}]', 'text', 5, 15, 1, '2026-09-01 01:44:56', '2026-09-02 12:19:39'),
(71, 21, NULL, 'Analogy', 'analogy', '<LI><UL>Focus on Analogy<UL>\n<ul>identify the exact relationship<ul><LI>', NULL, 'lessons/pdfs/Analogy Kharidar.pdf', '[{\"question\":\"Kathmandu : Nepal :: New Delhi : ?\",\"options\":[\"China\",\"India\",\"Pakistan\",\"Bangladesh\"],\"option_0\":\"China\",\"option_1\":\"India\",\"option_2\":\"Pakistan\",\"option_3\":\"Bangladesh\",\"answer\":1,\"hint\":\"Relationship is Capital City to Country.\",\"explanation\":\"Kathmandu is the capital of Nepal; New Delhi is the capital of India.\"},{\"question\":\"Mount Everest : Nepal :: Mount Kilimanjaro : ?\",\"options\":[\"Kenya\",\"Tanzania\",\"Egypt\",\"South Africa\"],\"option_0\":\"Kenya\",\"option_1\":\"Tanzania\",\"option_2\":\"Egypt\",\"option_3\":\"South Africa\",\"answer\":1,\"hint\":\"Highest peak of Africa located in this East African country.\",\"explanation\":\"Mount Everest is the highest mountain in Nepal; Mount Kilimanjaro is the highest peak in Tanzania (Africa).\"},{\"question\":\"Thermometer : Temperature :: Barometer : ?\",\"options\":[\"Humidity\",\"Atmospheric Pressure\",\"Wind Velocity\",\"Earthquake Intensity\"],\"option_0\":\"Humidity\",\"option_1\":\"Atmospheric Pressure\",\"option_2\":\"Wind Velocity\",\"option_3\":\"Earthquake Intensity\",\"answer\":1,\"hint\":\"Instrument to measuring quantity relationship.\",\"explanation\":\"A thermometer measures temperature; a barometer measures atmospheric pressure.\"},{\"question\":\"Doctor : Hospital :: Teacher : ?\",\"options\":[\"Court\",\"School\",\"Laboratory\",\"Library\"],\"option_0\":\"Court\",\"option_1\":\"School\",\"option_2\":\"Laboratory\",\"option_3\":\"Library\",\"answer\":1,\"hint\":\"Professional to workplace relationship.\",\"explanation\":\"A doctor works in a hospital; a teacher works in a school.\"},{\"question\":\"Heart : Cardiology :: Brain : ?\",\"options\":[\"Dermatology\",\"Neurology\",\"Nephrology\",\"Oncology\"],\"option_0\":\"Dermatology\",\"option_1\":\"Neurology\",\"option_2\":\"Nephrology\",\"option_3\":\"Oncology\",\"answer\":1,\"hint\":\"Organ to medical specialization relationship.\",\"explanation\":\"Cardiology is the study of the heart; neurology is the study of the brain and nervous system.\"},{\"question\":\"Book : Author :: Statue : ?\",\"options\":[\"Painter\",\"Sculptor\",\"Architect\",\"Mason\"],\"option_0\":\"Painter\",\"option_1\":\"Sculptor\",\"option_2\":\"Architect\",\"option_3\":\"Mason\",\"answer\":1,\"hint\":\"Creation to creator relationship.\",\"explanation\":\"An author writes a book; a sculptor carves a statue.\"},{\"question\":\"Pen : Writer :: Scalpel : ?\",\"options\":[\"Carpenter\",\"Surgeon\",\"Tailor\",\"Sculptor\"],\"option_0\":\"Carpenter\",\"option_1\":\"Surgeon\",\"option_2\":\"Tailor\",\"option_3\":\"Sculptor\",\"answer\":1,\"hint\":\"Tool to professional relationship.\",\"explanation\":\"A pen is the working tool of a writer; a scalpel is the surgical tool of a surgeon.\"},{\"question\":\"Nepal : Rupee :: Japan : ?\",\"options\":[\"Dollar\",\"Yen\",\"Won\",\"Yuan\"],\"option_0\":\"Dollar\",\"option_1\":\"Yen\",\"option_2\":\"Won\",\"option_3\":\"Yuan\",\"answer\":1,\"hint\":\"Country to official currency relationship.\",\"explanation\":\"Rupee is the currency of Nepal; Yen is the official currency of Japan.\"},{\"question\":\"Fish : Gills :: Human : ?\",\"options\":[\"Skin\",\"Lungs\",\"Heart\",\"Trachea\"],\"option_0\":\"Skin\",\"option_1\":\"Lungs\",\"option_2\":\"Heart\",\"option_3\":\"Trachea\",\"answer\":1,\"hint\":\"Organism to primary respiratory organ relationship.\",\"explanation\":\"Fish breathe through gills; human beings breathe using lungs.\"},{\"question\":\"Ornithology : Birds :: Entomology : ?\",\"options\":[\"Fossils\",\"Insects\",\"Plants\",\"Fungi\"],\"option_0\":\"Fossils\",\"option_1\":\"Insects\",\"option_2\":\"Plants\",\"option_3\":\"Fungi\",\"answer\":1,\"hint\":\"Branch of zoology to organism studied.\",\"explanation\":\"Ornithology is the scientific study of birds; entomology is the scientific study of insects.\"}]', 'text', 1, 15, 1, '2026-09-01 03:35:39', '2026-09-02 12:19:39'),
(72, 21, NULL, 'Classification', 'classification', NULL, NULL, 'lessons/pdfs/Classification Kharidar.pdf', '[{\"question\":\"Find the odd one out among the following geographical features:\",\"options\":[\"Mount Everest\",\"Rara Lake\",\"Kangchenjunga\",\"Annapurna\"],\"option_0\":\"Mount Everest\",\"option_1\":\"Rara Lake\",\"option_2\":\"Kangchenjunga\",\"option_3\":\"Annapurna\",\"answer\":1,\"hint\":\"Three are mountain peaks while one is a lake.\",\"explanation\":\"Mount Everest, Kangchenjunga, and Annapurna are Himalayan mountain peaks; Rara is a lake.\"},{\"question\":\"Which of the following is the odd one out among SAARC member nations?\",\"options\":[\"Nepal\",\"Myanmar\",\"Bhutan\",\"Sri Lanka\"],\"option_0\":\"Nepal\",\"option_1\":\"Myanmar\",\"option_2\":\"Bhutan\",\"option_3\":\"Sri Lanka\",\"answer\":1,\"hint\":\"Three are founding members of SAARC; one is a member of ASEAN.\",\"explanation\":\"Nepal, Bhutan, and Sri Lanka are SAARC member states; Myanmar belongs to ASEAN and is not a member of SAARC.\"},{\"question\":\"Find the odd number out in the group: 2, 3, 5, 7, 9, 11, 13\",\"options\":[\"7\",\"9\",\"11\",\"13\"],\"option_0\":\"7\",\"option_1\":\"9\",\"option_2\":\"11\",\"option_3\":\"13\",\"answer\":1,\"hint\":\"All other numbers are prime numbers except this composite number.\",\"explanation\":\"All numbers in the set are prime numbers except 9, which is a composite number divisible by 3.\"},{\"question\":\"Find the odd one out among the following cities:\",\"options\":[\"Kathmandu\",\"Sydney\",\"Tokyo\",\"London\"],\"option_0\":\"Kathmandu\",\"option_1\":\"Sydney\",\"option_2\":\"Tokyo\",\"option_3\":\"London\",\"answer\":1,\"hint\":\"Canberra is the capital of Australia, not Sydney.\",\"explanation\":\"Kathmandu, Tokyo, and London are national capitals; Sydney is a major Australian city but Canberra is the capital.\"},{\"question\":\"Which of the following organs is the odd one out?\",\"options\":[\"Eyes\",\"Stomach\",\"Ears\",\"Nose\"],\"option_0\":\"Eyes\",\"option_1\":\"Stomach\",\"option_2\":\"Ears\",\"option_3\":\"Nose\",\"answer\":1,\"hint\":\"Three are external sensory organs; one is an internal digestive organ.\",\"explanation\":\"Eyes, ears, and nose are sensory organs; the stomach is an internal digestive organ.\"},{\"question\":\"Find the odd one out among computer input and output hardware devices:\",\"options\":[\"Keyboard\",\"Printer\",\"Mouse\",\"Scanner\"],\"option_0\":\"Keyboard\",\"option_1\":\"Printer\",\"option_2\":\"Mouse\",\"option_3\":\"Scanner\",\"answer\":1,\"hint\":\"Three are input devices; one is an output device.\",\"explanation\":\"Keyboard, Mouse, and Scanner are input devices; Printer is an output peripheral.\"},{\"question\":\"Find the odd one out among objects in the Solar System:\",\"options\":[\"Earth\",\"Moon\",\"Mars\",\"Venus\"],\"option_0\":\"Earth\",\"option_1\":\"Moon\",\"option_2\":\"Mars\",\"option_3\":\"Venus\",\"answer\":1,\"hint\":\"Three are planets orbiting the Sun; one is a natural satellite orbiting Earth.\",\"explanation\":\"Earth, Mars, and Venus are planets; the Moon is a natural satellite.\"},{\"question\":\"Which unit of measurement is the odd one out?\",\"options\":[\"Kilogram\",\"Kilometer\",\"Gram\",\"Pound\"],\"option_0\":\"Kilogram\",\"option_1\":\"Kilometer\",\"option_2\":\"Gram\",\"option_3\":\"Pound\",\"answer\":1,\"hint\":\"Three measure mass\\/weight; one measures distance\\/length.\",\"explanation\":\"Kilogram, Gram, and Pound measure mass\\/weight; Kilometer measures distance.\"},{\"question\":\"Find the odd one out among the following substances:\",\"options\":[\"Iron\",\"Diamond\",\"Copper\",\"Gold\"],\"option_0\":\"Iron\",\"option_1\":\"Diamond\",\"option_2\":\"Copper\",\"option_3\":\"Gold\",\"answer\":1,\"hint\":\"Three are metallic chemical elements; one is an allotrope of carbon.\",\"explanation\":\"Iron, Copper, and Gold are metallic elements; Diamond is a crystalline non-metallic allotrope of Carbon.\"},{\"question\":\"Find the odd one out among state agencies of Nepal:\",\"options\":[\"Public Service Commission\",\"National Planning Commission\",\"Election Commission\",\"Commission for the Investigation of Abuse of Authority\"],\"option_0\":\"Public Service Commission\",\"option_1\":\"National Planning Commission\",\"option_2\":\"Election Commission\",\"option_3\":\"Commission for the Investigation of Abuse of Authority\",\"answer\":1,\"hint\":\"Three are constitutional bodies created directly under Parts 21-24; one is an executive advisory body.\",\"explanation\":\"PSC, Election Commission, and CIAA are constitutional bodies; the National Planning Commission is an executive advisory agency.\"}]', 'text', 2, 15, 1, '2026-09-01 03:44:17', '2026-09-02 12:19:39'),
(73, 21, NULL, 'Number Series', 'number-series', 'Focus on Number series', NULL, 'lessons/pdfs/Number Series Kharidar.pdf', '[{\"question\":\"Find the next number in the series: 2, 4, 8, 16, 32, ?\",\"options\":[\"48\",\"64\",\"56\",\"72\"],\"option_0\":\"48\",\"option_1\":\"64\",\"option_2\":\"56\",\"option_3\":\"72\",\"answer\":1,\"hint\":\"Each number is multiplied by 2.\",\"explanation\":\"Pattern: 2x2=4, 4x2=8, 8x2=16, 16x2=32, 32x2 = 64.\"},{\"question\":\"Find the next term in the series: 3, 6, 11, 18, 27, ?\",\"options\":[\"36\",\"38\",\"40\",\"42\"],\"option_0\":\"36\",\"option_1\":\"38\",\"option_2\":\"40\",\"option_3\":\"42\",\"answer\":1,\"hint\":\"Differences are successive odd numbers: +3, +5, +7, +9, +11.\",\"explanation\":\"Differences: 6-3=3, 11-6=5, 18-11=7, 27-18=9. Next difference is +11: 27 + 11 = 38.\"},{\"question\":\"Find the missing number in the Fibonacci sequence: 1, 1, 2, 3, 5, 8, 13, ?\",\"options\":[\"18\",\"21\",\"24\",\"26\"],\"option_0\":\"18\",\"option_1\":\"21\",\"option_2\":\"24\",\"option_3\":\"26\",\"answer\":1,\"hint\":\"Each term is the sum of the two preceding terms.\",\"explanation\":\"Fibonacci sequence: 1+1=2, 1+2=3, 2+3=5, 3+5=8, 5+8=13, 8+13 = 21.\"},{\"question\":\"Find the next number in the series: 1, 4, 9, 16, 25, 36, ?\",\"options\":[\"45\",\"49\",\"54\",\"64\"],\"option_0\":\"45\",\"option_1\":\"49\",\"option_2\":\"54\",\"option_3\":\"64\",\"answer\":1,\"hint\":\"Perfect squares of natural numbers: 1\\u00b2, 2\\u00b2, 3\\u00b2, 4\\u00b2, 5\\u00b2, 6\\u00b2, 7\\u00b2.\",\"explanation\":\"Series of squares: 1\\u00b2=1, 2\\u00b2=4, 3\\u00b2=9, 4\\u00b2=16, 5\\u00b2=25, 6\\u00b2=36, 7\\u00b2 = 49.\"},{\"question\":\"Find the next term in the series: 1, 8, 27, 64, 125, ?\",\"options\":[\"196\",\"216\",\"225\",\"343\"],\"option_0\":\"196\",\"option_1\":\"216\",\"option_2\":\"225\",\"option_3\":\"343\",\"answer\":1,\"hint\":\"Series of cubes: 1\\u00b3, 2\\u00b3, 3\\u00b3, 4\\u00b3, 5\\u00b3, 6\\u00b3.\",\"explanation\":\"1\\u00b3=1, 2\\u00b3=8, 3\\u00b3=27, 4\\u00b3=64, 5\\u00b3=125, 6\\u00b3 = 216.\"},{\"question\":\"Find the missing number: 100, 95, 85, 70, 50, ?\",\"options\":[\"30\",\"25\",\"20\",\"35\"],\"option_0\":\"30\",\"option_1\":\"25\",\"option_2\":\"20\",\"option_3\":\"35\",\"answer\":1,\"hint\":\"Subtracting consecutive multiples of 5: -5, -10, -15, -20, -25.\",\"explanation\":\"100-5=95, 95-10=85, 85-15=70, 70-20=50, 50-25 = 25.\"},{\"question\":\"Find the next number in the alternating series: 2, 3, 5, 6, 8, 9, 11, ?\",\"options\":[\"13\",\"12\",\"14\",\"15\"],\"option_0\":\"13\",\"option_1\":\"12\",\"option_2\":\"14\",\"option_3\":\"15\",\"answer\":1,\"hint\":\"Pattern alternates: +1, +2, +1, +2, +1, +2, +1.\",\"explanation\":\"2+1=3, 3+2=5, 5+1=6, 6+2=8, 8+1=9, 9+2=11, 11+1 = 12.\"},{\"question\":\"Find the missing term: 4, 9, 19, 39, 79, ?\",\"options\":[\"149\",\"159\",\"169\",\"179\"],\"option_0\":\"149\",\"option_1\":\"159\",\"option_2\":\"169\",\"option_3\":\"179\",\"answer\":1,\"hint\":\"Multiply by 2 and add 1.\",\"explanation\":\"(4x2)+1=9, (9x2)+1=19, (19x2)+1=39, (39x2)+1=79, (79x2)+1 = 159.\"},{\"question\":\"Find the next number in the series: 120, 99, 80, 63, 48, ?\",\"options\":[\"32\",\"35\",\"38\",\"40\"],\"option_0\":\"32\",\"option_1\":\"35\",\"option_2\":\"38\",\"option_3\":\"40\",\"answer\":1,\"hint\":\"Pattern: 11\\u00b2-1, 10\\u00b2-1, 9\\u00b2-1, 8\\u00b2-1, 7\\u00b2-1, 6\\u00b2-1.\",\"explanation\":\"11\\u00b2-1=120, 10\\u00b2-1=99, 9\\u00b2-1=80, 8\\u00b2-1=63, 7\\u00b2-1=48, 6\\u00b2-1 = 35.\"},{\"question\":\"Find the missing number in the series: 7, 14, 28, 56, 112, ?\",\"options\":[\"214\",\"224\",\"230\",\"240\"],\"option_0\":\"214\",\"option_1\":\"224\",\"option_2\":\"230\",\"option_3\":\"240\",\"answer\":1,\"hint\":\"Doubling each number: 112 multiplied by 2.\",\"explanation\":\"7x2=14, 14x2=28, 28x2=56, 56x2=112, 112x2 = 224.\"}]', 'text', 3, 15, 1, '2026-09-01 03:50:11', '2026-09-02 12:19:39'),
(74, 21, NULL, 'Letter Series', 'letter-series', 'Focus on letter series', NULL, 'lessons/pdfs/Letter Series Kharidar.pdf', '[{\"question\":\"Find the next letter in the series: A, C, E, G, I, ?\",\"options\":[\"J\",\"K\",\"L\",\"M\"],\"option_0\":\"J\",\"option_1\":\"K\",\"option_2\":\"L\",\"option_3\":\"M\",\"answer\":1,\"hint\":\"Skipping one letter forward (+2 positions).\",\"explanation\":\"Letter positions: A(1), C(3), E(5), G(7), I(9). Next is position 11 = K.\"},{\"question\":\"Find the next term in the series: Z, X, V, T, R, ?\",\"options\":[\"O\",\"P\",\"Q\",\"N\"],\"option_0\":\"O\",\"option_1\":\"P\",\"option_2\":\"Q\",\"option_3\":\"N\",\"answer\":1,\"hint\":\"Moving backwards by 2 letters (-2 positions).\",\"explanation\":\"Z(26), X(24), V(22), T(20), R(18). Next is 18 - 2 = 16 = P.\"},{\"question\":\"Find the missing group of letters: AB, CD, EF, GH, ?\",\"options\":[\"IK\",\"IJ\",\"JK\",\"IL\"],\"option_0\":\"IK\",\"option_1\":\"IJ\",\"option_2\":\"JK\",\"option_3\":\"IL\",\"answer\":1,\"hint\":\"Consecutive alphabet pairs.\",\"explanation\":\"The series groups consecutive letters: AB, CD, EF, GH, IJ.\"},{\"question\":\"Find the next letter in the series: B, D, G, K, P, ?\",\"options\":[\"U\",\"V\",\"W\",\"X\"],\"option_0\":\"U\",\"option_1\":\"V\",\"option_2\":\"W\",\"option_3\":\"X\",\"answer\":1,\"hint\":\"Increments increase by 1 each step: +2, +3, +4, +5, +6.\",\"explanation\":\"B(2)+2=D(4), D(4)+3=G(7), G(7)+4=K(11), K(11)+5=P(16). Next: 16+6 = 22 = V.\"},{\"question\":\"Find the next term in the series: AZ, BY, CX, DW, ?\",\"options\":[\"ET\",\"EV\",\"FU\",\"EW\"],\"option_0\":\"ET\",\"option_1\":\"EV\",\"option_2\":\"FU\",\"option_3\":\"EW\",\"answer\":1,\"hint\":\"Pairs of opposite letters from start and end of alphabet.\",\"explanation\":\"First letter moves forward (A, B, C, D, E), second moves backward (Z, Y, X, W, V) -> EV.\"},{\"question\":\"What is the missing term: CBA, FED, IHG, LKJ, ?\",\"options\":[\"NML\",\"ONM\",\"PON\",\"MLK\"],\"option_0\":\"NML\",\"option_1\":\"ONM\",\"option_2\":\"PON\",\"option_3\":\"MLK\",\"answer\":1,\"hint\":\"Triplets of 3 letters written in reverse order.\",\"explanation\":\"CBA is ABC reversed, FED is DEF reversed, IHG is GHI reversed, LKJ is JKL reversed. Next is MNO reversed = ONM.\"},{\"question\":\"Find the next letter in the series: A, D, I, P, ?\",\"options\":[\"W\",\"Y\",\"X\",\"Z\"],\"option_0\":\"W\",\"option_1\":\"Y\",\"option_2\":\"X\",\"option_3\":\"Z\",\"answer\":1,\"hint\":\"Positions correspond to square numbers: 1\\u00b2, 2\\u00b2, 3\\u00b2, 4\\u00b2, 5\\u00b2.\",\"explanation\":\"Square number positions: 1\\u00b2=A(1), 2\\u00b2=D(4), 3\\u00b2=I(9), 4\\u00b2=P(16), 5\\u00b2=Y(25).\"},{\"question\":\"Find the next term in the series: KPA, LQB, MRC, NSD, ?\",\"options\":[\"OTE\",\"OTE\",\"PTE\",\"OTF\"],\"option_0\":\"OTE\",\"option_1\":\"OTE\",\"option_2\":\"PTE\",\"option_3\":\"OTF\",\"answer\":0,\"hint\":\"Each letter in the triplet shifts +1 position.\",\"explanation\":\"First letters: K, L, M, N, O. Second: P, Q, R, S, T. Third: A, B, C, D, E -> OTE.\"},{\"question\":\"Find the next letter: J, F, M, A, M, J, J, A, S, O, N, ?\",\"options\":[\"O\",\"D\",\"P\",\"F\"],\"option_0\":\"O\",\"option_1\":\"D\",\"option_2\":\"P\",\"option_3\":\"F\",\"answer\":1,\"hint\":\"First letters of the 12 calendar months: January, February, March... December.\",\"explanation\":\"The series represents the first letter of each month of the year. The 12th month is December (D).\"},{\"question\":\"Find the missing letter in the series: O, T, T, F, F, S, S, E, N, ?\",\"options\":[\"E\",\"T\",\"O\",\"S\"],\"option_0\":\"E\",\"option_1\":\"T\",\"option_2\":\"O\",\"option_3\":\"S\",\"answer\":1,\"hint\":\"First letters of natural numbers: One, Two, Three, Four, Five, Six, Seven, Eight, Nine, Ten.\",\"explanation\":\"The letters represent the initial letters of English numbers 1 through 10. Number 10 is Ten, so the answer is T.\"}]', 'text', 4, 15, 1, '2026-09-01 03:55:44', '2026-09-02 12:19:39');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(75, 21, NULL, 'Coding-Decoding', 'coding-decoding', 'Focus on Coding-Decoding', NULL, 'lessons/pdfs/Coding Decoding Kharidar.pdf', '[{\"question\":\"If in a certain code, \\\"LOKSEWA\\\" is written as \\\"MQLTFZB\\\", how is \\\"NEPAL\\\" written in that code?\",\"options\":[\"OFQBM\",\"OFQBN\",\"OGQBN\",\"PEQBM\"],\"option_0\":\"OFQBM\",\"option_1\":\"OFQBN\",\"option_2\":\"OGQBN\",\"option_3\":\"PEQBM\",\"answer\":0,\"hint\":\"Each letter is shifted forward by +1 position.\",\"explanation\":\"Applying +1 forward shift to each letter: N->O, E->F, P->Q, A->B, L->M = OFQBM.\"},{\"question\":\"If \\\"CAT\\\" is coded as 24, what is the numerical code value for \\\"DOG\\\"?\",\"options\":[\"22\",\"26\",\"28\",\"30\"],\"option_0\":\"22\",\"option_1\":\"26\",\"option_2\":\"28\",\"option_3\":\"30\",\"answer\":1,\"hint\":\"Sum of the alphabetical position values of the letters: D=4, O=15, G=7.\",\"explanation\":\"D=4, O=15, G=7. Sum = 4 + 15 + 7 = 26.\"},{\"question\":\"If \\\"BOOK\\\" is coded as \\\"CPPL\\\", how is \\\"READ\\\" coded in the same language?\",\"options\":[\"SFBE\",\"SEBE\",\"SGBE\",\"TFBE\"],\"option_0\":\"SFBE\",\"option_1\":\"SEBE\",\"option_2\":\"SGBE\",\"option_3\":\"TFBE\",\"answer\":0,\"hint\":\"Shift each letter forward by +1 position.\",\"explanation\":\"R->S, E->F, A->B, D->E = SFBE.\"},{\"question\":\"In a code language, if \\\"WATER\\\" is coded as \\\"YCVGT\\\", what is the code for \\\"RIVER\\\"?\",\"options\":[\"TKXGT\",\"SKXGT\",\"TKYGT\",\"UKXGT\"],\"option_0\":\"TKXGT\",\"option_1\":\"SKXGT\",\"option_2\":\"TKYGT\",\"option_3\":\"UKXGT\",\"answer\":0,\"hint\":\"Shift each letter forward by +2 positions.\",\"explanation\":\"Each letter advances by 2 positions: R+2=T, I+2=K, V+2=X, E+2=G, R+2=T -> TKXGT.\"},{\"question\":\"If \\\"SUN\\\" is coded as 54, what is the code for \\\"MOON\\\"?\",\"options\":[\"50\",\"57\",\"60\",\"62\"],\"option_0\":\"50\",\"option_1\":\"57\",\"option_2\":\"60\",\"option_3\":\"62\",\"answer\":1,\"hint\":\"Sum of letter positions: M=13, O=15, O=15, N=14.\",\"explanation\":\"13 + 15 + 15 + 14 = 57.\"},{\"question\":\"If \\\"PEN\\\" is written as \\\"QFO\\\", how is \\\"INK\\\" written in that code?\",\"options\":[\"JOL\",\"KOL\",\"JPM\",\"INL\"],\"option_0\":\"JOL\",\"option_1\":\"KOL\",\"option_2\":\"JPM\",\"option_3\":\"INL\",\"answer\":0,\"hint\":\"Shift each letter forward by +1 position.\",\"explanation\":\"I->J, N->O, K->L = JOL.\"},{\"question\":\"If in a code language, 123 means \\\"Hot Filtered Coffee\\\", 356 means \\\"Very Hot Day\\\", and 589 means \\\"Day and Night\\\", which digit stands for \\\"Very\\\"?\",\"options\":[\"3\",\"6\",\"5\",\"8\"],\"option_0\":\"3\",\"option_1\":\"6\",\"option_2\":\"5\",\"option_3\":\"8\",\"answer\":1,\"hint\":\"Compare the common digits and common words across phrases.\",\"explanation\":\"Comparing sentences: 3 = Hot, 5 = Day. In \\\"356\\\" = \\\"Very Hot Day\\\", the remaining digit 6 represents \\\"Very\\\".\"},{\"question\":\"If \\\"DELHI\\\" is coded as \\\"EDMGJ\\\", how is \\\"MUMBAI\\\" coded in that pattern?\",\"options\":[\"NTNBZJ\",\"NTNCZJ\",\"NTNCBJ\",\"MTNBZJ\"],\"option_0\":\"NTNBZJ\",\"option_1\":\"NTNCZJ\",\"option_2\":\"NTNCBJ\",\"option_3\":\"MTNBZJ\",\"answer\":0,\"hint\":\"Alternating +1 and -1 shift pattern on each letter.\",\"explanation\":\"M+1=N, U-1=T, M+1=N, B-1=A\\/Z, A+1=B, I+1=J -> NTNBZJ.\"},{\"question\":\"If \\\"KTM\\\" is written as \\\"JSL\\\", how is \\\"POK\\\" written in that code?\",\"options\":[\"ONJ\",\"QPL\",\"OMJ\",\"PPL\"],\"option_0\":\"ONJ\",\"option_1\":\"QPL\",\"option_2\":\"OMJ\",\"option_3\":\"PPL\",\"answer\":0,\"hint\":\"Subtract 1 position (-1) from each letter.\",\"explanation\":\"P-1=O, O-1=N, K-1=J -> ONJ.\"},{\"question\":\"If \\\"NEPAL\\\" is coded in reverse as \\\"LAPEN\\\", how is \\\"KHARIDAR\\\" coded in the same system?\",\"options\":[\"RADIRAHK\",\"RADIRAKH\",\"RADAIRHK\",\"RADIRAHM\"],\"option_0\":\"RADIRAHK\",\"option_1\":\"RADIRAKH\",\"option_2\":\"RADAIRHK\",\"option_3\":\"RADIRAHM\",\"answer\":0,\"hint\":\"Spell the word backwards from right to left.\",\"explanation\":\"Reversing K-H-A-R-I-D-A-R yields R-A-D-I-R-A-H-K.\"}]', 'text', 5, 15, 1, '2026-09-01 03:59:07', '2026-09-02 12:19:39'),
(76, 2, NULL, 'Office Management', 'office-management', 'Focus on Office Management', NULL, 'lessons/pdfs/Office Management Kharidar.pdf', '[{\"question\":\"What is the primary purpose of the Registration (Darta) ledger in public offices?\",\"options\":[\"To prepare annual employee salary payroll\",\"To systematically record incoming official letters and documents entering the office\",\"To record outgoing letters dispatched to other agencies\",\"To record daily staff attendance\"],\"option_0\":\"To prepare annual employee salary payroll\",\"option_1\":\"To systematically record incoming official letters and documents entering the office\",\"option_2\":\"To record outgoing letters dispatched to other agencies\",\"option_3\":\"To record daily staff attendance\",\"answer\":1,\"hint\":\"The initial registration ledger where all incoming official correspondence is logged.\",\"explanation\":\"Darta is the official ledger used to systematically record all incoming letters, notices, and documents received by an office.\"},{\"question\":\"What is the Dispatch (Chalani) book used for in public office administration?\",\"options\":[\"Recording incoming letters from citizens\",\"Systematically recording and dispatching outgoing official correspondence to external agencies\",\"Calculating staff pension benefits\",\"Storing obsolete records in archive\"],\"option_0\":\"Recording incoming letters from citizens\",\"option_1\":\"Systematically recording and dispatching outgoing official correspondence to external agencies\",\"option_2\":\"Calculating staff pension benefits\",\"option_3\":\"Storing obsolete records in archive\",\"answer\":1,\"hint\":\"Assigns unique dispatch numbers and date to letters sent out from the office.\",\"explanation\":\"Chalani is the register where all outgoing letters, circulars, and orders sent from the office are numbered and documented.\"},{\"question\":\"What does an Administrative Note \\/ Minute (Tippani) represent in government decision-making in Nepal?\",\"options\":[\"A casual informal comment\",\"A structured administrative file note presenting facts, legal provisions, and recommendations for higher approval\",\"An annual auditing ledger\",\"A commercial purchase order invoice\"],\"option_0\":\"A casual informal comment\",\"option_1\":\"A structured administrative file note presenting facts, legal provisions, and recommendations for higher approval\",\"option_2\":\"An annual auditing ledger\",\"option_3\":\"A commercial purchase order invoice\",\"answer\":1,\"hint\":\"The formal written channel through which official policy and executive decisions are routed upwards for hierarchical approval.\",\"explanation\":\"Tippani is an administrative memo prepared on a case file that details background, rules, precedents, and proposed decisions for authorized sanction.\"},{\"question\":\"Which filing system arranges documents based on geographic locations such as Provinces, Districts, and Municipalities?\",\"options\":[\"Alphabetical Filing\",\"Geographical Filing\",\"Chronological Filing\",\"Numerical Filing\"],\"option_0\":\"Alphabetical Filing\",\"option_1\":\"Geographical Filing\",\"option_2\":\"Chronological Filing\",\"option_3\":\"Numerical Filing\",\"answer\":1,\"hint\":\"Organizes files by territory or administrative regions.\",\"explanation\":\"Geographical filing groups and stores records according to territorial jurisdictions, regions, or branch locations.\"},{\"question\":\"In public administration, what is a Citizen Charter?\",\"options\":[\"A political party election manifesto\",\"A public declaration displayed at government offices stating services offered, required documents, timeframe, fees, and grievance redressal officers\",\"A tax assessment booklet\",\"An internal employee disciplinary manual\"],\"option_0\":\"A political party election manifesto\",\"option_1\":\"A public declaration displayed at government offices stating services offered, required documents, timeframe, fees, and grievance redressal officers\",\"option_2\":\"A tax assessment booklet\",\"option_3\":\"An internal employee disciplinary manual\",\"answer\":1,\"hint\":\"Guarantees service delivery standards and public accountability to service seekers.\",\"explanation\":\"A Citizen Charter is a visible institutional commitment outlining the nature of services, turnaround times, fees, officer in charge, and compensation procedures.\"},{\"question\":\"Under Nepal Good Governance Act 2064, within what timeframe must a public body deliver administrative services when all documents are complete?\",\"options\":[\"Immediately or within the timeframe specified in the Citizen Charter\",\"Within 6 months\",\"Whenever staff are free\",\"Within 1 year\"],\"option_0\":\"Immediately or within the timeframe specified in the Citizen Charter\",\"option_1\":\"Within 6 months\",\"option_2\":\"Whenever staff are free\",\"option_3\":\"Within 1 year\",\"answer\":0,\"hint\":\"Services must be delivered promptly without causing unnecessary delays to citizens.\",\"explanation\":\"Section 16 of the Good Governance Act 2064 mandates that every public agency must provide services immediately or strictly within the timeline published in its Citizen Charter.\"},{\"question\":\"What is the purpose of Record Management \\/ Archiving in public offices?\",\"options\":[\"Destroying all old files immediately\",\"Systematically classifying, preserving valuable records, and disposing of obsolete files per statutory rules\",\"Restricting information from public access permanently\",\"Increasing office paperwork costs\"],\"option_0\":\"Destroying all old files immediately\",\"option_1\":\"Systematically classifying, preserving valuable records, and disposing of obsolete files per statutory rules\",\"option_2\":\"Restricting information from public access permanently\",\"option_3\":\"Increasing office paperwork costs\",\"answer\":1,\"hint\":\"Governed by the Record Preservation and Disposal Rules in Nepal.\",\"explanation\":\"Record management ensures systematic retention of historical, legal, and operational documents while safely disposing of time-expired records.\"},{\"question\":\"What is a Circular (Paripatra) in administrative correspondence?\",\"options\":[\"A personal letter to a friend\",\"A single official directive or notice sent simultaneously to multiple subordinate offices for uniform implementation\",\"A personal leave application\",\"A tender invitation notice published in a newspaper\"],\"option_0\":\"A personal letter to a friend\",\"option_1\":\"A single official directive or notice sent simultaneously to multiple subordinate offices for uniform implementation\",\"option_2\":\"A personal leave application\",\"option_3\":\"A tender invitation notice published in a newspaper\",\"answer\":1,\"hint\":\"Sent from higher headquarters to all branch or field offices.\",\"explanation\":\"A circular (Paripatra) is an official communication addressing multiple subordinates or departments regarding administrative directives or operational rules.\"},{\"question\":\"What is the primary role of the Information Officer appointed in every public agency under the Right to Information Act 2064?\",\"options\":[\"Drafting annual financial budgets\",\"Receiving citizen RTI requests, collecting information from departments, and disseminating it within statutory deadlines\",\"Handling court litigation only\",\"Inspecting physical office furniture\"],\"option_0\":\"Drafting annual financial budgets\",\"option_1\":\"Receiving citizen RTI requests, collecting information from departments, and disseminating it within statutory deadlines\",\"option_2\":\"Handling court litigation only\",\"option_3\":\"Inspecting physical office furniture\",\"answer\":1,\"hint\":\"Mandated by Section 6 of the RTI Act 2064 to uphold institutional transparency.\",\"explanation\":\"The Information Officer is the statutory liaison responsible for processing public information requests and proactively disclosing public agency data.\"},{\"question\":\"Which of the following is considered an essential element of modern electronic office management (e-Office)?\",\"options\":[\"Complete reliance on manual paper registers\",\"Paperless digital workflows, electronic signatures, automated file routing, and biometric attendance\",\"Eliminating internet connectivity\",\"Restricting computer access to senior executives only\"],\"option_0\":\"Complete reliance on manual paper registers\",\"option_1\":\"Paperless digital workflows, electronic signatures, automated file routing, and biometric attendance\",\"option_2\":\"Eliminating internet connectivity\",\"option_3\":\"Restricting computer access to senior executives only\",\"answer\":1,\"hint\":\"Improves administrative speed, transparency, and traceability.\",\"explanation\":\"Digital office systems (e-Office) streamline government processes through electronic document handling, computerized dispatch, and audit trails.\"}]', 'text', 1, 15, 1, '2026-09-01 04:22:03', '2026-09-02 12:19:39'),
(131, 58, NULL, 'Geography of Nepal', 'nasu-geography-of-nepal', 'Focus on Nepal Geography, ecological zones, borders, rivers, lakes, passes, and national parks.', NULL, 'lessons/pdfs/Geography of Nepal_compressed.pdf', '[{\"question\":\"Which is the highest mountain peak in the world located in Nepal?\",\"options\":[\"Mount K2\",\"Mount Everest\",\"Kangchenjunga\",\"Lhotse\"],\"option_0\":\"Mount K2\",\"option_1\":\"Mount Everest\",\"option_2\":\"Kangchenjunga\",\"option_3\":\"Lhotse\",\"answer\":1,\"hint\":\"Known locally as Sagarmatha and in Tibetan as Chomolungma.\",\"explanation\":\"Mount Everest (Sagarmatha) is the highest peak in the world at 8848.86 meters, situated in the Mahalangur range of Solukhumbu district.\"},{\"question\":\"Which river of Nepal is historically known in India as the \\\"Sorrow of Bihar\\\"?\",\"options\":[\"Gandaki River\",\"Karnali River\",\"Koshi River\",\"Mahakali River\"],\"option_0\":\"Gandaki River\",\"option_1\":\"Karnali River\",\"option_2\":\"Koshi River\",\"option_3\":\"Mahakali River\",\"answer\":2,\"hint\":\"It frequently changes its course and causes severe monsoon flooding in northern Bihar, India.\",\"explanation\":\"The Koshi River is known as the \\\"Sorrow of Bihar\\\" because of annual catastrophic flooding and silt deposition caused by shifts in its meandering channel.\"},{\"question\":\"What is the longest river in Nepal within Nepalese territorial borders?\",\"options\":[\"Koshi River\",\"Gandaki River\",\"Karnali River\",\"Trishuli River\"],\"option_0\":\"Koshi River\",\"option_1\":\"Gandaki River\",\"option_2\":\"Karnali River\",\"option_3\":\"Trishuli River\",\"answer\":2,\"hint\":\"Originates from the Mansarovar basin in Tibet and measures 507 km within Nepal.\",\"explanation\":\"Karnali is the longest river in Nepal, measuring 507 km within Nepalese territory before flowing into India as the Ghaghara.\"},{\"question\":\"Which is the deepest river in Nepal with the highest water discharge capacity?\",\"options\":[\"Karnali River\",\"Gandaki River\",\"Koshi River\",\"Bheri River\"],\"option_0\":\"Karnali River\",\"option_1\":\"Gandaki River\",\"option_2\":\"Koshi River\",\"option_3\":\"Bheri River\",\"answer\":1,\"hint\":\"Formed by seven major tributaries including Kali Gandaki, Trishuli, and Marsyangdi.\",\"explanation\":\"Gandaki (Narayani) is the deepest river in Nepal with deep gorges carved by the Kali Gandaki between Annapurna and Dhaulagiri.\"},{\"question\":\"Which is the largest lake in Nepal by surface area?\",\"options\":[\"Shey Phoksundo Lake\",\"Fewa Lake\",\"Rara Lake\",\"Tilicho Lake\"],\"option_0\":\"Shey Phoksundo Lake\",\"option_1\":\"Fewa Lake\",\"option_2\":\"Rara Lake\",\"option_3\":\"Tilicho Lake\",\"answer\":2,\"hint\":\"Located in Mugu District at an altitude of 2,990 meters, praised as the Queen of Lakes.\",\"explanation\":\"Rara Lake in Mugu district is the largest freshwater lake in Nepal with a surface area of 10.8 sq km.\"},{\"question\":\"Which is the deepest lake in Nepal?\",\"options\":[\"Rara Lake\",\"Shey Phoksundo Lake\",\"Gosaikunda Lake\",\"Begnas Lake\"],\"option_0\":\"Rara Lake\",\"option_1\":\"Shey Phoksundo Lake\",\"option_2\":\"Gosaikunda Lake\",\"option_3\":\"Begnas Lake\",\"answer\":1,\"hint\":\"An oligotrophic alpine lake situated in Dolpa district at 3,611 m altitude, famous for its turquoise blue water.\",\"explanation\":\"Shey Phoksundo Lake in Dolpa is the deepest lake in Nepal with a maximum depth of approximately 145 meters.\"},{\"question\":\"Nepal Standard Time is determined based on which meridian passing through Gaurishankar Himal?\",\"options\":[\"80 degrees 15 minutes East Longitude\",\"84 degrees 00 minutes East Longitude\",\"86 degrees 15 minutes East Longitude\",\"88 degrees 00 minutes East Longitude\"],\"option_0\":\"80 degrees 15 minutes East Longitude\",\"option_1\":\"84 degrees 00 minutes East Longitude\",\"option_2\":\"86 degrees 15 minutes East Longitude\",\"option_3\":\"88 degrees 00 minutes East Longitude\",\"answer\":2,\"hint\":\"Introduced on Baisakh 1, 2042 BS, making Nepal 5 hours and 45 minutes ahead of GMT.\",\"explanation\":\"Nepal Standard Time is based on the 86\\u00b015\' East longitude meridian intersecting Mount Gaurishankar (7,134 m), exactly GMT +5:45.\"},{\"question\":\"Which district of Nepal is known as the district across the Himalayas receiving the lowest average annual rainfall?\",\"options\":[\"Mustang\",\"Solukhumbu\",\"Sindhupalchok\",\"Ramechhap\"],\"option_0\":\"Mustang\",\"option_1\":\"Solukhumbu\",\"option_2\":\"Sindhupalchok\",\"option_3\":\"Ramechhap\",\"answer\":0,\"hint\":\"Lies in the rain-shadow area north of the Annapurna and Dhaulagiri mountain ranges.\",\"explanation\":\"Mustang lies in the trans-Himalayan rain-shadow zone and receives the lowest annual rainfall in Nepal (approx. <250 mm\\/year).\"},{\"question\":\"Which place in Nepal records the highest average annual rainfall?\",\"options\":[\"Dhangadhi\",\"Lumle\",\"Biratnagar\",\"Janakpur\"],\"option_0\":\"Dhangadhi\",\"option_1\":\"Lumle\",\"option_2\":\"Biratnagar\",\"option_3\":\"Janakpur\",\"answer\":1,\"hint\":\"Located near Pokhara valley south of the Annapurna mountain barrier.\",\"explanation\":\"Lumle in Kaski district receives the highest annual rainfall in Nepal, often exceeding 5,000 mm annually (Cherrapunji of Nepal).\"},{\"question\":\"Which was the first National Park established in Nepal?\",\"options\":[\"Sagarmatha National Park\",\"Chitwan National Park\",\"Bardia National Park\",\"Langtang National Park\"],\"option_0\":\"Sagarmatha National Park\",\"option_1\":\"Chitwan National Park\",\"option_2\":\"Bardia National Park\",\"option_3\":\"Langtang National Park\",\"answer\":1,\"hint\":\"Famous habitat of the One-horned Rhinoceros and Royal Bengal Tiger in the inner Terai.\",\"explanation\":\"Chitwan National Park was established in 1973 AD (2030 BS) as Nepal\\u2019s first national park and designated a UNESCO World Heritage Site in 1984.\"}]', 'text', 3, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(132, 58, NULL, 'Geography of World', 'nasu-geography-of-world', 'Focus on Continents, Oceans, Great mountain ranges, Deserts, and Climate belts of the world.', NULL, 'lessons/pdfs/01M1GG34XZX29EA3AWDWHPPXXE.pdf', '[{\"question\":\"Which is the largest continent in the world by both surface area and total population?\",\"options\":[\"Africa\",\"Asia\",\"North America\",\"Europe\"],\"option_0\":\"Africa\",\"option_1\":\"Asia\",\"option_2\":\"North America\",\"option_3\":\"Europe\",\"answer\":1,\"hint\":\"Covers nearly 30% of Earth\\u2019s land area and is home to about 60% of the world\\u2019s population.\",\"explanation\":\"Asia is the largest and most populous continent, spanning over 44.5 million square kilometers.\"},{\"question\":\"Which is the longest river in the world?\",\"options\":[\"Amazon River\",\"Nile River\",\"Yangtze River\",\"Mississippi River\"],\"option_0\":\"Amazon River\",\"option_1\":\"Nile River\",\"option_2\":\"Yangtze River\",\"option_3\":\"Mississippi River\",\"answer\":1,\"hint\":\"Flows northward through eleven countries in northeastern Africa into the Mediterranean Sea.\",\"explanation\":\"The Nile River in Africa is the longest river in the world with an estimated length of 6,650 km.\"},{\"question\":\"Which is the largest and deepest ocean on Earth?\",\"options\":[\"Atlantic Ocean\",\"Pacific Ocean\",\"Indian Ocean\",\"Arctic Ocean\"],\"option_0\":\"Atlantic Ocean\",\"option_1\":\"Pacific Ocean\",\"option_2\":\"Indian Ocean\",\"option_3\":\"Arctic Ocean\",\"answer\":1,\"hint\":\"Covers more than 30% of the Earth\\u2019s surface, larger than all land masses combined.\",\"explanation\":\"The Pacific Ocean is the largest and deepest ocean basin, containing the deepest oceanic point on Earth (Mariana Trench).\"},{\"question\":\"What is the deepest trench in the world oceans located in the western Pacific Ocean?\",\"options\":[\"Java Trench\",\"Mariana Trench\",\"Puerto Rico Trench\",\"Sunda Trench\"],\"option_0\":\"Java Trench\",\"option_1\":\"Mariana Trench\",\"option_2\":\"Puerto Rico Trench\",\"option_3\":\"Sunda Trench\",\"answer\":1,\"hint\":\"Its lowest section, Challenger Deep, descends nearly 11 kilometers below sea level.\",\"explanation\":\"The Mariana Trench (Challenger Deep) is the deepest oceanic trench on Earth with a depth of approximately 11,034 meters.\"},{\"question\":\"Which is the largest hot desert in the world?\",\"options\":[\"Gobi Desert\",\"Sahara Desert\",\"Kalahari Desert\",\"Thar Desert\"],\"option_0\":\"Gobi Desert\",\"option_1\":\"Sahara Desert\",\"option_2\":\"Kalahari Desert\",\"option_3\":\"Thar Desert\",\"answer\":1,\"hint\":\"Spans over 9 million square kilometers across North Africa.\",\"explanation\":\"The Sahara Desert in North Africa is the world\\u2019s largest subtropical hot desert, covering roughly the size of the United States.\"},{\"question\":\"Which is the world largest freshwater lake by surface area?\",\"options\":[\"Lake Baikal\",\"Lake Superior\",\"Lake Victoria\",\"Caspian Sea\"],\"option_0\":\"Lake Baikal\",\"option_1\":\"Lake Superior\",\"option_2\":\"Lake Victoria\",\"option_3\":\"Caspian Sea\",\"answer\":1,\"hint\":\"One of the Great Lakes shared between the United States and Canada.\",\"explanation\":\"Lake Superior is the world\\u2019s largest freshwater lake by surface area (approx. 82,100 sq km).\"},{\"question\":\"Which is the deepest freshwater lake in the world located in Siberia, Russia?\",\"options\":[\"Lake Tanganyika\",\"Lake Baikal\",\"Lake Malawi\",\"Lake Huron\"],\"option_0\":\"Lake Tanganyika\",\"option_1\":\"Lake Baikal\",\"option_2\":\"Lake Malawi\",\"option_3\":\"Lake Huron\",\"answer\":1,\"hint\":\"Contains 20% of the world\\u2019s unfrozen surface fresh water.\",\"explanation\":\"Lake Baikal in Russia is the deepest lake in the world with a maximum depth of 1,642 meters (5,387 feet).\"},{\"question\":\"Which strait separates Asia from North America connecting the Arctic Ocean with the Bering Sea?\",\"options\":[\"Strait of Gibraltar\",\"Bering Strait\",\"Strait of Malacca\",\"Bosphorus Strait\"],\"option_0\":\"Strait of Gibraltar\",\"option_1\":\"Bering Strait\",\"option_2\":\"Strait of Malacca\",\"option_3\":\"Bosphorus Strait\",\"answer\":1,\"hint\":\"Lies between Cape Dezhnev in Russia and Cape Prince of Wales in Alaska.\",\"explanation\":\"The Bering Strait connects the Chukchi Sea (Arctic Ocean) with the Bering Sea (Pacific Ocean), separating Russia from Alaska.\"},{\"question\":\"Which is the longest continental mountain range in the world?\",\"options\":[\"Himalayas\",\"Andes Mountain Range\",\"Rocky Mountains\",\"Alps\"],\"option_0\":\"Himalayas\",\"option_1\":\"Andes Mountain Range\",\"option_2\":\"Rocky Mountains\",\"option_3\":\"Alps\",\"answer\":1,\"hint\":\"Runs along the entire western coast of South America through seven countries.\",\"explanation\":\"The Andes is the longest continental mountain range in the world, extending about 7,000 km along western South America.\"},{\"question\":\"Which country in the world is known as the Land of the Midnight Sun?\",\"options\":[\"Japan\",\"Norway\",\"Canada\",\"New Zealand\"],\"option_0\":\"Japan\",\"option_1\":\"Norway\",\"option_2\":\"Canada\",\"option_3\":\"New Zealand\",\"answer\":1,\"hint\":\"During summer months north of the Arctic Circle, the sun never sets below the horizon.\",\"explanation\":\"Norway is called the Land of the Midnight Sun because northern regions experience continuous daylight during summer.\"}]', 'text', 2, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(133, 58, NULL, 'Universe and Basics', 'nasu-universe-basics', 'Focus on the Solar System, Planets, Stars, Sun, Moon, and Astronomical phenomena.', NULL, 'lessons/pdfs/General-Information-about-Universe-Loksewa-PDF_compressed.pdf', '[{\"question\":\"Which is the closest star to the planet Earth?\",\"options\":[\"Proxima Centauri\",\"The Sun\",\"Sirius\",\"Alpha Centauri\"],\"option_0\":\"Proxima Centauri\",\"option_1\":\"The Sun\",\"option_2\":\"Sirius\",\"option_3\":\"Alpha Centauri\",\"answer\":1,\"hint\":\"The center of our Solar System located approximately 149.6 million km from Earth.\",\"explanation\":\"The Sun is the closest star to Earth; light from the Sun takes approximately 8 minutes and 20 seconds to reach Earth.\"},{\"question\":\"Which planet in the Solar System is closest to the Sun?\",\"options\":[\"Venus\",\"Mercury\",\"Mars\",\"Earth\"],\"option_0\":\"Venus\",\"option_1\":\"Mercury\",\"option_2\":\"Mars\",\"option_3\":\"Earth\",\"answer\":1,\"hint\":\"The smallest planet in the solar system with an orbital period of just 88 Earth days.\",\"explanation\":\"Mercury is the innermost and smallest planet in our Solar System, orbiting closest to the Sun.\"},{\"question\":\"Which planet is known as both the Morning Star and Evening Star and is the hottest planet in the Solar System?\",\"options\":[\"Mercury\",\"Venus\",\"Mars\",\"Jupiter\"],\"option_0\":\"Mercury\",\"option_1\":\"Venus\",\"option_2\":\"Mars\",\"option_3\":\"Jupiter\",\"answer\":1,\"hint\":\"Dense carbon dioxide atmosphere creates an extreme runaway greenhouse effect.\",\"explanation\":\"Venus is the brightest natural object in night skies after the Moon and the hottest planet (~465\\u00b0C) due to dense CO2 atmosphere.\"},{\"question\":\"Which planet in the Solar System is known as the Red Planet?\",\"options\":[\"Mercury\",\"Mars\",\"Jupiter\",\"Saturn\"],\"option_0\":\"Mercury\",\"option_1\":\"Mars\",\"option_2\":\"Jupiter\",\"option_3\":\"Saturn\",\"answer\":1,\"hint\":\"Its surface contains abundant iron oxide giving it a reddish appearance.\",\"explanation\":\"Mars is called the Red Planet because widespread iron oxide on its surface imparts a distinct reddish tint.\"},{\"question\":\"Which is the largest planet in our Solar System?\",\"options\":[\"Saturn\",\"Jupiter\",\"Neptune\",\"Uranus\"],\"option_0\":\"Saturn\",\"option_1\":\"Jupiter\",\"option_2\":\"Neptune\",\"option_3\":\"Uranus\",\"answer\":1,\"hint\":\"A gas giant with the famous Great Red Spot storm, having a mass more than double all other planets combined.\",\"explanation\":\"Jupiter is the largest planet in the Solar System with a diameter of ~142,984 km and over 90 known moons.\"},{\"question\":\"Which planet in our Solar System is famously surrounded by prominent, bright planetary rings made of ice and dust?\",\"options\":[\"Jupiter\",\"Saturn\",\"Uranus\",\"Neptune\"],\"option_0\":\"Jupiter\",\"option_1\":\"Saturn\",\"option_2\":\"Uranus\",\"option_3\":\"Neptune\",\"answer\":1,\"hint\":\"The second largest planet in the Solar System, with Titan as its largest moon.\",\"explanation\":\"Saturn is renowned for its spectacular and complex ring system composed predominantly of water ice and rocky debris.\"},{\"question\":\"What is the name of the barred spiral galaxy containing our Solar System?\",\"options\":[\"Andromeda Galaxy\",\"Milky Way Galaxy\",\"Triangulum Galaxy\",\"Whirlpool Galaxy\"],\"option_0\":\"Andromeda Galaxy\",\"option_1\":\"Milky Way Galaxy\",\"option_2\":\"Triangulum Galaxy\",\"option_3\":\"Whirlpool Galaxy\",\"answer\":1,\"hint\":\"A spiral galaxy containing 100 to 400 billion stars.\",\"explanation\":\"Our Solar System is located in the Orion Arm of the Milky Way galaxy.\"},{\"question\":\"What is the speed of light in a vacuum?\",\"options\":[\"150,000 km\\/s\",\"300,000 km\\/s\",\"500,000 km\\/s\",\"3,000 km\\/s\"],\"option_0\":\"150,000 km\\/s\",\"option_1\":\"300,000 km\\/s\",\"option_2\":\"500,000 km\\/s\",\"option_3\":\"3,000 km\\/s\",\"answer\":1,\"hint\":\"Fundamental physical constant denoted by the letter c.\",\"explanation\":\"Light travels at approximately 299,792 km\\/s (~300,000 km\\/second) in a vacuum.\"},{\"question\":\"Which celestial object was reclassified from a major planet to a Dwarf Planet by the IAU in 2006?\",\"options\":[\"Ceres\",\"Pluto\",\"Eris\",\"Makemake\"],\"option_0\":\"Ceres\",\"option_1\":\"Pluto\",\"option_2\":\"Eris\",\"option_3\":\"Makemake\",\"answer\":1,\"hint\":\"Discovered in 1930 by Clyde Tombaugh in the Kuiper Belt.\",\"explanation\":\"Pluto was reclassified as a dwarf planet by the IAU in August 2006 because it had not cleared the neighborhood around its orbit.\"},{\"question\":\"What was the world first artificial satellite launched into Earth orbit by the Soviet Union in 1957?\",\"options\":[\"Explorer 1\",\"Sputnik 1\",\"Vostok 1\",\"Apollo 11\"],\"option_0\":\"Explorer 1\",\"option_1\":\"Sputnik 1\",\"option_2\":\"Vostok 1\",\"option_3\":\"Apollo 11\",\"answer\":1,\"hint\":\"Marked the beginning of the human Space Age on October 4, 1957.\",\"explanation\":\"Sputnik 1 was the first artificial satellite placed in orbit by the USSR on 4 October 1957, initiating the global Space Race.\"}]', 'text', 1, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(134, 58, NULL, 'History of Nepal', 'nasu-history-of-nepal', 'Focus on Ancient Lichhavi dynasty, Medieval Malla period, Shah unification, and modern political milestones.', NULL, 'lessons/pdfs/HIstory of Nepal.pdf', '[{\"question\":\"Who was the first Prime Minister (Mukhtiyar) of unified Nepal?\",\"options\":[\"Jung Bahadur Rana\",\"Bhimsen Thapa\",\"Damodar Pande\",\"Ranganath Poudel\"],\"option_0\":\"Jung Bahadur Rana\",\"option_1\":\"Bhimsen Thapa\",\"option_2\":\"Damodar Pande\",\"option_3\":\"Ranganath Poudel\",\"answer\":1,\"hint\":\"Served as Mukhtiyar from 1806 to 1837 AD and built the iconic Dharahara tower.\",\"explanation\":\"Bhimsen Thapa was the first Prime Minister (Mukhtiyar) of Nepal, serving from 1806 to 1837 AD during the reigns of King Girvan Yuddha and King Rajendra.\"},{\"question\":\"Who was the first King of the ancient Kirat Dynasty in Nepal according to historical chronicles?\",\"options\":[\"King Mandev\",\"King Yalambar\",\"King Gasti\",\"King Nimish\"],\"option_0\":\"King Mandev\",\"option_1\":\"King Yalambar\",\"option_2\":\"King Gasti\",\"option_3\":\"King Nimish\",\"answer\":1,\"hint\":\"Defeated the Abhir\\/Mahispal dynasty to establish Kirati rule in the Kathmandu valley.\",\"explanation\":\"King Yalambar was the founder and first king of the Kirat dynasty in Nepal, ruling from Shankhamul\\/Gokarna.\"},{\"question\":\"Which Licchavi King issued the first historical inscribed copper coins (Manaank) in Nepal?\",\"options\":[\"King Amshuverma\",\"King Mandev I\",\"King Gunakamadev\",\"King Shivadev\"],\"option_0\":\"King Amshuverma\",\"option_1\":\"King Mandev I\",\"option_2\":\"King Gunakamadev\",\"option_3\":\"King Shivadev\",\"answer\":1,\"hint\":\"Installed the earliest dated stone pillar inscription at Changu Narayan temple in 464 AD.\",\"explanation\":\"King Mandev I (464-505 AD) is the first authenticated historical king of Nepal who minted Manaank coins and erected the Changu Narayan inscription.\"},{\"question\":\"The Sugauli Treaty between Nepal and the British East India Company was ratified in which year?\",\"options\":[\"1814 AD\",\"1816 AD\",\"1846 AD\",\"1857 AD\"],\"option_0\":\"1814 AD\",\"option_1\":\"1816 AD\",\"option_2\":\"1846 AD\",\"option_3\":\"1857 AD\",\"answer\":1,\"hint\":\"Concluded the Anglo-Nepalese War (1814\\u20131816) fixing the Mechi and Mahakali boundary rivers.\",\"explanation\":\"The Sugauli Treaty was signed in December 1815 and officially ratified on 4 March 1816, establishing the modern borders of Nepal.\"},{\"question\":\"The 104-year Rana autocratic rule in Nepal began following which historical massacre in Kathmandu?\",\"options\":[\"Bhandarkhal Massacre\",\"Kot Massacre\",\"Alau Massacre\",\"38 Saal Massacre\"],\"option_0\":\"Bhandarkhal Massacre\",\"option_1\":\"Kot Massacre\",\"option_2\":\"Alau Massacre\",\"option_3\":\"38 Saal Massacre\",\"answer\":1,\"hint\":\"Occurred at the royal armory courtyard in Kathmandu on Ashwin 2, 1903 BS.\",\"explanation\":\"The Kot Massacre occurred on 14 September 1846 (1903 Ashwin 2 BS), eliminating major noble courtiers and elevating Jung Bahadur Rana to power.\"},{\"question\":\"Who established the first modern educational institution of Nepal, Durbar High School?\",\"options\":[\"Prithvi Narayan Shah\",\"Jung Bahadur Rana\",\"Bir Shumsher\",\"Dev Shumsher\"],\"option_0\":\"Prithvi Narayan Shah\",\"option_1\":\"Jung Bahadur Rana\",\"option_2\":\"Bir Shumsher\",\"option_3\":\"Dev Shumsher\",\"answer\":1,\"hint\":\"Established in 1910 BS following his historic diplomatic tour to Great Britain and France.\",\"explanation\":\"Jung Bahadur Rana founded Durbar High School inside the royal palace in 1910 BS (1853 AD) upon returning from Europe.\"},{\"question\":\"Which King of Gorkha initiated the Great Unification Campaign of Nepal?\",\"options\":[\"King Dravya Shah\",\"King Prithvi Narayan Shah\",\"King Pratap Singh Shah\",\"King Bahadur Shah\"],\"option_0\":\"King Dravya Shah\",\"option_1\":\"King Prithvi Narayan Shah\",\"option_2\":\"King Pratap Singh Shah\",\"option_3\":\"King Bahadur Shah\",\"answer\":1,\"hint\":\"Conquered Nuwakot in 1801 BS and later unified Kathmandu, Patan, and Bhaktapur into a single nation.\",\"explanation\":\"King Prithvi Narayan Shah of Gorkha began the unification of Nepal by annexing Nuwakot in 1744 AD and establishing Kathmandu as the capital in 1769 AD.\"},{\"question\":\"On which historic date was the Rana regime overthrown and Democracy declared in Nepal?\",\"options\":[\"Falgun 7, 2007 BS\",\"Chaitra 1, 2015 BS\",\"Chaitra 26, 2046 BS\",\"Jestha 15, 2065 BS\"],\"option_0\":\"Falgun 7, 2007 BS\",\"option_1\":\"Chaitra 1, 2015 BS\",\"option_2\":\"Chaitra 26, 2046 BS\",\"option_3\":\"Jestha 15, 2065 BS\",\"answer\":0,\"hint\":\"King Tribhuvan announced the end of Rana rule over state radio; celebrated as National Democracy Day.\",\"explanation\":\"Democracy was declared in Nepal on 7th Falgun 2007 BS (18 February 1951) by King Tribhuvan after the successful tripartite revolution.\"},{\"question\":\"Who was the first elected Prime Minister of Nepal following the general election of 2015 BS?\",\"options\":[\"Matrika Prasad Koirala\",\"Bishweshwar Prasad Koirala\",\"Tanka Prasad Acharya\",\"Kirti Nidhi Bista\"],\"option_0\":\"Matrika Prasad Koirala\",\"option_1\":\"Bishweshwar Prasad Koirala\",\"option_2\":\"Tanka Prasad Acharya\",\"option_3\":\"Kirti Nidhi Bista\",\"answer\":1,\"hint\":\"Leader of the Nepali Congress party that won a two-thirds majority in 2015 BS.\",\"explanation\":\"B.P. Koirala became the first democratically elected Prime Minister of Nepal on 13 Jestha 2016 BS (1959 AD).\"},{\"question\":\"The Constitution of Nepal currently in force was promulgated by the Constituent Assembly on which date?\",\"options\":[\"Mangsir 4, 2070 BS\",\"Ashwin 3, 2072 BS\",\"Magh 1, 2074 BS\",\"Jestha 15, 2065 BS\"],\"option_0\":\"Mangsir 4, 2070 BS\",\"option_1\":\"Ashwin 3, 2072 BS\",\"option_2\":\"Magh 1, 2074 BS\",\"option_3\":\"Jestha 15, 2065 BS\",\"answer\":1,\"hint\":\"Celebrated annually across Nepal as National Constitution Day.\",\"explanation\":\"The historic federal democratic Constitution of Nepal was promulgated by the second Constituent Assembly on 3rd Ashwin 2072 BS (20 September 2015).\"}]', 'text', 5, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(135, 58, NULL, 'History of World', 'nasu-history-of-world', 'Focus on Ancient Civilizations, Industrial Revolution, French Revolution, First & Second World Wars, and the United Nations.', NULL, 'lessons/pdfs/History-of-World-GK-PDF-Notes_compressed.pdf', '[{\"question\":\"The French Revolution began in which year with the storming of the Bastille prison?\",\"options\":[\"1776 AD\",\"1789 AD\",\"1804 AD\",\"1815 AD\"],\"option_0\":\"1776 AD\",\"option_1\":\"1789 AD\",\"option_2\":\"1804 AD\",\"option_3\":\"1815 AD\",\"answer\":1,\"hint\":\"Adopted the famous motto: Liberty, Equality, Fraternity.\",\"explanation\":\"The French Revolution commenced on 14 July 1789 with the storming of the Bastille in Paris, overturning absolute feudal monarchy.\"},{\"question\":\"In which country did the Industrial Revolution first begin in the mid-18th century?\",\"options\":[\"France\",\"Great Britain\",\"Germany\",\"United States\"],\"option_0\":\"France\",\"option_1\":\"Great Britain\",\"option_2\":\"Germany\",\"option_3\":\"United States\",\"answer\":1,\"hint\":\"Pioneered through mechanized textile manufacturing, steam engines, and coal mining.\",\"explanation\":\"The Industrial Revolution originated in Great Britain around 1760 due to inventions like James Watt\\u2019s steam engine and access to capital and coal.\"},{\"question\":\"The American Declaration of Independence from British rule was officially adopted on which date?\",\"options\":[\"July 4, 1776 AD\",\"August 15, 1783 AD\",\"January 1, 1789 AD\",\"December 25, 1775 AD\"],\"option_0\":\"July 4, 1776 AD\",\"option_1\":\"August 15, 1783 AD\",\"option_2\":\"January 1, 1789 AD\",\"option_3\":\"December 25, 1775 AD\",\"answer\":0,\"hint\":\"Drafted by Thomas Jefferson and signed in Philadelphia; celebrated as US Independence Day.\",\"explanation\":\"The 13 American colonies declared independence from Great Britain on July 4, 1776 in Philadelphia.\"},{\"question\":\"What was the duration of the First World War?\",\"options\":[\"1912 to 1916 AD\",\"1914 to 1918 AD\",\"1939 to 1945 AD\",\"1905 to 1911 AD\"],\"option_0\":\"1912 to 1916 AD\",\"option_1\":\"1914 to 1918 AD\",\"option_2\":\"1939 to 1945 AD\",\"option_3\":\"1905 to 1911 AD\",\"answer\":1,\"hint\":\"Triggered by the assassination of Archduke Franz Ferdinand of Austria in Sarajevo in June 1914.\",\"explanation\":\"World War I lasted from 28 July 1914 to 11 November 1918, ending with the signing of the Treaty of Versailles in 1919.\"},{\"question\":\"World War II began in September 1939 with Germany invasion of which country?\",\"options\":[\"France\",\"Poland\",\"Soviet Union\",\"Austria\"],\"option_0\":\"France\",\"option_1\":\"Poland\",\"option_2\":\"Soviet Union\",\"option_3\":\"Austria\",\"answer\":1,\"hint\":\"Led Great Britain and France to declare war on Nazi Germany two days later.\",\"explanation\":\"World War II commenced on September 1, 1939 when Adolf Hitler\\u2019s Nazi Germany launched a blitzkrieg invasion of Poland.\"},{\"question\":\"The Russian Bolshevik Revolution in 1917 was led by which revolutionary leader?\",\"options\":[\"Joseph Stalin\",\"Vladimir Lenin\",\"Leon Trotsky\",\"Karl Marx\"],\"option_0\":\"Joseph Stalin\",\"option_1\":\"Vladimir Lenin\",\"option_2\":\"Leon Trotsky\",\"option_3\":\"Karl Marx\",\"answer\":1,\"hint\":\"Overthrew Tsar Nicholas II and the provisional government to establish the Soviet Union.\",\"explanation\":\"Vladimir Lenin led the Bolsheviks during the October Revolution in November 1917, establishing the world\\u2019s first socialist state.\"},{\"question\":\"On which two Japanese cities did the United States drop atomic bombs in August 1945?\",\"options\":[\"Tokyo and Kyoto\",\"Hiroshima and Nagasaki\",\"Osaka and Yokohama\",\"Sapporo and Kobe\"],\"option_0\":\"Tokyo and Kyoto\",\"option_1\":\"Hiroshima and Nagasaki\",\"option_2\":\"Osaka and Yokohama\",\"option_3\":\"Sapporo and Kobe\",\"answer\":1,\"hint\":\"Little Boy was dropped on August 6 and Fat Man on August 9, 1945.\",\"explanation\":\"The US detonated atomic bombs over Hiroshima on 6 August 1945 and Nagasaki on 9 August 1945, leading to Japan\\u2019s surrender.\"},{\"question\":\"In which year was the United Nations officially founded in San Francisco?\",\"options\":[\"1919 AD\",\"1945 AD\",\"1948 AD\",\"1955 AD\"],\"option_0\":\"1919 AD\",\"option_1\":\"1945 AD\",\"option_2\":\"1948 AD\",\"option_3\":\"1955 AD\",\"answer\":1,\"hint\":\"Charter signed by 51 original member states on October 24, 1945.\",\"explanation\":\"The United Nations was officially established on 24 October 1945 when the UN Charter was ratified by the permanent Security Council members and majority signatories.\"},{\"question\":\"The historic fall of the Berlin Wall occurred in which year?\",\"options\":[\"1985 AD\",\"1989 AD\",\"1991 AD\",\"1995 AD\"],\"option_0\":\"1985 AD\",\"option_1\":\"1989 AD\",\"option_2\":\"1991 AD\",\"option_3\":\"1995 AD\",\"answer\":1,\"hint\":\"Paved the way for German reunification in 1990 and the dissolution of the Soviet Union.\",\"explanation\":\"The Berlin Wall fell on 9 November 1989, uniting East and West Germany and marking the symbolic end of the Cold War.\"},{\"question\":\"The Magna Carta, the foundational charter limiting royal power and establishing rule of law, was signed in England in:\",\"options\":[\"1066 AD\",\"1215 AD\",\"1492 AD\",\"1688 AD\"],\"option_0\":\"1066 AD\",\"option_1\":\"1215 AD\",\"option_2\":\"1492 AD\",\"option_3\":\"1688 AD\",\"answer\":1,\"hint\":\"Granted by King John of England at Runnymede.\",\"explanation\":\"King John of England granted the Magna Carta on 15 June 1215, establishing the legal principle that everyone, including the monarch, is subject to the law.\"}]', 'text', 4, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:39'),
(136, 59, NULL, 'Verbal Reasoning', 'nasu-gmat-verbal-reasoning', 'Focus on Verbal & Semantic Analogies, finding exact conceptual, functional, and relational similarities.', NULL, 'lessons/pdfs/01M1GH7TVYCSV16WJZXKJTD51J.pdf', '[{\"question\":\"Kathmandu : Nepal :: New Delhi : ?\",\"options\":[\"China\",\"India\",\"Pakistan\",\"Bangladesh\"],\"option_0\":\"China\",\"option_1\":\"India\",\"option_2\":\"Pakistan\",\"option_3\":\"Bangladesh\",\"answer\":1,\"hint\":\"Relationship is Capital City to Country.\",\"explanation\":\"Kathmandu is the capital of Nepal; New Delhi is the capital of India.\"},{\"question\":\"Mount Everest : Nepal :: Mount Kilimanjaro : ?\",\"options\":[\"Kenya\",\"Tanzania\",\"Egypt\",\"South Africa\"],\"option_0\":\"Kenya\",\"option_1\":\"Tanzania\",\"option_2\":\"Egypt\",\"option_3\":\"South Africa\",\"answer\":1,\"hint\":\"Highest peak of Africa located in this East African country.\",\"explanation\":\"Mount Everest is the highest mountain in Nepal; Mount Kilimanjaro is the highest peak in Tanzania (Africa).\"},{\"question\":\"Thermometer : Temperature :: Barometer : ?\",\"options\":[\"Humidity\",\"Atmospheric Pressure\",\"Wind Velocity\",\"Earthquake Intensity\"],\"option_0\":\"Humidity\",\"option_1\":\"Atmospheric Pressure\",\"option_2\":\"Wind Velocity\",\"option_3\":\"Earthquake Intensity\",\"answer\":1,\"hint\":\"Instrument to measuring quantity relationship.\",\"explanation\":\"A thermometer measures temperature; a barometer measures atmospheric pressure.\"},{\"question\":\"Doctor : Hospital :: Teacher : ?\",\"options\":[\"Court\",\"School\",\"Laboratory\",\"Library\"],\"option_0\":\"Court\",\"option_1\":\"School\",\"option_2\":\"Laboratory\",\"option_3\":\"Library\",\"answer\":1,\"hint\":\"Professional to workplace relationship.\",\"explanation\":\"A doctor works in a hospital; a teacher works in a school.\"},{\"question\":\"Heart : Cardiology :: Brain : ?\",\"options\":[\"Dermatology\",\"Neurology\",\"Nephrology\",\"Oncology\"],\"option_0\":\"Dermatology\",\"option_1\":\"Neurology\",\"option_2\":\"Nephrology\",\"option_3\":\"Oncology\",\"answer\":1,\"hint\":\"Organ to medical specialization relationship.\",\"explanation\":\"Cardiology is the study of the heart; neurology is the study of the brain and nervous system.\"},{\"question\":\"Book : Author :: Statue : ?\",\"options\":[\"Painter\",\"Sculptor\",\"Architect\",\"Mason\"],\"option_0\":\"Painter\",\"option_1\":\"Sculptor\",\"option_2\":\"Architect\",\"option_3\":\"Mason\",\"answer\":1,\"hint\":\"Creation to creator relationship.\",\"explanation\":\"An author writes a book; a sculptor carves a statue.\"},{\"question\":\"Pen : Writer :: Scalpel : ?\",\"options\":[\"Carpenter\",\"Surgeon\",\"Tailor\",\"Sculptor\"],\"option_0\":\"Carpenter\",\"option_1\":\"Surgeon\",\"option_2\":\"Tailor\",\"option_3\":\"Sculptor\",\"answer\":1,\"hint\":\"Tool to professional relationship.\",\"explanation\":\"A pen is the working tool of a writer; a scalpel is the surgical tool of a surgeon.\"},{\"question\":\"Nepal : Rupee :: Japan : ?\",\"options\":[\"Dollar\",\"Yen\",\"Won\",\"Yuan\"],\"option_0\":\"Dollar\",\"option_1\":\"Yen\",\"option_2\":\"Won\",\"option_3\":\"Yuan\",\"answer\":1,\"hint\":\"Country to official currency relationship.\",\"explanation\":\"Rupee is the currency of Nepal; Yen is the official currency of Japan.\"},{\"question\":\"Fish : Gills :: Human : ?\",\"options\":[\"Skin\",\"Lungs\",\"Heart\",\"Trachea\"],\"option_0\":\"Skin\",\"option_1\":\"Lungs\",\"option_2\":\"Heart\",\"option_3\":\"Trachea\",\"answer\":1,\"hint\":\"Organism to primary respiratory organ relationship.\",\"explanation\":\"Fish breathe through gills; human beings breathe using lungs.\"},{\"question\":\"Ornithology : Birds :: Entomology : ?\",\"options\":[\"Fossils\",\"Insects\",\"Plants\",\"Fungi\"],\"option_0\":\"Fossils\",\"option_1\":\"Insects\",\"option_2\":\"Plants\",\"option_3\":\"Fungi\",\"answer\":1,\"hint\":\"Branch of zoology to organism studied.\",\"explanation\":\"Ornithology is the scientific study of birds; entomology is the scientific study of insects.\"}]', 'text', 1, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:39');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(137, 59, NULL, 'Quantitative Reasoning', 'nasu-gmat-quantitative-reasoning', 'Focus on Odd-One-Out classification by identifying differing semantic, mathematical, and spatial properties.', NULL, 'lessons/pdfs/01M1GHP33S7KX41B7EZ2GN1DMK.pdf', '[{\"question\":\"Find the next number in the series: 2, 4, 8, 16, 32, ?\",\"options\":[\"48\",\"64\",\"56\",\"72\"],\"option_0\":\"48\",\"option_1\":\"64\",\"option_2\":\"56\",\"option_3\":\"72\",\"answer\":1,\"hint\":\"Each number is multiplied by 2.\",\"explanation\":\"Pattern: 2x2=4, 4x2=8, 8x2=16, 16x2=32, 32x2 = 64.\"},{\"question\":\"Find the next term in the series: 3, 6, 11, 18, 27, ?\",\"options\":[\"36\",\"38\",\"40\",\"42\"],\"option_0\":\"36\",\"option_1\":\"38\",\"option_2\":\"40\",\"option_3\":\"42\",\"answer\":1,\"hint\":\"Differences are successive odd numbers: +3, +5, +7, +9, +11.\",\"explanation\":\"Differences: 6-3=3, 11-6=5, 18-11=7, 27-18=9. Next difference is +11: 27 + 11 = 38.\"},{\"question\":\"Find the missing number in the Fibonacci sequence: 1, 1, 2, 3, 5, 8, 13, ?\",\"options\":[\"18\",\"21\",\"24\",\"26\"],\"option_0\":\"18\",\"option_1\":\"21\",\"option_2\":\"24\",\"option_3\":\"26\",\"answer\":1,\"hint\":\"Each term is the sum of the two preceding terms.\",\"explanation\":\"Fibonacci sequence: 1+1=2, 1+2=3, 2+3=5, 3+5=8, 5+8=13, 8+13 = 21.\"},{\"question\":\"Find the next number in the series: 1, 4, 9, 16, 25, 36, ?\",\"options\":[\"45\",\"49\",\"54\",\"64\"],\"option_0\":\"45\",\"option_1\":\"49\",\"option_2\":\"54\",\"option_3\":\"64\",\"answer\":1,\"hint\":\"Perfect squares of natural numbers: 1\\u00b2, 2\\u00b2, 3\\u00b2, 4\\u00b2, 5\\u00b2, 6\\u00b2, 7\\u00b2.\",\"explanation\":\"Series of squares: 1\\u00b2=1, 2\\u00b2=4, 3\\u00b2=9, 4\\u00b2=16, 5\\u00b2=25, 6\\u00b2=36, 7\\u00b2 = 49.\"},{\"question\":\"Find the next term in the series: 1, 8, 27, 64, 125, ?\",\"options\":[\"196\",\"216\",\"225\",\"343\"],\"option_0\":\"196\",\"option_1\":\"216\",\"option_2\":\"225\",\"option_3\":\"343\",\"answer\":1,\"hint\":\"Series of cubes: 1\\u00b3, 2\\u00b3, 3\\u00b3, 4\\u00b3, 5\\u00b3, 6\\u00b3.\",\"explanation\":\"1\\u00b3=1, 2\\u00b3=8, 3\\u00b3=27, 4\\u00b3=64, 5\\u00b3=125, 6\\u00b3 = 216.\"},{\"question\":\"Find the missing number: 100, 95, 85, 70, 50, ?\",\"options\":[\"30\",\"25\",\"20\",\"35\"],\"option_0\":\"30\",\"option_1\":\"25\",\"option_2\":\"20\",\"option_3\":\"35\",\"answer\":1,\"hint\":\"Subtracting consecutive multiples of 5: -5, -10, -15, -20, -25.\",\"explanation\":\"100-5=95, 95-10=85, 85-15=70, 70-20=50, 50-25 = 25.\"},{\"question\":\"Find the next number in the alternating series: 2, 3, 5, 6, 8, 9, 11, ?\",\"options\":[\"13\",\"12\",\"14\",\"15\"],\"option_0\":\"13\",\"option_1\":\"12\",\"option_2\":\"14\",\"option_3\":\"15\",\"answer\":1,\"hint\":\"Pattern alternates: +1, +2, +1, +2, +1, +2, +1.\",\"explanation\":\"2+1=3, 3+2=5, 5+1=6, 6+2=8, 8+1=9, 9+2=11, 11+1 = 12.\"},{\"question\":\"Find the missing term: 4, 9, 19, 39, 79, ?\",\"options\":[\"149\",\"159\",\"169\",\"179\"],\"option_0\":\"149\",\"option_1\":\"159\",\"option_2\":\"169\",\"option_3\":\"179\",\"answer\":1,\"hint\":\"Multiply by 2 and add 1.\",\"explanation\":\"(4x2)+1=9, (9x2)+1=19, (19x2)+1=39, (39x2)+1=79, (79x2)+1 = 159.\"},{\"question\":\"Find the next number in the series: 120, 99, 80, 63, 48, ?\",\"options\":[\"32\",\"35\",\"38\",\"40\"],\"option_0\":\"32\",\"option_1\":\"35\",\"option_2\":\"38\",\"option_3\":\"40\",\"answer\":1,\"hint\":\"Pattern: 11\\u00b2-1, 10\\u00b2-1, 9\\u00b2-1, 8\\u00b2-1, 7\\u00b2-1, 6\\u00b2-1.\",\"explanation\":\"11\\u00b2-1=120, 10\\u00b2-1=99, 9\\u00b2-1=80, 8\\u00b2-1=63, 7\\u00b2-1=48, 6\\u00b2-1 = 35.\"},{\"question\":\"Find the missing number in the series: 7, 14, 28, 56, 112, ?\",\"options\":[\"214\",\"224\",\"230\",\"240\"],\"option_0\":\"214\",\"option_1\":\"224\",\"option_2\":\"230\",\"option_3\":\"240\",\"answer\":1,\"hint\":\"Doubling each number: 112 multiplied by 2.\",\"explanation\":\"7x2=14, 14x2=28, 28x2=56, 56x2=112, 112x2 = 224.\"}]', 'text', 2, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:39'),
(138, 59, NULL, 'Non-Verbal Reasoning', 'nasu-gmat-non-verbal-reasoning', 'Focus on Arithmetic progressions, geometric jumps, alternating series, and difference trees.', NULL, 'lessons/pdfs/01M1GJFVGNG2WF9T9B19TCKXZ6.pdf', '[{\"question\":\"Find the odd one out among the following geographical features:\",\"options\":[\"Mount Everest\",\"Rara Lake\",\"Kangchenjunga\",\"Annapurna\"],\"option_0\":\"Mount Everest\",\"option_1\":\"Rara Lake\",\"option_2\":\"Kangchenjunga\",\"option_3\":\"Annapurna\",\"answer\":1,\"hint\":\"Three are mountain peaks while one is a lake.\",\"explanation\":\"Mount Everest, Kangchenjunga, and Annapurna are Himalayan mountain peaks; Rara is a lake.\"},{\"question\":\"Which of the following is the odd one out among SAARC member nations?\",\"options\":[\"Nepal\",\"Myanmar\",\"Bhutan\",\"Sri Lanka\"],\"option_0\":\"Nepal\",\"option_1\":\"Myanmar\",\"option_2\":\"Bhutan\",\"option_3\":\"Sri Lanka\",\"answer\":1,\"hint\":\"Three are founding members of SAARC; one is a member of ASEAN.\",\"explanation\":\"Nepal, Bhutan, and Sri Lanka are SAARC member states; Myanmar belongs to ASEAN and is not a member of SAARC.\"},{\"question\":\"Find the odd number out in the group: 2, 3, 5, 7, 9, 11, 13\",\"options\":[\"7\",\"9\",\"11\",\"13\"],\"option_0\":\"7\",\"option_1\":\"9\",\"option_2\":\"11\",\"option_3\":\"13\",\"answer\":1,\"hint\":\"All other numbers are prime numbers except this composite number.\",\"explanation\":\"All numbers in the set are prime numbers except 9, which is a composite number divisible by 3.\"},{\"question\":\"Find the odd one out among the following cities:\",\"options\":[\"Kathmandu\",\"Sydney\",\"Tokyo\",\"London\"],\"option_0\":\"Kathmandu\",\"option_1\":\"Sydney\",\"option_2\":\"Tokyo\",\"option_3\":\"London\",\"answer\":1,\"hint\":\"Canberra is the capital of Australia, not Sydney.\",\"explanation\":\"Kathmandu, Tokyo, and London are national capitals; Sydney is a major Australian city but Canberra is the capital.\"},{\"question\":\"Which of the following organs is the odd one out?\",\"options\":[\"Eyes\",\"Stomach\",\"Ears\",\"Nose\"],\"option_0\":\"Eyes\",\"option_1\":\"Stomach\",\"option_2\":\"Ears\",\"option_3\":\"Nose\",\"answer\":1,\"hint\":\"Three are external sensory organs; one is an internal digestive organ.\",\"explanation\":\"Eyes, ears, and nose are sensory organs; the stomach is an internal digestive organ.\"},{\"question\":\"Find the odd one out among computer input and output hardware devices:\",\"options\":[\"Keyboard\",\"Printer\",\"Mouse\",\"Scanner\"],\"option_0\":\"Keyboard\",\"option_1\":\"Printer\",\"option_2\":\"Mouse\",\"option_3\":\"Scanner\",\"answer\":1,\"hint\":\"Three are input devices; one is an output device.\",\"explanation\":\"Keyboard, Mouse, and Scanner are input devices; Printer is an output peripheral.\"},{\"question\":\"Find the odd one out among objects in the Solar System:\",\"options\":[\"Earth\",\"Moon\",\"Mars\",\"Venus\"],\"option_0\":\"Earth\",\"option_1\":\"Moon\",\"option_2\":\"Mars\",\"option_3\":\"Venus\",\"answer\":1,\"hint\":\"Three are planets orbiting the Sun; one is a natural satellite orbiting Earth.\",\"explanation\":\"Earth, Mars, and Venus are planets; the Moon is a natural satellite.\"},{\"question\":\"Which unit of measurement is the odd one out?\",\"options\":[\"Kilogram\",\"Kilometer\",\"Gram\",\"Pound\"],\"option_0\":\"Kilogram\",\"option_1\":\"Kilometer\",\"option_2\":\"Gram\",\"option_3\":\"Pound\",\"answer\":1,\"hint\":\"Three measure mass\\/weight; one measures distance\\/length.\",\"explanation\":\"Kilogram, Gram, and Pound measure mass\\/weight; Kilometer measures distance.\"},{\"question\":\"Find the odd one out among the following substances:\",\"options\":[\"Iron\",\"Diamond\",\"Copper\",\"Gold\"],\"option_0\":\"Iron\",\"option_1\":\"Diamond\",\"option_2\":\"Copper\",\"option_3\":\"Gold\",\"answer\":1,\"hint\":\"Three are metallic chemical elements; one is an allotrope of carbon.\",\"explanation\":\"Iron, Copper, and Gold are metallic elements; Diamond is a crystalline non-metallic allotrope of Carbon.\"},{\"question\":\"Find the odd one out among state agencies of Nepal:\",\"options\":[\"Public Service Commission\",\"National Planning Commission\",\"Election Commission\",\"Commission for the Investigation of Abuse of Authority\"],\"option_0\":\"Public Service Commission\",\"option_1\":\"National Planning Commission\",\"option_2\":\"Election Commission\",\"option_3\":\"Commission for the Investigation of Abuse of Authority\",\"answer\":1,\"hint\":\"Three are constitutional bodies created directly under Parts 21-24; one is an executive advisory body.\",\"explanation\":\"PSC, Election Commission, and CIAA are constitutional bodies; the National Planning Commission is an executive advisory agency.\"}]', 'text', 3, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:39'),
(144, 63, NULL, 'Demand Elasticity, Market Equilibrium & Pricing', 'nrb-officer-demand-elasticity', 'Focus on Price Elasticity of Demand, Income Elasticity, Cross Elasticity, and Market Equilibrium pricing.', NULL, NULL, '[{\"question\":\"When percentage change in quantity demanded equals percentage change in price, price elasticity of demand (|Ed|) is:\",\"options\":[\"Perfect elasticity (Ed = infinity)\",\"Unitary elasticity (Ed = 1)\",\"Inelastic (Ed < 1)\",\"Perfectly inelastic (Ed = 0)\"],\"answer\":1,\"hint\":\"Total revenue remains constant when price changes.\",\"explanation\":\"Unitary elasticity occurs when |Ed| = 1.\"},{\"question\":\"Which of the following describes an \\\"Inferior Good\\\" in microeconomics?\",\"options\":[\"Demand rises as income rises\",\"Demand falls as consumer income rises (Negative Income Elasticity)\",\"Demand is unresponsive to price\",\"A luxury commodity\"],\"answer\":1,\"hint\":\"Consumers purchase less of this good as their income rises.\",\"explanation\":\"Inferior goods have negative income elasticity of demand (Ey < 0).\"},{\"question\":\"In a perfectly competitive market, what is the shape of an individual firm\'s demand curve?\",\"options\":[\"Downwards sloping\",\"Perfect horizontal line (P = AR = MR)\",\"Vertical line\",\"U-shaped\"],\"answer\":1,\"hint\":\"Firms are price-takers facing infinite elasticity.\",\"explanation\":\"An individual firm in perfect competition faces a horizontal demand curve where P = AR = MR.\"},{\"question\":\"According to Fisher\'s Quantity Theory of Money (MV = PT), doubling M while V and T remain constant causes:\",\"options\":[\"Price level to halve\",\"Price level (P) to double proportionally\",\"No change in price\",\"Velocity to drop\"],\"answer\":1,\"hint\":\"Direct and proportional relationship between money supply and price level.\",\"explanation\":\"Fisher\'s equation dictates that money supply changes produce proportional changes in the price level.\"},{\"question\":\"What is the formula for calculating Gross Domestic Product (GDP) using the Expenditure Approach?\",\"options\":[\"GDP = C + I + G + (X - M)\",\"GDP = Wages + Rents + Interests + Profits\",\"GDP = Output - Intermediate Consumption\",\"GDP = Exports - Imports\"],\"answer\":0,\"hint\":\"Sum of Consumption, Investment, Government spending, and Net Exports.\",\"explanation\":\"Expenditure method: GDP = C + I + G + (X - M).\"},{\"question\":\"What economic term describes high inflation occurring simultaneously with economic stagnation and unemployment?\",\"options\":[\"Deflation\",\"Reflation\",\"Stagflation\",\"Hyperinflation\"],\"answer\":2,\"hint\":\"Stagnant growth combined with price inflation.\",\"explanation\":\"Stagflation is the coexistence of stagnant economic activity and high inflation.\"},{\"question\":\"In the IS-LM model, what does the \\\"IS\\\" curve represent?\",\"options\":[\"Equilibrium in money market\",\"Equilibrium in goods and services market (Investment = Saving)\",\"Labor equilibrium\",\"Balance of payments equilibrium\"],\"answer\":1,\"hint\":\"IS stands for Investment and Saving in the real goods sector.\",\"explanation\":\"The IS curve represents combinations of interest rate and income where goods market is in equilibrium (I = S).\"},{\"question\":\"What does the original Phillips Curve depict in short-run macroeconomics?\",\"options\":[\"Direct relationship between taxes and growth\",\"Inverse relationship between inflation rate and unemployment rate\",\"Inequality vs growth\",\"Money supply vs exchange rate\"],\"answer\":1,\"hint\":\"Lower unemployment is associated with higher inflation.\",\"explanation\":\"Phillips Curve shows the historical inverse tradeoff between inflation and unemployment.\"},{\"question\":\"What is \\\"Base Money\\\" or \\\"Reserve Money\\\" (M0) composed of in central banking?\",\"options\":[\"Currency in circulation + Commercial bank reserves at the Central Bank\",\"Total savings deposits in private banks\",\"Government bonds held by citizens\",\"Gold reserves only\"],\"answer\":0,\"hint\":\"Monetary base created directly by the central bank.\",\"explanation\":\"M0 consists of currency in circulation outside the central bank plus bank reserves deposited with the central bank.\"},{\"question\":\"What is \\\"Gresham\'s Law\\\" in monetary economics?\",\"options\":[\"Good money drives out bad money\",\"\\\"Bad money drives out good money\\\" when fixed by legal tender\",\"Money supply determines real output\",\"Low rates always cause inflation\"],\"answer\":1,\"hint\":\"Overvalued money drives undervalued money out of circulation.\",\"explanation\":\"Gresham\'s Law states that if coins of differing intrinsic metal value have equal legal tender, bad money circulates while good money is hoarded.\"}]', 'text', 1, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(145, 64, NULL, 'NRB Act 2058 & BAFIA 2073 Governance', 'nrb-ad-legal-governance', 'Focus on Central Bank governance, BAFIA licensing classes, NPL classification rules, and Basel III standards.', NULL, NULL, '[{\"question\":\"Under Section 4 of NRB Act 2058, what is the primary statutory objective of NRB?\",\"options\":[\"Maximize commercial banking profits\",\"Maintain price and balance of payments stability, ensure financial sector stability, and develop secure payment systems\",\"Direct political governance of fiscal policy\",\"Fix foreign stock prices\"],\"answer\":1,\"hint\":\"Price stability, external sector stability, financial sector resilience.\",\"explanation\":\"NRB Act 2058 Section 4 establishes price stability and financial stability as core mandates.\"},{\"question\":\"Who appoints the Governor of Nepal Rastra Bank, and for what term length under NRB Act 2058?\",\"options\":[\"President for 6 years\",\"Government of Nepal, Council of Ministers for a term of 5 years\",\"Parliamentary Hearing Committee for 4 years\",\"Ministry of Finance for 3 years\"],\"answer\":1,\"hint\":\"Appointed by the Cabinet for a 5-year tenure.\",\"explanation\":\"Section 15 states the Cabinet appoints the Governor for a 5-year term.\"},{\"question\":\"How many members constitute the Board of Directors of Nepal Rastra Bank?\",\"options\":[\"5 Members\",\"7 Members\",\"9 Members\",\"11 Members\"],\"answer\":1,\"hint\":\"Governor (Chair), Finance Secretary, 2 Deputy Governors, and 3 appointed expert Directors.\",\"explanation\":\"NRB Board of Directors consists of 7 members.\"},{\"question\":\"Under BAFIA 2073, commercial banks are categorized as which class of financial institution?\",\"options\":[\"\\\"Ka\\\" (Class A) Commercial Banks\",\"\\\"Kha\\\" (Class B) Development Banks\",\"\\\"Ga\\\" (Class C) Finance Companies\",\"\\\"Gha\\\" (Class D) Microfinance\"],\"answer\":0,\"hint\":\"Top tier commercial banks.\",\"explanation\":\"BAFIA 2073 categorizes commercial banks as Class \\\"A\\\" institutions.\"},{\"question\":\"According to NRB Unified Directives, what is the loan loss provision required for a \\\"Good\\\" (Pass) performing loan?\",\"options\":[\"1.20% \\/ 1.25%\",\"5.0%\",\"25.0%\",\"100.0%\"],\"answer\":0,\"hint\":\"Standard general loan loss provisioning for performing loans.\",\"explanation\":\"Performing pass loans require standard general loan loss provisioning (~1.20% to 1.25%).\"},{\"question\":\"Under NRB Prudential Directives, a loan with principal or interest overdue for >90 to 180 days is classified as:\",\"options\":[\"Good \\/ Pass Loan\",\"Substandard Loan (Kamal \\/ Kamjor)\",\"Doubtful Loan (Shankaspad)\",\"Loss Loan (Kharab \\/ Bad Debt)\"],\"answer\":1,\"hint\":\"Requires a mandatory 25% loan loss provisioning.\",\"explanation\":\"Loans overdue for 90 to 180 days are classified as Substandard (25% provision).\"},{\"question\":\"What is the minimum Capital Adequacy Ratio (CAR) under Basel III required for commercial banks in Nepal?\",\"options\":[\"6.0%\",\"11.0% Total Capital (including 2.5% Capital Conservation Buffer)\",\"15.0%\",\"20.0%\"],\"answer\":1,\"hint\":\"Tier 1 of 6% + CCB (2.5%) and Total Capital of 11%.\",\"explanation\":\"NRB Basel III guidelines mandate a total CAR of 11.0% (including CCB).\"},{\"question\":\"Under BAFIA 2073, what is the maximum continuous tenure allowed for a CEO of a commercial bank?\",\"options\":[\"1 term of 3 years\",\"2 consecutive terms of up to 4 years each (maximum 8 years)\",\"Unlimited tenures\",\"10 years\"],\"answer\":1,\"hint\":\"Section 29 limits a CEO to two 4-year terms.\",\"explanation\":\"BAFIA Section 29 restricts bank CEOs to a maximum of two consecutive 4-year terms.\"},{\"question\":\"Which unit in NRB serves as the national financial intelligence agency for AML\\/CFT enforcement?\",\"options\":[\"Banking Supervision\",\"Financial Information Unit (FIU-Nepal)\",\"Foreign Exchange Department\",\"Internal Audit\"],\"answer\":1,\"hint\":\"Receives and analyzes Suspicious Transaction Reports (STRs).\",\"explanation\":\"FIU-Nepal, established under AML Act 2064, is the national financial intelligence unit.\"},{\"question\":\"Under Foreign Exchange Regulation Act 2019, who holds the exclusive statutory authority to regulate foreign exchange in Nepal?\",\"options\":[\"Ministry of Finance\",\"Nepal Rastra Bank\",\"Department of Customs\",\"Commercial Banks Association\"],\"answer\":1,\"hint\":\"The central bank regulates foreign exchange and reserves.\",\"explanation\":\"NRB is the sole regulatory authority governing foreign exchange in Nepal.\"}]', 'text', 1, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(146, 65, NULL, 'MS Word & Excel Productivity', 'comp-word-excel-productivity', 'Focus on MS Word formatting, Mail Merge, Page Breaks, Excel formulas (SUMIF, VLOOKUP), and Pivot Tables.', NULL, NULL, '[{\"question\":\"What is the default file extension for Microsoft Word documents?\",\"options\":[\".doc\",\".docx\",\".txt\",\".rtf\"],\"answer\":1,\"hint\":\"XML-based format introduced in Office 2007.\",\"explanation\":\"Microsoft Word documents use the `.docx` format extension.\"},{\"question\":\"Which keyboard shortcut in MS Word creates a \\\"Page Break\\\" instantly?\",\"options\":[\"Ctrl + Enter\",\"Shift + Enter\",\"Alt + Enter\",\"Ctrl + Shift + Enter\"],\"answer\":0,\"hint\":\"Hold Control and tap Enter.\",\"explanation\":\"`Ctrl + Enter` inserts a page break immediately in MS Word.\"},{\"question\":\"Which Excel formula correctly adds values in A1:A10 only if they are greater than 50?\",\"options\":[\"=SUM(A1:A10, \\\">50\\\")\",\"=SUMIF(A1:A10, \\\">50\\\")\",\"=IF(A1:A10>50, SUM())\",\"=COUNTIF(A1:A10, 50)\"],\"answer\":1,\"hint\":\"Uses the conditional SUMIF function.\",\"explanation\":\"`=SUMIF(A1:A10, \\\">50\\\")` calculates the sum of cells greater than 50.\"},{\"question\":\"In MS Excel, what symbol must precede every formula or function?\",\"options\":[\"#\",\"@\",\"=\",\"+\"],\"answer\":2,\"hint\":\"The equal sign indicates a mathematical formula.\",\"explanation\":\"All Excel formulas begin with an equal sign (`=`).\"},{\"question\":\"What is the function of \\\"Mail Merge\\\" in Microsoft Word?\",\"options\":[\"Send offline emails\",\"Create personalized letters\\/envelopes in bulk from a data source\",\"Convert documents to PDF\",\"Compress file size\"],\"answer\":1,\"hint\":\"Generates customized mass documents using a template and data list.\",\"explanation\":\"Mail Merge merges templates with data sources to produce personalized bulk documents.\"},{\"question\":\"Which Excel feature summarizes large datasets dynamically without altering source rows?\",\"options\":[\"Data Validation\",\"Pivot Table\",\"Conditional Formatting\",\"Goal Seek\"],\"answer\":1,\"hint\":\"Drag-and-drop summary tool under Insert tab.\",\"explanation\":\"PivotTables summarize and group complex tables dynamically.\"},{\"question\":\"In Excel cell referencing, what does placing a dollar sign ($) before column\\/row (e.g. $A$1) achieve?\",\"options\":[\"Converts to US Dollars\",\"Creates an Absolute Reference that does not change when copied\",\"Hides formula\",\"Deletes cell\"],\"answer\":1,\"hint\":\"Locks cell coordinate reference.\",\"explanation\":\"The dollar sign creates an absolute cell reference (e.g., `$A$1`).\"},{\"question\":\"What is the universal encoding standard used for standardizing Nepali characters across all digital devices?\",\"options\":[\"ASCII\",\"Preeti Font\",\"Unicode (UTF-8)\",\"Kantipur Font\"],\"answer\":2,\"hint\":\"Universal character encoding (Nepali Unicode).\",\"explanation\":\"Unicode (UTF-8) provides a universal character set for digital Nepali.\"},{\"question\":\"In MS PowerPoint, which view displays thumbnail versions of all slides simultaneously for easy rearranging?\",\"options\":[\"Normal View\",\"Slide Sorter View\",\"Reading View\",\"Notes View\"],\"answer\":1,\"hint\":\"Displays horizontally arranged slide thumbnails.\",\"explanation\":\"Slide Sorter View lets you view and reorder all slide thumbnails.\"},{\"question\":\"Which network protocol securely encrypts web browsing sessions using TLS\\/SSL?\",\"options\":[\"HTTP\",\"HTTPS (Port 443)\",\"FTP\",\"Telnet\"],\"answer\":1,\"hint\":\"Indicated by the padlock icon in browsers.\",\"explanation\":\"HTTPS encrypts web traffic using Transport Layer Security (TLS\\/SSL).\"}]', 'text', 1, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(147, 66, NULL, 'Cellular Mobile Systems & Optical Networks', 'ntc-cellular-mobile-optical', 'Focus on GSM architecture, 4G LTE, optical fiber wavelengths (1310/1550nm), GPON FTTH, and NTA regulatory framework.', NULL, NULL, '[{\"question\":\"In GSM architecture, which element stores permanent subscription info and subscriber location?\",\"options\":[\"VLR\",\"Home Location Register (HLR)\",\"EIR\",\"BTS\"],\"answer\":1,\"hint\":\"Central permanent database storing IMSI and keys.\",\"explanation\":\"HLR is the permanent subscriber database in GSM networks.\"},{\"question\":\"What transmission technology is used in 4G LTE downlink communication to prevent multipath fading?\",\"options\":[\"CDMA\",\"OFDMA (Orthogonal Frequency Division Multiple Access)\",\"TDMA\",\"Pure FM\"],\"answer\":1,\"hint\":\"Splits wideband channels into orthogonal subcarriers.\",\"explanation\":\"LTE downlink employs OFDMA for high spectral efficiency.\"},{\"question\":\"What optical wavelength has the lowest attenuation (~0.2 dB\\/km) in single-mode fiber?\",\"options\":[\"850 nm\",\"1310 nm & 1550 nm\",\"650 nm\",\"980 nm\"],\"answer\":1,\"hint\":\"1550 nm corresponds to the lowest loss window.\",\"explanation\":\"1310 nm and 1550 nm are the standard telecom wavelengths.\"},{\"question\":\"In GPON (FTTH) architecture, what device splits optical signals to multiple subscribers without power?\",\"options\":[\"OLT\",\"Passive Optical Splitter\",\"ONU\",\"Switch\"],\"answer\":1,\"hint\":\"Unpowered optical splitter component.\",\"explanation\":\"Passive Optical Splitters divide signals to multiple subscribers.\"},{\"question\":\"Under Nepal Telecommunications Act 2053, which body allocates frequency spectrum and licenses operators?\",\"options\":[\"Ministry of Communication\",\"Nepal Telecommunications Authority (NTA)\",\"Nepal Telecom (NTC)\",\"Radio Nepal\"],\"answer\":1,\"hint\":\"Autonomous regulatory authority under Section 3.\",\"explanation\":\"NTA is the independent regulatory body for telecom in Nepal.\"},{\"question\":\"Which IP addressing format uses 128-bit addresses?\",\"options\":[\"IPv4\",\"IPv6\",\"MAC Address\",\"Subnet Mask\"],\"answer\":1,\"hint\":\"Next-generation 128-bit IP addressing.\",\"explanation\":\"IPv6 uses a 128-bit address space.\"},{\"question\":\"What does \\\"SIM\\\" stand for in mobile communications?\",\"options\":[\"Subscriber Identity Module\",\"System Information Memory\",\"Satellite Interface Module\",\"Secure Internet Mechanism\"],\"answer\":0,\"hint\":\"Smart card storing IMSI identity.\",\"explanation\":\"SIM stands for Subscriber Identity Module.\"},{\"question\":\"At which layer of the OSI 7-layer model do IP Routers primarily operate?\",\"options\":[\"Layer 1\",\"Layer 2\",\"Layer 3 (Network Layer)\",\"Layer 4\"],\"answer\":2,\"hint\":\"Responsible for packet forwarding and logical IP routing.\",\"explanation\":\"Routers operate at Layer 3 (Network Layer) of the OSI model.\"},{\"question\":\"What does VoLTE stand for in modern mobile communications?\",\"options\":[\"Voice over Long Term Evolution\",\"Variable Optical Line Termination\",\"Visual Online Live Telephony\",\"Virtual Open LTE\"],\"answer\":0,\"hint\":\"HD voice calling over 4G LTE networks.\",\"explanation\":\"VoLTE stands for Voice over Long-Term Evolution.\"},{\"question\":\"Which fund under the Telecom Act 2053 builds broadband infrastructure in rural Nepal using a 2% operator levy?\",\"options\":[\"Rural Telecommunication Development Fund (RTDF)\",\"National Telecom Reserve Fund\",\"Postal Savings Fund\",\"Digital Nepal Fund\"],\"answer\":0,\"hint\":\"Funded by a 2% levy on operators\' gross revenues.\",\"explanation\":\"RTDF finances rural telecommunications expansion in Nepal.\"}]', 'text', 1, 20, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(148, 60, NULL, 'Geographical, Social and Economic Condition of Nepal', 'geographical-social-and-economic-condition-of-nepal', NULL, NULL, 'lessons/pdfs/01M1GMJMQ1AWNHVAB1YV3CAFMP.pdf', '[{\"question\":\"According to the National Population and Housing Census 2078, what is the total population of Nepal?\",\"options\":[\"26,494,504\",\"29,164,578\",\"31,000,000\",\"28,000,000\"],\"option_0\":\"26,494,504\",\"option_1\":\"29,164,578\",\"option_2\":\"31,000,000\",\"option_3\":\"28,000,000\",\"answer\":1,\"hint\":\"Female population accounts for 51.02% and male population 48.98%.\",\"explanation\":\"The National Census 2078 recorded Nepal\\u2019s total population at 29,164,578 with an annual population growth rate of 0.92%.\"},{\"question\":\"What is the national literacy rate of Nepal as per the Census 2078?\",\"options\":[\"65.9%\",\"76.3%\",\"82.5%\",\"71.0%\"],\"option_0\":\"65.9%\",\"option_1\":\"76.3%\",\"option_2\":\"82.5%\",\"option_3\":\"71.0%\",\"answer\":1,\"hint\":\"Male literacy stands at 83.6% and female literacy at 69.4%.\",\"explanation\":\"Census 2078 showed a total literacy rate of 76.3% (Male: 83.6%, Female: 69.4%).\"},{\"question\":\"Which province of Nepal has the highest population as per Census 2078?\",\"options\":[\"Koshi Province\",\"Bagmati Province\",\"Madhesh Province\",\"Lumbini Province\"],\"option_0\":\"Koshi Province\",\"option_1\":\"Bagmati Province\",\"option_2\":\"Madhesh Province\",\"option_3\":\"Lumbini Province\",\"answer\":1,\"hint\":\"Home to the federal capital Kathmandu, accommodating ~20.97% of the total population.\",\"explanation\":\"Bagmati Province has the highest population (6,116,866 or 20.97%), while Karnali Province has the lowest (5.79%).\"},{\"question\":\"What is the standard fiscal year cycle in Nepal?\",\"options\":[\"January 1 to December 31\",\"Shrawan 1 to Ashad end\",\"Baisakh 1 to Chaitra end\",\"April 1 to March 31\"],\"option_0\":\"January 1 to December 31\",\"option_1\":\"Shrawan 1 to Ashad end\",\"option_2\":\"Baisakh 1 to Chaitra end\",\"option_3\":\"April 1 to March 31\",\"answer\":1,\"hint\":\"Annual federal budget is constitutionally presented on Jestha 15 for the upcoming fiscal year starting Shrawan 1.\",\"explanation\":\"Nepal\\u2019s fiscal year runs from 1st Shrawan (mid-July) to the end of Ashad (mid-July of the following calendar year).\"},{\"question\":\"On which constitutional date is the Federal Annual Budget presented by the Finance Minister to Parliament?\",\"options\":[\"Baisakh 1 BS\",\"Jestha 15 BS\",\"Ashad 1 BS\",\"Shrawan 1 BS\"],\"option_0\":\"Baisakh 1 BS\",\"option_1\":\"Jestha 15 BS\",\"option_2\":\"Ashad 1 BS\",\"option_3\":\"Shrawan 1 BS\",\"answer\":1,\"hint\":\"Fixed by Article 119(3) of the Constitution of Nepal on Republic Day.\",\"explanation\":\"Article 119(3) constitutionally mandates the Finance Minister to present the annual revenue and expenditure estimates on 15th Jestha.\"},{\"question\":\"Which is the largest contributor to the Gross Domestic Product (GDP) of Nepal among broad economic sectors?\",\"options\":[\"Manufacturing Sector\",\"Services Sector\",\"Agriculture and Forestry Sector\",\"Mining Sector\"],\"option_0\":\"Manufacturing Sector\",\"option_1\":\"Services Sector\",\"option_2\":\"Agriculture and Forestry Sector\",\"option_3\":\"Mining Sector\",\"answer\":1,\"hint\":\"Includes trade, real estate, banking, education, transport, and hospitality.\",\"explanation\":\"The services tertiary sector contributes over 60% of Nepal\\u2019s GDP, followed by agriculture (~24%) and industry (~13%).\"},{\"question\":\"Which is the major cash crop and agricultural export product of eastern Nepal?\",\"options\":[\"Paddy\",\"Orthodox Tea and Large Cardamom\",\"Wheat\",\"Cotton\"],\"option_0\":\"Paddy\",\"option_1\":\"Orthodox Tea and Large Cardamom\",\"option_2\":\"Wheat\",\"option_3\":\"Cotton\",\"answer\":1,\"hint\":\"Cultivated in high hills of Ilam, Jhapa, Panchthar, and Taplejung.\",\"explanation\":\"Orthodox tea, large cardamom (Alainchi), and ginger are major agricultural exports contributing significantly to rural income in eastern Nepal.\"},{\"question\":\"Which highway is the longest national highway in Nepal traversing east to west?\",\"options\":[\"Prithvi Highway\",\"Mahendra Highway\",\"Tribhuvan Highway\",\"Mid-Hill Highway\"],\"option_0\":\"Prithvi Highway\",\"option_1\":\"Mahendra Highway\",\"option_2\":\"Tribhuvan Highway\",\"option_3\":\"Mid-Hill Highway\",\"answer\":1,\"hint\":\"Extends from Kakarbhitta in the east to Gaddachauki in the west (1,027 km).\",\"explanation\":\"Mahendra Highway (East-West Highway) spans 1,027.67 km connecting Mechi to Mahakali across the Terai belt.\"},{\"question\":\"Which international airport in Nepal was inaugurated on January 1, 2023 as the country third international airport?\",\"options\":[\"Tribhuvan International Airport\",\"Pokhara International Airport\",\"Gautam Buddha International Airport\",\"Nijgadh International Airport\"],\"option_0\":\"Tribhuvan International Airport\",\"option_1\":\"Pokhara International Airport\",\"option_2\":\"Gautam Buddha International Airport\",\"option_3\":\"Nijgadh International Airport\",\"answer\":1,\"hint\":\"Located in the prime tourist city of Gandaki province.\",\"explanation\":\"Pokhara International Airport was officially inaugurated for operation on January 1, 2023.\"},{\"question\":\"Nepal is officially targeted to graduate from Least Developed Country (LDC) category to Developing Country status by:\",\"options\":[\"2024 AD\",\"2026 AD\",\"2030 AD\",\"2035 AD\"],\"option_0\":\"2024 AD\",\"option_1\":\"2026 AD\",\"option_2\":\"2030 AD\",\"option_3\":\"2035 AD\",\"answer\":1,\"hint\":\"Recommended by the UN Committee for Development Policy with a 5-year preparatory transition period.\",\"explanation\":\"Nepal is scheduled to graduate from the UN Least Developed Country (LDC) category to a Developing Country by November 2026.\"}]', 'text', 1, 15, 1, '2026-09-02 02:53:34', '2026-09-02 12:19:39'),
(149, 60, NULL, 'Constitutional System and Government', 'constitutional-system-and-government', NULL, NULL, 'lessons/pdfs/01M1GMT5P2XRGBP1F95RDKG8PW.pdf', '[{\"question\":\"How many Parts, Articles, and Schedules are contained in the Constitution of Nepal 2072?\",\"options\":[\"25 Parts, 250 Articles, 7 Schedules\",\"35 Parts, 308 Articles, 9 Schedules\",\"30 Parts, 300 Articles, 8 Schedules\",\"40 Parts, 320 Articles, 10 Schedules\"],\"option_0\":\"25 Parts, 250 Articles, 7 Schedules\",\"option_1\":\"35 Parts, 308 Articles, 9 Schedules\",\"option_2\":\"30 Parts, 300 Articles, 8 Schedules\",\"option_3\":\"40 Parts, 320 Articles, 10 Schedules\",\"answer\":1,\"hint\":\"Promulgated on Ashwin 3, 2072 BS by the Constituent Assembly.\",\"explanation\":\"The Constitution of Nepal comprises 35 Parts, 308 Articles, and 9 Schedules.\"},{\"question\":\"Which Part of the Constitution of Nepal enshrines the 31 Fundamental Rights?\",\"options\":[\"Part 2\",\"Part 3\",\"Part 4\",\"Part 5\"],\"option_0\":\"Part 2\",\"option_1\":\"Part 3\",\"option_2\":\"Part 4\",\"option_3\":\"Part 5\",\"answer\":1,\"hint\":\"Spans from Article 16 (Right to live with dignity) to Article 46 (Right to constitutional remedies).\",\"explanation\":\"Part 3 of the Constitution of Nepal provides 31 fundamental rights enforceable through the courts under Articles 46 and 133.\"},{\"question\":\"Under Article 7 of the Constitution of Nepal, which language in Devanagari script is designated as the Official Language of government business?\",\"options\":[\"Maithili\",\"Nepali Language\",\"Bhojpuri\",\"English Language\"],\"option_0\":\"Maithili\",\"option_1\":\"Nepali Language\",\"option_2\":\"Bhojpuri\",\"option_3\":\"English Language\",\"answer\":1,\"hint\":\"Written in Devanagari script; provinces may also designate additional regional languages.\",\"explanation\":\"Article 7(1) states that the Nepali language in Devanagari script shall be the official language of government business in Nepal.\"},{\"question\":\"Who is the executive head of the Government of Nepal under the constitutional parliamentary system?\",\"options\":[\"The President\",\"The Prime Minister\",\"The Chief Justice\",\"The Speaker of the House\"],\"option_0\":\"The President\",\"option_1\":\"The Prime Minister\",\"option_2\":\"The Chief Justice\",\"option_3\":\"The Speaker of the House\",\"answer\":1,\"hint\":\"Appointed under Article 76 from the party or coalition commanding a majority in the House of Representatives.\",\"explanation\":\"Under Article 75, executive power is vested in the Council of Ministers headed by the Prime Minister.\"},{\"question\":\"How many total members are there in the federal House of Representatives of Nepal?\",\"options\":[\"205 members\",\"275 members\",\"330 members\",\"601 members\"],\"option_0\":\"205 members\",\"option_1\":\"275 members\",\"option_2\":\"330 members\",\"option_3\":\"601 members\",\"answer\":1,\"hint\":\"165 elected through First-Past-The-Post and 110 through Proportional Representation.\",\"explanation\":\"Article 84 establishes the 275-member House of Representatives: 165 directly elected from single-member constituencies and 110 elected proportionally.\"},{\"question\":\"How many members constitute the National Assembly (Upper House) of Nepal?\",\"options\":[\"50 members\",\"59 members\",\"75 members\",\"100 members\"],\"option_0\":\"50 members\",\"option_1\":\"59 members\",\"option_2\":\"75 members\",\"option_3\":\"100 members\",\"answer\":1,\"hint\":\"56 elected from 7 provinces (8 from each province) and 3 nominated by the President.\",\"explanation\":\"Article 86 provides that the National Assembly consists of 59 members, serving as a permanent house with one-third retiring every two years.\"},{\"question\":\"Under Article 242 of the Constitution, which constitutional body conducts examinations for selection of candidates to civil service posts?\",\"options\":[\"Election Commission\",\"Public Service Commission\",\"Commission for the Investigation of Abuse of Authority\",\"National Human Rights Commission\"],\"option_0\":\"Election Commission\",\"option_1\":\"Public Service Commission\",\"option_2\":\"Commission for the Investigation of Abuse of Authority\",\"option_3\":\"National Human Rights Commission\",\"answer\":1,\"hint\":\"The premier merit-based recruitment authority established in 2008 BS.\",\"explanation\":\"The Public Service Commission (Article 242) conducts competitive examinations for appointments to the civil service, military, police, and public state enterprises.\"},{\"question\":\"Which schedule of the Constitution of Nepal lists the 22 Exclusive Powers of the Local Level?\",\"options\":[\"Schedule 5\",\"Schedule 8\",\"Schedule 6\",\"Schedule 9\"],\"option_0\":\"Schedule 5\",\"option_1\":\"Schedule 8\",\"option_2\":\"Schedule 6\",\"option_3\":\"Schedule 9\",\"answer\":1,\"hint\":\"Includes local police, local taxes, basic education, and local health services.\",\"explanation\":\"Schedule 8 outlines the 22 exclusive legislative and executive powers of Municipalities and Rural Municipalities in Nepal.\"},{\"question\":\"Who administers the oath of office and secrecy to the President of Nepal under Article 70?\",\"options\":[\"The Prime Minister\",\"The Chief Justice of Nepal\",\"The Speaker of the House\",\"The Chairman of the National Assembly\"],\"option_0\":\"The Prime Minister\",\"option_1\":\"The Chief Justice of Nepal\",\"option_2\":\"The Speaker of the House\",\"option_3\":\"The Chairman of the National Assembly\",\"answer\":1,\"hint\":\"The head of the judicial branch of the state.\",\"explanation\":\"Under the Constitution, the President takes the oath of office before the Chief Justice of the Supreme Court of Nepal.\"},{\"question\":\"What is the total number of Provinces in the federal structure of Nepal?\",\"options\":[\"5 Provinces\",\"7 Provinces\",\"9 Provinces\",\"14 Zones\"],\"option_0\":\"5 Provinces\",\"option_1\":\"7 Provinces\",\"option_2\":\"9 Provinces\",\"option_3\":\"14 Zones\",\"answer\":1,\"hint\":\"Replaced the old 5 development regions and 14 zones.\",\"explanation\":\"Article 56 partitions Nepal into 7 federal provinces (Koshi, Madhesh, Bagmati, Gandaki, Lumbini, Karnali, and Sudurpashchim).\"}]', 'text', 2, 15, 1, '2026-09-02 03:02:17', '2026-09-02 12:19:39'),
(150, 60, NULL, 'Public Service Operation and Management', 'public-service-operation-and-management', NULL, NULL, 'lessons/pdfs/01M1GPTVP61VZ6FM93Q03XHXAR.pdf', '[{\"question\":\"What is the classic definition of Public Administration as articulated by Woodrow Wilson in 1887?\",\"options\":[\"A purely political election campaign tool\",\"Detailed and systematic execution of public law\",\"Private commercial trade management\",\"A judicial criminal trial process\"],\"option_0\":\"A purely political election campaign tool\",\"option_1\":\"Detailed and systematic execution of public law\",\"option_2\":\"Private commercial trade management\",\"option_3\":\"A judicial criminal trial process\",\"answer\":1,\"hint\":\"Woodrow Wilson is celebrated as the Father of Public Administration.\",\"explanation\":\"Woodrow Wilson defined public administration as the detailed and systematic execution of public law in his seminal essay \\\"The Study of Administration\\\" (1887).\"},{\"question\":\"Who coined the famous administrative management acronym POSDCORB?\",\"options\":[\"Henri Fayol\",\"Luther Gulick and Lyndall Urwick\",\"Max Weber\",\"Herbert Simon\"],\"option_0\":\"Henri Fayol\",\"option_1\":\"Luther Gulick and Lyndall Urwick\",\"option_2\":\"Max Weber\",\"option_3\":\"Herbert Simon\",\"answer\":1,\"hint\":\"Planning, Organizing, Staffing, Directing, Coordinating, Reporting, and Budgeting.\",\"explanation\":\"Luther Gulick formulated POSDCORB to summarize the core executive functions of administrative management.\"},{\"question\":\"What are the three essential pillars of the classic 3Es in public expenditure audit?\",\"options\":[\"Equity, Environment, Emotion\",\"Economy, Efficiency, and Effectiveness\",\"Execution, Evaluation, Elimination\",\"Electricity, Energy, Emission\"],\"option_0\":\"Equity, Environment, Emotion\",\"option_1\":\"Economy, Efficiency, and Effectiveness\",\"option_2\":\"Execution, Evaluation, Elimination\",\"option_3\":\"Electricity, Energy, Emission\",\"answer\":1,\"hint\":\"Evaluated by the Auditor General to ensure value for taxpayer money.\",\"explanation\":\"Value-for-money audits evaluate Economy (minimizing cost of inputs), Efficiency (maximizing output per input), and Effectiveness (achieving target outcomes).\"},{\"question\":\"Which administrative reform concept emphasizes viewing citizens as customers and measuring government by results?\",\"options\":[\"Traditional Bureaucracy\",\"New Public Management\",\"Spoils System\",\"Legal Formalism\"],\"option_0\":\"Traditional Bureaucracy\",\"option_1\":\"New Public Management\",\"option_2\":\"Spoils System\",\"option_3\":\"Legal Formalism\",\"answer\":1,\"hint\":\"Emerged in the 1980s and 1990s through Osborne and Gaebler\\u2019s Reinventing Government.\",\"explanation\":\"New Public Management incorporates market-driven practices, customer satisfaction, accountability, and output indicators into public administration.\"},{\"question\":\"What is the primary role of the Public Accounts Committee of Parliament in Nepal?\",\"options\":[\"Levying local property taxes\",\"Examining the Annual Audit Report of the Auditor General and holding ministries accountable for fiscal irregularities\",\"Drafting civil service exam questions\",\"Managing foreign exchange reserves\"],\"option_0\":\"Levying local property taxes\",\"option_1\":\"Examining the Annual Audit Report of the Auditor General and holding ministries accountable for fiscal irregularities\",\"option_2\":\"Drafting civil service exam questions\",\"option_3\":\"Managing foreign exchange reserves\",\"answer\":1,\"hint\":\"Chaired customarily by an opposition member of parliament to maintain oversight.\",\"explanation\":\"The PAC examines public accounts and the Auditor General\\u2019s report, summoning secretaries and ministers to resolve audit arrears (Beruju).\"},{\"question\":\"Which principle of natural justice requires that No person shall be a judge in their own cause?\",\"options\":[\"Audi Alteram Partem\",\"Nemo Judex In Causa Sua\",\"Ultra Vires\",\"Locus Standi\"],\"option_0\":\"Audi Alteram Partem\",\"option_1\":\"Nemo Judex In Causa Sua\",\"option_2\":\"Ultra Vires\",\"option_3\":\"Locus Standi\",\"answer\":1,\"hint\":\"Ensures that decision-makers have no personal, financial, or familial bias in the subject matter.\",\"explanation\":\"Nemo Judex In Causa Sua prohibits bias and conflict of interest, ensuring that judges and administrators remain strictly neutral.\"},{\"question\":\"In Nepal, which apex constitutional body investigates corruption and improper conduct of public post holders?\",\"options\":[\"National Human Rights Commission\",\"Commission for the Investigation of Abuse of Authority\",\"Public Service Commission\",\"Judicial Council\"],\"option_0\":\"National Human Rights Commission\",\"option_1\":\"Commission for the Investigation of Abuse of Authority\",\"option_2\":\"Public Service Commission\",\"option_3\":\"Judicial Council\",\"answer\":1,\"hint\":\"Established under Part 21 (Article 238) of the Constitution of Nepal.\",\"explanation\":\"The CIAA investigates corruption offenses and prosecutes public officials before the Special Court.\"},{\"question\":\"What does Audit Arrears (Beruju) signify in government accounting in Nepal?\",\"options\":[\"Total budget surplus at year end\",\"Transactions or expenditures executed without statutory authority, supporting documents, or in violation of financial rules\",\"Foreign grant received from abroad\",\"Employee tax deductions\"],\"option_0\":\"Total budget surplus at year end\",\"option_1\":\"Transactions or expenditures executed without statutory authority, supporting documents, or in violation of financial rules\",\"option_2\":\"Foreign grant received from abroad\",\"option_3\":\"Employee tax deductions\",\"answer\":1,\"hint\":\"Flagged annually in the Auditor General\\u2019s report under advance arrears, unregularized spending, or misappropriation.\",\"explanation\":\"Beruju represents financial transactions executed contrary to prevailing laws, regulations, or accounting standards, requiring recovery or regularization.\"},{\"question\":\"Under Nepal Public Procurement Act 2063, what is the default and standard method for purchasing public goods and civil works?\",\"options\":[\"Direct sole-source purchase\",\"Open Competitive Bidding\",\"User committee construction without quotation\",\"Secret negotiation\"],\"option_0\":\"Direct sole-source purchase\",\"option_1\":\"Open Competitive Bidding\",\"option_2\":\"User committee construction without quotation\",\"option_3\":\"Secret negotiation\",\"answer\":1,\"hint\":\"Ensures equal opportunity, transparency, and competitive pricing for public value.\",\"explanation\":\"The Public Procurement Act 2063 mandates open competitive national or international bidding as the principal procurement method.\"},{\"question\":\"What is the primary role of a Social Audit in public development projects?\",\"options\":[\"Checking bank account interest rates\",\"Engaging direct beneficiaries and citizens in a public forum to evaluate project expenditure, quality, and service responsiveness\",\"Calculating employee income tax\",\"Filing international patent applications\"],\"option_0\":\"Checking bank account interest rates\",\"option_1\":\"Engaging direct beneficiaries and citizens in a public forum to evaluate project expenditure, quality, and service responsiveness\",\"option_2\":\"Calculating employee income tax\",\"option_3\":\"Filing international patent applications\",\"answer\":1,\"hint\":\"A participatory social accountability tool practiced across local governments in Nepal.\",\"explanation\":\"Social audit brings community members and officials together to transparently review project resources, progress, and public satisfaction.\"}]', 'text', 3, 15, 1, '2026-09-02 03:14:49', '2026-09-02 12:19:39');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(151, 67, NULL, 'Office Operations and Organizational Behavior', 'office-operations-and-organizational-behavior', NULL, NULL, 'lessons/pdfs/01M1GNH4V3AJKZ0HN777K0B6R6.pdf', '[{\"question\":\"What is the primary purpose of the Registration (Darta) ledger in public offices?\",\"options\":[\"To prepare annual employee salary payroll\",\"To systematically record incoming official letters and documents entering the office\",\"To record outgoing letters dispatched to other agencies\",\"To record daily staff attendance\"],\"option_0\":\"To prepare annual employee salary payroll\",\"option_1\":\"To systematically record incoming official letters and documents entering the office\",\"option_2\":\"To record outgoing letters dispatched to other agencies\",\"option_3\":\"To record daily staff attendance\",\"answer\":1,\"hint\":\"The initial registration ledger where all incoming official correspondence is logged.\",\"explanation\":\"Darta is the official ledger used to systematically record all incoming letters, notices, and documents received by an office.\"},{\"question\":\"What is the Dispatch (Chalani) book used for in public office administration?\",\"options\":[\"Recording incoming letters from citizens\",\"Systematically recording and dispatching outgoing official correspondence to external agencies\",\"Calculating staff pension benefits\",\"Storing obsolete records in archive\"],\"option_0\":\"Recording incoming letters from citizens\",\"option_1\":\"Systematically recording and dispatching outgoing official correspondence to external agencies\",\"option_2\":\"Calculating staff pension benefits\",\"option_3\":\"Storing obsolete records in archive\",\"answer\":1,\"hint\":\"Assigns unique dispatch numbers and date to letters sent out from the office.\",\"explanation\":\"Chalani is the register where all outgoing letters, circulars, and orders sent from the office are numbered and documented.\"},{\"question\":\"What does an Administrative Note \\/ Minute (Tippani) represent in government decision-making in Nepal?\",\"options\":[\"A casual informal comment\",\"A structured administrative file note presenting facts, legal provisions, and recommendations for higher approval\",\"An annual auditing ledger\",\"A commercial purchase order invoice\"],\"option_0\":\"A casual informal comment\",\"option_1\":\"A structured administrative file note presenting facts, legal provisions, and recommendations for higher approval\",\"option_2\":\"An annual auditing ledger\",\"option_3\":\"A commercial purchase order invoice\",\"answer\":1,\"hint\":\"The formal written channel through which official policy and executive decisions are routed upwards for hierarchical approval.\",\"explanation\":\"Tippani is an administrative memo prepared on a case file that details background, rules, precedents, and proposed decisions for authorized sanction.\"},{\"question\":\"Which filing system arranges documents based on geographic locations such as Provinces, Districts, and Municipalities?\",\"options\":[\"Alphabetical Filing\",\"Geographical Filing\",\"Chronological Filing\",\"Numerical Filing\"],\"option_0\":\"Alphabetical Filing\",\"option_1\":\"Geographical Filing\",\"option_2\":\"Chronological Filing\",\"option_3\":\"Numerical Filing\",\"answer\":1,\"hint\":\"Organizes files by territory or administrative regions.\",\"explanation\":\"Geographical filing groups and stores records according to territorial jurisdictions, regions, or branch locations.\"},{\"question\":\"In public administration, what is a Citizen Charter?\",\"options\":[\"A political party election manifesto\",\"A public declaration displayed at government offices stating services offered, required documents, timeframe, fees, and grievance redressal officers\",\"A tax assessment booklet\",\"An internal employee disciplinary manual\"],\"option_0\":\"A political party election manifesto\",\"option_1\":\"A public declaration displayed at government offices stating services offered, required documents, timeframe, fees, and grievance redressal officers\",\"option_2\":\"A tax assessment booklet\",\"option_3\":\"An internal employee disciplinary manual\",\"answer\":1,\"hint\":\"Guarantees service delivery standards and public accountability to service seekers.\",\"explanation\":\"A Citizen Charter is a visible institutional commitment outlining the nature of services, turnaround times, fees, officer in charge, and compensation procedures.\"},{\"question\":\"Under Nepal Good Governance Act 2064, within what timeframe must a public body deliver administrative services when all documents are complete?\",\"options\":[\"Immediately or within the timeframe specified in the Citizen Charter\",\"Within 6 months\",\"Whenever staff are free\",\"Within 1 year\"],\"option_0\":\"Immediately or within the timeframe specified in the Citizen Charter\",\"option_1\":\"Within 6 months\",\"option_2\":\"Whenever staff are free\",\"option_3\":\"Within 1 year\",\"answer\":0,\"hint\":\"Services must be delivered promptly without causing unnecessary delays to citizens.\",\"explanation\":\"Section 16 of the Good Governance Act 2064 mandates that every public agency must provide services immediately or strictly within the timeline published in its Citizen Charter.\"},{\"question\":\"What is the purpose of Record Management \\/ Archiving in public offices?\",\"options\":[\"Destroying all old files immediately\",\"Systematically classifying, preserving valuable records, and disposing of obsolete files per statutory rules\",\"Restricting information from public access permanently\",\"Increasing office paperwork costs\"],\"option_0\":\"Destroying all old files immediately\",\"option_1\":\"Systematically classifying, preserving valuable records, and disposing of obsolete files per statutory rules\",\"option_2\":\"Restricting information from public access permanently\",\"option_3\":\"Increasing office paperwork costs\",\"answer\":1,\"hint\":\"Governed by the Record Preservation and Disposal Rules in Nepal.\",\"explanation\":\"Record management ensures systematic retention of historical, legal, and operational documents while safely disposing of time-expired records.\"},{\"question\":\"What is a Circular (Paripatra) in administrative correspondence?\",\"options\":[\"A personal letter to a friend\",\"A single official directive or notice sent simultaneously to multiple subordinate offices for uniform implementation\",\"A personal leave application\",\"A tender invitation notice published in a newspaper\"],\"option_0\":\"A personal letter to a friend\",\"option_1\":\"A single official directive or notice sent simultaneously to multiple subordinate offices for uniform implementation\",\"option_2\":\"A personal leave application\",\"option_3\":\"A tender invitation notice published in a newspaper\",\"answer\":1,\"hint\":\"Sent from higher headquarters to all branch or field offices.\",\"explanation\":\"A circular (Paripatra) is an official communication addressing multiple subordinates or departments regarding administrative directives or operational rules.\"},{\"question\":\"What is the primary role of the Information Officer appointed in every public agency under the Right to Information Act 2064?\",\"options\":[\"Drafting annual financial budgets\",\"Receiving citizen RTI requests, collecting information from departments, and disseminating it within statutory deadlines\",\"Handling court litigation only\",\"Inspecting physical office furniture\"],\"option_0\":\"Drafting annual financial budgets\",\"option_1\":\"Receiving citizen RTI requests, collecting information from departments, and disseminating it within statutory deadlines\",\"option_2\":\"Handling court litigation only\",\"option_3\":\"Inspecting physical office furniture\",\"answer\":1,\"hint\":\"Mandated by Section 6 of the RTI Act 2064 to uphold institutional transparency.\",\"explanation\":\"The Information Officer is the statutory liaison responsible for processing public information requests and proactively disclosing public agency data.\"},{\"question\":\"Which of the following is considered an essential element of modern electronic office management (e-Office)?\",\"options\":[\"Complete reliance on manual paper registers\",\"Paperless digital workflows, electronic signatures, automated file routing, and biometric attendance\",\"Eliminating internet connectivity\",\"Restricting computer access to senior executives only\"],\"option_0\":\"Complete reliance on manual paper registers\",\"option_1\":\"Paperless digital workflows, electronic signatures, automated file routing, and biometric attendance\",\"option_2\":\"Eliminating internet connectivity\",\"option_3\":\"Restricting computer access to senior executives only\",\"answer\":1,\"hint\":\"Improves administrative speed, transparency, and traceability.\",\"explanation\":\"Digital office systems (e-Office) streamline government processes through electronic document handling, computerized dispatch, and audit trails.\"}]', 'text', 1, 15, 1, '2026-09-02 03:37:36', '2026-09-02 12:19:39'),
(152, 67, NULL, 'Administration and Management', 'administration-and-management', NULL, NULL, 'lessons/pdfs/01M1GPWTF70K20Z6NV8X5THE03.pdf', '[{\"question\":\"What is the classic definition of Public Administration as articulated by Woodrow Wilson in 1887?\",\"options\":[\"A purely political election campaign tool\",\"Detailed and systematic execution of public law\",\"Private commercial trade management\",\"A judicial criminal trial process\"],\"option_0\":\"A purely political election campaign tool\",\"option_1\":\"Detailed and systematic execution of public law\",\"option_2\":\"Private commercial trade management\",\"option_3\":\"A judicial criminal trial process\",\"answer\":1,\"hint\":\"Woodrow Wilson is celebrated as the Father of Public Administration.\",\"explanation\":\"Woodrow Wilson defined public administration as the detailed and systematic execution of public law in his seminal essay \\\"The Study of Administration\\\" (1887).\"},{\"question\":\"Who coined the famous administrative management acronym POSDCORB?\",\"options\":[\"Henri Fayol\",\"Luther Gulick and Lyndall Urwick\",\"Max Weber\",\"Herbert Simon\"],\"option_0\":\"Henri Fayol\",\"option_1\":\"Luther Gulick and Lyndall Urwick\",\"option_2\":\"Max Weber\",\"option_3\":\"Herbert Simon\",\"answer\":1,\"hint\":\"Planning, Organizing, Staffing, Directing, Coordinating, Reporting, and Budgeting.\",\"explanation\":\"Luther Gulick formulated POSDCORB to summarize the core executive functions of administrative management.\"},{\"question\":\"What are the three essential pillars of the classic 3Es in public expenditure audit?\",\"options\":[\"Equity, Environment, Emotion\",\"Economy, Efficiency, and Effectiveness\",\"Execution, Evaluation, Elimination\",\"Electricity, Energy, Emission\"],\"option_0\":\"Equity, Environment, Emotion\",\"option_1\":\"Economy, Efficiency, and Effectiveness\",\"option_2\":\"Execution, Evaluation, Elimination\",\"option_3\":\"Electricity, Energy, Emission\",\"answer\":1,\"hint\":\"Evaluated by the Auditor General to ensure value for taxpayer money.\",\"explanation\":\"Value-for-money audits evaluate Economy (minimizing cost of inputs), Efficiency (maximizing output per input), and Effectiveness (achieving target outcomes).\"},{\"question\":\"Which administrative reform concept emphasizes viewing citizens as customers and measuring government by results?\",\"options\":[\"Traditional Bureaucracy\",\"New Public Management\",\"Spoils System\",\"Legal Formalism\"],\"option_0\":\"Traditional Bureaucracy\",\"option_1\":\"New Public Management\",\"option_2\":\"Spoils System\",\"option_3\":\"Legal Formalism\",\"answer\":1,\"hint\":\"Emerged in the 1980s and 1990s through Osborne and Gaebler\\u2019s Reinventing Government.\",\"explanation\":\"New Public Management incorporates market-driven practices, customer satisfaction, accountability, and output indicators into public administration.\"},{\"question\":\"What is the primary role of the Public Accounts Committee of Parliament in Nepal?\",\"options\":[\"Levying local property taxes\",\"Examining the Annual Audit Report of the Auditor General and holding ministries accountable for fiscal irregularities\",\"Drafting civil service exam questions\",\"Managing foreign exchange reserves\"],\"option_0\":\"Levying local property taxes\",\"option_1\":\"Examining the Annual Audit Report of the Auditor General and holding ministries accountable for fiscal irregularities\",\"option_2\":\"Drafting civil service exam questions\",\"option_3\":\"Managing foreign exchange reserves\",\"answer\":1,\"hint\":\"Chaired customarily by an opposition member of parliament to maintain oversight.\",\"explanation\":\"The PAC examines public accounts and the Auditor General\\u2019s report, summoning secretaries and ministers to resolve audit arrears (Beruju).\"},{\"question\":\"Which principle of natural justice requires that No person shall be a judge in their own cause?\",\"options\":[\"Audi Alteram Partem\",\"Nemo Judex In Causa Sua\",\"Ultra Vires\",\"Locus Standi\"],\"option_0\":\"Audi Alteram Partem\",\"option_1\":\"Nemo Judex In Causa Sua\",\"option_2\":\"Ultra Vires\",\"option_3\":\"Locus Standi\",\"answer\":1,\"hint\":\"Ensures that decision-makers have no personal, financial, or familial bias in the subject matter.\",\"explanation\":\"Nemo Judex In Causa Sua prohibits bias and conflict of interest, ensuring that judges and administrators remain strictly neutral.\"},{\"question\":\"In Nepal, which apex constitutional body investigates corruption and improper conduct of public post holders?\",\"options\":[\"National Human Rights Commission\",\"Commission for the Investigation of Abuse of Authority\",\"Public Service Commission\",\"Judicial Council\"],\"option_0\":\"National Human Rights Commission\",\"option_1\":\"Commission for the Investigation of Abuse of Authority\",\"option_2\":\"Public Service Commission\",\"option_3\":\"Judicial Council\",\"answer\":1,\"hint\":\"Established under Part 21 (Article 238) of the Constitution of Nepal.\",\"explanation\":\"The CIAA investigates corruption offenses and prosecutes public officials before the Special Court.\"},{\"question\":\"What does Audit Arrears (Beruju) signify in government accounting in Nepal?\",\"options\":[\"Total budget surplus at year end\",\"Transactions or expenditures executed without statutory authority, supporting documents, or in violation of financial rules\",\"Foreign grant received from abroad\",\"Employee tax deductions\"],\"option_0\":\"Total budget surplus at year end\",\"option_1\":\"Transactions or expenditures executed without statutory authority, supporting documents, or in violation of financial rules\",\"option_2\":\"Foreign grant received from abroad\",\"option_3\":\"Employee tax deductions\",\"answer\":1,\"hint\":\"Flagged annually in the Auditor General\\u2019s report under advance arrears, unregularized spending, or misappropriation.\",\"explanation\":\"Beruju represents financial transactions executed contrary to prevailing laws, regulations, or accounting standards, requiring recovery or regularization.\"},{\"question\":\"Under Nepal Public Procurement Act 2063, what is the default and standard method for purchasing public goods and civil works?\",\"options\":[\"Direct sole-source purchase\",\"Open Competitive Bidding\",\"User committee construction without quotation\",\"Secret negotiation\"],\"option_0\":\"Direct sole-source purchase\",\"option_1\":\"Open Competitive Bidding\",\"option_2\":\"User committee construction without quotation\",\"option_3\":\"Secret negotiation\",\"answer\":1,\"hint\":\"Ensures equal opportunity, transparency, and competitive pricing for public value.\",\"explanation\":\"The Public Procurement Act 2063 mandates open competitive national or international bidding as the principal procurement method.\"},{\"question\":\"What is the primary role of a Social Audit in public development projects?\",\"options\":[\"Checking bank account interest rates\",\"Engaging direct beneficiaries and citizens in a public forum to evaluate project expenditure, quality, and service responsiveness\",\"Calculating employee income tax\",\"Filing international patent applications\"],\"option_0\":\"Checking bank account interest rates\",\"option_1\":\"Engaging direct beneficiaries and citizens in a public forum to evaluate project expenditure, quality, and service responsiveness\",\"option_2\":\"Calculating employee income tax\",\"option_3\":\"Filing international patent applications\",\"answer\":1,\"hint\":\"A participatory social accountability tool practiced across local governments in Nepal.\",\"explanation\":\"Social audit brings community members and officials together to transparently review project resources, progress, and public satisfaction.\"}]', 'text', 2, 15, 1, '2026-09-02 03:38:41', '2026-09-02 12:19:39'),
(153, 67, NULL, 'Legal Provisions Related to Public Service Management', 'legal-provisions-related-to-public-service-management', NULL, NULL, 'lessons/pdfs/01M1GQ09MQKDDETESQ6XS9MJXW.pdf', '[{\"question\":\"According to the Civil Service Act 2049 of Nepal, what is the mandatory age of retirement for civil servants?\",\"options\":[\"55 years\",\"58 years\",\"60 years\",\"62 years\"],\"option_0\":\"55 years\",\"option_1\":\"58 years\",\"option_2\":\"60 years\",\"option_3\":\"62 years\",\"answer\":1,\"hint\":\"Prescribed in Section 33 of the Civil Service Act 2049.\",\"explanation\":\"Section 33 of the Civil Service Act 2049 fixes the compulsory retirement age for permanent civil servants at 58 years.\"},{\"question\":\"What is the probation period for newly appointed male and female civil servants respectively?\",\"options\":[\"1 year for both\",\"1 year for male, 6 months for female\",\"6 months for male, 1 year for female\",\"2 years for both\"],\"option_0\":\"1 year for both\",\"option_1\":\"1 year for male, 6 months for female\",\"option_2\":\"6 months for male, 1 year for female\",\"option_3\":\"2 years for both\",\"answer\":1,\"hint\":\"Affirmative action provision under Section 10 of the Civil Service Act.\",\"explanation\":\"Section 10 provides that a female civil servant completes probation in 6 months, whereas a male civil servant requires 1 year.\"},{\"question\":\"What percentage of vacant civil service posts are reserved for inclusive clusters in open recruitment?\",\"options\":[\"33%\",\"45%\",\"50%\",\"55%\"],\"option_0\":\"33%\",\"option_1\":\"45%\",\"option_2\":\"50%\",\"option_3\":\"55%\",\"answer\":1,\"hint\":\"55% is open to all citizens; the remaining 45% is allocated among inclusive categories.\",\"explanation\":\"Section 7(7) of the Civil Service Act 2049 reserves 45% of open recruitment vacancies for specified inclusive categories.\"},{\"question\":\"Which of the following is considered an Ordinary Departmental Punishment under the Civil Service Act?\",\"options\":[\"Dismissal from service with disqualification\",\"Reprimand or withholding grade increment and promotion for up to 2 years\",\"Removal from service without disqualification\",\"Criminal jail sentence\"],\"option_0\":\"Dismissal from service with disqualification\",\"option_1\":\"Reprimand or withholding grade increment and promotion for up to 2 years\",\"option_2\":\"Removal from service without disqualification\",\"option_3\":\"Criminal jail sentence\",\"answer\":1,\"hint\":\"Special punishments involve termination; ordinary penalties involve warnings or grade\\/promotion withholding.\",\"explanation\":\"Section 59 categorizes Nasihat (reprimand) and withholding of promotion\\/grade increments as ordinary departmental punishments.\"},{\"question\":\"Under the Civil Service Code of Conduct, civil servants are strictly prohibited from:\",\"options\":[\"Wearing clean official uniforms\",\"Participating in partisan political campaigns, strikes, or accepting unauthorized gifts\",\"Attending official trainings\",\"Exercising legal delegated authority\"],\"option_0\":\"Wearing clean official uniforms\",\"option_1\":\"Participating in partisan political campaigns, strikes, or accepting unauthorized gifts\",\"option_2\":\"Attending official trainings\",\"option_3\":\"Exercising legal delegated authority\",\"answer\":1,\"hint\":\"Ensures political neutrality, integrity, and undivided loyalty to public duty.\",\"explanation\":\"Sections 41 to 55 mandate political neutrality, punctuality, prohibition of strikes, and non-acceptance of unauthorized gifts by civil servants.\"},{\"question\":\"What is the minimum qualifying service period required for a civil servant to be eligible for lifelong pension in Nepal?\",\"options\":[\"10 years\",\"20 years\",\"25 years\",\"15 years\"],\"option_0\":\"10 years\",\"option_1\":\"20 years\",\"option_2\":\"25 years\",\"option_3\":\"15 years\",\"answer\":1,\"hint\":\"Those retiring before 20 years receive gratuity instead of monthly pension.\",\"explanation\":\"Section 37 of the Civil Service Act specifies that civil servants who have completed 20 years or more of permanent service are entitled to monthly pension.\"},{\"question\":\"Which body evaluates performance appraisals for civil service promotion?\",\"options\":[\"Judicial Service Council\",\"Performance Appraisal Review Committee\",\"Parliamentary Committee\",\"Trade Union Board\"],\"option_0\":\"Judicial Service Council\",\"option_1\":\"Performance Appraisal Review Committee\",\"option_2\":\"Parliamentary Committee\",\"option_3\":\"Trade Union Board\",\"answer\":1,\"hint\":\"Evaluated out of 40 marks annually by Supervisor, Reviewer, and Review Committee.\",\"explanation\":\"Section 24A outlines the 40-mark annual appraisal assessed by the direct supervisor (25 marks), reviewer (10 marks), and review committee (5 marks).\"},{\"question\":\"Under Nepal Contribution-Based Pension Act 2075, what percentage of monthly salary is deducted from a civil servant basic salary for their pension fund?\",\"options\":[\"3%\",\"6%\",\"10%\",\"12%\"],\"option_0\":\"3%\",\"option_1\":\"6%\",\"option_2\":\"10%\",\"option_3\":\"12%\",\"answer\":1,\"hint\":\"Matched equally with 6% contributed by the Government of Nepal (total 12%).\",\"explanation\":\"Under the Pension Fund Act 2075, 6% is deducted from the employee\\u2019s basic salary and matched with 6% from the government.\"},{\"question\":\"How many total days of Casual Leave and Festival Leave is a permanent civil servant entitled to each year?\",\"options\":[\"6 days\",\"12 days in total\",\"18 days\",\"30 days\"],\"option_0\":\"6 days\",\"option_1\":\"12 days in total\",\"option_2\":\"18 days\",\"option_3\":\"30 days\",\"answer\":1,\"hint\":\"Composed of 6 days of casual leave and 6 days of festive leave.\",\"explanation\":\"Rule 55 of the Civil Service Rules grants 6 days of casual leave and 6 days of festive leave, totaling 12 days annually.\"},{\"question\":\"What is the maximum number of days of Home Leave a civil servant can accumulate for cash encashment upon retirement?\",\"options\":[\"90 days\",\"180 days\",\"240 days\",\"365 days\"],\"option_0\":\"90 days\",\"option_1\":\"180 days\",\"option_2\":\"240 days\",\"option_3\":\"365 days\",\"answer\":1,\"hint\":\"Earned at the rate of 1 day for every 12 days of working service.\",\"explanation\":\"A civil servant can accumulate up to 180 days of home leave and 150 days of sick leave, encashable upon retirement.\"}]', 'text', 3, 15, 1, '2026-09-02 03:40:35', '2026-09-02 12:19:39'),
(161, 70, NULL, 'Cellular Mobile Systems & 4G/5G Architecture', 'ntc-cellular-mobile-systems', NULL, NULL, NULL, '[{\"question\":\"In cellular mobile communications, what is the primary purpose of \\\"Frequency Reuse\\\"?\",\"options\":[\"To increase transmission power\",\"To serve higher user capacity using a limited set of radio frequencies\",\"To eliminate the need for base stations\",\"To convert analog signals to digital\"],\"answer\":1,\"hint\":\"Allows reusing identical frequencies in non-adjacent geographic cells.\",\"explanation\":\"Frequency reuse enables cellular networks to drastically increase capacity and spectral efficiency across coverage areas.\"},{\"question\":\"What is the core radio access network technology used in 4G LTE downlink transmission?\",\"options\":[\"CDMA\",\"TDMA\",\"OFDMA (Orthogonal Frequency Division Multiple Access)\",\"FDMA\"],\"answer\":2,\"hint\":\"Divides the wide carrier channel into multiple orthogonal subcarriers.\",\"explanation\":\"4G LTE employs OFDMA in the downlink for high data rates and spectral efficiency, and SC-FDMA in the uplink.\"},{\"question\":\"The central core network component in 4G LTE responsible for user authentication and mobility tracking is:\",\"options\":[\"eNodeB\",\"MME (Mobility Management Entity)\",\"SGW\",\"PGW\"],\"answer\":1,\"hint\":\"Control-plane element managing session states and paging.\",\"explanation\":\"The Mobility Management Entity (MME) is the key control-node for the LTE access-network.\"},{\"question\":\"Which key technology in 5G networks allows partitioning a single physical network into multiple virtual end-to-end networks?\",\"options\":[\"Network Slicing\",\"Circuit Switching\",\"Frequency Hopping\",\"Copper Twinning\"],\"answer\":0,\"hint\":\"Enables tailored network instances for eMBB, URLLC, and mMTC.\",\"explanation\":\"Network Slicing uses NFV and SDN to create isolated virtual networks tailored to distinct service requirements.\"},{\"question\":\"What is the maximum theoretical latency target for 5G Ultra-Reliable Low-Latency Communications (URLLC)?\",\"options\":[\"50 milliseconds\",\"20 milliseconds\",\"1 millisecond\",\"100 milliseconds\"],\"answer\":2,\"hint\":\"Critical for autonomous driving and industrial robotics.\",\"explanation\":\"URLLC in 5G targets end-to-end user-plane latency down to 1 millisecond.\"},{\"question\":\"In optical communications, what physical phenomenon allows light to propagate through the core of an optical fiber cable?\",\"options\":[\"Refraction\",\"Total Internal Reflection (TIR)\",\"Diffraction\",\"Polarization\"],\"answer\":1,\"hint\":\"Occurs when light strikes the core-cladding boundary at an angle greater than the critical angle.\",\"explanation\":\"Light signals propagate inside optical fiber via Total Internal Reflection where refractive index of core is higher than cladding.\"},{\"question\":\"What does DWDM stand for in optical fiber transmission networks?\",\"options\":[\"Digital Wireless Data Management\",\"Dense Wavelength Division Multiplexing\",\"Direct Wave Dual Modulation\",\"Dynamic Wideband Distribution Matrix\"],\"answer\":1,\"hint\":\"Multiplexes multiple optical carrier signals onto a single optical fiber.\",\"explanation\":\"DWDM transmits multiple data channels simultaneously over different wavelengths of laser light on a single fiber strand.\"},{\"question\":\"In fiber-to-the-home (FTTH) networks, what type of passive device is used to split one optical line into 32 or 64 subscriber lines?\",\"options\":[\"Optical Splitter (PLC Splitter)\",\"Optical Amplifier\",\"Active Router\",\"Modem\"],\"answer\":0,\"hint\":\"Passive Optical Network (PON) component that requires no electrical power.\",\"explanation\":\"Passive Optical Splitters divide the incoming optical signal among multiple end-users in GPON\\/EPON architectures.\"},{\"question\":\"Which IPv4 address class provides a default subnet mask of 255.255.0.0 (\\/16)?\",\"options\":[\"Class A\",\"Class B\",\"Class C\",\"Class D\"],\"answer\":1,\"hint\":\"Ranges from 128.0.0.0 to 191.255.255.255.\",\"explanation\":\"Class B networks use the first two octets for network ID (default \\/16 mask 255.255.0.0).\"},{\"question\":\"Which protocol is used for dynamically assigning IP addresses and network parameters to client devices?\",\"options\":[\"DNS\",\"DHCP (Dynamic Host Configuration Protocol)\",\"SNMP\",\"BGP\"],\"answer\":1,\"hint\":\"Operates on UDP ports 67 and 68.\",\"explanation\":\"DHCP dynamically provides IP address, subnet mask, default gateway, and DNS server IPs to network clients.\"}]', 'text', 1, 15, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(162, 70, NULL, 'IP Routing, Switching & Network Security', 'ntc-ip-routing-switching', NULL, NULL, NULL, '[{\"question\":\"Which routing protocol is an exterior gateway protocol (EGP) used for routing between Autonomous Systems on the Internet?\",\"options\":[\"OSPF\",\"RIP\",\"BGP (Border Gateway Protocol)\",\"EIGRP\"],\"answer\":2,\"hint\":\"The fundamental routing protocol of the global Internet.\",\"explanation\":\"BGP is the standardized exterior gateway protocol designed to exchange routing and reachability information among autonomous systems.\"},{\"question\":\"OSPF (Open Shortest Path First) uses which algorithm to compute the best loop-free path?\",\"options\":[\"Bellman-Ford Algorithm\",\"Dijkstra\\u2019s Shortest Path First (SPF) Algorithm\",\"Floyd-Warshall Algorithm\",\"Kruskal\\u2019s Algorithm\"],\"answer\":1,\"hint\":\"Link-state algorithm developed by Edsger Dijkstra.\",\"explanation\":\"OSPF uses Dijkstra\\u2019s algorithm to build a shortest path tree from the link-state database.\"},{\"question\":\"At which layer of the OSI model does a standard Ethernet Switch operate?\",\"options\":[\"Physical Layer (Layer 1)\",\"Data Link Layer (Layer 2)\",\"Network Layer (Layer 3)\",\"Transport Layer (Layer 4)\"],\"answer\":1,\"hint\":\"Forwards frames based on MAC addresses.\",\"explanation\":\"Layer 2 switches forward traffic based on hardware Media Access Control (MAC) addresses in the Data Link Layer.\"},{\"question\":\"What is the bit length of an IPv6 address compared to an IPv4 address?\",\"options\":[\"32 bits vs 16 bits\",\"64 bits vs 32 bits\",\"128 bits vs 32 bits\",\"256 bits vs 64 bits\"],\"answer\":2,\"hint\":\"IPv6 provides 2^128 unique addresses.\",\"explanation\":\"IPv6 addresses are 128 bits long (written in hexadecimal), whereas IPv4 addresses are 32 bits.\"},{\"question\":\"What is the purpose of Virtual Local Area Network (VLAN) defined under IEEE 802.1Q?\",\"options\":[\"Increasing physical wire resistance\",\"Logically segmenting a physical network into multiple isolated broadcast domains\",\"Converting fiber signals to copper\",\"Encrypting hard drives\"],\"answer\":1,\"hint\":\"Provides network isolation and traffic management on switches.\",\"explanation\":\"VLANs divide a single physical switch into multiple logical networks for security, traffic control, and broadcast isolation.\"},{\"question\":\"Which security protocol provides encrypted communication and secure web browsing over port 443?\",\"options\":[\"HTTP\",\"HTTPS (TLS\\/SSL)\",\"FTP\",\"Telnet\"],\"answer\":1,\"hint\":\"Uses Transport Layer Security to encrypt client-server communication.\",\"explanation\":\"HTTPS uses TLS\\/SSL encryption to secure HTTP communication over TCP port 443.\"},{\"question\":\"What type of cyberattack floods a target telecom server or network with excessive traffic to make it unavailable to legitimate users?\",\"options\":[\"Phishing Attack\",\"DDoS (Distributed Denial of Service) Attack\",\"SQL Injection\",\"Man-in-the-Middle Attack\"],\"answer\":1,\"hint\":\"Uses distributed botnets to overwhelm bandwidth.\",\"explanation\":\"DDoS attacks overwhelm network bandwidth or system resources with flood traffic from compromised hosts.\"},{\"question\":\"In public key cryptography (asymmetric encryption), if data is encrypted with a recipient\\u2019s Public Key, it can only be decrypted by:\",\"options\":[\"Sender\\u2019s Public Key\",\"Recipient\\u2019s Private Key\",\"Sender\\u2019s Private Key\",\"Any intermediate router\"],\"answer\":1,\"hint\":\"Only the intended recipient possesses the matching secret key.\",\"explanation\":\"Asymmetric encryption ensures confidentiality: plaintext encrypted with the public key is decipherable only with the corresponding private key.\"},{\"question\":\"Which network protocol operates on port 53 and translates domain names (e.g., ntc.net.np) into IP addresses?\",\"options\":[\"DHCP\",\"DNS (Domain Name System)\",\"SMTP\",\"NTP\"],\"answer\":1,\"hint\":\"The phonebook of the Internet.\",\"explanation\":\"DNS maps human-friendly hostnames to numerical IP addresses.\"},{\"question\":\"In telecom network operations, what does MPLS stand for?\",\"options\":[\"Multi-Protocol Label Switching\",\"Mobile Packet Line System\",\"Maximum Protection Layer Standard\",\"Multiple Point Link Synchronizer\"],\"answer\":0,\"hint\":\"High-performance telecommunications network routing technique using short path labels.\",\"explanation\":\"MPLS speeds up network traffic flow by using short path labels rather than complex lookups in a routing table.\"}]', 'text', 2, 15, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(163, 71, NULL, 'Telecommunications Act 2053 & NTA Regulatory Framework', 'ntc-telecommunications-act', NULL, NULL, NULL, '[{\"question\":\"The Telecommunications Act of Nepal was enacted in which Bikram Sambat year?\",\"options\":[\"2049 BS\",\"2053 BS\",\"2058 BS\",\"2064 BS\"],\"answer\":1,\"hint\":\"Established Nepal Telecommunications Authority (NTA) as the regulatory body.\",\"explanation\":\"The Telecommunications Act 2053 was enacted to regulate and develop telecommunications services in Nepal.\"},{\"question\":\"Who appoints the Chairman and members of the Nepal Telecommunications Authority (NTA)?\",\"options\":[\"Managing Director of Nepal Telecom\",\"Government of Nepal (Council of Ministers)\",\"Public Service Commission\",\"Parliamentary Committee\"],\"answer\":1,\"hint\":\"Appointed by the federal executive government upon recommendation.\",\"explanation\":\"Under Section 5 of the Telecommunications Act 2053, the Government of Nepal appoints the Chairman and members of NTA.\"},{\"question\":\"What is the Rural Telecommunication Development Fund (RTDF) established under the Telecom Act used for?\",\"options\":[\"Paying corporate dividends\",\"Developing, expanding, and operating telecommunication services in rural and remote areas of Nepal\",\"Covering international marketing expenses\",\"Purchasing private telecom company shares\"],\"answer\":1,\"hint\":\"Financed by a 2% levy on gross income of licensed telecom service providers.\",\"explanation\":\"Section 30 of the Act creates RTDF to bridge the digital divide by financing telecom infrastructure in remote areas.\"},{\"question\":\"What percentage of gross annual income must licensed telecom operators contribute to the RTDF in Nepal?\",\"options\":[\"1%\",\"2%\",\"5%\",\"10%\"],\"answer\":1,\"hint\":\"Mandatory statutory contribution deducted annually.\",\"explanation\":\"Licensed telecommunication service providers must contribute 2% of their annual gross revenue to the RTDF.\"},{\"question\":\"Which regulatory body in Nepal is responsible for radio frequency allocation and pricing for mobile cellular networks?\",\"options\":[\"Nepal Telecom Management\",\"Radio Frequency Policy Determination Committee \\/ NTA\",\"Tribhuvan University\",\"Department of Information Technology\"],\"answer\":1,\"hint\":\"Determined under the Telecommunications Act and national frequency policy.\",\"explanation\":\"Frequency allocation and spectrum management are determined by the Radio Frequency Policy Determination Committee under Section 49.\"},{\"question\":\"In telecom operations, what does MTTR stand for as a key performance indicator (KPI)?\",\"options\":[\"Maximum Total Transmission Rate\",\"Mean Time to Repair \\/ Resolve\",\"Mobile Terminal Tower Radius\",\"Managed Traffic Threshold Ratio\"],\"answer\":1,\"hint\":\"Measures the average time required to troubleshoot and fix a network fault.\",\"explanation\":\"Mean Time to Repair (MTTR) is a critical QoS metric representing the average time taken to restore service after failure.\"},{\"question\":\"What is \\\"Number Portability (MNP)\\\" in telecommunications regulation?\",\"options\":[\"Changing phone numbers every month\",\"Enabling subscribers to retain their existing mobile number when switching service providers\",\"Exporting mobile devices overseas\",\"Merging multiple SIM cards into one\"],\"answer\":1,\"hint\":\"Promotes competitive service choice for consumers without losing phone contacts.\",\"explanation\":\"Mobile Number Portability allows a mobile phone customer to keep their number when changing telecom operators.\"},{\"question\":\"Which service provides customer authentication and billing records by logging CDRs (Call Detail Records)?\",\"options\":[\"OSS\\/BSS (Operations and Business Support Systems)\",\"DNS Server\",\"DHCP Relay\",\"Tower Mast\"],\"answer\":0,\"hint\":\"Enterprise software suite managing customer accounts, billing, and network operations.\",\"explanation\":\"BSS\\/OSS systems manage billing, rating, subscription lifecycles, and network inventory for telecom carriers.\"},{\"question\":\"Under Nepal Telecommunications Regulations, tapping or listening to private telephone conversations without judicial warrant is:\",\"options\":[\"Permitted for all employees\",\"Strictly prohibited and punishable by law\",\"Encouraged for marketing surveys\",\"Allowed on public holidays\"],\"answer\":1,\"hint\":\"Violates the constitutional right to privacy.\",\"explanation\":\"Unauthorized interception or wiretapping of telecom transmissions is a criminal offense under the Telecommunications Act.\"},{\"question\":\"Nepal Telecom (Nepal Doorsanchar Company Limited) was transformed from a statutory corporation into a public limited company in which year?\",\"options\":[\"2050 BS\",\"2055 BS\",\"2060 BS\",\"2068 BS\"],\"answer\":2,\"hint\":\"Converted on Baisakh 1, 2060 BS (2004 AD) under the Companies Act.\",\"explanation\":\"Nepal Telecom was incorporated as a public limited company on 1st Baisakh 2060 BS (April 14, 2004 AD).\"}]', 'text', 1, 15, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(164, 63, NULL, 'Demand Elasticity, Market Equilibrium & Pricing', 'nrb-demand-elasticity-pricing', NULL, NULL, NULL, '[{\"question\":\"If a 10% increase in price leads to a 20% decrease in quantity demanded, the price elasticity of demand (Ed) is:\",\"options\":[\"0.5 (Inelastic)\",\"1.0 (Unitary)\",\"2.0 (Elastic)\",\"Zero\"],\"answer\":2,\"hint\":\"Elasticity = (% Change in Quantity) \\/ (% Change in Price) = 20 \\/ 10.\",\"explanation\":\"Ed = 20% \\/ 10% = 2.0 (greater than 1, hence demand is price elastic).\"},{\"question\":\"When cross-price elasticity of demand between two goods is positive, the goods are:\",\"options\":[\"Complementary Goods\",\"Substitute Goods\",\"Inferior Goods\",\"Giffen Goods\"],\"answer\":1,\"hint\":\"An increase in the price of one good raises demand for the other (e.g. Tea and Coffee).\",\"explanation\":\"Positive cross-elasticity means when price of Good Y increases, demand for Good X increases (Substitute goods).\"},{\"question\":\"In a perfectly competitive market, the horizontal demand curve faced by an individual firm is equal to:\",\"options\":[\"Marginal Cost\",\"Marginal Revenue and Average Revenue (P = AR = MR)\",\"Total Revenue\",\"Average Fixed Cost\"],\"answer\":1,\"hint\":\"Firms are price takers in perfect competition.\",\"explanation\":\"Under perfect competition, the firm is a price taker, so Price = Average Revenue = Marginal Revenue (P = AR = MR).\"},{\"question\":\"What is the condition for profit maximization for any firm in the short run?\",\"options\":[\"Total Revenue = Total Cost\",\"Marginal Revenue = Marginal Cost (MR = MC)\",\"Price = Average Fixed Cost\",\"Average Revenue = Zero\"],\"answer\":1,\"hint\":\"Occurs where the additional revenue from the last unit equals its additional cost.\",\"explanation\":\"Profit is maximized where Marginal Revenue equals Marginal Cost (MR = MC) and MC cuts MR from below.\"},{\"question\":\"A market structure characterized by a single seller of a unique product with high entry barriers is called:\",\"options\":[\"Monopoly\",\"Oligopoly\",\"Monopolistic Competition\",\"Duopoly\"],\"answer\":0,\"hint\":\"Price maker market with no close substitutes.\",\"explanation\":\"Monopoly is a market structure with a single firm controlling the entire market supply.\"},{\"question\":\"Which macroeconomic curve shows the inverse short-run relationship between inflation and unemployment?\",\"options\":[\"Lorenz Curve\",\"Phillips Curve\",\"Kuznets Curve\",\"Laffer Curve\"],\"answer\":1,\"hint\":\"Developed by A.W. Phillips in 1958.\",\"explanation\":\"The Phillips Curve demonstrates that in the short run, lower unemployment is associated with higher inflation.\"},{\"question\":\"The Gini Coefficient is a standard economic metric used to measure:\",\"options\":[\"Inflation rate\",\"Income inequality and wealth distribution\",\"Unemployment percentage\",\"Currency depreciation\"],\"answer\":1,\"hint\":\"Ranges from 0 (perfect equality) to 1 (complete inequality).\",\"explanation\":\"The Gini Coefficient derived from the Lorenz Curve measures the degree of income or wealth inequality.\"},{\"question\":\"In national income accounting, GDP at market price minus Net Indirect Taxes equals:\",\"options\":[\"Gross National Product\",\"GDP at Factor Cost\",\"Net National Product\",\"Personal Disposable Income\"],\"answer\":1,\"hint\":\"Factor cost excludes indirect taxes and includes subsidies.\",\"explanation\":\"GDP at Factor Cost = GDP at Market Price - Indirect Taxes + Subsidies.\"},{\"question\":\"What is \\\"Stagflation\\\" in macroeconomic theory?\",\"options\":[\"High economic growth with falling prices\",\"Stagnant economic growth and high unemployment accompanied by high inflation\",\"Zero interest rates with rapid exports\",\"Rapid budget surplus with deflation\"],\"answer\":1,\"hint\":\"Combination of stagnation and inflation.\",\"explanation\":\"Stagflation occurs when an economy experiences slow growth, high unemployment, and rising inflation simultaneously.\"},{\"question\":\"According to the Keynesian consumption function C = a + bY, what does \\\"b\\\" represent?\",\"options\":[\"Autonomous Consumption\",\"Marginal Propensity to Consume (MPC)\",\"Average Propensity to Save\",\"Investment Multiplier\"],\"answer\":1,\"hint\":\"The change in consumption resulting from a one-unit change in disposable income (dC\\/dY).\",\"explanation\":\"In C = a + bY, \\\"a\\\" is autonomous consumption and \\\"b\\\" is the Marginal Propensity to Consume (MPC).\"}]', 'text', 1, 15, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(165, 63, NULL, 'Monetary Policy, Central Banking & Money Supply', 'nrb-monetary-policy-central-banking', NULL, NULL, NULL, '[{\"question\":\"What is the primary statutory objective of Nepal Rastra Bank under Section 4 of the NRB Act 2058?\",\"options\":[\"Maximizing commercial banking profits\",\"Maintaining price, financial and external sector stability to support sustainable economic growth\",\"Collecting personal income tax\",\"Managing stock market IPOs\"],\"answer\":1,\"hint\":\"Prescribed as the prime objective of the central bank.\",\"explanation\":\"Under NRB Act Section 4, the primary objective is maintaining price stability, external sector stability, and financial stability.\"},{\"question\":\"Which monetary policy instrument requires commercial banks to maintain a mandatory percentage of their total deposits with the central bank in cash?\",\"options\":[\"Statutory Liquidity Ratio (SLR)\",\"Cash Reserve Ratio (CRR)\",\"Bank Rate\",\"Policy Repo Rate\"],\"answer\":1,\"hint\":\"Compulsory cash deposit held at NRB without interest.\",\"explanation\":\"Cash Reserve Ratio (CRR) is the minimum percentage of total customer deposits that commercial banks must hold as reserves at NRB.\"},{\"question\":\"When Nepal Rastra Bank wants to absorb excess liquidity from the banking system, which open market operation does it conduct?\",\"options\":[\"Outright Purchase\",\"Reverse Repo \\/ Deposit Collection Auction\",\"Lowering CRR\",\"Slashing Bank Rate\"],\"answer\":1,\"hint\":\"Central bank sells securities or invites interest-bearing deposits from commercial banks.\",\"explanation\":\"NRB issues Reverse Repo or Deposit Collection tools to mop up surplus liquidity from the interbank market.\"},{\"question\":\"Broad Money Supply (M2) in Nepal includes Narrow Money (M1) plus:\",\"options\":[\"Currency in circulation only\",\"Time Deposits (Fixed and Savings deposits)\",\"Foreign direct investment\",\"Government Treasury bills\"],\"answer\":1,\"hint\":\"M2 = M1 (Currency + Demand deposits) + Time\\/Quasi-money deposits.\",\"explanation\":\"Broad Money (M2) consists of Narrow Money (M1) and time\\/saving deposits with the banking sector.\"},{\"question\":\"What is the \\\"Bank Rate\\\" prescribed by Nepal Rastra Bank?\",\"options\":[\"The rate at which banks lend to personal borrowers\",\"The discount\\/lending rate at which NRB extends lender-of-last-resort credit to licensed BFIs\",\"The average fixed deposit interest rate\",\"The inflation rate\"],\"answer\":1,\"hint\":\"Apex central bank refinancing rate under the Interest Rate Corridor.\",\"explanation\":\"The Bank Rate is the rate at which NRB provides standing liquidity or lender-of-last-resort credit to banks.\"},{\"question\":\"The \\\"Interest Rate Corridor (IRC)\\\" implemented by Nepal Rastra Bank is designed to:\",\"options\":[\"Fix all consumer loan rates permanently\",\"Minimize volatility in short-term interbank interest rates within a standing ceiling and floor\",\"Eliminate all banking profits\",\"Manage foreign exchange reserves only\"],\"answer\":1,\"hint\":\"Comprises Standing Liquidity Facility (ceiling), Policy Rate, and Deposit Collection Rate (floor).\",\"explanation\":\"The Interest Rate Corridor stabilizes short-term market interest rates around the target policy rate.\"},{\"question\":\"What is the Credit-to-Deposit (CD) ratio ceiling currently prescribed by NRB for commercial banks in Nepal?\",\"options\":[\"75%\",\"80%\",\"90%\",\"95%\"],\"answer\":2,\"hint\":\"Limits total credit advances relative to total domestic deposits.\",\"explanation\":\"NRB unified directives mandate that commercial banks must maintain their CD ratio within the 90% prudential limit.\"},{\"question\":\"Which department within Nepal Rastra Bank is responsible for formulating and implementing national monetary policy?\",\"options\":[\"Bank Supervision Department\",\"Monetary Policy Department\",\"Foreign Exchange Management Department\",\"Payment Systems Department\"],\"answer\":1,\"hint\":\"Drafts the annual and half-yearly monetary review documents.\",\"explanation\":\"The Monetary Policy Department of NRB analyzes macroeconomic indicators and designs monetary instruments.\"},{\"question\":\"The process where an initial deposit generates a multiple expansion of credit across the banking system is called:\",\"options\":[\"Deposit Multiplier \\/ Money Creation Process\",\"Hyperinflation\",\"Fiscal Drag\",\"Capital Depreciation\"],\"answer\":0,\"hint\":\"Money Multiplier = 1 \\/ Reserve Requirement.\",\"explanation\":\"Commercial banks create derivative deposits through the fractional reserve banking money multiplier process.\"},{\"question\":\"What does \\\"Lender of Last Resort (LOLR)\\\" mean in central banking operations?\",\"options\":[\"NRB lends only to foreign governments\",\"NRB provides emergency liquidity to solvent banks facing acute liquidity stress when no market alternative exists\",\"NRB borrows from private money lenders\",\"NRB liquidates all failing businesses\"],\"answer\":1,\"hint\":\"A classic central bank responsibility formulated by Walter Bagehot.\",\"explanation\":\"As lender of last resort, the central bank provides emergency liquidity support to prevent systemic banking runs and panic.\"}]', 'text', 2, 15, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(166, 72, NULL, 'NRB Act 2058 & BAFIA 2073 Governance', 'nrb-act-bafia-governance', NULL, NULL, NULL, '[{\"question\":\"How many members constitute the Board of Directors of Nepal Rastra Bank under Section 14 of the NRB Act 2058?\",\"options\":[\"5 members\",\"7 members\",\"9 members\",\"11 members\"],\"answer\":1,\"hint\":\"Comprises Governor, Finance Secretary, 2 Deputy Governors, and 3 appointed experts.\",\"explanation\":\"The Board of Directors of NRB consists of 7 members: Governor (Chairman), Secretary of Finance, two Deputy Governors, and three nominated experts.\"},{\"question\":\"Who appoints the Governor of Nepal Rastra Bank as per the NRB Act 2058?\",\"options\":[\"President of Nepal\",\"Government of Nepal (Council of Ministers) on recommendation of a 3-member committee\",\"Public Service Commission\",\"Parliamentary Finance Committee\"],\"answer\":1,\"hint\":\"The recommendation committee is chaired by the Finance Minister.\",\"explanation\":\"The Council of Ministers appoints the Governor from among three names recommended by a committee headed by the Finance Minister.\"},{\"question\":\"What is the tenure of the Governor and Deputy Governors of Nepal Rastra Bank?\",\"options\":[\"3 years\",\"4 years\",\"5 years\",\"6 years\"],\"answer\":2,\"hint\":\"Standard five-year term with eligibility for reappointment provisions.\",\"explanation\":\"Under Section 18 of the NRB Act 2058, the term of office of the Governor and Deputy Governors is 5 years.\"},{\"question\":\"Under the Bank and Financial Institutions Act 2073 (BAFIA), banks and financial institutions in Nepal are categorized into how many classes?\",\"options\":[\"Two classes (Commercial & Development)\",\"Three classes (A, B, C)\",\"Four classes (\\\"A\\\" Commercial, \\\"B\\\" Development, \\\"C\\\" Finance, \\\"D\\\" Microfinance)\",\"Five classes\"],\"answer\":2,\"hint\":\"Class A, Class B, Class C, and Class D institutions.\",\"explanation\":\"BAFIA 2073 categorizes BFIs into four classes: Class \\\"A\\\" (Commercial Banks), Class \\\"B\\\" (Development Banks), Class \\\"C\\\" (Finance Companies), and Class \\\"D\\\" (Microfinance Financial Institutions).\"},{\"question\":\"According to BAFIA 2073, what is the minimum percentage of shares that must be allocated to the general public (IPO) upon establishment of a bank?\",\"options\":[\"15%\",\"30%\",\"49%\",\"51%\"],\"answer\":1,\"hint\":\"Promoters generally hold 70% while 30% is issued to the general public.\",\"explanation\":\"Section 9 of BAFIA 2073 requires BFIs to allocate at least 30% of their total issued capital to the general public.\"},{\"question\":\"Under Anti-Money Laundering (AML\\/CFT) Act 2064, banks are required to report Cash Transactions (CTR) exceeding which threshold to the Financial Information Unit (FIU)?\",\"options\":[\"NPR 5 Lakhs\",\"NPR 10 Lakhs\",\"NPR 25 Lakhs\",\"NPR 50 Lakhs\"],\"answer\":1,\"hint\":\"Standard threshold for mandatory cash transaction reporting in Nepal.\",\"explanation\":\"Under AML\\/CFT regulations, all cash transactions of NPR 10 Lakhs or above in a single day must be reported to the FIU.\"},{\"question\":\"The Financial Information Unit (FIU-Nepal) is established under which statutory authority?\",\"options\":[\"Ministry of Home Affairs\",\"Nepal Rastra Bank (under AML Act 2064)\",\"Nepal Police CIB\",\"Department of Money Laundering Investigation\"],\"answer\":1,\"hint\":\"Autonomous national financial intelligence agency located at NRB.\",\"explanation\":\"The Financial Information Unit (FIU-Nepal) operates as an independent national agency within Nepal Rastra Bank under the AML Act 2064.\"},{\"question\":\"In banking supervision, what does the CAMELS supervisory rating framework evaluate?\",\"options\":[\"Only foreign exchange profits\",\"Capital adequacy, Asset quality, Management, Earnings, Liquidity, and Sensitivity to market risk\",\"Customer marketing campaigns\",\"Corporate social responsibility scores\"],\"answer\":1,\"hint\":\"International bank assessment methodology used by central banks.\",\"explanation\":\"CAMELS evaluates Capital Adequacy (C), Asset Quality (A), Management (M), Earnings (E), Liquidity (L), and Sensitivity to Market Risk (S).\"},{\"question\":\"Under Basel III capital requirements implemented by NRB, what is the minimum total capital adequacy ratio (CAR) for commercial banks in Nepal including capital conservation buffer?\",\"options\":[\"8%\",\"10%\",\"11%\",\"15%\"],\"answer\":2,\"hint\":\"Includes 8.5% Tier 1 plus 2.5% Capital Conservation Buffer.\",\"explanation\":\"NRB Capital Adequacy Framework mandates a minimum Total Capital Adequacy Ratio of 11.0% (including 2.5% CCB) for Class \\\"A\\\" commercial banks.\"},{\"question\":\"What is the maximum single borrower credit limit (Single Borrower Limit - SBL) for fund-based loans under NRB Unified Directives?\",\"options\":[\"15% of Core Capital\",\"25% of Core Capital\",\"50% of Core Capital\",\"100% of Total Assets\"],\"answer\":1,\"hint\":\"Prevents concentration risk to a single borrower or corporate group.\",\"explanation\":\"NRB directives limit fund-based exposure to a single borrower or related group to a maximum of 25% of the bank\\u2019s Tier 1 Core Capital.\"}]', 'text', 1, 15, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(167, 73, NULL, 'Balance of Payments, Forex Reserves & Exchange Rate Management', 'nrb-ad-bop-forex-management', NULL, NULL, NULL, '[{\"question\":\"Nepal maintains a conventional fixed\\/pegged exchange rate system with which foreign currency?\",\"options\":[\"US Dollar (USD)\",\"Indian Rupee (INR)\",\"Euro (EUR)\",\"Chinese Yuan (CNY)\"],\"answer\":1,\"hint\":\"Fixed at NPR 160 per INR 100.\",\"explanation\":\"The Nepalese Rupee has been pegged to the Indian Rupee at the fixed rate of 1.60 (NPR 160 = INR 100) since 1993 AD.\"},{\"question\":\"In the Balance of Payments (BOP), workers\\u2019 remittances sent from abroad are recorded under which account?\",\"options\":[\"Capital Account\",\"Secondary Income Account within Current Account\",\"Direct Investment in Financial Account\",\"Official Reserves Account\"],\"answer\":1,\"hint\":\"Classified as current unilateral transfers without a financial claim.\",\"explanation\":\"Personal remittances are recorded under the Secondary Income component of the Current Account in the standard IMF BPM6 framework.\"},{\"question\":\"What does an increase in Real Effective Exchange Rate (REER) above 100 typically indicate for an economy?\",\"options\":[\"Loss of export competitiveness due to domestic currency overvaluation\",\"Gain in export competitiveness\",\"Immediate zero trade balance\",\"Absolute price deflation\"],\"answer\":0,\"hint\":\"Indicates that domestic goods have become relatively more expensive compared to trading partners.\",\"explanation\":\"An appreciation in REER indicates that the domestic currency is overvalued relative to trade partners, eroding export price competitiveness.\"},{\"question\":\"What is the statutory minimum threshold of foreign exchange reserves target maintained by NRB in terms of prospective merchandise and service imports?\",\"options\":[\"At least 3 months\",\"At least 7 months\",\"At least 12 months\",\"At least 24 months\"],\"answer\":1,\"hint\":\"Policy benchmark specified in the annual Monetary Policy of Nepal.\",\"explanation\":\"NRB Monetary Policy benchmark aims to maintain sufficient gross foreign exchange reserves to cover at least 7 months of prospective imports of goods and services.\"},{\"question\":\"Special Drawing Rights (SDR) is an international reserve asset created by which organization?\",\"options\":[\"World Bank\",\"International Monetary Fund (IMF)\",\"Bank for International Settlements (BIS)\",\"World Trade Organization (WTO)\"],\"answer\":1,\"hint\":\"Based on a basket of 5 currencies (USD, EUR, CNY, JPY, GBP).\",\"explanation\":\"The SDR is an interest-bearing international reserve asset created by the IMF in 1969 to supplement member countries\\u2019 official reserves.\"},{\"question\":\"Which financial account item represents cross-border investment where an investor acquires a lasting management interest (10% or more voting power)?\",\"options\":[\"Foreign Portfolio Investment (FPI)\",\"Foreign Direct Investment (FDI)\",\"Trade Credit\",\"Commercial Loan\"],\"answer\":1,\"hint\":\"Involves lasting interest and active management control.\",\"explanation\":\"FDI reflects the objective of establishing a lasting interest by a resident in one economy in an enterprise in another economy (standard threshold 10%+).\"},{\"question\":\"Under Foreign Exchange (Regulation) Act 2019 of Nepal, who holds the exclusive power to regulate and license foreign currency transactions?\",\"options\":[\"Ministry of Finance\",\"Nepal Rastra Bank\",\"Customs Department\",\"Commercial Banks Federation\"],\"answer\":1,\"hint\":\"Central bank is the sole foreign exchange regulator in Nepal.\",\"explanation\":\"Nepal Rastra Bank is the designated regulator for foreign exchange transactions and licensing in Nepal under the Forex Act 2019.\"},{\"question\":\"What does \\\"Current Account Convertibility\\\" mean?\",\"options\":[\"Freedom to convert local currency for trade in goods, services, travel, and interest payments without restrictions\",\"Freedom to buy overseas real estate and stocks\",\"Total conversion of paper money into gold coins\",\"Banning all foreign bank accounts\"],\"answer\":0,\"hint\":\"IMF Article VIII obligation adopted by Nepal in 1994.\",\"explanation\":\"Current account convertibility allows unrestricted purchase and sale of foreign exchange for international trade and service transactions.\"},{\"question\":\"When imports of goods exceed exports of goods in a nation\\u2019s trade ledger, the economy experiences a:\",\"options\":[\"Trade Surplus\",\"Trade Deficit (Merchandise Trade Deficit)\",\"Budget Surplus\",\"Capital Surplus\"],\"answer\":1,\"hint\":\"A chronic structural feature of Nepal\\u2019s foreign trade.\",\"explanation\":\"A trade deficit occurs when a country\\u2019s merchandise imports exceed its merchandise exports.\"},{\"question\":\"Which international bank based in Basel, Switzerland is known as the \\\"central bank of central banks\\\"?\",\"options\":[\"International Monetary Fund (IMF)\",\"Bank for International Settlements (BIS)\",\"European Central Bank (ECB)\",\"Federal Reserve\"],\"answer\":1,\"hint\":\"Hosts the Basel Committee on Banking Supervision (BCBS).\",\"explanation\":\"The Bank for International Settlements (BIS) fosters international monetary and financial cooperation and serves as a bank for central banks.\"}]', 'text', 1, 15, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(170, 65, NULL, 'MS Word, Excel & Office Productivity Mastery', 'comp-ms-word-excel-mastery', NULL, NULL, NULL, '[{\"question\":\"In Microsoft Word, which feature is used to produce personalized letters, labels, and envelopes to multiple recipients from a single template?\",\"options\":[\"AutoCorrect\",\"Mail Merge\",\"Macros\",\"Cross-reference\"],\"answer\":1,\"hint\":\"Combines a main document with a recipient data source.\",\"explanation\":\"Mail Merge merges a master document with a data source (e.g. Excel spreadsheet) to generate customized copies for multiple recipients.\"},{\"question\":\"What is the default shortcut key in MS Word to create a hanging indent for citations?\",\"options\":[\"Ctrl + T\",\"Ctrl + H\",\"Ctrl + I\",\"Ctrl + M\"],\"answer\":0,\"hint\":\"Indents all lines of a paragraph except the first line.\",\"explanation\":\"Ctrl + T creates a hanging indent, while Ctrl + M increases the left indent.\"},{\"question\":\"In Microsoft Excel, which formula searches for a value in the leftmost column of a table and returns a value in the same row from a specified column?\",\"options\":[\"HLOOKUP\",\"VLOOKUP\",\"COUNTIF\",\"CONCATENATE\"],\"answer\":1,\"hint\":\"V stands for Vertical lookup.\",\"explanation\":\"VLOOKUP(lookup_value, table_array, col_index_num, [range_lookup]) performs a vertical search down the first column.\"},{\"question\":\"In MS Excel, what is the purpose of placing a dollar sign ($) before row and column references (e.g., $A$1)?\",\"options\":[\"Formatting the cell as US currency\",\"Creating an Absolute Cell Reference that does not change when copied to other cells\",\"Multiplying the cell value by 100\",\"Locking the workbook with password\"],\"answer\":1,\"hint\":\"Prevents the cell coordinates from shifting during autofill\\/copy.\",\"explanation\":\"$A$1 is an absolute reference ensuring the column and row remain fixed when the formula is replicated.\"},{\"question\":\"Which Excel feature summarizes large datasets into aggregated tables showing sums, averages, and counts without writing formulas?\",\"options\":[\"Data Validation\",\"PivotTable\",\"Goal Seek\",\"Text to Columns\"],\"answer\":1,\"hint\":\"Interactive tool for multidimensional data analysis and crosstabulation.\",\"explanation\":\"A PivotTable dynamically reorganizes, aggregates, and summarizes complex worksheets for business reporting.\"},{\"question\":\"In MS PowerPoint, what master slide view controls the universal theme fonts, colors, background styles, and logo placement across all slides?\",\"options\":[\"Slide Master View\",\"Handout Master\",\"Notes Page View\",\"Outline View\"],\"answer\":0,\"hint\":\"Top slide in the hierarchy storing presentation-wide formatting.\",\"explanation\":\"The Slide Master stores information about theme and layout settings applied globally across the entire presentation.\"},{\"question\":\"In Microsoft Access relational database, what key uniquely identifies each record in a table and prevents duplicate rows?\",\"options\":[\"Foreign Key\",\"Primary Key\",\"Candidate Key\",\"Composite Index\"],\"answer\":1,\"hint\":\"A unique identifier containing non-null unique values for every record.\",\"explanation\":\"A Primary Key is a field or combination of fields that uniquely identifies each record in a database table.\"},{\"question\":\"Which SQL command is used to retrieve specific columns from a database table based on a condition?\",\"options\":[\"UPDATE\",\"SELECT ... FROM ... WHERE\",\"INSERT INTO\",\"DROP TABLE\"],\"answer\":1,\"hint\":\"Standard data query language statement.\",\"explanation\":\"SELECT column_names FROM table_name WHERE condition; is the standard SQL query syntax.\"},{\"question\":\"What is the keyboard shortcut to immediately open Windows Task Manager in Windows 10\\/11?\",\"options\":[\"Ctrl + Alt + Del\",\"Ctrl + Shift + Esc\",\"Win + R\",\"Alt + F4\"],\"answer\":1,\"hint\":\"Direct one-step shortcut that bypasses the security screen.\",\"explanation\":\"Ctrl + Shift + Esc directly opens Windows Task Manager without intermediate prompt screens.\"},{\"question\":\"Which network command-line utility is used to test reachability and packet round-trip time (latency) to an IP address or domain?\",\"options\":[\"ipconfig\",\"ping\",\"tracert\",\"nslookup\"],\"answer\":1,\"hint\":\"Sends ICMP Echo Request packets to the target host.\",\"explanation\":\"The ping utility sends ICMP Echo Request messages to verify network layer connectivity and measure round-trip time.\"}]', 'text', 1, 15, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(679, 140, 185, '1.1 Physical, Social and Economic Geography of Nepal and the World', '11-physical-social-and-economic-geography-of-nepal-and-the-world-185', '<div class=\"space-y-6\">\n    <p class=\"text-sm font-medium text-emerald-800 bg-emerald-50 p-4 rounded-2xl border border-emerald-200\">\n        Below are PSC Section Officer exam-oriented notes for Topic 1.1 (Geography). The notes focus on concepts, Nepal-specific physical/social/economic geography, international atmospheric frameworks, important facts, and likely analytical areas for both objective and subjective questions.\n    </p>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. WORLD GEOGRAPHY</h2>\n    \n    <h3 class=\"text-base font-bold text-gray-900\">1. Earth Movements, Coordinates and Solar Time</h3>\n    <p>The Earth is an oblate spheroid rotating from <strong>West to East</strong> once every 24 hours (1,440 minutes) on its tilted axis of 23.5°.</p>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Longitudes (देवान्तर रेखा):</strong> 360 imaginary vertical lines running from North to South Pole. 0° Prime Meridian passes through Greenwich, London.</li>\n        <li><strong>Time Calculation:</strong> 360° = 24 hours => 15° longitude = 1 hour => <strong>1° longitude = exactly 4 minutes</strong> of solar time difference.</li>\n        <li><strong>International Date Line (IDL):</strong> 180° Meridian running through the Pacific Ocean. Crossing West adds a calendar day; crossing East subtracts a calendar day.</li>\n        <li><strong>Latitudes (अक्षांश रेखा):</strong> Parallel horizontal rings measuring angular distance north/south of the Equator (0°). Tropics of Cancer (23.5° N) and Capricorn (23.5° S).</li>\n    </ul>\n\n    <div class=\"bg-amber-50 p-4 rounded-xl border border-amber-200 text-sm\">\n        <strong class=\"text-amber-950 font-bold\">PSC Exam Point:</strong> The Equatorial climate zone experiences minimum annual temperature variance due to consistent direct overhead solar insolation throughout the year.\n    </div>\n\n    <h3 class=\"text-base font-bold text-gray-900\">2. Global Continents and Geographic Epithets</h3>\n    <div class=\"overflow-x-auto\">\n        <table class=\"min-w-full text-xs text-left border border-gray-200 rounded-lg overflow-hidden\">\n            <thead class=\"bg-gray-900 text-white font-bold\">\n                <tr><th class=\"p-2.5\">Geographic Region / Continent</th><th class=\"p-2.5\">Celebrated Epithet</th><th class=\"p-2.5\">Key Physical Significance</th></tr>\n            </thead>\n            <tbody class=\"divide-y divide-gray-200 text-gray-700\">\n                <tr class=\"bg-white\"><td class=\"p-2 font-bold\">Asia</td><td class=\"p-2\">Continent of Extremes</td><td class=\"p-2\">Highest peak (Everest 8,848.86m), lowest land point (Dead Sea -430m), highest plateau (Pamir Knot).</td></tr>\n                <tr class=\"bg-gray-50\"><td class=\"p-2 font-bold\">Africa</td><td class=\"p-2\">Dark Continent / Savanna (Zoo of the World)</td><td class=\"p-2\">World\'s longest river (Nile 6,650 km), largest desert (Sahara), vast tropical grasslands.</td></tr>\n                <tr class=\"bg-white\"><td class=\"p-2 font-bold\">Europe</td><td class=\"p-2\">Peninsula of Peninsulas</td><td class=\"p-2\">Composed of Iberian, Scandinavian, Italian, and Balkan peninsulas; no true deserts.</td></tr>\n                <tr class=\"bg-gray-50\"><td class=\"p-2 font-bold\">Pamir Plateau</td><td class=\"p-2\">Roof of the World</td><td class=\"p-2\">Central Asian junction knot of Himalayas, Karakoram, Hindu Kush, and Tian Shan ranges.</td></tr>\n            </tbody>\n        </table>\n    </div>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">B. GEOGRAPHY OF NEPAL</h2>\n    \n    <h3 class=\"text-base font-bold text-gray-900\">1. Spatial Dimensions and Location</h3>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Total Area:</strong> 147,516 sq. km (0.03% of world, 0.3% of Asia).</li>\n        <li><strong>Latitudinal Extent:</strong> 26°22\' N to 30°27\' N latitude.</li>\n        <li><strong>Longitudinal Extent:</strong> 80°04\' E to 88°12\' E longitude.</li>\n        <li><strong>Standard Time:</strong> Based on <strong>86°15\' East Longitude</strong> passing through Mt. Gaurishankar (Rolwaling Himal), set exactly <strong>UTC + 5:45</strong> on Baisakh 1, 2042 BS.</li>\n    </ul>\n\n    <h3 class=\"text-base font-bold text-gray-900\">2. Three Ecological Belts of Nepal</h3>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Himalayan Region (15% area):</strong> Altitudes 3,000m to 8,848.86m. Contains 8 of the world\'s 14 eight-thousanders (Everest, Kanchenjunga, Lhotse, Makalu, Cho Oyu, Dhaulagiri, Manaslu, Annapurna I).</li>\n        <li><strong>Hilly Region (68% area):</strong> Altitudes 600m to 3,000m. Comprises Mahabharat Range (Lesser Himalaya) and Chure/Siwalik foothills, containing fertile tectonic valleys (Kathmandu, Pokhara).</li>\n        <li><strong>Terai Region (17% area):</strong> Altitudes 58m to 600m. Highly fertile alluvial plain bordering India; lowest point in Nepal is Mukhiyapatti Musarniya in Dhanusha (58m).</li>\n    </ul>\n\n    <h3 class=\"text-base font-bold text-gray-900\">3. Major River Systems</h3>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Koshi River Basin:</strong> Largest discharge basin in eastern Nepal with 7 tributaries (Sunkoshi, Tamakoshi, Dudhkoshi, Indrawati, Likhu, Arun, Tamor).</li>\n        <li><strong>Gandaki River Basin:</strong> Central river basin with deepest gorge in the world (Dana Gorge in Kaligandaki between Dhaulagiri and Annapurna).</li>\n        <li><strong>Karnali River Basin:</strong> Longest river in Nepal (507 km within Nepal) originating from the Tibetan plateau near Lake Manasarovar.</li>\n        <li><strong>Mahakali River:</strong> Forms the western boundary river between Nepal and India.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HHSDW36QY0A93YZ2RTZ3YA.pdf', '[{\"question\":\"Where do the Trade Winds (\\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930\\u093f\\u0915 \\u0935\\u093e\\u092f\\u0941) blow on the globe?\",\"options\":[\"Above Europe\",\"In the Cape of Good Hope\",\"Between the Tropics and the Equator\",\"In the Arctic Circle\"],\"answer\":2,\"explanation\":\"Trade winds blow consistently from the subtropical high-pressure belts (Tropics) towards the equatorial low-pressure zone.\"},{\"question\":\"In which climate zone does the minimum difference in seasonal temperature exist?\",\"options\":[\"Equatorial Zone\",\"Monsoon Zone\",\"Temperate Zone\",\"Mediterranean Zone\"],\"answer\":0,\"explanation\":\"The Equatorial climate zone maintains a high, almost uniform temperature throughout the year with minimal annual range.\"},{\"question\":\"For every 1 degree of longitude traversed east or west, what is the difference in local solar time?\",\"options\":[\"1 minute\",\"4 minutes\",\"15 minutes\",\"60 minutes\"],\"answer\":1,\"explanation\":\"Earth rotates 360 degrees in 24 hours (1,440 minutes), meaning 1 degree of longitude equals exactly 4 minutes.\"},{\"question\":\"Which continent is famously referred to as the \\\"Continent of Extremes\\\" (\\u0935\\u093f\\u0937\\u092e\\u0924\\u093e\\u0915\\u094b \\u092e\\u0939\\u093e\\u0926\\u0947\\u0936)?\",\"options\":[\"Africa\",\"Asia\",\"North America\",\"Australia\"],\"answer\":1,\"explanation\":\"Asia is called the Continent of Extremes due to extreme variations in altitude, climate, population, and cultures.\"},{\"question\":\"Which continent is known as the \\\"Dark Continent\\\" (\\u0905\\u0901\\u0927\\u094d\\u092f\\u093e\\u0930\\u094b \\u092e\\u0939\\u093e\\u0926\\u0947\\u0936)?\",\"options\":[\"Africa\",\"Europe\",\"Antarctica\",\"South America\"],\"answer\":0,\"explanation\":\"Africa was historically termed the Dark Continent because its interior remained unexplored by outsiders until the late 19th century.\"},{\"question\":\"Which plateau in Central Asia is known as the \\\"Roof of the World\\\" (\\u0938\\u0902\\u0938\\u093e\\u0930\\u0915\\u094b \\u091b\\u093e\\u0928\\u094b)?\",\"options\":[\"Tibetan Plateau\",\"Pamir Knot \\/ Plateau\",\"Deccan Plateau\",\"Anatolian Plateau\"],\"answer\":1,\"explanation\":\"The Pamir Mountains\\/Plateau is geographically celebrated as the Roof of the World.\"},{\"question\":\"Which vast tropical grassland biome in Africa is known as the \\\"Zoo of the World\\\" (\\u0938\\u0902\\u0938\\u093e\\u0930\\u0915\\u094b \\u091a\\u093f\\u0921\\u093f\\u092f\\u093e\\u0916\\u093e\\u0928\\u093e)?\",\"options\":[\"Prairies\",\"Savanna\",\"Steppes\",\"Pampas\"],\"answer\":1,\"explanation\":\"The African Savanna is known as the Zoo of the World due to its immense biodiversity of large herbivores and carnivores.\"},{\"question\":\"Which continent is called the \\\"Peninsula of Peninsulas\\\" (\\u092a\\u094d\\u0930\\u093e\\u092f\\u0926\\u094d\\u0935\\u0940\\u092a\\u0939\\u0930\\u0942\\u0915\\u094b \\u092a\\u0928\\u093f \\u092a\\u094d\\u0930\\u093e\\u092f\\u0926\\u094d\\u0935\\u0940\\u092a)?\",\"options\":[\"Europe\",\"Asia\",\"Africa\",\"North America\"],\"answer\":0,\"explanation\":\"Europe is surrounded by water on three sides and composed of multiple large peninsulas (Iberian, Italian, Balkan, Scandinavian).\"},{\"question\":\"Considering the land area of SAARC nations from smallest to largest, which is the correct ascending order?\",\"options\":[\"Maldives, Bhutan, Sri Lanka, Nepal, Bangladesh, Pakistan, Afghanistan, India\",\"Maldives, Bhutan, Sri Lanka, Nepal, Bangladesh, Afghanistan, Pakistan, India\",\"Bhutan, Maldives, Nepal, Sri Lanka, Bangladesh, Afghanistan, Pakistan, India\",\"Maldives, Nepal, Bhutan, Sri Lanka, Afghanistan, Bangladesh, Pakistan, India\"],\"answer\":1,\"explanation\":\"The ascending order of area is: Maldives (300 km\\u00b2), Bhutan (38,394 km\\u00b2), Sri Lanka (65,610 km\\u00b2), Nepal (147,516 km\\u00b2), Bangladesh (147,570 km\\u00b2), Afghanistan (652,864 km\\u00b2), Pakistan (881,913 km\\u00b2), and India (3.287M km\\u00b2).\"},{\"question\":\"Which meridian line represents the International Date Line?\",\"options\":[\"0\\u00b0 Prime Meridian (Greenwich)\",\"90\\u00b0 East Meridian\",\"180\\u00b0 Longitude\",\"82.5\\u00b0 East Longitude\"],\"answer\":2,\"explanation\":\"The 180\\u00b0 meridian in the Pacific Ocean serves as the International Date Line.\"}]', 'text', 1, 30, 1, '2026-09-02 11:54:52', '2026-09-02 12:19:38'),
(680, 140, 185, '1.2 World History, Nepalese History, Culture and Socio-Political Evolution', '12-world-history-nepalese-history-culture-and-socio-political-evolution-185', '<div class=\"space-y-6\">\n    <p class=\"text-sm font-medium text-emerald-800 bg-emerald-50 p-4 rounded-2xl border border-emerald-200\">\n        Below are PSC Section Officer exam-oriented notes for Topic 1.2 (History, Culture and Social System).\n    </p>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. WORLD HISTORICAL MILESTONES</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Magna Carta (1215 AD):</strong> \"Great Charter\" sealed by King John of England at Runnymede; foundational constitutional document establishing that the ruler is subject to the law.</li>\n        <li><strong>Industrial Revolution (c. 1760 AD):</strong> Commenced in Great Britain; transition from agrarian manual craft to steam-powered industrial manufacturing (James Watt, Arkwright).</li>\n        <li><strong>French Revolution (1789 AD):</strong> Intellectual and social upheaval against absolute monarchy and feudal estates; gave the world \"Liberty, Equality, Fraternity\". Influenced by Rousseau, Voltaire, Montesquieu.</li>\n        <li><strong>Indian Independence Movement (1919–1947 AD):</strong> Gandhian Age characterized by Non-Cooperation, Civil Disobedience (Salt March 1930), and Quit India Movement (1942).</li>\n    </ul>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">B. NEPALESE HISTORICAL PERIODS</h2>\n    <h3 class=\"text-base font-bold text-gray-900\">1. Ancient and Medieval Periods</h3>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Kirat Dynasty:</strong> First recorded organized ruling dynasty of Kathmandu Valley (first king Yalambar, 32 kings).</li>\n        <li><strong>Lichhavi Period (\"Golden Era\"):</strong> King Manadeva (erected Changu Narayan pillar 464 AD, first coined money <em>Mananka</em>), Amshuverma (Kailashkut Bhawan, diplomacy with Tibet and China).</li>\n        <li><strong>Malla Period:</strong> Development of art, Newari architecture, pagoda temples (Dattatreya, Nyatapola), woodwork, and quadratic social structures.</li>\n    </ul>\n\n    <h3 class=\"text-base font-bold text-gray-900\">2. Modern Political History & Democratic Movements</h3>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Unification of Nepal:</strong> Initiated by King Prithvi Narayan Shah of Gorkha in 1744 AD (Capture of Nuwakot) and Kathmandu in 1768 AD.</li>\n        <li><strong>Rana Autocracy (1846–1951 AD):</strong> Established by Jung Bahadur Rana after the Kot Massacre (1903 BS). District administration structured into Mauja, Praganna, and Jilla.</li>\n        <li><strong>Revolution of 2007 BS:</strong> Overthrow of Rana regime; proclamation of democracy on Falgun 7, 2007 BS by King Tribhuvan.</li>\n        <li><strong>Jana Andolan I (2046 BS):</strong> 50-day movement organized by United Left Front and Nepali Congress restoring constitutional multiparty democracy.</li>\n        <li><strong>Jana Andolan II (2062/63 BS):</strong> 19-day historic mass movement from Chaitra 24 to Baisakh 11, 2063 BS ending monarchy, followed by Comprehensive Peace Accord (2063 Manshir 5) and promulgation of the Republican Constitution in 2072 BS.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HHXNTWRQ8Z6GCMPF4ZTD3R.pdf', '[{\"question\":\"In which historical period did the three levels of local administration\\u2014Mauja, Praganna, and Jilla\\u2014exist in Nepal?\",\"options\":[\"Panchayat Period\",\"Rana Period\",\"Lichhavi Period\",\"Malla Period\"],\"answer\":1,\"explanation\":\"During the Rana regime, local Terai and district administration was divided into Mauja, Praganna, and Jilla.\"},{\"question\":\"The famous Wooden Museum conserving medieval wooden idols in Nepal is located in:\",\"options\":[\"Patan\",\"Kathmandu\",\"Bhaktapur (Dattatreya Square)\",\"Kirtipur\"],\"answer\":2,\"explanation\":\"The National Woodcarving Museum is situated at the Pujari Math in Dattatreya Square, Bhaktapur.\"},{\"question\":\"Which historic document signed in 1215 AD is regarded as the cornerstone of ancient constitutional rights and rule of law?\",\"options\":[\"Petition of Right\",\"Magna Carta\",\"Bill of Rights 1689\",\"US Declaration of Independence\"],\"answer\":1,\"explanation\":\"King John of England signed the Magna Carta in 1215 AD, establishing that monarchs are subject to law.\"},{\"question\":\"Where did the Industrial Revolution first originate in the mid-18th century?\",\"options\":[\"France\",\"Italy\",\"Great Britain (England)\",\"Germany\"],\"answer\":2,\"explanation\":\"The Industrial Revolution began in Great Britain around 1760 due to mechanization and steam power.\"},{\"question\":\"The French Revolution of 1789 is also widely celebrated as an \\\"Intellectual Revolution\\\" inspired by which philosophers?\",\"options\":[\"Rousseau, Voltaire, and Montesquieu\",\"Plato and Aristotle\",\"Karl Marx and Engels\",\"Adam Smith and Ricardo\"],\"answer\":0,\"explanation\":\"Enlightenment thinkers Jean-Jacques Rousseau, Voltaire, and Montesquieu laid the intellectual foundation for Liberty, Equality, and Fraternity.\"},{\"question\":\"In the Indian Independence Movement, which period is prominently recognized as the \\\"Gandhian Era\\\"?\",\"options\":[\"1857 \\u2013 1885\",\"1885 \\u2013 1905\",\"1919 \\u2013 1947\",\"1947 \\u2013 1960\"],\"answer\":2,\"explanation\":\"The period from 1919 (Rowlatt Act\\/Jallianwala Bagh) to 1947 (Independence) was dominated by Mahatma Gandhi\'s non-violent movements.\"},{\"question\":\"The traditional rotating credit and mutual self-help system among the Thakali community in Nepal is called:\",\"options\":[\"Bheja\",\"Dhikur (\\u0922\\u093f\\u0915\\u0941\\u0930)\",\"Guthi\",\"Parma\"],\"answer\":1,\"explanation\":\"Dhikur is an indigenous revolving savings and credit association practiced by the Thakali community.\"},{\"question\":\"Which ancient Greek philosopher was sentenced to death by drinking Hemlock poison for challenging conventional dogmas?\",\"options\":[\"Plato\",\"Socrates\",\"Aristotle\",\"Herodotus\"],\"answer\":1,\"explanation\":\"Socrates was condemned to death in 399 BC by drinking hemlock for his philosophical teachings.\"},{\"question\":\"Who authored the classic foundational treatise \\\"The Politics\\\"?\",\"options\":[\"Aristotle\",\"Socrates\",\"Machiavelli\",\"John Locke\"],\"answer\":0,\"explanation\":\"Aristotle authored \\\"The Politics\\\", examining constitutions and the nature of the state.\"},{\"question\":\"Who authored \\\"Das Kapital\\\" and formulated the \\\"Theory of Surplus Value\\\"?\",\"options\":[\"Max Weber\",\"Karl Marx\",\"Adam Smith\",\"John Maynard Keynes\"],\"answer\":1,\"explanation\":\"Karl Marx developed the Theory of Surplus Value in his critique of political economy.\"}]', 'text', 2, 30, 1, '2026-09-02 11:54:52', '2026-09-02 12:19:38'),
(681, 140, 185, '1.3 Constitution of Nepal, Political Systems and Administrative Evolution', '13-constitution-of-nepal-political-systems-and-administrative-evolution-185', '<div class=\"space-y-6\">\n    <p class=\"text-sm font-medium text-emerald-800 bg-emerald-50 p-4 rounded-2xl border border-emerald-200\">\n        Below are PSC Section Officer exam-oriented notes for Topic 1.3 (Constitution and Governance).\n    </p>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. THE CONSTITUTION OF NEPAL (2072 BS)</h2>\n    <p class=\"text-sm text-gray-700\">Promulgated on <strong>Ashwin 3, 2072 BS (September 20, 2015 AD)</strong> by the Constituent Assembly. Structure: <strong>35 Parts, 308 Articles, 9 Schedules</strong>.</p>\n\n    <h3 class=\"text-base font-bold text-gray-900\">1. Salient Features</h3>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Sovereignty & State Power (Art. 2):</strong> Vested in the Nepali people.</li>\n        <li><strong>Form of State (Art. 4):</strong> Federal Democratic Republican State with 3 tiers: Federation, 7 Provinces, 753 Local Levels.</li>\n        <li><strong>31 Fundamental Rights (Arts. 16 to 46):</strong> Right to live with dignity (Art. 16), Equality (Art. 18), Freedom (Art. 17), Clean environment (Art. 30), Women rights (Art. 38), Dalit rights (Art. 40), Social Justice (Art. 42), and Constitutional Remedies (Art. 46 & 133).</li>\n        <li><strong>Independent Judiciary (Part 11):</strong> Three-tier courts: Supreme Court (1 Chief Justice + max 20 Judges), High Courts (7), and District Courts (77). Supreme Court exercises writ jurisdiction (Habeas Corpus, Mandamus, Certiorari, Prohibition, Quo Warranto).</li>\n        <li><strong>Constitutional Bodies:</strong> Commission for the Investigation of Abuse of Authority - CIAA (Part 21), Auditor General (Part 22), Public Service Commission (Part 23), Election Commission (Part 24), National Human Rights Commission (Part 26).</li>\n    </ul>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">B. EVOLUTION OF PUBLIC ADMINISTRATION</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Pre-2007 BS:</strong> Traditional, feudal patronage administration focused on revenue collection and law-and-order maintenance.</li>\n        <li><strong>Post-2007 BS Modernization:</strong> Formation of Public Service Commission (2008 BS), Buch Commission (2009 BS), Civil Service Act 2013 BS, Administrative Reform Commission 2048 BS, and enactment of Civil Service Act 2049 BS.</li>\n        <li><strong>Federal Transition:</strong> Civil Service Integration (कर्मचारी समायोजन ऐन २०७५) deploying personnel across Federal, Provincial, and Local service cadres.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HJ1DZQPV8BC899JXXX2HA7.pdf', '[{\"question\":\"Under Article 101 of the Constitution of Nepal, what majority is required in the House of Representatives to pass an Impeachment motion against the President or Chief Justice?\",\"options\":[\"Simple Majority\",\"Two-thirds (2\\/3rd) majority of the total existing members\",\"Three-fourths majority\",\"Absolute majority\"],\"answer\":1,\"explanation\":\"A two-thirds majority of the total existing members of the House of Representatives is mandatory to pass impeachment.\"},{\"question\":\"Under Article 284, who acts as the Chairperson of the Constitutional Council?\",\"options\":[\"President of Nepal\",\"Prime Minister of Nepal\",\"Chief Justice of Nepal\",\"Speaker of the House of Representatives\"],\"answer\":1,\"explanation\":\"The Constitutional Council is headed by the Prime Minister.\"},{\"question\":\"Which Article of the Constitution empowers the Supreme Court to exercise Extraordinary Jurisdiction and issue Writs (Habeas Corpus, Mandamus, Certiorari, Prohibition, Quo Warranto)?\",\"options\":[\"Article 46 and Article 133\",\"Article 100\",\"Article 215\",\"Article 300\"],\"answer\":0,\"explanation\":\"Article 133 grants extraordinary writ jurisdiction to the Supreme Court for enforcing fundamental rights.\"},{\"question\":\"Which writ is issued to restrain an inferior court or tribunal from exceeding its statutory jurisdiction?\",\"options\":[\"Mandamus\",\"Habeas Corpus\",\"Prohibition (\\u092a\\u094d\\u0930\\u0924\\u093f\\u0937\\u0947\\u0927)\",\"Quo Warranto\"],\"answer\":2,\"explanation\":\"Writ of Prohibition is issued by a superior court to stop lower courts from acting without or in excess of jurisdiction.\"},{\"question\":\"Which writ is issued to quash an unlawful judicial or quasi-judicial order passed by an inferior authority?\",\"options\":[\"Certiorari (\\u0909\\u0924\\u094d\\u092a\\u094d\\u0930\\u0947\\u0937\\u0923)\",\"Habeas Corpus\",\"Mandamus\",\"Injunction\"],\"answer\":0,\"explanation\":\"Certiorari quashes decisions passed by lower bodies that violated the law or natural justice.\"},{\"question\":\"What is the minimum age required for appointment as Chief Justice or Judge of the Supreme Court of Nepal?\",\"options\":[\"35 years\",\"40 years\",\"45 years\",\"50 years\"],\"answer\":2,\"explanation\":\"Under Article 129, a person must be at least 45 years of age to be appointed as a Supreme Court Judge.\"},{\"question\":\"Under Article 84, what is the composition ratio of FPTP vs PR seats in the House of Representatives?\",\"options\":[\"50% FPTP and 50% PR\",\"60% FPTP (165 seats) and 40% PR (110 seats)\",\"70% FPTP and 30% PR\",\"100% FPTP\"],\"answer\":1,\"explanation\":\"The 275-member House of Representatives consists of 165 members (60%) via FPTP and 110 members (40%) via Proportional Representation.\"},{\"question\":\"Which constitutional amendment process applies when an amendment bill affects the boundaries of any Province (Article 274)?\",\"options\":[\"Consensus of Prime Minister alone\",\"Must be sent to the concerned Provincial Assembly for consent within 30 days\",\"Simple referendum\",\"Presidential decree\"],\"answer\":1,\"explanation\":\"Article 274(4) requires consent of the concerned Provincial Assembly for altering provincial boundaries.\"},{\"question\":\"Under Article 267, who is the Supreme Commander-in-Chief of the Nepali Army?\",\"options\":[\"Prime Minister\",\"Defense Minister\",\"President of Nepal\",\"Chief of Army Staff\"],\"answer\":2,\"explanation\":\"The President of Nepal is the Supreme Commander of the Nepali Army.\"},{\"question\":\"Which body advises the Government of Nepal on national security and mobilization of the army under Article 266?\",\"options\":[\"National Security Council (NSC)\",\"Cabinet Committee\",\"Defense Board\",\"Joint Military Command\"],\"answer\":0,\"explanation\":\"The National Security Council headed by the Prime Minister advises on army mobilization and national defense.\"}]', 'text', 3, 30, 1, '2026-09-02 11:54:52', '2026-09-02 12:19:38'),
(682, 140, 185, '1.4 Economic Development, National Planning and Global Integration', '14-economic-development-national-planning-and-global-integration-185', '<div class=\"space-y-6\">\n    <p class=\"text-sm font-medium text-emerald-800 bg-emerald-50 p-4 rounded-2xl border border-emerald-200\">\n        Below are PSC Section Officer exam-oriented notes for Topic 1.4 (Economic Development & Planning).\n    </p>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. NATIONAL PLANNING IN NEPAL</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Planning History:</strong> First Five-Year Plan initiated in 2013 BS (1956 AD) under PM Tanka Prasad Acharya.</li>\n        <li><strong>16th Periodic Plan (FY 2081/82 – 2085/86):</strong> Themed around <em>\"Good Governance, Social Justice, and Prosperity\"</em>, targeting average economic growth of 7.0%–7.5%.</li>\n        <li><strong>LDC Graduation:</strong> Nepal is scheduled to graduate from the Least Developed Country (LDC) category by 2026 under UN Committee for Development Policy criteria (GNI per capita, Human Assets Index, Economic & Environmental Vulnerability Index).</li>\n    </ul>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">B. ECONOMIC PILLARS & MACROECONOMIC INDICATORS</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Gross Domestic Product (GDP):</strong> Total monetary value of all finished goods and services produced within Nepal in a fiscal year. Agriculture accounts for ~24%, Industry ~13%, Services ~63%.</li>\n        <li><strong>Remittance Economy:</strong> Inward remittance from migrant workers accounts for 22%–25% of GDP, sustaining foreign exchange reserves and private household consumption.</li>\n        <li><strong>Trade Deficit:</strong> High ratio of imports to exports (~10:1 ratio); mitigated via service exports and remittances.</li>\n        <li><strong>International Economic Integration:</strong> Acceded to the World Trade Organization (WTO) on April 23, 2004; member of BIMSTEC, SAFTA, and signatory to cross-border transit protocols.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HJ5W9WJEV4BMR8S5ADP2C2.pdf', '[{\"question\":\"What is the primary quantitative target for national GDP growth rate during the 16th Periodic Plan (2081\\/82 - 2085\\/86)?\",\"options\":[\"4.0% - 5.0%\",\"7.0% - 7.5%\",\"9.5% - 10.0%\",\"12.0%\"],\"answer\":1,\"explanation\":\"The 16th Periodic Plan sets an average annual economic growth target of 7.0% to 7.5%.\"},{\"question\":\"What is the primary indicator used to calculate the Human Development Index (HDI)?\",\"options\":[\"Life expectancy, Mean\\/Expected years of schooling, and Gross National Income (GNI) per capita (PPP)\",\"Gold reserves and military expenditure\",\"Exports volume alone\",\"Total agricultural land area\"],\"answer\":0,\"explanation\":\"HDI combines three dimensions: Health (life expectancy), Education (schooling years), and Standard of living (GNI per capita PPP).\"},{\"question\":\"Which international trade organization did Nepal formally join as a member in April 2004?\",\"options\":[\"OPEC\",\"World Trade Organization (WTO)\",\"OECD\",\"APEC\"],\"answer\":1,\"explanation\":\"Nepal became the 147th member of the WTO on April 23, 2004 (first LDC via standard accession).\"},{\"question\":\"What is the main driver of Nepal\'s current account surplus and foreign exchange reserve accumulation in recent years?\",\"options\":[\"Petroleum exports\",\"Worker Remittances (Bipreshan)\",\"Heavy industrial manufacturing\",\"Foreign loans alone\"],\"answer\":1,\"explanation\":\"Inflows of worker remittances from migrant workers provide vital foreign exchange and support the balance of payments.\"},{\"question\":\"What is the Fiscal Deficit (\\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u0918\\u093e\\u091f\\u093e) in government budgetary operations?\",\"options\":[\"Total Government Expenditure exceeding Total Revenue receipts (excluding debt borrowings)\",\"Exports exceeding imports\",\"Tax collection exceeding spending\",\"Zero budget variance\"],\"answer\":0,\"explanation\":\"Fiscal deficit occurs when total expenditure exceeds total revenue receipts, financed by domestic and external debt.\"},{\"question\":\"Which statutory institution in Nepal formulates and implements Monetary Policy (\\u092e\\u094c\\u0926\\u094d\\u0930\\u093f\\u0915 \\u0928\\u0940\\u0924\\u093f)?\",\"options\":[\"Ministry of Finance\",\"Nepal Rastra Bank (NRB)\",\"National Planning Commission\",\"Commercial Banks Association\"],\"answer\":1,\"explanation\":\"Nepal Rastra Bank, as the central bank, formulates annual and quarterly monetary policies.\"},{\"question\":\"What is the term for the total market value of all final goods and services produced within the geographic boundaries of a country during a financial year?\",\"options\":[\"Gross National Product (GNP)\",\"Gross Domestic Product (GDP)\",\"Net National Income (NNI)\",\"Personal Disposable Income\"],\"answer\":1,\"explanation\":\"GDP measures domestic economic output within national borders.\"},{\"question\":\"What is the Gini Coefficient used to measure in economic analysis?\",\"options\":[\"Inflation rate\",\"Income and wealth inequality distribution (0 = complete equality, 1 = complete inequality)\",\"Trade deficit percentage\",\"Interest rate fluctuations\"],\"answer\":1,\"explanation\":\"The Gini Coefficient measures the degree of economic inequality in income or wealth.\"},{\"question\":\"Which international regional integration arrangement established in 1997 includes Bangladesh, Bhutan, India, Myanmar, Nepal, Sri Lanka, and Thailand?\",\"options\":[\"BIMSTEC\",\"ASEAN\",\"SAARC\",\"SCO\"],\"answer\":0,\"explanation\":\"BIMSTEC (Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation) was founded in 1997.\"},{\"question\":\"What is Foreign Direct Investment (FDI)?\",\"options\":[\"Short-term foreign bank loans\",\"Investment made by a foreign firm to acquire lasting management interest and physical operations in an enterprise of another economy\",\"Buying foreign lottery tickets\",\"International food aid\"],\"answer\":1,\"explanation\":\"FDI represents long-term cross-border capital investment in business operations with management control.\"}]', 'text', 4, 30, 1, '2026-09-02 11:54:52', '2026-09-02 12:19:38');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(683, 140, 185, '1.5 Sustainable Development, Biodiversity, Climate Change and Environment', '15-sustainable-development-biodiversity-climate-change-and-environment-185', '<div class=\"space-y-6\">\n    <p class=\"text-sm font-medium text-emerald-800 bg-emerald-50 p-4 rounded-2xl border border-emerald-200\">\n        Below are PSC Section Officer exam-oriented notes for Topic 1.5. The notes focus on concepts, Nepal-specific issues, international frameworks, important facts, and likely analytical areas for both objective and subjective questions.\n    </p>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. SUSTAINABLE DEVELOPMENT</h2>\n\n    <h3 class=\"text-base font-bold text-gray-900\">1. Meaning of Sustainable Development</h3>\n    <p class=\"text-sm text-gray-700\">Sustainable development means development that meets the needs of the present generation without compromising the ability of future generations to meet their own needs.</p>\n    <p class=\"text-sm font-bold text-emerald-900 bg-emerald-50 p-2.5 rounded-lg\">\n        Economic Development + Social Development + Environmental Protection\n    </p>\n\n    <h4 class=\"text-sm font-bold text-gray-800\">Three Pillars of Sustainable Development</h4>\n    <ol class=\"list-decimal pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Economic sustainability:</strong> Economic growth, employment, productivity, poverty reduction.</li>\n        <li><strong>Social sustainability:</strong> Equality, education, health, social inclusion, human rights.</li>\n        <li><strong>Environmental sustainability:</strong> Conservation of natural resources, biodiversity protection, pollution control, climate protection.</li>\n    </ol>\n    <p class=\"text-xs font-bold text-gray-600\">Key Principle: Development should be economically viable, socially inclusive and environmentally responsible.</p>\n\n    <h3 class=\"text-base font-bold text-gray-900\">2. Sustainable Development Goals (SDGs)</h3>\n    <p class=\"text-sm text-gray-700\">The United Nations adopted 17 Sustainable Development Goals in 2015 under the 2030 Agenda for Sustainable Development (to be achieved by 2030).</p>\n    \n    <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs text-gray-700 bg-gray-50 p-4 rounded-xl border border-gray-200\">\n        <div>1. No Poverty</div>\n        <div>2. Zero Hunger</div>\n        <div>3. Good Health and Well-being</div>\n        <div>4. Quality Education</div>\n        <div>5. Gender Equality</div>\n        <div>6. Clean Water and Sanitation</div>\n        <div>7. Affordable and Clean Energy</div>\n        <div>8. Decent Work & Economic Growth</div>\n        <div>9. Industry, Innovation & Infrastructure</div>\n        <div>10. Reduced Inequalities</div>\n        <div>11. Sustainable Cities & Communities</div>\n        <div>12. Responsible Consumption & Production</div>\n        <div>13. Climate Action</div>\n        <div>14. Life Below Water</div>\n        <div>15. Life on Land</div>\n        <div>16. Peace, Justice & Strong Institutions</div>\n        <div>17. Partnerships for the Goals</div>\n    </div>\n    <div class=\"bg-amber-50 p-3 rounded-xl border border-amber-200 text-xs font-bold text-amber-950\">\n        PSC Exam Point: SDGs = 17 goals + 169 targets + 2030 Agenda\n    </div>\n\n    <h3 class=\"text-base font-bold text-gray-900\">3. Sustainable Development in Nepal</h3>\n    <p class=\"text-sm text-gray-700\">Nepal has incorporated sustainable development principles into its periodic development planning.</p>\n    <ul class=\"list-disc pl-5 space-y-1 text-xs text-gray-700\">\n        <li><strong>Major Areas:</strong> Poverty reduction, food security, renewable energy, sustainable agriculture, forest conservation, biodiversity protection, climate adaptation, disaster risk reduction.</li>\n        <li><strong>Major Challenges:</strong> Poverty and inequality, unplanned urbanization, deforestation, pollution, climate change, natural disasters, infrastructure pressure, unsustainable resource use, weak implementation capacity.</li>\n    </ul>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">B. BIODIVERSITY</h2>\n    <h3 class=\"text-base font-bold text-gray-900\">1. Meaning and 3 Levels of Biodiversity</h3>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Genetic Diversity:</strong> Variation of genes within a species (e.g. different varieties of rice).</li>\n        <li><strong>Species Diversity:</strong> Variety of different species in an area (e.g. tigers, rhinos, elephants, birds, plants).</li>\n        <li><strong>Ecosystem Diversity:</strong> Variety of ecosystems (e.g. forests, wetlands, grasslands, mountains, rivers).</li>\n    </ul>\n\n    <h3 class=\"text-base font-bold text-gray-900\">2. Ecosystem Services</h3>\n    <ul class=\"list-disc pl-5 space-y-1 text-xs text-gray-700\">\n        <li><strong>Provisioning Services:</strong> Food, fresh water, timber, medicine.</li>\n        <li><strong>Regulating Services:</strong> Climate and flood regulation, water purification.</li>\n        <li><strong>Cultural Services:</strong> Recreation, eco-tourism, spiritual and aesthetic values.</li>\n        <li><strong>Supporting Services:</strong> Soil formation, nutrient cycling, photosynthesis.</li>\n    </ul>\n\n    <h3 class=\"text-base font-bold text-gray-900\">3. Protected Areas & Wildlife of Nepal</h3>\n    <ul class=\"list-disc pl-5 space-y-1 text-xs text-gray-700\">\n        <li><strong>Protected Categories:</strong> 12 National Parks, 1 Wildlife Reserve (Koshi Tappu), 6 Conservation Areas, 1 Hunting Reserve (Dhorpatan), Buffer Zones.</li>\n        <li><strong>Key Parks:</strong> Chitwan National Park (One-horned Rhino, Bengal Tiger), Sagarmatha National Park (Everest ecosystem), Langtang, Rara, Shey Phoksundo (High altitude, Blue Sheep), Bardiya National Park.</li>\n        <li><strong>National Symbols:</strong> National Animal = Cow; National Bird = Danphe (Himalayan Monal).</li>\n    </ul>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">C. ENVIRONMENT & POLLUTION</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Components:</strong> Biotic (Plants, animals, microorganisms, humans) and Abiotic (Air, water, soil, temperature, sunlight, minerals).</li>\n        <li><strong>Air Pollution Sources in Nepal:</strong> Vehicle emissions, brick kilns, industries, road dust, forest fires, household fuel burning.</li>\n        <li><strong>Solid Waste Management & 3R Principle:</strong> Reduce + Reuse + Recycle (Waste hierarchy: Reduce -> Reuse -> Recycle -> Recover -> Dispose).</li>\n    </ul>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">D. CLIMATE CHANGE</h2>\n    <p class=\"text-sm text-gray-700\"><strong>Greenhouse Gases:</strong> CO₂, CH₄, N₂O, Water vapor, Ozone, Fluorinated gases. Trapping of infrared radiation causes global warming.</p>\n    <div class=\"bg-gray-50 p-3 rounded-xl border border-gray-200 text-xs text-gray-700\">\n        <strong>Difference:</strong> Global warming = rise in average global temperature. Climate change = broader long-term shifts in weather and climate patterns.\n    </div>\n\n    <h3 class=\"text-base font-bold text-gray-900\">Climate Change Adaptation vs Mitigation</h3>\n    <ul class=\"list-disc pl-5 space-y-1 text-xs text-gray-700\">\n        <li><strong>Adaptation (Adjust to impacts):</strong> Climate-resilient agriculture, early warning sirens, flood embankments, water conservation.</li>\n        <li><strong>Mitigation (Reduce root causes):</strong> Clean hydropower, solar energy, electric vehicles, afforestation, forest conservation.</li>\n    </ul>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">E. MAJOR INTERNATIONAL ENVIRONMENTAL AGREEMENTS</h2>\n    <div class=\"overflow-x-auto\">\n        <table class=\"min-w-full text-xs text-left border border-gray-200 rounded-lg overflow-hidden\">\n            <thead class=\"bg-gray-900 text-white font-bold\">\n                <tr><th class=\"p-2\">Year</th><th class=\"p-2\">International Agreement / Milestone</th><th class=\"p-2\">Primary Significance</th></tr>\n            </thead>\n            <tbody class=\"divide-y divide-gray-200 text-gray-700\">\n                <tr class=\"bg-white\"><td class=\"p-2 font-bold\">1972</td><td class=\"p-2\">Stockholm Conference</td><td class=\"p-2\">First UN global conference on the Human Environment (created UNEP).</td></tr>\n                <tr class=\"bg-gray-50\"><td class=\"p-2 font-bold\">1987</td><td class=\"p-2\">Brundtland Report (Our Common Future)</td><td class=\"p-2\">Popularized modern definition of Sustainable Development.</td></tr>\n                <tr class=\"bg-white\"><td class=\"p-2 font-bold\">1992</td><td class=\"p-2\">Rio Earth Summit (UNCED)</td><td class=\"p-2\">Adopted Rio Declaration, Agenda 21, UNFCCC, and CBD.</td></tr>\n                <tr class=\"bg-gray-50\"><td class=\"p-2 font-bold\">1997</td><td class=\"p-2\">Kyoto Protocol</td><td class=\"p-2\">Legally binding greenhouse gas reduction commitments for developed countries.</td></tr>\n                <tr class=\"bg-white\"><td class=\"p-2 font-bold\">2015</td><td class=\"p-2\">Paris Agreement</td><td class=\"p-2\">Target to limit global warming to well below 2°C (pursuing 1.5°C) via NDCs.</td></tr>\n                <tr class=\"bg-gray-50\"><td class=\"p-2 font-bold\">2015</td><td class=\"p-2\">2030 Agenda (SDGs)</td><td class=\"p-2\">17 Sustainable Development Goals adopted unanimously by 193 UN members.</td></tr>\n            </tbody>\n        </table>\n    </div>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">F. CORE ENVIRONMENTAL PRINCIPLES</h2>\n    <ol class=\"list-decimal pl-5 space-y-1 text-xs text-gray-700\">\n        <li><strong>Sustainable Development Principle:</strong> Balancing economic growth, social equity, and ecological integrity.</li>\n        <li><strong>Polluter Pays Principle:</strong> The polluter must bear the financial cost of pollution prevention and remediation.</li>\n        <li><strong>Precautionary Principle:</strong> Lack of full scientific certainty shall not be used as an excuse for postponing cost-effective preventive action.</li>\n        <li><strong>Intergenerational Equity:</strong> Preserving natural wealth and planetary health for future generations.</li>\n        <li><strong>Public Participation:</strong> Involving citizens, local communities, and women in environmental decision-making.</li>\n    </ol>\n</div>', NULL, 'lessons/pdfs/01M1HJCQNFGVWDFVR975YM5A9S.pdf', '[{\"question\":\"In which correct chronological sequence did Nepal ratify the following major UN human rights conventions?\",\"options\":[\"Convention against Slavery -> CEDAW -> Torture Convention -> Child Rights Convention\",\"CEDAW -> Child Rights -> Torture -> Slavery\",\"Child Rights -> CEDAW -> Slavery -> Torture\",\"Torture -> Slavery -> CEDAW -> Child Rights\"],\"answer\":0,\"explanation\":\"Nepal ratified: Slavery Convention (1963), CEDAW (1991), Convention Against Torture \\/ CAT (1991), and Child Rights Convention \\/ CRC (1990).\"},{\"question\":\"What is the target timeline under Nepal\'s Long-Term Strategy to achieve Net-Zero greenhouse gas emissions?\",\"options\":[\"2030\",\"2040\",\"2045\",\"2060\"],\"answer\":2,\"explanation\":\"Nepal submitted its long-term strategy committing to carbon neutrality \\/ Net-Zero emissions by 2045.\"},{\"question\":\"Which ecosystem assessment tool calculates the biological capacity of the Earth required to absorb humanity\'s resource consumption and waste?\",\"options\":[\"Ecological Footprint\",\"Carbon Credit Counter\",\"Ozone Depletion Index\",\"Soil pH Scale\"],\"answer\":0,\"explanation\":\"Ecological Footprint measures ecological assets and biocapacity consumed by populations.\"},{\"question\":\"What is the prime objective of the Ramsar Convention signed in Iran in 1971?\",\"options\":[\"Nuclear non-proliferation\",\"Conservation and sustainable use of Wetlands\",\"Regulating sea trade\",\"Space exploration\"],\"answer\":1,\"explanation\":\"The Ramsar Convention protects wetlands of international ecological importance.\"},{\"question\":\"How many species of flora and fauna in Nepal are strictly protected under Appendix I of CITES (Convention on International Trade in Endangered Species)?\",\"options\":[\"Rare wildlife including Snow Leopard, Red Panda, One-horned Rhino, Gharial Crocodile, Bengal Tiger\",\"Domestic cattle\",\"Common crows and pigeons\",\"Cultivated rice\"],\"answer\":0,\"explanation\":\"CITES Appendix I prohibits international commercial trade in endangered species like the Tiger, Rhino, and Red Panda.\"},{\"question\":\"Which international fund established under the UNFCCC provides climate finance grants and concessional loans to vulnerable developing nations?\",\"options\":[\"Green Climate Fund (GCF)\",\"World Bank Trust\",\"IMF Gold Reserve\",\"Asian Development Bank fund\"],\"answer\":0,\"explanation\":\"The Green Climate Fund (GCF) is the primary multilateral climate fund.\"},{\"question\":\"What does REDD+ stand for in international forest carbon financing?\",\"options\":[\"Reducing Emissions from Deforestation and Forest Degradation, and conservation of forest carbon stocks\",\"Renewable Energy Development Directorate\",\"Rural Ecology Disaster Division\",\"Resource Extraction Data Deposit\"],\"answer\":0,\"explanation\":\"REDD+ creates financial incentives for developing countries to conserve forests and store carbon.\"},{\"question\":\"Which district in Nepal is home to Shey-Phoksundo National Park, renowned for trans-Himalayan biodiversity and blue sheep?\",\"options\":[\"Dolpa and Mugu\",\"Solukhumbu\",\"Kaski\",\"Chitwan\"],\"answer\":0,\"explanation\":\"Shey-Phoksundo National Park is located in Dolpa and Mugu districts.\"},{\"question\":\"What is the main danger posed by rapidly melting Himalayan glaciers in the Khumbu and Rolwaling valleys?\",\"options\":[\"Glacial Lake Outburst Floods (GLOFs)\",\"Earthquake triggering\",\"Sandstorms\",\"Volcanic eruptions\"],\"answer\":0,\"explanation\":\"Rising temperatures cause glacial lakes to expand, threatening catastrophic downstream GLOF surges.\"},{\"question\":\"What is the Sendai Framework (2015-2030) dedicated to achieving globally?\",\"options\":[\"Disaster Risk Reduction (DRR)\",\"Cyber warfare regulation\",\"Nuclear disarmament\",\"Maritime shipping lanes\"],\"answer\":0,\"explanation\":\"The Sendai Framework outlines global targets and priorities for Disaster Risk Reduction.\"}]', 'text', 5, 30, 1, '2026-09-02 11:54:52', '2026-09-02 12:19:38'),
(684, 140, 185, '1.6 Science, Technology, International Relations and Multilateralism', '16-science-technology-international-relations-and-multilateralism-185', '<div class=\"space-y-6\">\n    <p class=\"text-sm font-medium text-emerald-800 bg-emerald-50 p-4 rounded-2xl border border-emerald-200\">\n        Below are PSC Section Officer exam-oriented notes for Topic 1.6 & 1.7 (Science, Tech & International Organizations).\n    </p>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. SCIENCE AND TECHNOLOGY IN GOVERNANCE</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Forensic Science:</strong> DNA Fingerprinting analyzing Short Tandem Repeats (STRs) from biological trace samples (hair, saliva, blood) for legal identification.</li>\n        <li><strong>Gene Editing:</strong> CRISPR-Cas9 technology enabling precise targeted genetic alterations.</li>\n        <li><strong>Space & Atmospheric Tech:</strong> Remote sensing satellites, GIS mapping for land use and forest inventory, helioscope/coronagraph instruments for solar activity monitoring.</li>\n    </ul>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">B. SAARC AND REGIONAL INSTITUTIONS</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>SAARC Establishment:</strong> Founded on December 8, 1985 in Dhaka. Permanent Secretariat established in <strong>Kathmandu</strong> on January 16, 1987.</li>\n        <li><strong>Regional Centers:</strong>\n            <ul class=\"list-circle pl-5 mt-1 space-y-0.5 text-xs\">\n                <li>SAARC Tuberculosis and HIV/AIDS Centre (STAC) -> <strong>Bhaktapur, Nepal</strong></li>\n                <li>SAARC Agriculture Centre (SAC) -> <strong>Dhaka, Bangladesh</strong></li>\n                <li>SAARC Energy Centre (SEC) -> <strong>Islamabad, Pakistan</strong></li>\n                <li>SAARC Disaster Management Centre (SDMC) -> <strong>Gandhinagar, India</strong></li>\n            </ul>\n        </li>\n    </ul>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">C. UNITED NATIONS AND MULTILATERALISM</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>UN Membership:</strong> Nepal admitted on <strong>December 14, 1955 AD</strong> under the 16-country \"Package Deal\".</li>\n        <li><strong>Principal Organs:</strong> General Assembly, Security Council (5 permanent with veto + 10 non-permanent), ECOSOC, International Court of Justice (The Hague), Secretariat.</li>\n        <li><strong>Peacekeeping Operations (UNPKO):</strong> Nepal is currently among the highest troop- and police-contributing countries globally, serving in blue helmets since 1958 (UNOGIL Lebanon).</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HJHFPZHRY7HFHTW9C35VGD.pdf', '[{\"question\":\"What scientific technique analyzes short tandem repeats (STRs) in hair, saliva, or blood samples to identify individuals in forensic investigations?\",\"options\":[\"DNA Fingerprinting \\/ Profiling\",\"Radiocarbon Dating\",\"Spectroscopy\",\"Chromatography\"],\"answer\":0,\"explanation\":\"DNA Fingerprinting developed by Sir Alec Jeffreys is used in criminal forensics and paternity verification.\"},{\"question\":\"What is the scientific instrument used specifically for observing the surface and corona of the Sun?\",\"options\":[\"Heliograph \\/ Helescope (Coronagraph)\",\"Telescope\",\"Seismograph\",\"Periscope\"],\"answer\":0,\"explanation\":\"A helioscope \\/ solar coronagraph is designed for solar observation.\"},{\"question\":\"Where is the SAARC Tuberculosis and HIV\\/AIDS Centre (STAC) located?\",\"options\":[\"Kathmandu (Thimi, Bhaktapur), Nepal\",\"Dhaka, Bangladesh\",\"Islamabad, Pakistan\",\"New Delhi, India\"],\"answer\":0,\"explanation\":\"The SAARC Tuberculosis and HIV\\/AIDS Centre is located in Thimi, Bhaktapur, Nepal.\"},{\"question\":\"Where is the SAARC Agriculture Centre (SAC) located?\",\"options\":[\"Dhaka, Bangladesh\",\"Islamabad, Pakistan\",\"Colombo, Sri Lanka\",\"Thimphu, Bhutan\"],\"answer\":0,\"explanation\":\"The SAARC Agriculture Centre is headquartered in Dhaka, Bangladesh.\"},{\"question\":\"Where is the SAARC Energy Centre (SEC) established?\",\"options\":[\"Islamabad, Pakistan\",\"Kathmandu, Nepal\",\"Male, Maldives\",\"Kabul, Afghanistan\"],\"answer\":0,\"explanation\":\"The SAARC Energy Centre is located in Islamabad, Pakistan.\"},{\"question\":\"Where is the permanent headquarters of the SAARC Secretariat located?\",\"options\":[\"Kathmandu, Nepal\",\"New Delhi, India\",\"Colombo, Sri Lanka\",\"Dhaka, Bangladesh\"],\"answer\":0,\"explanation\":\"The SAARC Secretariat was established in Kathmandu on January 16, 1987.\"},{\"question\":\"Who is the current executive head of the United Nations Secretariat holding the post of Secretary-General?\",\"options\":[\"Ant\\u00f3nio Guterres\",\"Ban Ki-moon\",\"Kofi Annan\",\"Boutros Boutros-Ghali\"],\"answer\":0,\"explanation\":\"Ant\\u00f3nio Guterres of Portugal serves as the 9th Secretary-General of the United Nations.\"},{\"question\":\"How many permanent members (P5) with veto power sit on the UN Security Council?\",\"options\":[\"5 (USA, UK, France, Russia, China)\",\"10\",\"15\",\"20\"],\"answer\":0,\"explanation\":\"The 5 permanent veto-wielding members of the UNSC are the USA, UK, France, Russia, and China.\"},{\"question\":\"When did Nepal formally join the United Nations as a member state?\",\"options\":[\"December 14, 1955 AD (Package Deal)\",\"1945 AD\",\"1960 AD\",\"1972 AD\"],\"answer\":0,\"explanation\":\"Nepal was admitted to the United Nations on December 14, 1955 under the Package Deal.\"},{\"question\":\"Which gene editing technology was awarded the Nobel Prize in Chemistry in 2020 for revolutionizing genetics?\",\"options\":[\"CRISPR-Cas9\",\"Recombinant DNA\",\"Polymerase Chain Reaction\",\"Western Blotting\"],\"answer\":0,\"explanation\":\"Emmanuelle Charpentier and Jennifer Doudna won the Nobel Prize for developing the CRISPR-Cas9 genetic scissors.\"}]', 'text', 6, 30, 1, '2026-09-02 11:54:52', '2026-09-02 12:19:38'),
(685, 141, 186, '2.1 Verbal Reasoning & Logical Problem Solving', '21-verbal-reasoning-logical-problem-solving-186', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. VERBAL REASONING PATTERNS</h2>\n    <h3 class=\"text-base font-bold text-gray-900\">1. Alphanumeric & Letter Series</h3>\n    <p class=\"text-sm text-gray-700\">Memorize alphabet forward (A=1, Z=26) and reverse (A=26, Z=1) positions. Rule of 27: <code>Forward_Rank + Reverse_Rank = 27</code>.</p>\n    \n    <h3 class=\"text-base font-bold text-gray-900\">2. Direction and Distance Sense</h3>\n    <p class=\"text-sm text-gray-700\">Always plot cardinal directions (North, South, East, West). Use the Pythagorean theorem for diagonal shortest distance: <code>Displacement = √(Δx² + Δy²)</code>.</p>\n\n    <h3 class=\"text-base font-bold text-gray-900\">3. Ranking and Order Test</h3>\n    <p class=\"text-sm text-gray-700\">Standard linear ranking formula: <code>Total Students = (Rank from Top) + (Rank from Bottom) - 1</code>.</p>\n</div>', NULL, 'lessons/pdfs/01M1HP7PZA3RMA9SEPSZXWWQ8D.pdf', '[{\"question\":\"Find the next letter in the sequence: O, T, T, F, F, S, S, E, (?)\",\"options\":[\"E\",\"N\",\"O\",\"T\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"First letters of counting numbers: One, Two, Three, Four, Five, Six, Seven, Eight, Nine -> N.\"},{\"question\":\"\'Reading\' is related to \'Knowledge\' in the same way as \'Work\' is related to:\",\"options\":[\"Money\",\"Engagement\",\"Employment\",\"Experience\"],\"answer\":3,\"hint\":\"\",\"explanation\":\"Reading yields knowledge; work yields experience.\"},{\"question\":\"Complete the analogy: PARTS : STRAP :: WOLF : ?\",\"options\":[\"FOX\",\"ANIMAL\",\"FLOW\",\"WOOD\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"The letters of the first word are reversed: PARTS -> STRAP, WOLF -> FLOW.\"},{\"question\":\"If TABLET is coded as UACMET, how is CAPSULE written in that code?\",\"options\":[\"BAORUKE\",\"DAQTUME\",\"BAQRUKE\",\"DAOTUME\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Letter shifting: T(+1)=U, A(0)=A, B(+1)=C, L(+1)=M, E(0)=E, T(0)=T. Similarly CAPSULE becomes DAQTUME.\"},{\"question\":\"Choose the word which is odd\\/different from the rest: Anger, Anxiety, Feeling, Joy\",\"options\":[\"Anger\",\"Anxiety\",\"Feeling\",\"Joy\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Anger, anxiety, and joy are specific emotions, whereas Feeling is the broad generic category.\"},{\"question\":\"If adjacent letters in the alphabet are swapped (1st&2nd, 3rd&4th: BA DC FE HG...), what is the 15th letter?\",\"options\":[\"N\",\"O\",\"P\",\"Q\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Original 15th is O and 16th is P. After swapping the 15th-16th pair (OP -> PO), the 15th letter is P.\"},{\"question\":\"In a class of 45 students, a boy is ranked 20th. When 2 new boys join ahead of him, his rank drops to 21st. What is his new rank from the end?\",\"options\":[\"25th\",\"26th\",\"27th\",\"28th\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Total students = 47. Rank from end = Total - Rank from top + 1 = 47 - 21 + 1 = 27th.\"},{\"question\":\"Pointing to a photograph, Ramesh said, \\\"She is the daughter of the only son of my grandfather.\\\" How is the girl related to Ramesh?\",\"options\":[\"Mother\",\"Sister\",\"Daughter\",\"Aunt\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Only son of grandfather = Father. Daughter of father = Sister.\"},{\"question\":\"A man travels 5 km North, turns right and walks 3 km, then turns right and walks 5 km. In which direction is he from his starting point?\",\"options\":[\"North\",\"South\",\"East\",\"West\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"He moved 5km North and 5km South (net vertical movement 0), and 3km East. He is East of starting point.\"},{\"question\":\"If RED is coded as 27 (18+5+4), what is the numerical code for GREEN (7+18+5+5+14)?\",\"options\":[\"45\",\"49\",\"52\",\"55\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Sum of alphabetical positions: G(7) + R(18) + E(5) + E(5) + N(14) = 49.\"}]', 'text', 1, 25, 1, '2026-09-02 11:54:52', '2026-09-02 12:46:23'),
(686, 141, 186, '2.2 Analytical Reasoning, Assertion-Reason and Statement-Inference', '22-analytical-reasoning-assertion-reason-and-statement-inference-186', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. ASSERTION AND REASON (A&R)</h2>\n    <p class=\"text-sm text-gray-700\">Systematic evaluation technique:</p>\n    <ol class=\"list-decimal pl-5 space-y-1 text-sm text-gray-700\">\n        <li>Step 1: Check if Assertion (A) is factually true independently.</li>\n        <li>Step 2: Check if Reason (R) is factually true independently.</li>\n        <li>Step 3: Connect (A) and (R) using the word \"BECAUSE\". If it forms a scientifically/legally sound explanation, choose option (A).</li>\n    </ol>\n\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">B. CAUSE AND EFFECT</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Direct Cause & Effect:</strong> Event A directly causes Event B (e.g. Failure of police deterrence -> Rise in crime).</li>\n        <li><strong>Effects of Common Cause:</strong> Both events stem from a single shared root cause.</li>\n        <li><strong>Independent Causes:</strong> Unrelated phenomena occurring simultaneously.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HPEGZ8Q0SGZ1M3R5Y7WYVN.pdf', '[{\"question\":\"Assertion (A): DNA fingerprinting is a reliable tool in criminal investigations for murder and paternity cases.\\\\nReason (R): Biological traces such as hair root, saliva, and blood contain unique genetic codes sufficient for DNA analysis.\",\"options\":[\"Both (A) and (R) are true and (R) is the correct explanation of (A)\",\"Both (A) and (R) are true but (R) is not the correct explanation\",\"(A) is true but (R) is false\",\"(A) is false but (R) is true\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"DNA contains unique individual nucleotide sequences that accurately distinguish identities.\"},{\"question\":\"Statement I: Crimes against women have increased in the city.\\\\nStatement II: Police authorities have failed to apprehend the perpetrators committing the crimes.\",\"options\":[\"Statement I is cause and Statement II is effect\",\"Statement II is cause and Statement I is effect (or related effect of common cause)\",\"Both are independent causes\",\"Both are effects of independent causes\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Lack of enforcement and deterrence (Statement II) leads to emboldened criminal offenses (Statement I).\"},{\"question\":\"Statement: \\\"All machines make noise. Some machines are noisy. No machine makes noise. Some machines are not noisy.\\\" Which two statements cannot both be true, but can both be false?\",\"options\":[\"1 and 3 (All machines make noise \\/ No machine makes noise)\",\"3 and 4\",\"1 and 2\",\"2 and 4\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Universal Affirmative (All) and Universal Negative (None) are contrary statements; both cannot be true simultaneously.\"},{\"question\":\"K is heavier than N. M weighs less than N. L is heavier than M but lighter than N. Who is the lightest among all?\",\"options\":[\"K\",\"N\",\"L\",\"M\"],\"answer\":3,\"hint\":\"\",\"explanation\":\"Descending weight order: K > N > L > M. M is the lightest.\"},{\"question\":\"If D is the brother of B, how is B related to C? To answer this, which statements are necessary?\\\\n1. The son of D is the grandson of C.\\\\n2. B is the sister of D.\",\"options\":[\"Only 1 is sufficient\",\"Only 2 is sufficient\",\"Either 1 or 2 alone\",\"Both 1 and 2 are required together\"],\"answer\":3,\"hint\":\"\",\"explanation\":\"Statement 1 establishes parental generation of C, while Statement 2 reveals B\'s gender (daughter). Both are needed.\"},{\"question\":\"In a Venn diagram of 3 intersecting circles: Triangle = Girls, Square = Sports Persons, Circle = Coaches. What represents Girls who are Sports Persons but NOT Coaches?\",\"options\":[\"The region inside Triangle and Square outside Circle\",\"Inside all three\",\"Inside Circle only\",\"Outside all\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Intersection of triangle and square excluding the circle represents girls in sports who are not coaches.\"},{\"question\":\"In a survey of 2,878 persons, 1,652 were males. 1,226 voted Against (796 males). 1,425 voted For. 196 females were Undecided. How many females voted For the proposal?\",\"options\":[\"430\",\"600\",\"624\",\"640\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Total females = 2,878 - 1,652 = 1,226. Females Against = 1,226 - 796 = 430. Females For = 1,226 - 430 - 196 = 600.\"},{\"question\":\"From the survey above, how many males were Undecided?\",\"options\":[\"31\",\"227\",\"426\",\"581\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Total undecided = 2,878 - 1,226 - 1,425 = 227. Undecided males = 227 - 196 (females) = 31.\"},{\"question\":\"From the survey above, how many females voted Against (were not in favor)?\",\"options\":[\"430\",\"496\",\"586\",\"1226\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Total against = 1,226. Males against = 796. Females against = 1,226 - 796 = 430.\"},{\"question\":\"Four persons A, B, C, D live on one side of a street. D owns a white car. B\'s house is not at either end. A owns the 2nd house from the left. C owns a blue car. Which people own the red and green cars?\",\"options\":[\"B and A\",\"C and B\",\"D and A\",\"C and D\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"D has White, C has Blue. The remaining two individuals A and B must own the Red and Green cars.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:52', '2026-09-02 12:50:07'),
(687, 141, 186, '2.3 Non-Verbal Reasoning, Spatial & Visual Intelligence', '23-non-verbal-reasoning-spatial-visual-intelligence-186', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. NON-VERBAL SPATIAL PROBLEM TYPES</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Mirror Images (दर्पण प्रतिबिम्ब):</strong> Lateral inversion where Left becomes Right and Right becomes Left; Top and Bottom remain unchanged.</li>\n        <li><strong>Water Images (जल प्रतिबिम्ब):</strong> Vertical inversion where Top becomes Bottom and Bottom becomes Top; Left and Right remain unchanged.</li>\n        <li><strong>Cube Nets & Dice Folding:</strong> Alternate squares in a line are strictly opposite to each other. Adjacent faces on the flat net can never be opposite.</li>\n        <li><strong>Venn Diagrams:</strong> Representing categorical logical relationships (e.g. All A are B, Some B are C).</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HPHFVW0W30Z1G8MVJVEEBB.pdf', '[{\"question\":\"Find the next letter in the sequence: O, T, T, F, F, S, S, E, (?)\",\"options\":[\"E\",\"N\",\"O\",\"T\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"First letters of counting numbers: One, Two, Three, Four, Five, Six, Seven, Eight, Nine -> N.\"},{\"question\":\"\'Reading\' is related to \'Knowledge\' in the same way as \'Work\' is related to:\",\"options\":[\"Money\",\"Engagement\",\"Employment\",\"Experience\"],\"answer\":3,\"hint\":\"\",\"explanation\":\"Reading yields knowledge; work yields experience.\"},{\"question\":\"Complete the analogy: PARTS : STRAP :: WOLF : ?\",\"options\":[\"FOX\",\"ANIMAL\",\"FLOW\",\"WOOD\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"The letters of the first word are reversed: PARTS -> STRAP, WOLF -> FLOW.\"},{\"question\":\"If TABLET is coded as UACMET, how is CAPSULE written in that code?\",\"options\":[\"BAORUKE\",\"DAQTUME\",\"BAQRUKE\",\"DAOTUME\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Letter shifting: T(+1)=U, A(0)=A, B(+1)=C, L(+1)=M, E(0)=E, T(0)=T. Similarly CAPSULE becomes DAQTUME.\"},{\"question\":\"Choose the word which is odd\\/different from the rest: Anger, Anxiety, Feeling, Joy\",\"options\":[\"Anger\",\"Anxiety\",\"Feeling\",\"Joy\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Anger, anxiety, and joy are specific emotions, whereas Feeling is the broad generic category.\"},{\"question\":\"If adjacent letters in the alphabet are swapped (1st&2nd, 3rd&4th: BA DC FE HG...), what is the 15th letter?\",\"options\":[\"N\",\"O\",\"P\",\"Q\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Original 15th is O and 16th is P. After swapping the 15th-16th pair (OP -> PO), the 15th letter is P.\"},{\"question\":\"In a class of 45 students, a boy is ranked 20th. When 2 new boys join ahead of him, his rank drops to 21st. What is his new rank from the end?\",\"options\":[\"25th\",\"26th\",\"27th\",\"28th\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Total students = 47. Rank from end = Total - Rank from top + 1 = 47 - 21 + 1 = 27th.\"},{\"question\":\"Pointing to a photograph, Ramesh said, \\\"She is the daughter of the only son of my grandfather.\\\" How is the girl related to Ramesh?\",\"options\":[\"Mother\",\"Sister\",\"Daughter\",\"Aunt\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Only son of grandfather = Father. Daughter of father = Sister.\"},{\"question\":\"A man travels 5 km North, turns right and walks 3 km, then turns right and walks 5 km. In which direction is he from his starting point?\",\"options\":[\"North\",\"South\",\"East\",\"West\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"He moved 5km North and 5km South (net vertical movement 0), and 3km East. He is East of starting point.\"},{\"question\":\"If RED is coded as 27 (18+5+4), what is the numerical code for GREEN (7+18+5+5+14)?\",\"options\":[\"45\",\"49\",\"52\",\"55\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Sum of alphabetical positions: G(7) + R(18) + E(5) + E(5) + N(14) = 49.\"}]', 'text', 3, 25, 1, '2026-09-02 11:54:52', '2026-09-02 12:51:44'),
(688, 141, 186, '2.4 Quantitative Aptitude & Numerical Reasoning', '24-quantitative-aptitude-numerical-reasoning-186', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. ESSENTIAL QUANTITATIVE FORMULAS</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Averages:</strong> <code>Average = Sum of Observations / Number of Observations</code>.</li>\n        <li><strong>Set Overlaps:</strong> Minimum intersection percentage: <code>P(A ∩ B) = P(A) + P(B) - 100%</code>.</li>\n        <li><strong>Double Round-Robin Tournament Matches:</strong> <code>Total Matches = n * (n - 1)</code> for n participating teams.</li>\n        <li><strong>Time and Work:</strong> If A finishes work in X days and B in Y days, together they take <code>(X * Y) / (X + Y)</code> days.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HQ08RBF642GS98RNQZQ3RT.pdf', '[{\"question\":\"Find the next number in the sequence: 8, 6, 9, 23, 87, (?)\",\"options\":[\"174\",\"226\",\"324\",\"429\"],\"answer\":3,\"hint\":\"\",\"explanation\":\"Pattern: 8*1 - 2 = 6; 6*2 - 3 = 9; 9*3 - 4 = 23; 23*4 - 5 = 87; 87*5 - 6 = 429.\"},{\"question\":\"A student on her first 4 tests received an average score of N points. If she scores (N + 20) points on her 5th test, what is her new average for all 5 tests?\",\"options\":[\"N + 20\",\"N + 10\",\"N + 4\",\"N + 5\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Total score = 4N + (N + 20) = 5N + 20. New average = (5N + 20)\\/5 = N + 4.\"},{\"question\":\"Find the incorrect number in the sequence: 1, 2, 6, 15, 31, 56, 91\",\"options\":[\"6\",\"31\",\"56\",\"91\"],\"answer\":3,\"hint\":\"\",\"explanation\":\"Differences are squares: +1, +4 (+2\\u00b2), +9 (+3\\u00b2), +16 (+4\\u00b2), +25 (+5\\u00b2 -> 31+25=56), +36 (+6\\u00b2 -> 56+36=92, not 91).\"},{\"question\":\"In Baglung, 70% speak Nepali and 60% speak Magar. What is the minimum percentage that speaks both languages?\",\"options\":[\"10%\",\"20%\",\"30%\",\"40%\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Minimum overlap = 70% + 60% - 100% = 30%.\"},{\"question\":\"Ten football teams participate in a tournament. If each team plays every other team twice (home & away), how many total matches are played?\",\"options\":[\"45\",\"55\",\"90\",\"100\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Matches = 2 * C(10,2) = 2 * (10 * 9 \\/ 2) = 90 matches.\"},{\"question\":\"There are 21 juice bottles: 7 full, 7 half-full, and 7 empty. Divided equally among 3 friends without measuring cups, how many empty bottles does each get?\",\"options\":[\"2 or 3 (depending on combination totaling 3.5 units juice and 7 bottles each)\",\"0\",\"5\",\"7\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Total juice = 7*1 + 7*0.5 = 10.5 units (3.5 units each). Each receives 7 bottles total.\"},{\"question\":\"Two numbers are in the ratio 5:4 and their difference is 10. What is the larger number?\",\"options\":[\"30\",\"40\",\"50\",\"60\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"5x - 4x = 10 => x = 10. Larger number = 5 * 10 = 50.\"},{\"question\":\"An egg basket doubles its count every day and is completely full on Day 12. On which day was the basket half (1\\/2) full?\",\"options\":[\"Day 11\",\"Day 10\",\"Day 9\",\"Day 6\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Since the count doubles each day, on the preceding day (Day 11) the basket was half full.\"},{\"question\":\"If the 7th day of a month is 3 days earlier than Friday (i.e. Tuesday), what day of the week will it be on the 16th day of the month?\",\"options\":[\"Sunday\",\"Tuesday\",\"Thursday\",\"Friday\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"7th is Tuesday. 14th is Tuesday. 15th is Wednesday. 16th is Thursday.\"},{\"question\":\"If 15 men can complete a project in 20 days, how many men are required to finish it in 12 days?\",\"options\":[\"18\",\"20\",\"25\",\"30\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Total man-days = 15 * 20 = 300. Men needed = 300 \\/ 12 = 25 men.\"}]', 'text', 4, 25, 1, '2026-09-02 11:54:52', '2026-09-02 12:59:48'),
(689, 141, 186, '2.5 Data Interpretation & Data Sufficiency', '25-data-interpretation-data-sufficiency-186', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. DATA INTERPRETATION METHODOLOGY</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Ratio Analysis:</strong> In an Import/Export graph (I/E), ratio &lt; 1.0 signifies trade surplus (Exports &gt; Imports), while ratio &gt; 1.0 signifies trade deficit.</li>\n        <li><strong>Pie Chart Angles:</strong> <code>Sector Angle = (Category Value / Total Value) * 360°</code>.</li>\n        <li><strong>Data Sufficiency Rules:</strong> Evaluate whether Statement 1 alone, Statement 2 alone, or both combined are necessary to reach a unique unambiguous solution.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HQ484V93105N933755GB8P.pdf', '[{\"question\":\"In a data table of student exam performance across 4 papers where Student W scored 60, 81, 45, 55 out of 100, what is W\'s aggregate percentage?\",\"options\":[\"58.5%\",\"60.25%\",\"62.0%\",\"65.5%\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Aggregate = (60 + 81 + 45 + 55) \\/ 400 * 100% = 241 \\/ 4 = 60.25%.\"},{\"question\":\"In an import-to-export ratio graph (I\\/E), in which scenario are exports greater than imports?\",\"options\":[\"When ratio < 1.0\",\"When ratio > 1.0\",\"When ratio = 1.0\",\"When ratio is zero\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Ratio = Imports \\/ Exports. If Ratio < 1.0, then Exports > Imports.\"},{\"question\":\"If the import-to-export ratio of a country in 1996 is 0.85 and total imports were Rs. 272 million, what were the total exports?\",\"options\":[\"Rs. 300 million\",\"Rs. 320 million\",\"Rs. 340 million\",\"Rs. 360 million\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Exports = Imports \\/ 0.85 = 272 \\/ 0.85 = Rs. 320 million.\"},{\"question\":\"In a university faculty breakdown by discipline where Psychology professors constitute 2% of total faculty (total 10 professors), what is the total faculty size?\",\"options\":[\"400\",\"500\",\"600\",\"700\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Total faculty = 10 \\/ 0.02 = 500 professors.\"},{\"question\":\"In a physics department with 32 male and 8 female professors, what is the ratio of males to females?\",\"options\":[\"3:1\",\"4:1\",\"5:1\",\"8:1\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Ratio = 32 \\/ 8 = 4:1.\"},{\"question\":\"What is \\\"Data Sufficiency\\\" in aptitude examinations?\",\"options\":[\"Determining whether the given statements provide sufficient information to solve a problem\",\"Memorizing data\",\"Calculating big sums\",\"Writing essays\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Data sufficiency questions test if given statements contain enough facts to reach a unique solution.\"},{\"question\":\"In a cumulative marks table of 100 students where 32 scored >=30 in Paper I and 21 scored >=30 in Paper II, what is the difference in qualifying students?\",\"options\":[\"9\",\"11\",\"13\",\"15\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"Difference = 32 - 21 = 11 students.\"},{\"question\":\"In a Pie Chart representing total annual budget expenditures of Rs. 1,800 billion, what angle represents an allocation of Rs. 450 billion?\",\"options\":[\"45\\u00b0\",\"60\\u00b0\",\"90\\u00b0\",\"120\\u00b0\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Angle = (450 \\/ 1800) * 360\\u00b0 = (1\\/4) * 360\\u00b0 = 90\\u00b0.\"},{\"question\":\"In a line chart showing monthly sales, what represents the rate of change between two successive months?\",\"options\":[\"The slope (gradient) of the connecting line segment\",\"The height from the axis\",\"The color of line\",\"The thickness of line\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The slope indicates the rate of growth or decline between periods.\"},{\"question\":\"What type of chart is best suited for displaying the distribution of continuous numerical data in grouped intervals?\",\"options\":[\"Histogram\",\"Pie Chart\",\"Scatter plot\",\"Venn diagram\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"A histogram displays frequency distributions across continuous class intervals.\"}]', 'text', 5, 25, 1, '2026-09-02 11:54:52', '2026-09-02 13:01:58');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(695, 143, 188, '4.1 State, Nation-Building, Constitutionalism and Democratic Values', '41-state-nation-building-constitutionalism-and-democratic-values-188', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. STATE AND CONSTITUTIONALISM</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Four Elements of the State:</strong> Population, Defined Territory, Government, and Sovereignty.</li>\n        <li><strong>Constitutionalism (संविधानवाद):</strong> The doctrine that government power is limited by and subject to constitutional law and fundamental human rights.</li>\n        <li><strong>Separation of Powers:</strong> Baron de Montesquieu (1748) tripartite separation: Legislature (lawmaking), Executive (enforcement), Judiciary (interpretation & review).</li>\n        <li><strong>Rule of Law (A.V. Dicey):</strong> Absence of arbitrary power, equality before the ordinary law, and constitutional protection of civil liberties.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HQWWQ8JDAFPA3A5TYWBZSG.pdf', '[{\"question\":\"What are the four essential elements that constitute a sovereign State under political science?\",\"options\":[\"Population, Defined Territory, Government, and Sovereignty\",\"Military, Police, Courts, and Tax\",\"Language, Culture, Religion, and History\",\"Parliament, Cabinet, Civil Service, and Judiciary\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"A state requires: Permanent Population, Defined Territory, Organized Government, and Internal\\/External Sovereignty.\"},{\"question\":\"What is Constitutionalism (\\u0938\\u0902\\u0935\\u093f\\u0927\\u093e\\u0928\\u0935\\u093e\\u0926)?\",\"options\":[\"The doctrine that government authority is limited by and derived from fundamental constitutional law and rule of law\",\"Writing long constitutions\",\"Arbitrary rule by parliament\",\"Military administration\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Constitutionalism mandates limited government, separation of powers, and supremacy of law over arbitrary power.\"},{\"question\":\"Who propounded the doctrine of \\\"Separation of Powers\\\" (\\u0936\\u0915\\u094d\\u0924\\u093f \\u092a\\u0943\\u0925\\u0915\\u0940\\u0915\\u0930\\u0923) in his 1748 work \\\"The Spirit of the Laws\\\"?\",\"options\":[\"Baron de Montesquieu\",\"John Locke\",\"Thomas Hobbes\",\"Jean-Jacques Rousseau\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Montesquieu formulated the tripartite separation among Legislative, Executive, and Judicial branches.\"},{\"question\":\"What mechanism ensures that no single branch of government exercises absolute unmonitored power?\",\"options\":[\"Checks and Balances (\\u0928\\u093f\\u092f\\u0928\\u094d\\u0924\\u094d\\u0930\\u0923 \\u0930 \\u0938\\u0928\\u094d\\u0924\\u0941\\u0932\\u0928)\",\"Total Centralization\",\"Military oversight\",\"Emergency decrees\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Checks and balances allow branches to check and balance each other (e.g. judicial review, parliamentary ratification).\"},{\"question\":\"What is the core principle of \\\"Rule of Law\\\" (\\u0935\\u093f\\u0927\\u093f\\u0915\\u094b \\u0936\\u093e\\u0938\\u0928) as articulated by A.V. Dicey?\",\"options\":[\"Supremacy of regular law, equality before the law, and predominance of legal spirit without arbitrary power\",\"Ruler\'s command is supreme\",\"Police discretionary power\",\"Different laws for public officials\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Dicey established: Absence of arbitrary power, equality of all citizens before ordinary law, and constitutional protection of rights.\"},{\"question\":\"What form of state is Nepal declared as under Article 4 of the Constitution?\",\"options\":[\"Independent, indivisible, sovereign, secular, inclusive, democratic, socialism-oriented, federal democratic republican state\",\"Unitary monarchy\",\"Religious state\",\"Military republic\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Article 4 defines the comprehensive constitutional character of the Federal Republic of Nepal.\"},{\"question\":\"What is \\\"Good Governance\\\" (\\u0938\\u0941\\u0936\\u093e\\u0938\\u0928) defined as under the Good Governance Act 2064?\",\"options\":[\"Governance ensuring rule of law, transparency, accountability, citizen participation, efficiency, and social justice\",\"Secret administration\",\"Delayed official response\",\"Bureaucratic monopoly\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Good governance ensures transparent, responsive, and accountable public service delivery.\"},{\"question\":\"What is Democratic Decentralization (\\u092a\\u094d\\u0930\\u091c\\u093e\\u0924\\u093e\\u0928\\u094d\\u0924\\u094d\\u0930\\u093f\\u0915 \\u0935\\u093f\\u0915\\u0947\\u0928\\u094d\\u0926\\u094d\\u0930\\u0940\\u0915\\u0930\\u0923)?\",\"options\":[\"Devolving political, administrative, and fiscal decision-making power from central authorities to autonomous local elected governments\",\"Concentrating power in capital city\",\"Appointing central officers to rule villages\",\"Cancelling local elections\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Decentralization empowers local self-governance closest to the citizenry.\"},{\"question\":\"What is Judicial Review (\\u0928\\u094d\\u092f\\u093e\\u092f\\u093f\\u0915 \\u092a\\u0941\\u0928\\u0930\\u093e\\u0935\\u0932\\u094b\\u0915\\u0928)?\",\"options\":[\"The constitutional power of the Supreme Court to examine and strike down legislative acts or executive orders that violate the constitution\",\"Judge salary revision\",\"Police investigation\",\"Parliament voting\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Judicial review maintains constitutional supremacy by invalidating unconstitutional laws.\"},{\"question\":\"Which political concept distinguishes a \\\"Nation\\\" (\\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930) from a \\\"State\\\" (\\u0930\\u093e\\u091c\\u094d\\u092f)?\",\"options\":[\"A Nation is a psycho-cultural community bound by shared identity\\/aspirations, whereas a State is a legal-political sovereign entity\",\"They are identical terms\",\"A nation has no people\",\"A state has no territory\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Nation refers to socio-cultural identity; State refers to the legal sovereign apparatus.\"}]', 'text', 1, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:15:26'),
(696, 143, 188, '4.2 Federal Governance & Inter-Governmental Relations in Nepal', '42-federal-governance-inter-governmental-relations-in-nepal-188', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. FEDERAL ARCHITECTURE</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Article 232 Principles:</strong> Relations among Federation, Provinces, and Local Levels shall be based on <strong>Cooperation, Co-existence, and Coordination</strong>.</li>\n        <li><strong>Inter-Provincial Council (Art. 234):</strong> Headed by the Prime Minister to resolve inter-tier political disputes.</li>\n        <li><strong>Fiscal Federalism & NNRFC (Art. 250):</strong> Recommends Equalisation Grants, Conditional Grants, Matching Grants, Special Grants, and revenue sharing formulas.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HQZXK64DD4MPBWDM6JX7CS.pdf', '[{\"question\":\"Under Article 56 of the Constitution of Nepal, what are the three tiers of the Federal structure?\",\"options\":[\"Federation, Province, and Local Level\",\"Central, Regional, and District\",\"Cabinet, Parliament, and Judiciary\",\"Zone, District, and VDC\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Article 56 establishes the three-tier federal architecture of Nepal.\"},{\"question\":\"Which Article mandates that relations among Federation, Provinces, and Local Levels shall be based on Cooperation, Co-existence, and Coordination?\",\"options\":[\"Article 232\",\"Article 50\",\"Article 100\",\"Article 300\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Article 232 lays down the guiding principles of inter-governmental coordination.\"},{\"question\":\"Which high-level forum chaired by the Prime Minister resolves political disputes between the Federation and Provinces under Article 234?\",\"options\":[\"Inter-Provincial Council (\\u0905\\u0928\\u094d\\u0924\\u0930-\\u092a\\u094d\\u0930\\u0926\\u0947\\u0936 \\u092a\\u0930\\u093f\\u0937\\u0926\\u094d)\",\"Judicial Council\",\"Constitutional Council\",\"National Planning Commission\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The Inter-Provincial Council addresses inter-tier disputes.\"},{\"question\":\"What is Fiscal Federalism (\\u0935\\u093f\\u0924\\u094d\\u0924\\u0940\\u092f \\u0938\\u0902\\u0918\\u0940\\u092f\\u0924\\u093e)?\",\"options\":[\"The system of revenue assignment, tax expenditure powers, inter-governmental fiscal transfers, and borrowing among different tiers of government\",\"Central bank printing money\",\"Provincial foreign loans\",\"Local private banking\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Fiscal federalism divides taxation and expenditure responsibilities across government tiers.\"},{\"question\":\"Which constitutional commission recommends Equalisation Grants, Conditional Grants, and Revenue Sharing formulas in Nepal?\",\"options\":[\"National Natural Resources and Fiscal Commission (NNRFC \\/ \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u093f\\u092f \\u092a\\u094d\\u0930\\u093e\\u0915\\u0943\\u0924\\u093f\\u0915 \\u0938\\u094d\\u0930\\u094b\\u0924 \\u0924\\u0925\\u093e \\u0935\\u093f\\u0924\\u094d\\u0924 \\u0906\\u092f\\u094b\\u0917)\",\"Auditor General\",\"Public Service Commission\",\"Ministry of Finance alone\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"NNRFC determines objective revenue sharing and grant allocations under Article 250.\"},{\"question\":\"What are the four types of Inter-Governmental Fiscal Transfers provided to sub-national governments in Nepal?\",\"options\":[\"Fiscal Equalisation Grant, Conditional Grant, Matching \\/ Complementary Grant, and Special Grant\",\"Gold grant, Silver grant, Cash grant, Loan grant\",\"Federal tax, Provincial tax, Local tax, Custom duty\",\"Salary grant, House grant, Travel grant, Food grant\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Inter-governmental transfers comprise Equalisation, Conditional, Matching, and Special grants.\"},{\"question\":\"Under Article 214 and Schedule 8, what are the executive powers of Local Governments?\",\"options\":[\"Local taxation, municipal police, basic education, local roads, sanitation, and drinking water services\",\"National defense and foreign affairs\",\"Currency printing\",\"Customs border posts\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Schedule 8 lists 22 exclusive local government functions.\"},{\"question\":\"Which tier of government holds residual legislative and executive powers not enumerated in Schedules 5 to 9 (Article 58)?\",\"options\":[\"The Federal Government (Federation)\",\"Provincial Government\",\"Local Level\",\"Supreme Court\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Article 58 vests residual power exclusively in the Federal Government.\"},{\"question\":\"What is the role of the District Coordination Committee (DCC \\/ \\u091c\\u093f\\u0932\\u094d\\u0932\\u093e \\u0938\\u092e\\u0928\\u094d\\u0935\\u092f \\u0938\\u092e\\u093f\\u0924\\u093f) under Article 220?\",\"options\":[\"Coordinating development projects and public services among local levels and province\\/federal agencies within the district\",\"Collecting all income tax\",\"Passing criminal verdicts\",\"Enacting national statutes\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The DCC acts as a coordinating and monitoring entity across municipal units in the district.\"},{\"question\":\"How are disputes regarding natural resource royalties (hydropower, forests, mines) among provinces and local levels resolved?\",\"options\":[\"Through NNRFC recommendations and statutory royalty allocation frameworks\",\"By military decree\",\"By cancelling projects\",\"By international arbitration\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"NNRFC sets equitable royalty distribution criteria between host local levels, provinces, and federation.\"}]', 'text', 2, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:17:05'),
(697, 143, 188, '4.3 Public Administration, Civil Service & Administrative Reform', '43-public-administration-civil-service-administrative-reform-188', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. PUBLIC ADMINISTRATION PARADIGMS</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Woodrow Wilson (1887):</strong> Father of Public Administration; politics-administration dichotomy.</li>\n        <li><strong>Max Weber Bureaucracy:</strong> Hierarchy, written regulations, impersonal application, meritocratic career tenure.</li>\n        <li><strong>New Public Management (NPM):</strong> Results-oriented management, performance indicators, efficiency, and customer satisfaction.</li>\n        <li><strong>Administrative Neutrality:</strong> Impartial, non-partisan execution of state policies.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HR63VECWSTRHH4DGA7SNVV.pdf', '[{\"question\":\"What is New Public Management (NPM \\/ \\u0928\\u0935\\u0940\\u0928 \\u0938\\u093e\\u0930\\u094d\\u0935\\u091c\\u0928\\u093f\\u0915 \\u0935\\u094d\\u092f\\u0935\\u0938\\u094d\\u0925\\u093e\\u092a\\u0928)?\",\"options\":[\"An administrative paradigm emphasizing efficiency, market mechanisms, performance metrics, customer orientation, and managerial autonomy in public sector management\",\"Classical military hierarchy\",\"Closed door bureaucracy\",\"Eliminating all civil servants\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"NPM adopts private sector management practices, results-orientation, and competitive delivery in governance.\"},{\"question\":\"Who is celebrated as the \\\"Father of Public Administration\\\" for his 1887 seminal essay \\\"The Study of Administration\\\"?\",\"options\":[\"Woodrow Wilson\",\"Max Weber\",\"Frederick Taylor\",\"Dwight Waldo\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Woodrow Wilson established public administration as an independent academic discipline.\"},{\"question\":\"What are the key characteristics of Max Weber\'s \\\"Ideal Bureaucracy\\\"?\",\"options\":[\"Hierarchical authority, written rules and regulations, impersonality, division of labor, and merit-based career tenure\",\"Nepotism and favoritism\",\"Arbitrary decision-making\",\"Informal oral agreements\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Weberian bureaucracy relies on rationality, legal authority, specialization, and neutral rules.\"},{\"question\":\"What is \\\"Administrative Neutrality\\\" (\\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0928\\u093f\\u0915 \\u0924\\u091f\\u0938\\u094d\\u0925\\u0924\\u093e)?\",\"options\":[\"The principle that civil servants must serve the democratically elected government impartially without political bias or party affiliation\",\"Refusing to work\",\"Joining political rallies\",\"Changing rules at will\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Neutrality requires civil servants to implement policies professionally regardless of which political party holds power.\"},{\"question\":\"What is \\\"Performance-Based Management\\\" in civil service?\",\"options\":[\"Evaluating and rewarding employees based on measurable outputs, Key Performance Indicators (KPIs), and service outcomes\",\"Promotions based solely on age\",\"Fixed salary without work evaluation\",\"Random assignments\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Performance management links appraisal, promotion, and incentives to verified achievements.\"},{\"question\":\"What was the major administrative reform commission formed in 2048 BS under Prime Minister Girija Prasad Koirala?\",\"options\":[\"Administrative Reform Commission 2048 (headed by PM)\",\"Buch Commission\",\"Thapa Commission\",\"Sathghare Commission\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The ARC 2048 recommended downsizing bureaucracy, privatization, and civil service modernization.\"},{\"question\":\"What is the \\\"Public Policy Cycle\\\" sequence?\",\"options\":[\"Problem Identification -> Policy Formulation -> Policy Adoption -> Policy Implementation -> Policy Evaluation\",\"Implementation before formulation\",\"Evaluation only\",\"Direct enactment without problem identification\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The standard policy cycle proceeds from agenda setting to formulation, adoption, execution, and evaluation.\"},{\"question\":\"What administrative tool is mandatory under the Good Governance Act to inform citizens of service fees, required documents, and delivery timeframes?\",\"options\":[\"Citizen Charter (\\u0928\\u093e\\u0917\\u0930\\u093f\\u0915 \\u092c\\u0921\\u093e\\u092a\\u0924\\u094d\\u0930)\",\"Police notice\",\"Cabinet secret diary\",\"Budget ledger\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Citizen Charters display service details, costs, designated officials, and resolution timeframes.\"},{\"question\":\"What is \\\"New Public Service\\\" (NPS) as advocated by Robert and Janet Denhardt?\",\"options\":[\"An approach emphasizing that public servants should serve and empower citizens rather than steer or row customers\",\"Selling public assets\",\"Automating all courts\",\"Abolishing local taxes\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"NPS prioritizes democratic citizenship, public interest, and collaborative service.\"},{\"question\":\"What is the prime objective of Administrative Capability Building (\\u0915\\u094d\\u0937\\u092e\\u0924\\u093e \\u0935\\u093f\\u0915\\u093e\\u0938)?\",\"options\":[\"Enhancing the knowledge, technical skills, ethical mindset, and digital competence of civil servants\",\"Increasing office furniture\",\"Buying cars\",\"Lengthening procedures\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Capacity development equips administrative human resources to handle complex modern public challenges.\"}]', 'text', 3, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:20:28'),
(700, 144, 189, '5.1 Social Justice, Inclusion, Human Rights and Demographic Dynamics', '51-social-justice-inclusion-human-rights-and-demographic-dynamics-189', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. SOCIAL JUSTICE & INCLUSION</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Article 42 Proportional Inclusion:</strong> Participation in state structures for marginalized groups.</li>\n        <li><strong>45% Reservation System:</strong> Women (33%), Adivasi Janajati (27%), Madhesi (22%), Dalit (9%), Tharu (5%), Muslim (4%).</li>\n        <li><strong>Demographic Dividend:</strong> High ratio of working-age population (15–64 years) creating economic growth potential.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HRAB987B199CC43R396ED1.pdf', '[{\"question\":\"What is the constitutional principle of \\\"Proportional Inclusion\\\" (\\u0938\\u092e\\u093e\\u0928\\u0941\\u092a\\u093e\\u0924\\u093f\\u0915 \\u0938\\u092e\\u093e\\u0935\\u0947\\u0936\\u0940\\u0915\\u0930\\u0923) under the Constitution of Nepal?\",\"options\":[\"Ensuring equitable participation of all historically marginalized classes, genders, and ethnic communities in state structures based on demographic presence\",\"Majority rule without minority rights\",\"Random lottery selection\",\"Inherited feudal positions\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Article 42 guarantees participation in state structures based on the principle of proportional inclusion.\"},{\"question\":\"What is \\\"Affirmative Action \\/ Positive Discrimination\\\" (\\u0938\\u0915\\u093e\\u0930\\u093e\\u0924\\u094d\\u092e\\u0915 \\u0935\\u093f\\u092d\\u0947\\u0926)?\",\"options\":[\"Temporary targeted policy measures and reservation quotas designed to uplift historically disadvantaged groups and achieve substantive equality\",\"Negative discrimination against majorities\",\"Permanent legal inequality\",\"Arbitrary taxation\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Affirmative action compensates for historical injustices to establish a level playing field.\"},{\"question\":\"What is the \\\"Demographic Dividend\\\" (\\u091c\\u0928\\u0938\\u093e\\u0902\\u0916\\u094d\\u092f\\u093f\\u0915\\u0940\\u092f \\u0932\\u093e\\u092d\\u093e\\u0902\\u0936)?\",\"options\":[\"The economic growth potential that results when the working-age population (15-64 years) is larger than the dependent population (children & elderly)\",\"A bonus paid to mothers\",\"Population census counting cost\",\"Emigration of citizens\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Demographic dividend occurs when a high proportion of working-age population drives economic productivity.\"},{\"question\":\"What does \\\"Social Capital\\\" (\\u0938\\u093e\\u092e\\u093e\\u091c\\u093f\\u0915 \\u092a\\u0941\\u0901\\u091c\\u0940) refer to in socio-economic development?\",\"options\":[\"Networks of relationships, shared norms, mutual trust, and civic cooperation that enable a society to function effectively\",\"Bank capital reserves\",\"Government treasury funds\",\"Physical roads and bridges\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Social capital encompasses interpersonal trust, civic associations, and communal cooperation.\"},{\"question\":\"Which Article of the Constitution of Nepal explicitly guarantees the \\\"Rights of Women\\\"?\",\"options\":[\"Article 38\",\"Article 18\",\"Article 25\",\"Article 45\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Article 38 guarantees equal lineage rights, reproductive healthcare rights, and property rights to women.\"},{\"question\":\"Under Article 40 of the Constitution, what specific rights are guaranteed to Dalits in Nepal?\",\"options\":[\"Proportional representation in state organs, free education with scholarships, health services, and traditional occupational modernization\",\"Separate territory\",\"Tax exemptions only\",\"Free foreign travel\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Article 40 protects Dalit rights to education, health, employment, and land empowerment.\"},{\"question\":\"What is \\\"Social Security\\\" (\\u0938\\u093e\\u092e\\u093e\\u091c\\u093f\\u0915 \\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093e) as guaranteed under Article 43 of the Constitution?\",\"options\":[\"State support provided to indigent citizens, helpless single women, persons with disabilities, children, and endangered ethnicities\",\"Military police protection\",\"Bank account security\",\"Password encryption\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Article 43 guarantees social security allowances and welfare safety nets.\"},{\"question\":\"What is \\\"Gender Mainstreaming\\\" (\\u0932\\u0948\\u0919\\u094d\\u0917\\u093f\\u0915 \\u092e\\u0942\\u0932\\u092a\\u094d\\u0930\\u0935\\u093e\\u0939\\u0940\\u0915\\u0930\\u0923)?\",\"options\":[\"Integrating a gender perspective and assessing gender implications across all legislation, public policies, budgets, and development programs\",\"Promoting one gender only\",\"Separate government for women\",\"Eliminating male employment\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Gender mainstreaming ensures policies actively advance gender equality at every stage.\"},{\"question\":\"What is the \\\"Poverty Headcount Ratio\\\" based on the Multidimensional Poverty Index (MPI)?\",\"options\":[\"The proportion of a population experiencing overlapping deprivations across health, education, and living standards\",\"Count of people without cash\",\"Count of people in slums only\",\"Number of unemployed graduates\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"MPI captures non-income deprivations in health, nutrition, education, sanitation, and electricity.\"},{\"question\":\"Which independent constitutional commission in Nepal is responsible for investigating human rights abuses under Part 26?\",\"options\":[\"National Human Rights Commission (NHRC \\/ \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u093f\\u092f \\u092e\\u093e\\u0928\\u0935 \\u0905\\u0927\\u093f\\u0915\\u093e\\u0930 \\u0906\\u092f\\u094b\\u0917)\",\"CIAA\",\"Public Service Commission\",\"Election Commission\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"NHRC monitors, investigates, and recommends compensation\\/prosecution for human rights violations.\"}]', 'text', 1, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:22:47'),
(701, 144, 189, '5.2 Macroeconomic Management, Public Finance and Resource Mobilization', '52-macroeconomic-management-public-finance-and-resource-mobilization-189', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. PUBLIC FINANCE MANAGEMENT</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Federal Budget Presentation (Art. 119):</strong> Presented annually on <strong>Jestha 15</strong> in Federal Parliament.</li>\n        <li><strong>Medium-Term Expenditure Framework (MTEF):</strong> 3-year rolling budget projections linking periodic plan targets with annual appropriations.</li>\n        <li><strong>Single VAT Rate:</strong> 13% single rate under VAT Act 2052.</li>\n        <li><strong>Treasury Single Account (TSA):</strong> Real-time consolidated government treasury liquidity managed by FCGO.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HRD4CNHMC7B0TPR4R9A632.pdf', '[{\"question\":\"What is Fiscal Policy (\\u0930\\u093e\\u091c\\u0938\\u094d\\u0935 \\u0924\\u0925\\u093e \\u092c\\u091c\\u0947\\u091f \\u0928\\u0940\\u0924\\u093f)?\",\"options\":[\"The use of government taxation, borrowing, and public spending to influence macroeconomic conditions, employment, and growth\",\"Central bank interest rate decisions\",\"Commercial bank lending rates\",\"Private company pricing\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Fiscal policy is managed by the Ministry of Finance through the annual national budget.\"},{\"question\":\"What is the Medium-Term Expenditure Framework (MTEF \\/ \\u092e\\u0927\\u094d\\u092f\\u092e\\u0915\\u093e\\u0932\\u0940\\u0928 \\u0916\\u0930\\u094d\\u091a \\u0938\\u0902\\u0930\\u091a\\u0928\\u093e)?\",\"options\":[\"A 3-year rolling expenditure planning framework linking multi-year periodic development plans with annual budget allocations\",\"A 10-year bank loan\",\"Daily cash receipt record\",\"Foreign currency reserve report\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"MTEF balances multi-year resource projections with priority development projects.\"},{\"question\":\"What is the difference between Direct Tax and Indirect Tax?\",\"options\":[\"Direct tax (e.g. Income Tax) is paid directly by the person upon whom it is levied, while Indirect tax (e.g. VAT, Customs) is shifted to the end consumer\",\"Direct tax is paid in cash; indirect tax in cheques\",\"Direct tax is local; indirect tax is foreign\",\"No difference\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Direct tax incidence cannot be shifted; indirect taxes are passed along the supply chain to final consumers.\"},{\"question\":\"What is the standard Value Added Tax (VAT) rate enforced in Nepal under the VAT Act 2052?\",\"options\":[\"13%\",\"10%\",\"15%\",\"18%\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The standard single VAT rate in Nepal is 13%.\"},{\"question\":\"What is the \\\"Balance of Payments\\\" (\\u0936\\u094b\\u0927\\u0928\\u093e\\u0928\\u094d\\u0924\\u0930 \\u0938\\u094d\\u0925\\u093f\\u0924\\u093f \\/ BoP)?\",\"options\":[\"A systematic statistical statement summarizing all economic and financial transactions between residents of a country and the rest of the world over a specified period\",\"Domestic bank account balance\",\"Government tax collection ledger\",\"Stock exchange turnover\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"BoP records all international payments, exports, imports, remittances, loans, and FDI.\"},{\"question\":\"What is \\\"Headline Inflation\\\" measured by the Consumer Price Index (CPI)?\",\"options\":[\"The measure of total inflation within an economy, including volatile food and energy commodity prices\",\"Stock price inflation\",\"Gold price index\",\"Real estate rate index\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"CPI headline inflation measures changes in the cost of a standard consumer basket of goods and services.\"},{\"question\":\"What is Public Debt (\\u0938\\u093e\\u0930\\u094d\\u0935\\u091c\\u0928\\u093f\\u0915 \\u090b\\u0923) comprised of?\",\"options\":[\"Domestic debt (treasury bills, development bonds) and External debt (concessional loans from World Bank, ADB, bilateral partners)\",\"Private bank customer loans\",\"Personal mortgages\",\"Company shares\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Public debt represents the total accumulated internal and external sovereign obligations of the government.\"},{\"question\":\"What is the statutory deadline specified in Article 119 of the Constitution for the Minister of Finance to present the annual Federal Budget to Parliament?\",\"options\":[\"Jestha 15 each year (Bikram Sambat)\",\"Ashadh 1\",\"Shrawan 1\",\"Baishakh 1\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Article 119(3) mandates presenting the federal budget to the joint session of Federal Parliament on Jestha 15.\"},{\"question\":\"What is the Treasury Single Account (TSA \\/ \\u090f\\u0915\\u0932 \\u0916\\u093e\\u0924\\u093e \\u0915\\u094b\\u0937)?\",\"options\":[\"A unified government banking arrangement where all government bank accounts are consolidated into a single central bank account structure managed by the Financial Comptroller General Office (FCGO)\",\"A personal bank account of the Finance Minister\",\"A commercial bank savings scheme\",\"An international aid account\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"TSA consolidates public revenues and payments for real-time liquidity management.\"},{\"question\":\"What is \\\"Crowding Out Effect\\\" in public economics?\",\"options\":[\"When heavy government domestic borrowing drives up interest rates, thereby reducing private sector investment spending\",\"People overcrowding banks\",\"Cancelling taxes\",\"Foreign aid reduction\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Excessive public borrowing absorbs loanable funds, crowding out private business borrowing.\"}]', 'text', 2, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:24:18'),
(702, 144, 189, '5.3 Sectoral Economic Growth: Agriculture, Industry, Tourism & Energy', '53-sectoral-economic-growth-agriculture-industry-tourism-energy-189', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. SECTORAL ENGINES OF GROWTH</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Agriculture:</strong> Commercialization via 20-Year ADS (2015–2035).</li>\n        <li><strong>Industry:</strong> Special Economic Zones (SEZs), One-Stop Service Centre, Geographical Indications (GI).</li>\n        <li><strong>Hydropower & Clean Energy:</strong> Exploiting 42,000 MW economic hydropower potential for domestic security and cross-border power trade with India and Bangladesh.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HRK5ZVQ0MKBQYD04H1FRT9.pdf', '[{\"question\":\"What is the prime strategic objective of the 20-Year Agriculture Development Strategy (ADS 2015-2035) in Nepal?\",\"options\":[\"Transforming subsistence agriculture into a competitive, commercial, inclusive, and sustainable agricultural sector\",\"Banning all agricultural imports immediately\",\"Nationalizing all private farms\",\"Eliminating all machinery\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"ADS aims to commercialize agriculture, enhance productivity, food security, and rural incomes.\"},{\"question\":\"What does \\\"Agro-Processing Industry\\\" (\\u0915\\u0943\\u0937\\u093f \\u092a\\u094d\\u0930\\u0936\\u094b\\u0927\\u0928 \\u0909\\u0926\\u094d\\u092f\\u094b\\u0917) achieve in the national value chain?\",\"options\":[\"Adds economic value to raw farm produce (processing, packaging, preservation), reducing post-harvest losses and increasing export revenues\",\"Replaces all farming with mining\",\"Burns surplus crops\",\"Increases import duties\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Agro-processing links rural farming with urban and export consumer markets.\"},{\"question\":\"What is the role of Special Economic Zones (SEZs) in Nepal\'s industrialization policy?\",\"options\":[\"Providing world-class export infrastructure, duty-free raw material imports, tax incentives, and one-stop administrative clearances for export industries\",\"Housing government ministries\",\"Agricultural farming only\",\"Residential townships\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"SEZs incentivize export-oriented industrial manufacturing.\"},{\"question\":\"What is the primary statutory body promoting, branding, and marketing Nepal\'s international tourism destinations?\",\"options\":[\"Nepal Tourism Board (NTB \\/ \\u0928\\u0947\\u092a\\u093e\\u0932 \\u092a\\u0930\\u094d\\u092f\\u091f\\u0928 \\u092c\\u094b\\u0930\\u094d\\u0921)\",\"Civil Aviation Authority\",\"Department of Immigration\",\"Hotel Association alone\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"NTB operates as a public-private partnership promoting national tourism.\"},{\"question\":\"What is \\\"Ecotourism\\\" (\\u092a\\u093e\\u0930\\u093f\\u0938\\u094d\\u0925\\u093f\\u0924\\u093f\\u0915 \\u092a\\u0930\\u094d\\u092f\\u091f\\u0928)?\",\"options\":[\"Responsible travel to natural areas that conserves the environment, sustains local well-being, and involves educational interpretation\",\"Luxury casino travel\",\"Building concrete highways through national parks\",\"Industrial sightseeing\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Ecotourism minimizes ecological footprint while benefiting local host communities.\"},{\"question\":\"Why is clean Hydropower considered Nepal\'s most strategic economic growth engine?\",\"options\":[\"It provides domestic energy security, substitutes fossil fuel imports, powers green industrialization, and earns foreign exchange through cross-border power trade\",\"It requires no capital\",\"It needs no transmission lines\",\"It pollutes water\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Hydropower provides clean energy independence and massive export potential.\"},{\"question\":\"What is the Industrial Enterprises Act 2076 classification based on fixed capital investment for \\\"Large Scale Industry\\\" in Nepal?\",\"options\":[\"Fixed capital investment exceeding Rs. 50 Crores (Rs. 500 Million)\",\"Fixed capital exceeding Rs. 10 Crores\",\"Fixed capital exceeding Rs. 1 Crore\",\"Fixed capital exceeding Rs. 100 Crores\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Industries with fixed capital > Rs. 500 Million are classified as Large Scale.\"},{\"question\":\"What is a \\\"Geographical Indication\\\" (GI \\/ \\u092d\\u094c\\u0917\\u094b\\u0932\\u093f\\u0915 \\u0938\\u0902\\u0915\\u0947\\u0924) in intellectual property and trade?\",\"options\":[\"A sign used on goods that have a specific geographical origin and possess qualities or a reputation due to that place (e.g. Ilam Tea, Palpali Dhaka)\",\"A national flag\",\"A GPS coordinate only\",\"A company logo\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"GI tags protect specialty local products tied to geographical reputation and traditional craft.\"},{\"question\":\"What is the \\\"One-Stop Service Centre\\\" (\\u090f\\u0915\\u0932 \\u092c\\u093f\\u0928\\u094d\\u0926\\u0941 \\u0938\\u0947\\u0935\\u093e \\u0915\\u0947\\u0928\\u094d\\u0926\\u094d\\u0930) established at the Department of Industry?\",\"options\":[\"A unified facility providing business registration, licensing, FDI approvals, visa facilitation, and utility connections under one roof\",\"A single retail shop\",\"A bus counter\",\"A railway station\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The One-Stop Centre simplifies foreign and domestic industrial investor approvals.\"},{\"question\":\"What is \\\"Trade Diversification\\\" (\\u0935\\u094d\\u092f\\u093e\\u092a\\u093e\\u0930 \\u0935\\u093f\\u0935\\u093f\\u0927\\u093f\\u0915\\u0930\\u0923)?\",\"options\":[\"Expanding both the basket of export products (commodity diversification) and destination countries (geographic diversification) to minimize trade risk\",\"Stopping all international trade\",\"Trading with only one neighboring country\",\"Exporting single raw materials\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Diversification broadens products and export markets, reducing vulnerability to shocks.\"}]', 'text', 3, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:27:36'),
(703, 144, 189, '5.4 Climate Vulnerability, Disaster Management and Green Economy', '54-climate-vulnerability-disaster-management-and-green-economy-189', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. DISASTER RISK REDUCTION & CLIMATE RESILIENCE</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>NDRRMA:</strong> National Disaster Risk Reduction and Management Authority under Disaster Act 2074.</li>\n        <li><strong>Disaster Cycle:</strong> Mitigation -> Preparedness -> Response & Relief -> Recovery & Resilient Reconstruction (Build Back Better).</li>\n        <li><strong>Climate Finance:</strong> Green Climate Fund (GCF) mobilization and Net-Zero 2045 carbon emissions target.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HRNX5TD537HEFHAC8RRFP8.pdf', '[{\"question\":\"In which correct chronological sequence did Nepal ratify the following major UN human rights conventions?\",\"options\":[\"Convention against Slavery -> CEDAW -> Torture Convention -> Child Rights Convention\",\"CEDAW -> Child Rights -> Torture -> Slavery\",\"Child Rights -> CEDAW -> Slavery -> Torture\",\"Torture -> Slavery -> CEDAW -> Child Rights\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Nepal ratified: Slavery Convention (1963), CEDAW (1991), Convention Against Torture \\/ CAT (1991), and Child Rights Convention \\/ CRC (1990).\"},{\"question\":\"What is the target timeline under Nepal\'s Long-Term Strategy to achieve Net-Zero greenhouse gas emissions?\",\"options\":[\"2030\",\"2040\",\"2045\",\"2060\"],\"answer\":2,\"hint\":\"\",\"explanation\":\"Nepal submitted its long-term strategy committing to carbon neutrality \\/ Net-Zero emissions by 2045.\"},{\"question\":\"Which ecosystem assessment tool calculates the biological capacity of the Earth required to absorb humanity\'s resource consumption and waste?\",\"options\":[\"Ecological Footprint\",\"Carbon Credit Counter\",\"Ozone Depletion Index\",\"Soil pH Scale\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Ecological Footprint measures ecological assets and biocapacity consumed by populations.\"},{\"question\":\"What is the prime objective of the Ramsar Convention signed in Iran in 1971?\",\"options\":[\"Nuclear non-proliferation\",\"Conservation and sustainable use of Wetlands\",\"Regulating sea trade\",\"Space exploration\"],\"answer\":1,\"hint\":\"\",\"explanation\":\"The Ramsar Convention protects wetlands of international ecological importance.\"},{\"question\":\"How many species of flora and fauna in Nepal are strictly protected under Appendix I of CITES (Convention on International Trade in Endangered Species)?\",\"options\":[\"Rare wildlife including Snow Leopard, Red Panda, One-horned Rhino, Gharial Crocodile, Bengal Tiger\",\"Domestic cattle\",\"Common crows and pigeons\",\"Cultivated rice\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"CITES Appendix I prohibits international commercial trade in endangered species like the Tiger, Rhino, and Red Panda.\"},{\"question\":\"Which international fund established under the UNFCCC provides climate finance grants and concessional loans to vulnerable developing nations?\",\"options\":[\"Green Climate Fund (GCF)\",\"World Bank Trust\",\"IMF Gold Reserve\",\"Asian Development Bank fund\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The Green Climate Fund (GCF) is the primary multilateral climate fund.\"},{\"question\":\"What does REDD+ stand for in international forest carbon financing?\",\"options\":[\"Reducing Emissions from Deforestation and Forest Degradation, and conservation of forest carbon stocks\",\"Renewable Energy Development Directorate\",\"Rural Ecology Disaster Division\",\"Resource Extraction Data Deposit\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"REDD+ creates financial incentives for developing countries to conserve forests and store carbon.\"},{\"question\":\"Which district in Nepal is home to Shey-Phoksundo National Park, renowned for trans-Himalayan biodiversity and blue sheep?\",\"options\":[\"Dolpa and Mugu\",\"Solukhumbu\",\"Kaski\",\"Chitwan\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Shey-Phoksundo National Park is located in Dolpa and Mugu districts.\"},{\"question\":\"What is the main danger posed by rapidly melting Himalayan glaciers in the Khumbu and Rolwaling valleys?\",\"options\":[\"Glacial Lake Outburst Floods (GLOFs)\",\"Earthquake triggering\",\"Sandstorms\",\"Volcanic eruptions\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Rising temperatures cause glacial lakes to expand, threatening catastrophic downstream GLOF surges.\"},{\"question\":\"What is the Sendai Framework (2015-2030) dedicated to achieving globally?\",\"options\":[\"Disaster Risk Reduction (DRR)\",\"Cyber warfare regulation\",\"Nuclear disarmament\",\"Maritime shipping lanes\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The Sendai Framework outlines global targets and priorities for Disaster Risk Reduction.\"}]', 'text', 4, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:29:06'),
(705, 145, 190, 'Civil Service Act & Rules in Nepal', 'civil-service-act-rules-in-nepal-190', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. CIVIL SERVICE ACT 2049 & RULES 2050</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Ranks:</strong> Gazetted (Special, 1st, 2nd, 3rd Class / Section Officer) and Non-Gazetted.</li>\n        <li><strong>Probation:</strong> 6 months for female employees, 1 year for male employees.</li>\n        <li><strong>Leaves:</strong> Casual leave (12 days), Home leave (1 day per 10 days worked, max 180 days encashable), Sick leave (12 days), Maternity leave (98 days).</li>\n        <li><strong>Retirement & Pension:</strong> Compulsory retirement age <strong>58 years</strong>. Monthly Pension = <code>(Years of Service * Last Basic Salary) / 50</code>.</li>\n        <li><strong>Penalties:</strong> Minor (Censure, withholding increment/promotion) vs Major (Removal with eligibility, Dismissal with disqualification).</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HS2WZYFH34264NG4WTHDQ4.pdf', '[{\"question\":\"Under the Civil Service Act 2049, what are the two broad divisions of civil service posts?\",\"options\":[\"Gazetted (\\u0930\\u093e\\u091c\\u092a\\u0924\\u094d\\u0930\\u093e\\u0902\\u0915\\u093f\\u0924) and Non-Gazetted (\\u0930\\u093e\\u091c\\u092a\\u0924\\u094d\\u0930 \\u0905\\u0928\\u0902\\u0915\\u093f\\u0924)\",\"Permanent and Daily wage\",\"Military and Police\",\"Local and International\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Civil service ranks are classified into Gazetted (Special, First, Second, Third Class \\/ Section Officer) and Non-Gazetted (First to Fifth Class).\"},{\"question\":\"Section Officer (\\u0936\\u093e\\u0916\\u093e \\u0905\\u0927\\u093f\\u0915\\u0943\\u0924) belongs to which class of civil service in Nepal?\",\"options\":[\"Gazetted Third Class (\\u0930\\u093e\\u091c\\u092a\\u0924\\u094d\\u0930\\u093e\\u0902\\u0915\\u093f\\u0924 \\u0924\\u0943\\u0924\\u0940\\u092f \\u0936\\u094d\\u0930\\u0947\\u0923\\u0940)\",\"Gazetted Second Class\",\"Non-Gazetted First Class\",\"Gazetted First Class\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Section Officer is the entry-level Gazetted Third Class officer post in civil service.\"},{\"question\":\"Under the Civil Service Act, what percentage of vacant Section Officer posts is filled through Open Competition vs Internal Promotion?\",\"options\":[\"70% Open Competition and 30% Internal Promotion \\/ Competitions (as per service quotas)\",\"100% Open\",\"100% Promotion\",\"50% Open and 50% Contract\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Civil Service Act prescribes ratios for open competitive exams and internal promotions.\"},{\"question\":\"What is the probationary period (\\u092a\\u0930\\u0940\\u0915\\u094d\\u0937\\u0923 \\u0915\\u093e\\u0932) for newly appointed male and female civil servants in Nepal?\",\"options\":[\"6 months for Female and 1 year for Male employees\",\"1 year for both\",\"2 years for both\",\"3 months for both\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Section 10 of the Civil Service Act sets a 6-month probation for women and 1 year for men.\"},{\"question\":\"How many years of minimum service in a lower rank is required to be eligible for promotion to the next higher rank in civil service?\",\"options\":[\"5 years (or 4 years in remote geographic areas)\",\"1 year\",\"10 years\",\"15 years\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"A minimum of 5 years of completed service in the post is standard for promotion eligibility.\"},{\"question\":\"Which of the following is classified as a \\\"Major Penalty\\\" (\\u0935\\u093f\\u0936\\u0947\\u0937 \\u0938\\u091c\\u093e\\u092f) under the Civil Service Act 2049?\",\"options\":[\"Removal from service (eligible for future employment) and Dismissal from service (disqualified from future government service)\",\"Censure (\\u0928\\u0938\\u093f\\u0939\\u0924)\",\"Withholding of annual grade increment for 2 years\",\"Withholding of promotion for 2 years\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Major penalties comprise Removal and Dismissal from government service.\"},{\"question\":\"What is the statutory compulsory retirement age for civil servants under the prevailing Civil Service Act 2049?\",\"options\":[\"58 years\",\"60 years\",\"62 years\",\"65 years\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Section 33 mandates compulsory retirement upon reaching 58 years of age.\"},{\"question\":\"What formula calculates monthly Pension (\\u0928\\u093f\\u0935\\u0943\\u0924\\u094d\\u0924\\u093f\\u092d\\u0930\\u0923) under the Civil Service Act?\",\"options\":[\"(Total Service Years * Last Drawn Basic Salary) \\/ 50\",\"(Total Years * Salary) \\/ 100\",\"(Years + Salary) \\/ 2\",\"Fixed 50% of salary\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Pension = (Completed Years of Service * Last Basic Salary) \\/ 50.\"},{\"question\":\"What is the maximum accumulable Home Leave (\\u0918\\u0930 \\u092c\\u093f\\u0926\\u093e) for which encashment is paid upon retirement?\",\"options\":[\"Up to 180 days\",\"90 days\",\"365 days\",\"No limit\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"A civil servant can accumulate and encash up to 180 days of unused home leave upon retirement.\"},{\"question\":\"Who serves as the Chairperson of the Promotion Committee (\\u092c\\u0922\\u0941\\u0935\\u093e \\u0938\\u092e\\u093f\\u0924\\u093f) for Gazetted civil posts in Nepal?\",\"options\":[\"Chairperson of the Public Service Commission (or designated PSC Member)\",\"Chief Secretary\",\"Ministry Secretary\",\"Minister of General Administration\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"PSC Chair \\/ Member heads the statutory promotion committee for gazetted posts.\"}]', 'text', 1, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:36:11');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(706, 145, 190, 'Administrative Law, Delegation of Authority and Discretionary Powers', 'administrative-law-delegation-of-authority-and-discretionary-powers-190', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. ADMINISTRATIVE JURISPRUDENCE</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Principles of Natural Justice:</strong> <em>Audi Alteram Partem</em> (Hear the other side) and <em>Nemo Judex in Causa Sua</em> (No one should be a judge in their own cause).</li>\n        <li><strong>Ultra Vires Doctrine:</strong> Actions executed beyond statutory limits are illegal, null, and void.</li>\n        <li><strong>Delegation Rule:</strong> <em>Delegatus non potest delegare</em> (A delegate cannot further delegate power without explicit statutory permission).</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HS65VHNQ4SMQBQND2N8WBM.pdf', '[{\"question\":\"What is Administrative Law (\\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0915\\u0940\\u092f \\u0915\\u093e\\u0928\\u0942\\u0928)?\",\"options\":[\"The body of law governing the organization, powers, duties, procedures, and judicial oversight of administrative agencies and public authorities\",\"Private corporate bylaws\",\"International maritime treaty\",\"Criminal penal code alone\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Administrative law regulates executive power, administrative adjudication, and citizen protection.\"},{\"question\":\"What are the two core cardinal pillars of the \\\"Principles of Natural Justice\\\" (\\u092a\\u094d\\u0930\\u093e\\u0915\\u0943\\u0924\\u093f\\u0915 \\u0928\\u094d\\u092f\\u093e\\u092f\\u0915\\u093e \\u0938\\u093f\\u0926\\u094d\\u0927\\u093e\\u0928\\u094d\\u0924)?\",\"options\":[\"Audi Alteram Partem (Hear the other side) and Nemo Judex in Causa Sua (No one should be a judge in their own cause)\",\"Eye for an eye and tooth for tooth\",\"Guilty until proven innocent\",\"Trial by combat\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Natural justice demands a fair hearing and freedom from personal or institutional bias.\"},{\"question\":\"What does the legal maxim \\\"Ultra Vires\\\" (\\u0905\\u0927\\u093f\\u0915\\u093e\\u0930 \\u0915\\u094d\\u0937\\u0947\\u0924\\u094d\\u0930 \\u092c\\u093e\\u0939\\u093f\\u0930) mean in administrative law?\",\"options\":[\"Beyond the legal powers or statutory authority granted by law (rendering the action null and void)\",\"Within the law\",\"Under police command\",\"Approved by cabinet\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"An act performed beyond authorized statutory limits is ultra vires and invalid.\"},{\"question\":\"What is \\\"Delegation of Authority\\\" (\\u0905\\u0927\\u093f\\u0915\\u093e\\u0930 \\u092a\\u094d\\u0930\\u0924\\u094d\\u092f\\u093e\\u092f\\u094b\\u091c\\u0928)?\",\"options\":[\"The formal assignment of specified decision-making powers and operational duties from a superior authority to a subordinate officer\",\"Resigning from office\",\"Refusing to make decisions\",\"Stealing power\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Delegation entrusts authority to subordinates while the delegator retains ultimate responsibility.\"},{\"question\":\"Can a public officer sub-delegate authority that has been delegated to them without explicit statutory authorization (\\\"Delegatus non potest delegare\\\")?\",\"options\":[\"No, a delegate cannot further delegate power unless the principal law explicitly permits it\",\"Yes, anytime\",\"Only verbally\",\"To anyone on the street\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The legal maxim establishes that delegated powers cannot be sub-delegated without legal sanction.\"},{\"question\":\"What is \\\"Administrative Discretion\\\" (\\u092a\\u094d\\u0930\\u0936\\u093e\\u0938\\u0915\\u0940\\u092f \\u0938\\u094d\\u0935\\u0935\\u093f\\u0935\\u0947\\u0915)?\",\"options\":[\"The lawful flexibility and choice granted to public officials to select the most appropriate course of action within statutory limits\",\"Arbitrary despotism\",\"Acting contrary to written law\",\"Ignoring court orders\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Discretion allows administrative flexibility guided by reason, justice, and statutory objectives.\"},{\"question\":\"What is a \\\"Quasi-Judicial Body\\\" (\\u0905\\u0930\\u094d\\u0927-\\u0928\\u094d\\u092f\\u093e\\u092f\\u093f\\u0915 \\u0928\\u093f\\u0915\\u093e\\u092f)?\",\"options\":[\"An administrative entity or officer (e.g. Chief District Officer - CDO, Land Revenue Officer) empowered by statute to adjudicate specific legal disputes\",\"Supreme Court\",\"Private company board\",\"Military unit\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Quasi-judicial bodies exercise judicial-like powers in administrative domains.\"},{\"question\":\"What is the remedy when an administrative tribunal violates procedural fairness or acts without jurisdiction?\",\"options\":[\"Filing a Writ of Certiorari \\/ Mandamus in High Court or Supreme Court\",\"Self-help retaliation\",\"Physical protest\",\"No remedy exists\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Courts exercise judicial review to quash biased or unlawful administrative tribunal orders.\"},{\"question\":\"What is \\\"Promissory Estoppel\\\" in administrative law?\",\"options\":[\"A legal doctrine preventing the government from going back on a clear promise made to a citizen who relied upon it to their detriment\",\"A bank promissory note\",\"A police warning\",\"A tax receipt\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Promissory estoppel binds public authorities to lawful representations relied upon in good faith.\"},{\"question\":\"What is the concept of \\\"Ombudsman\\\" (\\u0932\\u094b\\u0915\\u093e\\u092f\\u0941\\u0915\\u094d\\u0924)?\",\"options\":[\"An independent statutory official appointed to investigate citizen complaints against public maladministration, unfairness, or corruption\",\"A police chief\",\"A cabinet minister\",\"A court clerk\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"An Ombudsman investigates citizen grievances against administrative abuse and injustice.\"}]', 'text', 2, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:37:59'),
(708, 145, 190, 'Financial Procedures & Fiscal Responsibility Legislation', '64-financial-procedures-fiscal-responsibility-legislation-190', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. FISCAL RESPONSIBILITY ACT 2076</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Accounting Officer (लेखा उत्तरदायी अधिकृत):</strong> The Secretary of the Ministry who carries primary legal responsibility for budget execution and internal controls.</li>\n        <li><strong>Beruju Classification:</strong> Regularizable, Recoverable, and Unsettled Advances. Reviewed by the Public Accounts Committee (PAC).</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HS96P6GK6BF34EKRS1KZ3T.pdf', '[{\"question\":\"Which legislation governs public expenditure discipline, fiscal accountability, and treasury operations in Nepal?\",\"options\":[\"Financial Procedures and Fiscal Responsibility Act, 2076 (2019)\",\"Company Act 2063\",\"Civil Code 2074\",\"Police Act 2012\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The Financial Procedures and Fiscal Responsibility Act 2076 regulates budget discipline, cash management, and fiscal duties.\"},{\"question\":\"Who is the apex government accounting and treasury authority responsible for monitoring public expenditure and consolidated accounts across Nepal?\",\"options\":[\"Financial Comptroller General Office (FCGO \\/ \\u092e\\u0939\\u093e\\u0932\\u0947\\u0916\\u093e \\u0928\\u093f\\u092f\\u0928\\u094d\\u0924\\u094d\\u0930\\u0915 \\u0915\\u093e\\u0930\\u094d\\u092f\\u093e\\u0932\\u092f)\",\"Auditor General alone\",\"Inland Revenue Department\",\"Nepal Rastra Bank alone\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"FCGO manages government accounting standards, TSA, LMBIS, and public expenditure control.\"},{\"question\":\"At the district level, which office operates treasury single accounts and processes government salary\\/project payment authorizations?\",\"options\":[\"District Treasury Controller Office (DTCO \\/ \\u0915\\u094b\\u0937 \\u0924\\u0925\\u093e \\u0932\\u0947\\u0916\\u093e \\u0928\\u093f\\u092f\\u0928\\u094d\\u0924\\u094d\\u0930\\u0915 \\u0915\\u093e\\u0930\\u094d\\u092f\\u093e\\u0932\\u092f - \\u0915\\u094b\\u0932\\u0947\\u0928\\u093f\\u0915\\u093e)\",\"District Police Office\",\"Land Revenue Office\",\"District Court\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"DTCO handles treasury payments and expenditure accounting for all government offices in the district.\"},{\"question\":\"What is the responsibility of the \\\"Accounting Officer\\\" (\\u0932\\u0947\\u0916\\u093e \\u0909\\u0924\\u094d\\u0924\\u0930\\u0926\\u093e\\u092f\\u0940 \\u0905\\u0927\\u093f\\u0915\\u0943\\u0924) under the Fiscal Responsibility Act?\",\"options\":[\"The Ministry Secretary \\/ Chief of Agency who is legally responsible for budget execution, internal control, financial regularity, and Beruju settlement\",\"The junior bank teller\",\"The computer typist\",\"An outside auditor\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The Secretary of the Ministry\\/Agency is designated as the Accounting Officer with primary financial responsibility.\"},{\"question\":\"What is the legal deadline for settling official travel and program Advances (\\u092a\\u0947\\u0936\\u094d\\u0915\\u0940)?\",\"options\":[\"Within 15 to 30 days of completing the work or fiscal year end, beyond which interest and disciplinary deductions apply\",\"5 years\",\"Whenever convenient\",\"Never settled\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Unsettled advances are classified as irregularities and deducted from salaries with penalties.\"},{\"question\":\"What are the three categories of Audit Queries \\/ Irregularities (\\u092c\\u0947\\u0930\\u0941\\u091c\\u0941)?\",\"options\":[\"Regularizable (\\u0928\\u093f\\u092f\\u092e\\u093f\\u0924 \\u0917\\u0930\\u094d\\u0928\\u0947), Recoverable (\\u0905\\u0938\\u0941\\u0932\\u0940 \\u0917\\u0930\\u094d\\u0928\\u0947), and Advances Remaining (\\u092a\\u0947\\u0936\\u094d\\u0915\\u0940 \\u092c\\u093e\\u0901\\u0915\\u0940)\",\"Income, Expense, Asset\",\"Small, Medium, Big\",\"Direct, Indirect, Tax\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Beruju is officially classified into Regularizable, Recoverable, and Unsettled Advances.\"},{\"question\":\"Which parliamentary committee conducts public hearings and scrutinizes the Auditor General\'s annual report on government financial irregularities?\",\"options\":[\"Public Accounts Committee (PAC \\/ \\u0938\\u093e\\u0930\\u094d\\u0935\\u091c\\u0928\\u093f\\u0915 \\u0932\\u0947\\u0916\\u093e \\u0938\\u092e\\u093f\\u0924\\u093f)\",\"State Affairs Committee\",\"Finance Committee\",\"Law and Human Rights Committee\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"The PAC holds ministries and agencies accountable for financial discipline and Beruju clearance.\"},{\"question\":\"What is \\\"Internal Audit\\\" (\\u0906\\u0928\\u094d\\u0924\\u0930\\u093f\\u0915 \\u0932\\u0947\\u0916\\u093e\\u092a\\u0930\\u0940\\u0915\\u094d\\u0937\\u0923) conducted by DTCO\\/FCGO?\",\"options\":[\"Continuous, concurrent audit during the fiscal year to ensure legal compliance, financial regularity, and proper documentation before final external audit\",\"Audit by foreign firms\",\"Police investigation\",\"Public survey\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Internal audit checks transactions concurrently to maintain financial regularity.\"},{\"question\":\"What is the \\\"Consolidated Fund of the State\\\" (\\u0938\\u0902\\u0918\\u0940\\u092f \\u0938\\u091e\\u094d\\u091a\\u093f\\u0924 \\u0915\\u094b\\u0937) under Article 116 of the Constitution?\",\"options\":[\"The central government treasury account where all revenues, loan receipts, and loan repayments received by the Government of Nepal are deposited\",\"A private bank locker\",\"Party fund\",\"A local savings club\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"All federal revenues and loan proceeds are credited into the Federal Consolidated Fund.\"},{\"question\":\"What statute authorizes the government to withdraw funds from the Consolidated Fund for annual public expenditures?\",\"options\":[\"Appropriation Act (\\u0935\\u093f\\u0928\\u093f\\u092f\\u094b\\u091c\\u0928 \\u0910\\u0928)\",\"Civil Code\",\"Customs Act\",\"Police Rules\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Under Article 118, no money can be withdrawn from the Consolidated Fund without an Appropriation Act passed by Parliament.\"}]', 'text', 3, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:43:12'),
(709, 145, 190, ' Office Management, Decision Making and Official Correspondence', '65-office-management-decision-making-and-official-correspondence-190', '<div class=\"space-y-6\">\n    <h2 class=\"text-xl font-bold text-gray-900 border-b border-gray-200 pb-2\">A. ADMINISTRATIVE OFFICE PROCEDURES</h2>\n    <ul class=\"list-disc pl-5 space-y-1 text-sm text-gray-700\">\n        <li><strong>Tippani (टिप्पणी / Office Note):</strong> Formal written administrative note analyzing facts, legal provisions, precedents, and proposed options to reach a structured official decision.</li>\n        <li><strong>Darta & Chalani:</strong> Darta registers incoming documents with unique entry numbers; Chalani registers and dispatches outgoing decisions.</li>\n        <li><strong>Records Retention Schedules:</strong> Preservation of permanent records vs scheduled destruction of expired routine paperwork.</li>\n    </ul>\n</div>', NULL, 'lessons/pdfs/01M1HSCX6CDTCA0N33Z7XGG61V.pdf', '[{\"question\":\"What is an official \\\"Tippani\\\" (\\u091f\\u093f\\u092a\\u094d\\u092a\\u0923\\u0940 \\/ Office Note) in Nepalese civil administration?\",\"options\":[\"A formal written administrative note initiated by a desk officer presenting facts, legal rules, precedents, and policy options to seek a structured decision from higher authorities\",\"A personal letter\",\"A casual text message\",\"A published press release\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Tippani is the cornerstone of official bureaucratic decision-making in Nepal.\"},{\"question\":\"What are the essential structural components of a standard government Tippani?\",\"options\":[\"Subject, Background facts, Legal\\/Rule reference, Analysis of options, Proposed recommendation, and Signature with date\",\"Greeting only\",\"Financial bills only\",\"List of names only\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"A complete Tippani analyzes facts and laws, leading to a clear, actionable recommendation.\"},{\"question\":\"What is \\\"Darta\\\" (\\u0926\\u0930\\u094d\\u0924\\u093e \\/ Registration) in government record management?\",\"options\":[\"The systematic recording of all incoming letters, petitions, and official documents in a chronological registration ledger with a unique entry number\",\"Sending outgoing mail\",\"Destroying old files\",\"Printing vouchers\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Darta registers incoming official correspondence.\"},{\"question\":\"What is \\\"Chalani\\\" (\\u091a\\u0932\\u093e\\u0928\\u0940 \\/ Dispatch) in government office administration?\",\"options\":[\"The formal recording and dispatching of outgoing official letters and decisions with a unique dispatch number and date\",\"Receiving mail\",\"Internal meetings\",\"Filing taxes\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Chalani registers outgoing correspondence.\"},{\"question\":\"Under the Good Governance Act 2064, what is the maximum standard timeframe for an administrative officer to make a decision on a routine citizen file?\",\"options\":[\"Within 7 days (or immediately if routine; max 15 days if complex investigation required)\",\"6 months\",\"1 year\",\"No time limit\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Good governance rules require prompt decisions without unnecessary administrative delay.\"},{\"question\":\"What is the hierarchy of official correspondence from lower to higher rank in government administration?\",\"options\":[\"Initiated by Assistant\\/Officer -> Verified by Under Secretary -> Reviewed by Joint Secretary -> Approved by Secretary\\/Minister\",\"Directly from peon to President\",\"Reversed from Minister down without files\",\"Through private email\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Files move hierarchically through the administrative chain of command.\"},{\"question\":\"What is \\\"File Retention \\/ Disposal Schedule\\\" (\\u0927\\u0941\\u0932\\u094d\\u092f\\u093e\\u0909\\u0928\\u0947 \\u0930 \\u0905\\u092d\\u093f\\u0932\\u0947\\u0916 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923)?\",\"options\":[\"A statutory schedule categorizing documents into permanent records (never destroyed), 20-year records, 10-year records, and routine records destroyed after 1-3 years\",\"Burning all files annually\",\"Keeping everything forever\",\"Throwing mail\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Document retention schedules preserve historically vital files while discarding expired temporary paperwork.\"},{\"question\":\"What is a \\\"Cabinet Note\\\" (\\u092e\\u0928\\u094d\\u0924\\u094d\\u0930\\u093f\\u092a\\u0930\\u093f\\u0937\\u0926\\u094d \\u092a\\u094d\\u0930\\u0938\\u094d\\u0924\\u093e\\u0935)?\",\"options\":[\"A high-level formal proposal prepared by a ministry secretary with ministerial approval submitted to the Council of Ministers (Cabinet) for policy decisions\",\"A secret memo\",\"A budget bill draft\",\"A court summons\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Cabinet proposals seek executive approval on national policies and statutory bills.\"},{\"question\":\"What is an \\\"Office Circular\\\" (\\u092a\\u0930\\u093f\\u092a\\u0924\\u094d\\u0930)?\",\"options\":[\"An official administrative directive or instructional notice issued to all subordinate offices and departments for uniform compliance\",\"An advertising flyer\",\"A personal greeting\",\"A court writ\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Circulars standardize operational procedures across all subordinate branch offices.\"},{\"question\":\"What is a \\\"Citizen Charter\\\" (\\u0928\\u093e\\u0917\\u0930\\u093f\\u0915 \\u092c\\u0921\\u093e\\u092a\\u0924\\u094d\\u0930) posted at the entrance of government offices?\",\"options\":[\"A public commitment detailing services available, designated officers, room numbers, processing fees, required documents, and service delivery timeframes\",\"A political poster\",\"A price menu\",\"An office staff directory only\"],\"answer\":0,\"hint\":\"\",\"explanation\":\"Citizen Charters ensure transparency and empower citizens with service delivery commitments.\"}]', 'text', 4, 30, 1, '2026-09-02 11:54:52', '2026-09-02 13:43:29'),
(710, 146, 191, '1.1 Topographical Structure and Physical Features of Nepal', '11-topographical-structure-and-physical-features-of-nepal-191', '<h3>1. Geographical Overview of Nepal</h3>\n<p>Nepal is a landlocked sovereign state in South Asia, located along the southern slopes of the Himalayan mountain ranges between latitudes 26°22\' N to 30°27\' N and longitudes 80°04\' E to 88°12\' E. Total land area is <strong>147,516 sq. km</strong> (incorporating the updated political map including Limpiyadhura, Lipulekh, and Kalapani).</p>\n\n<h3>2. Ecological and Topographical Divisions</h3>\n<p>Nepal is divided into three distinct physiographic/ecological regions from north to south:</p>\n<ul>\n    <li><strong>Himalayan Region (Parbat / Himal):</strong>\n        <ul>\n            <li>Covers approximately <strong>15%</strong> of the total land surface, with altitudes ranging from 3,000m to 8,848.86m above sea level.</li>\n            <li>Home to 8 of the world\'s 14 peaks above 8,000 meters, including Mount Everest (Sagarmatha - 8,848.86m), Kanchenjunga (8,586m), Lhotse (8,516m), Makalu (8,485m), Cho Oyu (8,188m), Dhaulagiri (8,167m), Manaslu (8,163m), and Annapurna I (8,091m).</li>\n            <li>Characterized by permanent glaciers, moraines, high-altitude alpine meadows, and permafrost.</li>\n        </ul>\n    </li>\n    <li><strong>Hilly Region (Pahad):</strong>\n        <ul>\n            <li>Covers approximately <strong>68%</strong> of total land area, with altitudes between 600m and 3,000m.</li>\n            <li>Composed of two primary mountain systems: <em>Mahabharat Range</em> (Lesser Himalayas) and <em>Siwalik / Chure Range</em> (Sub-Himalayas).</li>\n            <li>Contains fertile inter-montane tectonic valleys (e.g., Kathmandu Valley, Pokhara Valley, Dang Valley).</li>\n        </ul>\n    </li>\n    <li><strong>Terai Region (Madhesh & Inner Terai):</strong>\n        <ul>\n            <li>Covers approximately <strong>17%</strong> of total area, extending along the southern frontier with altitudes between 60m (Mukhyapatti Musharniya, Dhanusha) and 600m.</li>\n            <li>Rich in alluvial soil; known as the \"Granary of Nepal\" (Annapurna of Nepal) due to high agricultural productivity.</li>\n        </ul>\n    </li>\n</ul>\n\n<h3>3. Major River Basins (Drainage Systems)</h3>\n<ol>\n    <li><strong>Koshi River System (Eastern Nepal):</strong> Largest river system by water discharge volume. Comprises 7 tributaries (Sunkoshi, Tamakoshi, Dudhkoshi, Indrawati, Bhotekoshi, Arun, Tamor). Originates in Tibet and Eastern Himalayas.</li>\n    <li><strong>Gandaki River System (Central Nepal):</strong> Known as Saptagandaki. Includes Trishuli, Budhigandaki, Marsyangdi, Seti Gandaki, Madi, Kaligandaki, and Daraudi. Kaligandaki forms the world\'s deepest gorge (Dana Gorge) between Annapurna and Dhaulagiri.</li>\n    <li><strong>Karnali River System (Western Nepal):</strong> Longest river within Nepal (~507 km). Formed by Humla Karnali, Mugu Karnali, Tila, Bheri, and Seti rivers. Originates near Lake Mansarovar.</li>\n    <li><strong>Mahakali River System (Far-Western Border):</strong> Forms the western boundary between Nepal and India.</li>\n</ol>', NULL, 'lessons/pdfs/Geography of Nepal_compressed.pdf', '[{\"question\":\"What is the official total land area of Nepal in square kilometers?\",\"options\":[\"147,181 sq. km\",\"147,516 sq. km\",\"147,984 sq. km\",\"148,000 sq. km\"],\"answer\":1,\"explanation\":\"The official updated area of Nepal including Limpiyadhura and Lipulekh is 147,516 sq. km.\"},{\"question\":\"What percentage of Nepal\'s total land area is occupied by the Hilly (Pahad) region?\",\"options\":[\"15%\",\"68%\",\"17%\",\"50%\"],\"answer\":1,\"explanation\":\"The Hilly region covers approximately 68% of Nepal\'s land surface.\"},{\"question\":\"What percentage of Nepal\'s land area is covered by the Himalayan region?\",\"options\":[\"15%\",\"68%\",\"17%\",\"25%\"],\"answer\":0,\"explanation\":\"The Himalayan region covers approximately 15% of the total land.\"},{\"question\":\"Which is the longest river in Nepal?\",\"options\":[\"Koshi River\",\"Gandaki River\",\"Karnali River\",\"Bagmati River\"],\"answer\":2,\"explanation\":\"Karnali is the longest river in Nepal with a length of approximately 507 km.\"},{\"question\":\"Which river system has the highest water discharge volume in Nepal?\",\"options\":[\"Koshi River System\",\"Gandaki River System\",\"Karnali River System\",\"Mahakali River System\"],\"answer\":0,\"explanation\":\"The Koshi River system has the largest water discharge volume.\"},{\"question\":\"What is the official height of Mount Everest (Sagarmatha)?\",\"options\":[\"8,848.00 m\",\"8,848.86 m\",\"8,850.00 m\",\"8,844.43 m\"],\"answer\":1,\"explanation\":\"The joint measurement announced in 2020 by Nepal and China is 8,848.86 meters.\"},{\"question\":\"The deepest gorge in the world (Dana Gorge \\/ Kali Gandaki Gorge) lies between which two mountain massifs?\",\"options\":[\"Everest and Lhotse\",\"Annapurna and Dhaulagiri\",\"Kanchenjunga and Makalu\",\"Manaslu and Ganesh Himal\"],\"answer\":1,\"explanation\":\"Dana Gorge lies between the Annapurna and Dhaulagiri mountain ranges.\"},{\"question\":\"What is the lowest altitude point of Nepal?\",\"options\":[\"Kechana Kalan, Jhapa (58m)\",\"Mukhyapatti Musharniya, Dhanusha (59-60m)\",\"Birgunj (70m)\",\"Janakpur (65m)\"],\"answer\":1,\"explanation\":\"Mukhyapatti Musharniya in Dhanusha \\/ Kechana Kalan in Jhapa represent the lowest points (~58-60m).\"},{\"question\":\"How many peaks above 8,000 meters are located in Nepal?\",\"options\":[\"6\",\"8\",\"10\",\"14\"],\"answer\":1,\"explanation\":\"Out of the world\'s 14 peaks above 8,000 meters, 8 are located in Nepal.\"},{\"question\":\"Which mountain range lies south of the Mahabharat range in Nepal?\",\"options\":[\"Greater Himalayas\",\"Chure \\/ Siwalik Range\",\"Tibetan Plateau\",\"Lesser Himalayas\"],\"answer\":1,\"explanation\":\"The Chure (Siwalik) range forms the southernmost mountain belt in Nepal.\"}]', 'text', 1, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:39'),
(711, 146, 191, '1.2 Climate of Nepal: Types, Characteristics and Weather Dynamics', '12-climate-of-nepal-types-characteristics-and-weather-dynamics-191', '<h3>1. Factors Influencing Climate in Nepal</h3>\n<p>Nepal experiences extraordinary climatic diversity within a narrow north-south span of ~193 km due to sharp altitudinal gradients, topography, and the South Asian summer monsoon.</p>\n\n<h3>2. Five Altitudinal Climatic Zones</h3>\n<table border=\"1\" cellpadding=\"8\" style=\"border-collapse: collapse; width: 100%;\">\n    <thead>\n        <tr style=\"background-color: #f1f5f9;\">\n            <th>Climatic Zone</th>\n            <th>Altitude Range</th>\n            <th>Average Summer Temp</th>\n            <th>Characteristics</th>\n        </tr>\n    </thead>\n    <tbody>\n        <tr>\n            <td><strong>Subtropical / Tropical</strong></td>\n            <td>Below 1,200m (Terai, Chure, Valleys)</td>\n            <td>30°C - 42°C</td>\n            <td>Hot, humid summers; mild winters; high monsoon rainfall.</td>\n        </tr>\n        <tr>\n            <td><strong>Warm Temperate</strong></td>\n            <td>1,200m - 2,100m (Mid-Hills)</td>\n            <td>20°C - 30°C</td>\n            <td>Pleasant climate, moderate rainfall; Kathmandu & Pokhara valleys.</td>\n        </tr>\n        <tr>\n            <td><strong>Cool Temperate</strong></td>\n            <td>2,100m - 3,300m (High-Hills)</td>\n            <td>15°C - 20°C</td>\n            <td>Chilly winters with frost and occasional light snow; coniferous forests.</td>\n        </tr>\n        <tr>\n            <td><strong>Alpine</strong></td>\n            <td>3,300m - 5,000m (Lower Himalayas)</td>\n            <td>10°C - 15°C</td>\n            <td>Cold alpine meadows; short growing season; heavy snowfall.</td>\n        </tr>\n        <tr>\n            <td><strong>Tundra / Arctic</strong></td>\n            <td>Above 5,000m (Snowline)</td>\n            <td>Below 0°C</td>\n            <td>Perpetual frost, polar ice caps, rock desert, no vegetation.</td>\n        </tr>\n    </tbody>\n</table>\n\n<h3>3. Monsoon System in Nepal</h3>\n<ul>\n    <li><strong>Summer Monsoon (South-East):</strong> Enters from Bay of Bengal in early June and lasts until late September. Brings <strong>80% of total annual precipitation</strong>. Rainfall decreases from east to west and south to north.</li>\n    <li><strong>Winter Monsoon (Western Disturbance):</strong> Enters from the Mediterranean Sea in December-February. Brings snow to high mountains and light winter showers essential for winter crops (wheat, mustard).</li>\n    <li><strong>Rain Shadow Areas:</strong> Trans-Himalayan districts like Mustang and Manang receive very little rainfall (< 300 mm/year) due to the obstruction of the Annapurna and Dhaulagiri ranges.</li>\n</ul>', NULL, NULL, '[{\"question\":\"What percentage of annual rainfall in Nepal is brought by the Summer Monsoon?\",\"options\":[\"50%\",\"60%\",\"80%\",\"95%\"],\"answer\":2,\"explanation\":\"Around 80% of total annual rainfall occurs during the Summer Monsoon (June to September).\"},{\"question\":\"From which body of water does the summer monsoon originate before entering Nepal?\",\"options\":[\"Arabian Sea\",\"Bay of Bengal\",\"Mediterranean Sea\",\"Red Sea\"],\"answer\":1,\"explanation\":\"The summer monsoon enters Nepal from the Bay of Bengal.\"},{\"question\":\"Which direction does the summer monsoon travel across Nepal?\",\"options\":[\"West to East\",\"East to West\",\"North to South\",\"North-West to South-East\"],\"answer\":1,\"explanation\":\"The monsoon enters from the South-East\\/East and advances towards the West.\"},{\"question\":\"Winter rainfall in western Nepal is primarily caused by which weather system?\",\"options\":[\"South-East Monsoon\",\"Western Disturbance (Mediterranean Sea)\",\"Typhoon circulation\",\"Polar vortex\"],\"answer\":1,\"explanation\":\"Western Disturbance originating from the Mediterranean brings winter showers and snow.\"},{\"question\":\"Which district in Nepal receives the lowest annual rainfall due to rain-shadow effect?\",\"options\":[\"Jhapa\",\"Mustang\",\"Kaski\",\"Ilam\"],\"answer\":1,\"explanation\":\"Mustang and Manang lie in the rain-shadow of the Himalayas and receive very little rainfall (<300mm\\/yr).\"},{\"question\":\"Which place in Nepal records the highest average annual rainfall?\",\"options\":[\"Lumle, Kaski\",\"Dhangadhi, Kailali\",\"Namche Bazaar\",\"Dharan, Sunsari\"],\"answer\":0,\"explanation\":\"Lumle (near Pokhara, Kaski) receives over 5,000 mm of annual rainfall.\"},{\"question\":\"Which climatic zone is found at altitudes between 1,200m and 2,100m in Nepal?\",\"options\":[\"Tropical\",\"Warm Temperate\",\"Alpine\",\"Tundra\"],\"answer\":1,\"explanation\":\"Warm Temperate climate prevails in the mid-hills (1,200m - 2,100m).\"},{\"question\":\"The permanent snowline in Nepal generally starts above which altitude?\",\"options\":[\"3,000m\",\"4,000m\",\"5,000m\",\"6,500m\"],\"answer\":2,\"explanation\":\"The permanent snowline and Tundra zone in Nepal begins above 5,000 meters.\"},{\"question\":\"What is the climate of the Terai and Inner Terai regions?\",\"options\":[\"Sub-tropical \\/ Tropical\",\"Alpine\",\"Temperate\",\"Polar\"],\"answer\":0,\"explanation\":\"The Terai has a tropical to sub-tropical climate with hot summers and mild winters.\"},{\"question\":\"During which months does the post-monsoon (Autumn\\/Sharad) season occur in Nepal?\",\"options\":[\"March - May\",\"June - August\",\"October - November\",\"December - February\"],\"answer\":2,\"explanation\":\"October to November is the post-monsoon autumn season with clear skies.\"}]', 'text', 2, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(712, 146, 191, '1.3 Major Natural Resources and Conservation in Nepal', '13-major-natural-resources-and-conservation-in-nepal-191', '<h3>1. Water Resources</h3>\n<p>Nepal possesses over 6,000 rivers, rivulets, and streams with an estimated total run-off volume of 225 billion cubic meters annually. Nepal accounts for approximately 2.27% of global freshwater resources.</p>\n\n<h3>2. Forest Resources</h3>\n<p>According to recent Forest Resource Assessments, forests and other wooded land cover approximately <strong>45.31%</strong> of Nepal\'s total land area.</p>\n<ul>\n    <li><strong>Terai & Siwalik Forests:</strong> Sal (<em>Shorea robusta</em>), Sissoo, Khair, Saj, Semal.</li>\n    <li><strong>Mid-Hills Forests:</strong> Pine (Chir pine, Blue pine), Chilaune, Katus, Rhododendron (Lali Gurans - National Flower).</li>\n    <li><strong>High Mountain Forests:</strong> Fir, Spruce, Birch (Bhojpatra), Juniper, Himalayan Yew (Lothsalla - source of Taxol).</li>\n</ul>\n\n<h3>3. Protected Areas & Biodiversity</h3>\n<ul>\n    <li><strong>National Parks (12):</strong> Chitwan National Park (First NP, 1973; UNESCO World Heritage Site), Sagarmatha NP (UNESCO Site), Bardiya NP, Langtang NP, Rara NP, Shey-Phoksundo NP (Largest NP - 3,555 sq. km), Makalu Barun NP, Shivapuri Nagarjun NP, Banke NP, Khaptad NP, Shuklaphanta NP, Parsa NP.</li>\n    <li><strong>Wildlife Reserves (1):</strong> Koshi Tappu Wildlife Reserve (Ramsar Wetland Site, home to wild water buffalo / Arna).</li>\n    <li><strong>Conservation Areas (6):</strong> Annapurna Conservation Area (Largest - 7,629 sq. km), Kanchenjunga CA, Manaslu CA, Gaurishankar CA, Api Nampa CA, Blackbuck (Krishnasar) CA.</li>\n    <li><strong>Hunting Reserve (1):</strong> Dhorpatan Hunting Reserve (Famous for Blue Sheep / Naur).</li>\n</ul>\n\n<h3>4. Mineral Resources</h3>\n<p>Limestone (Chun Dhunga - essential for cement production in Udayapur, Hetauda, Chobhar), Iron ore (Phulchoki, Those), Copper, Zinc, Lead, Mica, Magnesite (Kharidhunga), Semi-precious gemstones (Tourmaline, Ruby, Aquamarine in Ganesh Himal and Sankhuwasabha), and natural gas in Kathmandu Valley.</p>', NULL, NULL, '[{\"question\":\"What percentage of Nepal\'s land area is covered by forest and other wooded land?\",\"options\":[\"25.4%\",\"37.0%\",\"45.31%\",\"55.0%\"],\"answer\":2,\"explanation\":\"National forest assessments show approximately 45.31% forest and wooded land cover.\"},{\"question\":\"Which is the first national park established in Nepal (1973 AD)?\",\"options\":[\"Sagarmatha National Park\",\"Chitwan National Park\",\"Bardiya National Park\",\"Langtang National Park\"],\"answer\":1,\"explanation\":\"Chitwan National Park was established in 1973 AD as Nepal\'s first national park.\"},{\"question\":\"Which is the largest National Park in Nepal by surface area?\",\"options\":[\"Chitwan NP\",\"Shey-Phoksundo NP (3,555 sq. km)\",\"Makalu Barun NP\",\"Bardiya NP\"],\"answer\":1,\"explanation\":\"Shey-Phoksundo National Park (3,555 sq. km) is the largest national park in Nepal.\"},{\"question\":\"Which is the only Hunting Reserve in Nepal?\",\"options\":[\"Koshi Tappu\",\"Parsa\",\"Dhorpatan Hunting Reserve\",\"Shuklaphanta\"],\"answer\":2,\"explanation\":\"Dhorpatan Hunting Reserve is the sole hunting reserve in Nepal.\"},{\"question\":\"What is the largest Conservation Area in Nepal?\",\"options\":[\"Annapurna Conservation Area (7,629 sq. km)\",\"Kanchenjunga CA\",\"Manaslu CA\",\"Gaurishankar CA\"],\"answer\":0,\"explanation\":\"Annapurna Conservation Area (ACAP) is the largest conservation area in Nepal.\"},{\"question\":\"Koshi Tappu Wildlife Reserve is globally renowned for protecting which endangered animal?\",\"options\":[\"Snow Leopard\",\"Wild Water Buffalo (Arna)\",\"One-horned Rhinoceros\",\"Red Panda\"],\"answer\":1,\"explanation\":\"Koshi Tappu is the prime habitat for wild water buffalo (Arna).\"},{\"question\":\"Which mineral deposit is abundantly found and mined at Kharidhunga, Dolakha?\",\"options\":[\"Gold\",\"Magnesite\",\"Coal\",\"Petroleum\"],\"answer\":1,\"explanation\":\"Kharidhunga has one of South Asia\'s largest high-grade magnesite deposits.\"},{\"question\":\"What is the national flower of Nepal?\",\"options\":[\"Lotus\",\"Rhododendron (Lali Gurans)\",\"Marigold\",\"Orchid\"],\"answer\":1,\"explanation\":\"Rhododendron Arboreum (Lali Gurans) is the national flower.\"},{\"question\":\"What is the national bird of Nepal?\",\"options\":[\"Spiny Babbler\",\"Danphe (Lophophorus \\/ Impeyan Pheasant)\",\"Himalayan Monal\",\"Peacock\"],\"answer\":1,\"explanation\":\"Danphe (Lophophorus) is the national bird of Nepal.\"},{\"question\":\"Which tree species found in the Himalayas of Nepal is famous as a natural source for the anti-cancer drug Taxol?\",\"options\":[\"Yarsagumba\",\"Himalayan Yew (Lothsalla)\",\"Chir Pine\",\"Sissoo\"],\"answer\":1,\"explanation\":\"Himalayan Yew (Taxus wallichiana \\/ Lothsalla) leaves are harvested for Taxol.\"}]', 'text', 3, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(713, 146, 192, '1.4 Socio-Cultural Environment and Heritage of Nepal', '14-socio-cultural-environment-and-heritage-of-nepal-192', '<h3>1. Demography and Diversity (Census 2078 / 2021)</h3>\n<ul>\n    <li><strong>Total Population:</strong> 29,164,578 (Female: 51.02%, Male: 48.98%). Annual growth rate: 0.92%.</li>\n    <li><strong>Sex Ratio:</strong> 95.59 males per 100 females. Population density: 198 persons/sq. km.</li>\n    <li><strong>Castes and Ethnic Groups:</strong> 142 distinct ethnic and caste groups recorded. Major groups: Chhetri (16.45%), Brahman-Hill (11.29%), Magar (6.9%), Tharu (6.2%), Tamang (5.62%), Newar (4.6%).</li>\n    <li><strong>Mother Tongues:</strong> 124 languages spoken. Nepali is the official working language spoken by 44.86% as mother tongue, followed by Maithili (11.05%), Bhojpuri (6.24%), Tharu (5.88%), Tamang (4.88%), and Newari (2.96%).</li>\n    <li><strong>Religious Harmony:</strong> Hinduism (81.19%), Buddhism (8.21%), Islam (5.09%), Kirat (3.17%), Christianity (1.76%), and Prakriti/others.</li>\n</ul>\n\n<h3>2. Cultural and Religious Heritage</h3>\n<ul>\n    <li><strong>UNESCO Cultural World Heritage Sites:</strong> Kathmandu Valley (7 monument zones: Pashupatinath, Swayambhunath, Boudhanath, Changunarayan, Kathmandu Durbar Square, Patan Durbar Square, Bhaktapur Durbar Square) and Lumbini (Birthplace of Lord Buddha).</li>\n    <li><strong>Major Festivals:</strong> Dashain (Bijaya Dashami), Tihar (Deepawali/Chhath), Lhosar (Tamu, Sonam, Gyalpo), Eid, Maghi, Ubhauli/Udhauli, Buddha Jayanti, Teej, Holi, Gaijatra, Bisket Jatra.</li>\n    <li><strong>Constitutional Guarantee:</strong> Secularism (Dharma Nirapekshata), freedom to practice religion, conservation of sanatan dharma and religious harmony (Article 4 & 26).</li>\n</ul>', NULL, NULL, '[{\"question\":\"According to National Population Census 2078 (2021), what is the total population of Nepal?\",\"options\":[\"26,494,504\",\"29,164,578\",\"30,500,000\",\"28,500,000\"],\"answer\":1,\"explanation\":\"Census 2078 recorded Nepal\'s population at 29,164,578.\"},{\"question\":\"What was the annual population growth rate recorded in Census 2078?\",\"options\":[\"1.35%\",\"0.92%\",\"2.10%\",\"0.45%\"],\"answer\":1,\"explanation\":\"The annual exponential population growth rate was 0.92%.\"},{\"question\":\"How many distinct castes and ethnic groups were recorded in Census 2078?\",\"options\":[\"125\",\"142\",\"100\",\"150\"],\"answer\":1,\"explanation\":\"Census 2078 recorded 142 distinct caste and ethnic communities.\"},{\"question\":\"How many mother tongues were enumerated in Nepal in Census 2078?\",\"options\":[\"92\",\"124\",\"142\",\"110\"],\"answer\":1,\"explanation\":\"124 distinct mother tongues were enumerated in Nepal.\"},{\"question\":\"What percentage of the population speaks Nepali as their mother tongue?\",\"options\":[\"44.86%\",\"58.20%\",\"35.40%\",\"65.00%\"],\"answer\":0,\"explanation\":\"Nepali is spoken as mother tongue by 44.86% of the population.\"},{\"question\":\"How many monument zones in Kathmandu Valley are inscribed as UNESCO World Heritage sites?\",\"options\":[\"3\",\"5\",\"7\",\"10\"],\"answer\":2,\"explanation\":\"Kathmandu Valley comprises 7 monument zones (Pashupati, Swayambhu, Bauddha, Changu, 3 Durbar Squares).\"},{\"question\":\"Which festival is the most prominent harvest festival celebrated by the Tharu community in Terai?\",\"options\":[\"Chhath\",\"Maghi\",\"Ubhauli\",\"Bisket Jatra\"],\"answer\":1,\"explanation\":\"Maghi (Makar Sankranti) is celebrated as the New Year and major festival by the Tharu people.\"},{\"question\":\"Ubhauli and Udhauli festivals are celebrated by which ethnic community in Nepal?\",\"options\":[\"Gurung\",\"Rai and Limbu (Kirat)\",\"Newar\",\"Sherpa\"],\"answer\":1,\"explanation\":\"Kirat communities (Rai, Limbu, Yakkha, Sunuwar) celebrate Ubhauli and Udhauli.\"},{\"question\":\"Ghewa is the traditional death ritual practiced by which community in Nepal?\",\"options\":[\"Tamang\",\"Brahmin\",\"Tharu\",\"Maithil\"],\"answer\":0,\"explanation\":\"Ghewa is the sacred funeral ritual of the Tamang community.\"},{\"question\":\"What is the sex ratio (males per 100 females) in Nepal according to Census 2078?\",\"options\":[\"91.50\",\"95.59\",\"98.20\",\"102.10\"],\"answer\":1,\"explanation\":\"The sex ratio was recorded at 95.59 males per 100 females.\"}]', 'text', 1, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(714, 146, 192, '1.5 Current Periodic Plan of Nepal: Objectives, Targets & Strategies', '15-current-periodic-plan-of-nepal-objectives-targets-strategies-192', '<h3>1. Historical Background of Planning in Nepal</h3>\n<p>Periodic economic planning in Nepal commenced in <strong>2013 BS (1956 AD)</strong> with the First Five-Year Plan under Prime Minister Tanka Prasad Acharya. The National Planning Commission (NPC) is the apex advisory body for formulating development plans and policies.</p>\n\n<h3>2. The 16th Periodic Plan (FY 2081/82 - 2085/86 / 2024-2029)</h3>\n<p>The 16th Plan is centered around the overarching theme: <strong>\"Good Governance, Social Justice, and Prosperity\" (सुशासन, सामाजिक न्याय र समृद्धि)</strong>.</p>\n\n<h4>Key Objectives:</h4>\n<ol>\n    <li>Establish structural transformation across production, employment, and public service delivery.</li>\n    <li>Achieve high, sustainable, and inclusive economic growth through modernization of agriculture, clean industrial development, and energy expansion.</li>\n    <li>Ensure social justice through poverty alleviation, universal social protection, and reduction of economic inequality.</li>\n    <li>Smooth transition and sustainable graduation from the Least Developed Country (LDC) category by 2026.</li>\n</ol>\n\n<h4>Strategic Pillars & Targets:</h4>\n<ul>\n    <li><strong>Economic Growth Target:</strong> Targeted annual average GDP growth rate of 7.0% - 7.5%.</li>\n    <li><strong>Poverty Reduction:</strong> Reducing absolute poverty below 12% by the end of the plan period.</li>\n    <li><strong>Hydropower & Energy Target:</strong> Increasing total electricity installed capacity beyond 5,000 MW, targeting 100% universal electricity access, and expanding cross-border power transmission lines.</li>\n    <li><strong>Human Development:</strong> Raising Human Development Index (HDI) above 0.65.</li>\n</ul>', NULL, NULL, '[{\"question\":\"In which year BS was periodic planning first introduced in Nepal with the 1st Five-Year Plan?\",\"options\":[\"2007 BS\",\"2013 BS\",\"2019 BS\",\"2028 BS\"],\"answer\":1,\"explanation\":\"The First Five-Year Plan began in 2013 BS under PM Tanka Prasad Acharya.\"},{\"question\":\"What is the main slogan\\/theme of the 16th Periodic Plan of Nepal (2081\\/82 - 2085\\/86)?\",\"options\":[\"Prosperous Nepal, Happy Nepali\",\"Good Governance, Social Justice, and Prosperity\",\"Sustainable Energy for All\",\"Inclusive Industrialization\"],\"answer\":1,\"explanation\":\"The core theme of the 16th Plan is \\\"Good Governance, Social Justice, and Prosperity\\\".\"},{\"question\":\"Who serves as the ex-officio Chairperson of the National Planning Commission (NPC) of Nepal?\",\"options\":[\"Finance Minister\",\"Governor of NRB\",\"Prime Minister\",\"Vice-Chairman of NPC\"],\"answer\":2,\"explanation\":\"The Prime Minister of Nepal is the ex-officio Chairperson of the NPC.\"},{\"question\":\"What is the target year for Nepal to graduate from the Least Developed Country (LDC) category?\",\"options\":[\"2024\",\"2026\",\"2030\",\"2035\"],\"answer\":1,\"explanation\":\"Nepal is scheduled for graduation from LDC status by December 2026.\"},{\"question\":\"Which long-term vision document guides Nepal\'s periodic plans towards 2100 BS?\",\"options\":[\"Vision 2020\",\"National Vision 2100 BS\",\"SDG Roadmap 2030\",\"Plan 2050\"],\"answer\":1,\"explanation\":\"The 25-year Long-term Vision 2100 BS sets targets for a high-income developed nation.\"},{\"question\":\"What is the annual economic growth (GDP) rate targeted by the 16th Periodic Plan?\",\"options\":[\"4.5%\",\"7.0% - 7.5%\",\"10.5%\",\"12.0%\"],\"answer\":1,\"explanation\":\"The 16th Plan targets an average economic growth rate of 7.0% to 7.5%.\"},{\"question\":\"What is the target for electricity generation capacity under recent medium-term energy plans?\",\"options\":[\"2,500 MW\",\"5,000 MW+\",\"1,000 MW\",\"3,000 MW\"],\"answer\":1,\"explanation\":\"Plans aim to exceed 5,000 MW to 10,000 MW generation capacity in the medium term.\"},{\"question\":\"Which institution in Nepal is responsible for approving the final draft of periodic plans?\",\"options\":[\"Parliament alone\",\"National Development Council (Rashtriya Bikas Parishad)\",\"Nepal Rastra Bank\",\"Ministry of Finance\"],\"answer\":1,\"explanation\":\"The National Development Council approves the guidelines and draft periodic plans.\"},{\"question\":\"How many periodic plans (including 3-year interim plans) has Nepal completed to date?\",\"options\":[\"10\",\"12\",\"15\",\"18\"],\"answer\":2,\"explanation\":\"Nepal has implemented 15 periodic plans and is currently in the 16th Plan.\"},{\"question\":\"The concept of Gender Responsive Budgeting (GRB) was formally institutionalized in Nepal in which fiscal year?\",\"options\":[\"FY 2050\\/51\",\"FY 2064\\/65\",\"FY 2072\\/73\",\"FY 2078\\/79\"],\"answer\":1,\"explanation\":\"Gender Responsive Budgeting was institutionalized starting FY 2064\\/65.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(715, 146, 192, '1.6 Major Drivers of Economic Development in Nepal', '16-major-drivers-of-economic-development-in-nepal-192', '<h3>Key Economic Pillars of Nepal</h3>\n\n<h4>1. Agriculture Sector</h4>\n<p>Contributes approximately 24% to GDP and employs over 60% of the workforce. Focus areas include commercialization, irrigation expansion, mechanization, high-value cash crops (tea, cardamom, ginger, coffee), and agro-processing industries.</p>\n\n<h4>2. Industry and Manufacturing</h4>\n<p>Contribution to GDP is around 13-14%. Promoted through Special Economic Zones (SEZ in Bhairahawa, Simara), small and medium enterprises (SMEs), export-oriented manufacturing, and cement/steel production.</p>\n\n<h4>3. Tourism Sector</h4>\n<p>Major source of foreign exchange and employment. Key products: Trekking, mountaineering (Mountaineering tourism), eco-tourism, cultural pilgrimage (Lumbini, Pashupatinath, Muktinath, Janakpur), adventure sports (rafting, paragliding, bungee jumping).</p>\n\n<h4>4. Human Resources & Foreign Employment</h4>\n<p>Remittances account for over 22-25% of national GDP. Shift towards developing skilled technical human resources, vocational training (CTEVT), and domestic employment creation (Prime Minister Employment Program).</p>\n\n<h4>5. Electricity and Energy</h4>\n<p>The backbone of industrial transformation. Clean hydropower generation displaces fossil fuels, reduces trade deficits with India, powers electric transportation, and generates export revenues.</p>\n\n<h4>6. Health & Education</h4>\n<p>Essential social infrastructure. Expansion of universal basic health coverage, health insurance schemes, technical education, and digital literacy.</p>', NULL, NULL, '[{\"question\":\"What is the approximate contribution of the Agriculture sector to Nepal\'s GDP?\",\"options\":[\"10%\",\"24%\",\"50%\",\"65%\"],\"answer\":1,\"explanation\":\"Agriculture contributes approximately 24% to Nepal\'s Gross Domestic Product.\"},{\"question\":\"Approximately what percentage of Nepal\'s total labor force is employed in agriculture?\",\"options\":[\"20%\",\"40%\",\"60%+\",\"85%\"],\"answer\":2,\"explanation\":\"Over 60% of Nepal\'s population depends on agriculture for employment.\"},{\"question\":\"What is the approximate share of worker remittances in Nepal\'s national GDP?\",\"options\":[\"5%\",\"10%\",\"22% - 25%\",\"50%\"],\"answer\":2,\"explanation\":\"Remittances contribute between 22% to 25% of Nepal\'s GDP.\"},{\"question\":\"Where is Nepal\'s first Special Economic Zone (SEZ) located and operationalized?\",\"options\":[\"Biratnagar\",\"Bhairahawa\",\"Simara\",\"Surkhet\"],\"answer\":1,\"explanation\":\"Bhairahawa SEZ in Rupandehi is Nepal\'s first operational Special Economic Zone.\"},{\"question\":\"Which cash crop is known as \\\"Black Gold\\\" in the eastern hilly districts of Nepal?\",\"options\":[\"Large Cardamom (Alainchi)\",\"Ginger\",\"Tea\",\"Coffee\"],\"answer\":0,\"explanation\":\"Large cardamom (Alainchi) is prized as black gold due to high export earnings.\"},{\"question\":\"What is the full form of CTEVT, the apex body for technical vocational training in Nepal?\",\"options\":[\"Council for Technical Education and Vocational Training\",\"Central Technical Education and Village Training\",\"Committee for Technology and Education Vocational Trade\",\"Center for Trade and Vocational Technology\"],\"answer\":0,\"explanation\":\"CTEVT stands for Council for Technical Education and Vocational Training.\"},{\"question\":\"Which international airport is the third international gateway operational in Nepal?\",\"options\":[\"TIA Kathmandu\",\"Gautam Buddha International Airport (GBIA)\",\"Pokhara International Airport (PIA)\",\"Biratnagar Airport\"],\"answer\":2,\"explanation\":\"Pokhara International Airport is the 3rd international airport in Nepal.\"},{\"question\":\"What is the prime objective of the Prime Minister Employment Program (PMEP)?\",\"options\":[\"Providing 100 days of guaranteed wage employment to unemployed citizens\",\"Free overseas work visas\",\"Industrial subsidies\",\"Higher education scholarships\"],\"answer\":0,\"explanation\":\"PMEP guarantees a minimum of 100 days of basic employment to listed unemployed citizens.\"},{\"question\":\"Which sector is considered the primary engine for industrial power transition in Nepal?\",\"options\":[\"Hydropower \\/ Clean Energy\",\"Coal mining\",\"Diesel import\",\"Handloom\"],\"answer\":0,\"explanation\":\"Clean hydropower is the critical foundation for replacing fossil fuels and industrial growth.\"},{\"question\":\"What is the main statutory regulatory body for insurance companies in Nepal?\",\"options\":[\"SEBON\",\"Nepal Insurance Authority (Bima Pradhikaran)\",\"Nepal Rastra Bank\",\"Ministry of Industry\"],\"answer\":1,\"explanation\":\"Nepal Insurance Authority (formerly Bima Samiti) regulates the insurance sector.\"}]', 'text', 3, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(716, 146, 193, '1.7 Water Resources, Solar Energy and Wind Energy in Nepal', '17-water-resources-solar-energy-and-wind-energy-in-nepal-193', '<h3>1. Water Resources & Hydro Potential</h3>\n<ul>\n    <li><strong>Theoretical Potential:</strong> Estimated at <strong>83,000 MW</strong> based on Dr. Hari Man Shrestha\'s 1966 research.</li>\n    <li><strong>Technically & Economically Feasible:</strong> Approximately <strong>42,000 MW to 45,000 MW</strong>.</li>\n    <li><strong>Run-of-River (RoR) vs Storage (Reservoir) Projects:</strong> Most existing plants are RoR (high generation in monsoon, reduced output in dry winter). Nepal is prioritizing Peaking RoR (PROR) like Upper Tamakoshi (456 MW), Trishuli 3A, and Storage Projects like Kulekhani (60+32+14=106 MW), Budhigandaki (1,200 MW), Dudhkoshi (635 MW), Tanahu (140 MW), and Upper Arun (1,061 MW) for grid stability.</li>\n</ul>\n\n<h3>2. Solar Energy Potential</h3>\n<ul>\n    <li>Nepal receives an average of <strong>300 sunny days per year</strong> with solar radiation averaging 4.5 to 5.5 kWh/m²/day.</li>\n    <li>Commercial grid-connected solar plants: Nuwakot Solar Project (25 MW - NEA), Mithila Solar (10 MW), Butwal Solar (8.5 MW).</li>\n    <li>Decentralized solar home systems (SHS) installed widely in off-grid rural areas via Alternative Energy Promotion Centre (AEPC).</li>\n</ul>\n\n<h3>3. Wind and Biomass Energy</h3>\n<ul>\n    <li>Wind energy potential estimated at over 3,000 MW in mountainous wind corridors (Mustang, Kagbeni, Ramechhap, Pyuthan).</li>\n    <li>Biomass and biogas provide clean cooking alternatives in rural households, reducing fuelwood consumption.</li>\n</ul>', NULL, NULL, '[{\"question\":\"Who conducted the pioneer research estimating Nepal\'s theoretical hydropower potential at 83,000 MW?\",\"options\":[\"Dr. Hari Man Shrestha (1966)\",\"Kul Man Ghising\",\"Dr. Dilli Raman Regmi\",\"B.P. Koirala\"],\"answer\":0,\"explanation\":\"Dr. Hari Man Shrestha calculated the 83,000 MW potential in his 1966 PhD thesis in Moscow.\"},{\"question\":\"What is the estimated technically and economically feasible hydropower potential of Nepal?\",\"options\":[\"20,000 MW\",\"42,000 MW\",\"83,000 MW\",\"100,000 MW\"],\"answer\":1,\"explanation\":\"Approximately 42,000 MW is considered economically and technically viable.\"},{\"question\":\"Which is the first hydropower plant constructed in Nepal (500 KW, 1968 BS)?\",\"options\":[\"Sundarijal\",\"Pharping Hydropower\",\"Panauti\",\"Kulekhani\"],\"answer\":1,\"explanation\":\"Pharping (Chandrajyoti) was established in 1968 BS (1911 AD) with 500 KW capacity.\"},{\"question\":\"Which is the largest operational storage\\/reservoir hydropower project in Nepal?\",\"options\":[\"Kulekhani (I, II, III)\",\"Kaligandaki A\",\"Upper Tamakoshi\",\"Marsyangdi\"],\"answer\":0,\"explanation\":\"Kulekhani reservoir project (total 106 MW) is Nepal\'s key storage project for peak winter load.\"},{\"question\":\"What is the generation capacity of Upper Tamakoshi Hydropower Project?\",\"options\":[\"144 MW\",\"456 MW\",\"60 MW\",\"700 MW\"],\"answer\":1,\"explanation\":\"Upper Tamakoshi located in Dolakha has a capacity of 456 MW (Peaking RoR).\"},{\"question\":\"What is the capacity of the grid-connected solar power project installed by NEA in Nuwakot?\",\"options\":[\"5 MW\",\"10 MW\",\"25 MW\",\"50 MW\"],\"answer\":2,\"explanation\":\"Nuwakot Solar Project built by NEA has a capacity of 25 MW.\"},{\"question\":\"On average, how many sunny days per year does Nepal enjoy for solar power harvesting?\",\"options\":[\"150 days\",\"200 days\",\"300 days\",\"365 days\"],\"answer\":2,\"explanation\":\"Nepal receives approximately 300 sunny days per year.\"},{\"question\":\"Which agency is responsible for promoting decentralized renewable energy (solar, mini-grid, biogas) in rural Nepal?\",\"options\":[\"AEPC (Alternative Energy Promotion Centre)\",\"NOC\",\"NTC\",\"NEA alone\"],\"answer\":0,\"explanation\":\"AEPC promotes off-grid renewable energy technologies.\"},{\"question\":\"Which transmission voltage line connects Dhalkebar (Nepal) and Muzaffarpur (India) for cross-border power trade?\",\"options\":[\"66 kV\",\"132 kV\",\"220 kV\",\"400 kV\"],\"answer\":3,\"explanation\":\"The Dhalkebar-Muzaffarpur cross-border line operates at 400 kV.\"},{\"question\":\"What type of hydropower plant generates power directly from natural river flow without large seasonal water reservoirs?\",\"options\":[\"Run-of-River (RoR)\",\"Reservoir \\/ Storage\",\"Nuclear\",\"Pumped Storage\"],\"answer\":0,\"explanation\":\"Run-of-River (RoR) plants utilize the instantaneous river flow.\"}]', 'text', 1, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(717, 146, 193, '1.8 Hydropower Development: Role of NEA and Private Sector', '18-hydropower-development-role-of-nea-and-private-sector-193', '<h3>1. Nepal Electricity Authority (NEA - नेपाल विद्युत प्राधिकरण)</h3>\n<p>Established on <strong>Bhadra 1, 2042 BS (August 16, 1985)</strong> under the <em>Nepal Electricity Authority Act, 2041</em> by merging the Department of Electricity, Electricity Corporation, and related development boards.</p>\n<h4>Primary Mandates of NEA:</h4>\n<ol>\n    <li>Generation, transmission, and distribution of electricity throughout Nepal in a reliable, safe, and cost-effective manner.</li>\n    <li>Managing the integrated National Power System (INPS) and system operation load dispatch center (LDC).</li>\n    <li>Constructing and operating high-voltage transmission backbones (132 kV, 220 kV, 400 kV lines such as Dhalkebar-Muzaffarpur 400 kV cross-border line).</li>\n    <li>Entering into Power Purchase Agreements (PPA) with Independent Power Producers (IPPs).</li>\n    <li>Rural electrification and smart grid modernization (smart meters, automated sub-stations, underground cabling).</li>\n    <li>Cross-border electricity trade with India and Bangladesh via Day-Ahead, Real-Time, and bilateral power markets.</li>\n</ol>\n\n<h3>2. Role of the Private Sector (IPPs)</h3>\n<ul>\n    <li>Private sector power producers contribute over <strong>60%</strong> of Nepal\'s total grid-connected electricity generation capacity.</li>\n    <li>IPPAN (Independent Power Producers\' Association, Nepal) represents private developers.</li>\n    <li>Build-Own-Operate-Transfer (BOOT) model: Projects are granted generation licenses for 30-35 years, after which ownership reverts to the Government of Nepal in operational condition.</li>\n</ul>', NULL, NULL, '[{\"question\":\"On which date was Nepal Electricity Authority (NEA) formally established?\",\"options\":[\"1984 Jan 1\",\"2041 Poush 1\",\"2042 Bhadra 1 (Aug 16, 1985)\",\"2046 Chaitra 30\"],\"answer\":2,\"explanation\":\"NEA was founded on Bhadra 1, 2042 BS by merging the Electricity Department and Corporation.\"},{\"question\":\"Who serves as the Member Secretary of the Board of Directors of NEA?\",\"options\":[\"Energy Secretary\",\"Managing Director of NEA\",\"Finance Joint Secretary\",\"Auditor General\"],\"answer\":1,\"explanation\":\"The Managing Director (MD) of NEA acts as the Member Secretary of the Board.\"},{\"question\":\"What is the full form of IPP in the context of power generation in Nepal?\",\"options\":[\"Independent Power Producer\",\"Integrated Power Plan\",\"Internal Public Project\",\"International Power Program\"],\"answer\":0,\"explanation\":\"IPP stands for Independent Power Producer.\"},{\"question\":\"What does PPA stand for in electricity transactions?\",\"options\":[\"Power Purchase Agreement\",\"Public Policy Act\",\"Power Project Allocation\",\"Primary Power Authority\"],\"answer\":0,\"explanation\":\"PPA stands for Power Purchase Agreement between NEA and power generators.\"},{\"question\":\"Which independent commission regulates electricity tariffs and consumer standards in Nepal?\",\"options\":[\"SEBON\",\"Electricity Regulatory Commission (ERC)\",\"NEA Board\",\"CIAA\"],\"answer\":1,\"explanation\":\"The Electricity Regulatory Commission (ERC) regulates tariffs and sector competition.\"},{\"question\":\"What model is commonly used where private developers build, operate, and transfer hydro projects to the government after 30-35 years?\",\"options\":[\"BOOT (Build-Own-Operate-Transfer)\",\"Turnkey Contract\",\"Outsourcing\",\"Franchise\"],\"answer\":0,\"explanation\":\"BOOT is the standard concession framework for private hydro projects in Nepal.\"},{\"question\":\"Where is the National Load Dispatch Centre (NLDC) of NEA located?\",\"options\":[\"Ratnapark, Kathmandu\",\"Siuchatar, Kathmandu\",\"Bhaktapur\",\"Hetauda\"],\"answer\":1,\"explanation\":\"The central NLDC for grid operations is located at Siuchatar, Kathmandu.\"},{\"question\":\"Which company is the electricity trading subsidiary established by NEA for national and cross-border power commerce?\",\"options\":[\"Nepal Power Exchange Ltd (NPEL)\",\"NEA Engineering Company\",\"Nepal Electricity Power Trading Company (NEPTC \\/ PTCN)\",\"Rastriya Prasaran Grid Company\"],\"answer\":2,\"explanation\":\"NEA formed PTCN\\/trading subsidiaries to engage in bilateral and regional electricity trade.\"},{\"question\":\"Nepal recently signed a tripartite agreement to export 40 MW of electricity to which third country via the Indian grid?\",\"options\":[\"Bhutan\",\"Bangladesh\",\"Sri Lanka\",\"Maldives\"],\"answer\":1,\"explanation\":\"Nepal signed a historic tripartite deal to export 40 MW power to Bangladesh.\"},{\"question\":\"Approximately what percentage of grid-connected generation capacity in Nepal is contributed by private IPPs?\",\"options\":[\"10%\",\"25%\",\"Over 60%\",\"95%\"],\"answer\":2,\"explanation\":\"Private IPPs now own and generate over 60% of Nepal\'s grid electricity.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(718, 146, 194, '1.9 Sustainable Development, Population and Climate Change', '19-sustainable-development-population-and-climate-change-194', '<h3>1. Sustainable Development Goals (SDGs 2016-2030)</h3>\n<p>Adopted by the UN in 2015 comprising 17 Global Goals and 169 targets. Nepal has integrated SDGs into its national periodic plans:</p>\n<ul>\n    <li><strong>Goal 7 (Affordable and Clean Energy):</strong> Universal access to reliable electricity, expanding renewable energy share.</li>\n    <li><strong>Goal 13 (Climate Action):</strong> Integrating climate change measures into national policies and planning.</li>\n    <li><strong>Goal 1 (No Poverty), Goal 5 (Gender Equality), Goal 8 (Decent Work & Economic Growth).</strong></li>\n</ul>\n\n<h3>2. Climate Vulnerability of Nepal</h3>\n<p>Despite contributing less than 0.03% of global greenhouse gas emissions, Nepal is ranked among the most climate-vulnerable countries due to fragile Himalayan topography.</p>\n<h4>Key Climate Impacts:</h4>\n<ul>\n    <li>Accelerated melting of Himalayan glaciers and formation of dangerous glacial lakes (GLOF - Glacial Lake Outburst Floods risk e.g., Tsho Rolpa, Imja).</li>\n    <li>Erratic precipitation, flash floods, landslides in hills, and droughts in winter.</li>\n    <li>Fluctuations in river discharge impacting seasonal hydropower generation.</li>\n</ul>', NULL, NULL, '[{\"question\":\"What percentage of annual rainfall in Nepal is brought by the Summer Monsoon?\",\"options\":[\"50%\",\"60%\",\"80%\",\"95%\"],\"answer\":2,\"explanation\":\"Around 80% of total annual rainfall occurs during the Summer Monsoon (June to September).\"},{\"question\":\"From which body of water does the summer monsoon originate before entering Nepal?\",\"options\":[\"Arabian Sea\",\"Bay of Bengal\",\"Mediterranean Sea\",\"Red Sea\"],\"answer\":1,\"explanation\":\"The summer monsoon enters Nepal from the Bay of Bengal.\"},{\"question\":\"Which direction does the summer monsoon travel across Nepal?\",\"options\":[\"West to East\",\"East to West\",\"North to South\",\"North-West to South-East\"],\"answer\":1,\"explanation\":\"The monsoon enters from the South-East\\/East and advances towards the West.\"},{\"question\":\"Winter rainfall in western Nepal is primarily caused by which weather system?\",\"options\":[\"South-East Monsoon\",\"Western Disturbance (Mediterranean Sea)\",\"Typhoon circulation\",\"Polar vortex\"],\"answer\":1,\"explanation\":\"Western Disturbance originating from the Mediterranean brings winter showers and snow.\"},{\"question\":\"Which district in Nepal receives the lowest annual rainfall due to rain-shadow effect?\",\"options\":[\"Jhapa\",\"Mustang\",\"Kaski\",\"Ilam\"],\"answer\":1,\"explanation\":\"Mustang and Manang lie in the rain-shadow of the Himalayas and receive very little rainfall (<300mm\\/yr).\"},{\"question\":\"Which place in Nepal records the highest average annual rainfall?\",\"options\":[\"Lumle, Kaski\",\"Dhangadhi, Kailali\",\"Namche Bazaar\",\"Dharan, Sunsari\"],\"answer\":0,\"explanation\":\"Lumle (near Pokhara, Kaski) receives over 5,000 mm of annual rainfall.\"},{\"question\":\"Which climatic zone is found at altitudes between 1,200m and 2,100m in Nepal?\",\"options\":[\"Tropical\",\"Warm Temperate\",\"Alpine\",\"Tundra\"],\"answer\":1,\"explanation\":\"Warm Temperate climate prevails in the mid-hills (1,200m - 2,100m).\"},{\"question\":\"The permanent snowline in Nepal generally starts above which altitude?\",\"options\":[\"3,000m\",\"4,000m\",\"5,000m\",\"6,500m\"],\"answer\":2,\"explanation\":\"The permanent snowline and Tundra zone in Nepal begins above 5,000 meters.\"},{\"question\":\"What is the climate of the Terai and Inner Terai regions?\",\"options\":[\"Sub-tropical \\/ Tropical\",\"Alpine\",\"Temperate\",\"Polar\"],\"answer\":0,\"explanation\":\"The Terai has a tropical to sub-tropical climate with hot summers and mild winters.\"},{\"question\":\"During which months does the post-monsoon (Autumn\\/Sharad) season occur in Nepal?\",\"options\":[\"March - May\",\"June - August\",\"October - November\",\"December - February\"],\"answer\":2,\"explanation\":\"October to November is the post-monsoon autumn season with clear skies.\"}]', 'text', 1, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(719, 146, 194, '1.10 Environmental Pollution Control and Climate Management in Nepal', '110-environmental-pollution-control-and-climate-management-in-nepal-194', '<h3>1. Legal and Institutional Frameworks</h3>\n<ul>\n    <li><strong>Environment Protection Act, 2076 (2019) & Rules, 2077:</strong> Mandates Environmental Impact Assessment (EIA), Initial Environmental Examination (IEE), and Environmental Management Plan (EMP) for development projects.</li>\n    <li><strong>National Climate Change Policy, 2076:</strong> Framework for climate adaptation, carbon financing, low-carbon development, and disaster resilience.</li>\n    <li><strong>Nationally Determined Contributions (Second NDC - 2020):</strong>\n        <ul>\n            <li>Net-zero greenhouse gas emissions target by <strong>2045</strong>.</li>\n            <li>Target to generate 15,000 MW of clean energy by 2030 (including 5-10% mini/micro-hydro, solar, wind, and bio-energy).</li>\n            <li>Promoting electric vehicles (EVs) to account for 90% of all private passenger vehicle sales by 2030.</li>\n            <li>Maintaining 45% of total land area under forest cover.</li>\n        </ul>\n    </li>\n</ul>\n\n<h3>2. NEA\'s Environmental Commitments</h3>\n<ul>\n    <li>Installation of EV charging stations across national highway networks.</li>\n    <li>Strict adherence to environmental flow (minimum 10% downstream environmental release) in river diversions.</li>\n    <li>Reforestation (compensatory plantation at 1:10 or 1:25 ratio for trees felled during transmission line construction).</li>\n</ul>', NULL, NULL, '[{\"question\":\"What percentage of annual rainfall in Nepal is brought by the Summer Monsoon?\",\"options\":[\"50%\",\"60%\",\"80%\",\"95%\"],\"answer\":2,\"explanation\":\"Around 80% of total annual rainfall occurs during the Summer Monsoon (June to September).\"},{\"question\":\"From which body of water does the summer monsoon originate before entering Nepal?\",\"options\":[\"Arabian Sea\",\"Bay of Bengal\",\"Mediterranean Sea\",\"Red Sea\"],\"answer\":1,\"explanation\":\"The summer monsoon enters Nepal from the Bay of Bengal.\"},{\"question\":\"Which direction does the summer monsoon travel across Nepal?\",\"options\":[\"West to East\",\"East to West\",\"North to South\",\"North-West to South-East\"],\"answer\":1,\"explanation\":\"The monsoon enters from the South-East\\/East and advances towards the West.\"},{\"question\":\"Winter rainfall in western Nepal is primarily caused by which weather system?\",\"options\":[\"South-East Monsoon\",\"Western Disturbance (Mediterranean Sea)\",\"Typhoon circulation\",\"Polar vortex\"],\"answer\":1,\"explanation\":\"Western Disturbance originating from the Mediterranean brings winter showers and snow.\"},{\"question\":\"Which district in Nepal receives the lowest annual rainfall due to rain-shadow effect?\",\"options\":[\"Jhapa\",\"Mustang\",\"Kaski\",\"Ilam\"],\"answer\":1,\"explanation\":\"Mustang and Manang lie in the rain-shadow of the Himalayas and receive very little rainfall (<300mm\\/yr).\"},{\"question\":\"Which place in Nepal records the highest average annual rainfall?\",\"options\":[\"Lumle, Kaski\",\"Dhangadhi, Kailali\",\"Namche Bazaar\",\"Dharan, Sunsari\"],\"answer\":0,\"explanation\":\"Lumle (near Pokhara, Kaski) receives over 5,000 mm of annual rainfall.\"},{\"question\":\"Which climatic zone is found at altitudes between 1,200m and 2,100m in Nepal?\",\"options\":[\"Tropical\",\"Warm Temperate\",\"Alpine\",\"Tundra\"],\"answer\":1,\"explanation\":\"Warm Temperate climate prevails in the mid-hills (1,200m - 2,100m).\"},{\"question\":\"The permanent snowline in Nepal generally starts above which altitude?\",\"options\":[\"3,000m\",\"4,000m\",\"5,000m\",\"6,500m\"],\"answer\":2,\"explanation\":\"The permanent snowline and Tundra zone in Nepal begins above 5,000 meters.\"},{\"question\":\"What is the climate of the Terai and Inner Terai regions?\",\"options\":[\"Sub-tropical \\/ Tropical\",\"Alpine\",\"Temperate\",\"Polar\"],\"answer\":0,\"explanation\":\"The Terai has a tropical to sub-tropical climate with hot summers and mild winters.\"},{\"question\":\"During which months does the post-monsoon (Autumn\\/Sharad) season occur in Nepal?\",\"options\":[\"March - May\",\"June - August\",\"October - November\",\"December - February\"],\"answer\":2,\"explanation\":\"October to November is the post-monsoon autumn season with clear skies.\"}]', 'text', 2, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(720, 146, 195, '1.11 Current Affairs of National Importance, Sports, Arts & Literature', '111-current-affairs-of-national-importance-sports-arts-literature-195', '<h3>1. High-Yield Current Affairs Topics for Exam</h3>\n<ul>\n    <li><strong>Energy & Infrastructure Milestones:</strong> Operationalization of Pokhara International Airport, Gautam Buddha International Airport (Bhairahawa), transmission line interconnections (Dhalkebar-Muzaffarpur, Butwal-Gorakhpur 400 kV), export of electricity to India (up to 700+ MW approved) and tripartite agreement with Bangladesh for 40 MW power export.</li>\n    <li><strong>Prestigious National Honors & Awards:</strong>\n        <ul>\n            <li><em>Madan Puraskar & Jagadamba Shree:</em> Premier literary honors of Nepal.</li>\n            <li><em>Rastriya Pratibha Puraskar:</em> National talent awards across science, art, literature, and social contribution.</li>\n            <li><em>Janasewa Shree & Nepal Ratna:</em> Highest civilian state decorations.</li>\n        </ul>\n    </li>\n    <li><strong>Sports Milestones:</strong> Nepal Cricket Team participation in ICC Men\'s T20 World Cup, National Games (Rastriya Khelkud), South Asian Games (SAG) medal tallies, martial arts achievements.</li>\n    <li><strong>Evolving Economic Indicators:</strong> Annual budget size, inflation rate, foreign exchange reserves (covering 12+ months of imports), and remittance inflows.</li>\n</ul>', NULL, NULL, '[{\"question\":\"Which literary award is considered the most prestigious annual prize for Nepali literature?\",\"options\":[\"Madan Puraskar\",\"Sajha Puraskar\",\"Gorkha Dakshina Bahu\",\"Prabal Janasewa\"],\"answer\":0,\"explanation\":\"Madan Puraskar is the highest literary honor for outstanding books in Nepali.\"},{\"question\":\"Jagadamba Shree Puraskar is awarded for what achievement?\",\"options\":[\"Lifetime contribution to Nepali language, art, and literature\",\"Best single novel\",\"Science invention\",\"Sports excellence\"],\"answer\":0,\"explanation\":\"Jagadamba Shree honors lifetime dedicated service to the Nepali language and culture.\"},{\"question\":\"What is the highest civilian state honor awarded by the President of Nepal?\",\"options\":[\"Nepal Ratna\",\"Mahaujjwal Rastradeep\",\"Suprabal Janasewashree\",\"Gorkha Dakshin Bahu\"],\"answer\":0,\"explanation\":\"Nepal Ratna is the highest civilian decoration of Nepal.\"},{\"question\":\"In which sports discipline did Nepal qualify and play in the ICC T20 World Cups (2014 & 2024)?\",\"options\":[\"Football\",\"Cricket\",\"Volleyball\",\"Basketball\"],\"answer\":1,\"explanation\":\"The National Cricket Team of Nepal competed in the 2014 and 2024 ICC Men\'s T20 World Cups.\"},{\"question\":\"What is the national sport of Nepal designated by the government in 2074 BS?\",\"options\":[\"Football\",\"Dandi Biyo\",\"Volleyball\",\"Cricket\"],\"answer\":2,\"explanation\":\"Volleyball was officially declared the national sport of Nepal in Jestha 2074 BS.\"},{\"question\":\"Who is known as the \\\"Mahakavi\\\" (Great Poet) of Nepali literature?\",\"options\":[\"Bhanubhakta Acharya\",\"Laxmi Prasad Devkota\",\"Madhav Prasad Ghimire\",\"Motiram Bhatta\"],\"answer\":1,\"explanation\":\"Laxmi Prasad Devkota is revered as Mahakavi (author of Muna Madan, Shakuntala).\"},{\"question\":\"Who is honored as the \\\"Aadi Kavi\\\" (First Poet) of Nepali literature for translating Ramayana into Nepali?\",\"options\":[\"Bhanubhakta Acharya\",\"Laxmi Prasad Devkota\",\"Lekhnath Paudyal\",\"Balkrishna Sama\"],\"answer\":0,\"explanation\":\"Bhanubhakta Acharya translated the Ramayana into accessible rhythmic Nepali verse.\"},{\"question\":\"Who is known as the \\\"Rashtrakavi\\\" (National Poet) of Nepal?\",\"options\":[\"Madhav Prasad Ghimire\",\"Bhairav Aryal\",\"Parijat\",\"Bhupi Sherchan\"],\"answer\":0,\"explanation\":\"Madhav Prasad Ghimire was bestowed the title of Rashtrakavi.\"},{\"question\":\"Which famous novel by Parijat won the Madan Puraskar in 2022 BS?\",\"options\":[\"Siris Ko Phool (The Blue Mimosa)\",\"Muna Madan\",\"Seto Bagh\",\"Gauri\"],\"answer\":0,\"explanation\":\"Siris Ko Phool by female writer Parijat won the Madan Puraskar in 2022 BS.\"},{\"question\":\"What is the current base currency peg relationship between Nepalese Rupee (NPR) and Indian Rupee (INR)?\",\"options\":[\"100 INR = 160 NPR (Fixed Peg)\",\"100 INR = 150 NPR\",\"100 INR = 175 NPR\",\"Floating market rate\"],\"answer\":0,\"explanation\":\"The Nepalese Rupee is pegged to the Indian Rupee at 1 INR = 1.60 NPR (100 INR = 160 NPR).\"}]', 'text', 1, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(721, 146, 195, '1.12 Federalism in Nepal: Concept, Meaning and Importance', '112-federalism-in-nepal-concept-meaning-and-importance-195', '<h3>1. Concept and Rationale of Federalism</h3>\n<p>Federalism is a system of governance where constitutional sovereignty and governing authority are divided between a central national government and sub-national constituent units (provinces and local governments).</p>\n\n<h3>2. Evolution of Federalism in Nepal</h3>\n<p>Formally institutionalized by the <strong>Constitution of Nepal 2072 (promulgated on Ashwin 3, 2072 / Sept 20, 2015)</strong>, transforming Nepal from a unitary monarchical state into a Federal Democratic Republic (संघीय लोकतान्त्रिक गणतन्त्र नेपाल).</p>\n\n<h3>3. Three Tiers of Government</h3>\n<ol>\n    <li><strong>Federal Government (संघीय सरकार):</strong> Apex authority handling national defense, foreign affairs, monetary policy, central banking, national highways, mega transmission grids, and inter-provincial matters.</li>\n    <li><strong>7 Provincial Governments (प्रदेश सरकार):</strong> Koshi, Madhesh, Bagmati, Gandaki, Lumbini, Karnali, and Sudurpashchim. Handle provincial policing, health services, provincial roads, electricity projects up to specified thresholds.</li>\n    <li><strong>753 Local Governments (स्थानीय तह):</strong>\n        <ul>\n            <li>6 Metropolitan Cities (Mahanagarpalika)</li>\n            <li>11 Sub-Metropolitan Cities (Upa-Mahanagarpalika)</li>\n            <li>276 Municipalities (Nagarpalika)</li>\n            <li>460 Rural Municipalities (Gaunpalika)</li>\n            <li>Total 6,743 Wards</li>\n        </ul>\n    </li>\n</ol>\n\n<h3>4. Principles of Inter-governmental Relations (Article 232)</h3>\n<p>The relations among the Federation, Provinces, and Local levels are based on the principles of <strong>Cooperation, Co-existence, and Coordination (सहकारिता, सहअस्तित्व र समन्वय)</strong>.</p>', NULL, NULL, '[{\"question\":\"How many Provinces are established in Nepal under the Constitution of Nepal 2072?\",\"options\":[\"5 Provinces\",\"7 Provinces\",\"9 Provinces\",\"14 Provinces\"],\"answer\":1,\"explanation\":\"The Constitution established 7 federal provinces.\"},{\"question\":\"How many total Local Levels (Sthaniya Tah) exist in Nepal?\",\"options\":[\"500\",\"753\",\"777\",\"1,000\"],\"answer\":1,\"explanation\":\"Nepal has exactly 753 local level local governments.\"},{\"question\":\"How many Metropolitan Cities (Mahanagarpalika) are there in Nepal?\",\"options\":[\"4\",\"6\",\"11\",\"14\"],\"answer\":1,\"explanation\":\"Nepal has 6 Metropolitan Cities (Kathmandu, Lalitpur, Pokhara, Bharatpur, Biratnagar, Birgunj).\"},{\"question\":\"How many Sub-Metropolitan Cities (Upa-Mahanagarpalika) are in Nepal?\",\"options\":[\"8\",\"11\",\"15\",\"22\"],\"answer\":1,\"explanation\":\"There are 11 Sub-Metropolitan Cities.\"},{\"question\":\"How many total Municipalities (Nagarpalika) are in Nepal?\",\"options\":[\"276\",\"460\",\"753\",\"300\"],\"answer\":0,\"explanation\":\"Nepal has 276 urban Municipalities (Nagarpalika).\"},{\"question\":\"How many Rural Municipalities (Gaunpalika) are there in Nepal?\",\"options\":[\"276\",\"460\",\"500\",\"753\"],\"answer\":1,\"explanation\":\"Nepal has 460 Rural Municipalities (Gaunpalika).\"},{\"question\":\"How many total wards are there across all 753 local levels in Nepal?\",\"options\":[\"3,500\",\"5,200\",\"6,743\",\"7,530\"],\"answer\":2,\"explanation\":\"There are 6,743 ward units in Nepal.\"},{\"question\":\"Which Article of the Constitution defines the principles of inter-governmental relations in Nepal?\",\"options\":[\"Article 56\",\"Article 100\",\"Article 232\",\"Article 300\"],\"answer\":2,\"explanation\":\"Article 232 specifies relations based on Cooperation, Co-existence, and Coordination.\"},{\"question\":\"Which council headed by the Prime Minister resolves political disputes between Federation and Provinces?\",\"options\":[\"Inter-Provincial Council (Article 234)\",\"Judicial Council\",\"Constitutional Council\",\"National Security Council\"],\"answer\":0,\"explanation\":\"Article 234 establishes the Inter-Provincial Council.\"},{\"question\":\"Which constitutional commission recommends equalisation grants and revenue distribution among the three tiers?\",\"options\":[\"National Natural Resources and Fiscal Commission (NNRFC)\",\"Auditor General\",\"Public Service Commission\",\"Election Commission\"],\"answer\":0,\"explanation\":\"NNRFC (Part 26, Article 250) determines inter-governmental fiscal transfers.\"}]', 'text', 2, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(722, 146, 195, '1.13 Democracy, Inclusion and Social Justice', '113-democracy-inclusion-and-social-justice-195', '<h3>1. Principles of Democratic Governance</h3>\n<p>Constitutional supremacy, rule of law, periodic competitive elections, multi-party system, independent judiciary, separation of powers, checks and balances, and citizen fundamental freedoms.</p>\n\n<h3>2. Social Inclusion (समावेशीकरण)</h3>\n<p>The process of ensuring that marginalized, underprivileged, and disadvantaged groups participate equitably in political decision-making, civil service, and socio-economic life.</p>\n<h4>Key Inclusion Mechanisms in Nepal:</h4>\n<ul>\n    <li><strong>Proportional Representation (समानुपातिक प्रतिनिधित्व):</strong> Mixed electoral system (FPTP + PR) in federal and provincial parliaments.</li>\n    <li><strong>Affirmative Action / Reservations in Public Service:</strong> 45% of open competitive vacancies reserved for:\n        <ul>\n            <li>Women (33%)</li>\n            <li>Adivasi Janajati (27%)</li>\n            <li>Madhesi (22%)</li>\n            <li>Dalit (9%)</li>\n            <li>Tharu (5%)</li>\n            <li>Muslim (4%)</li>\n            <li>Backward Regions & Persons with Disabilities (additional reservations).</li>\n        </ul>\n    </li>\n    <li><strong>Social Justice (Article 42):</strong> Right of socially backward groups to participate in state organs on the basis of the principle of proportional inclusion.</li>\n</ul>', NULL, NULL, '[{\"question\":\"Which Article of the Constitution of Nepal guarantees the \\\"Right to Social Justice\\\"?\",\"options\":[\"Article 18\",\"Article 24\",\"Article 42\",\"Article 48\"],\"answer\":2,\"explanation\":\"Article 42 guarantees the Right to Social Justice based on proportional inclusion.\"},{\"question\":\"What percentage of civil service\\/public enterprise open vacancy seats is reserved for inclusion groups in Nepal?\",\"options\":[\"33%\",\"45%\",\"50%\",\"55%\"],\"answer\":1,\"explanation\":\"45% of total vacant seats are reserved for targeted inclusive clusters.\"},{\"question\":\"Out of the 45% reserved quota in public employment, what percentage is allocated for women?\",\"options\":[\"22%\",\"27%\",\"33%\",\"50%\"],\"answer\":2,\"explanation\":\"33% of the reserved quota is strictly earmarked for women.\"},{\"question\":\"What percentage is allocated to Adivasi Janajati from the reserved cluster?\",\"options\":[\"15%\",\"22%\",\"27%\",\"33%\"],\"answer\":2,\"explanation\":\"27% of the reserved quota is allocated to Adivasi Janajati.\"},{\"question\":\"What percentage is allocated to Madhesi cluster from the 45% reservation?\",\"options\":[\"10%\",\"22%\",\"27%\",\"33%\"],\"answer\":1,\"explanation\":\"22% is allocated to the Madhesi cluster.\"},{\"question\":\"What percentage of the reserved quota is allocated to Dalit candidates?\",\"options\":[\"5%\",\"9%\",\"15%\",\"20%\"],\"answer\":1,\"explanation\":\"9% is allocated to Dalit candidates.\"},{\"question\":\"Which electoral system combines First-Past-The-Post (FPTP) and Proportional Representation (PR) in Nepal?\",\"options\":[\"Parallel Mixed Electoral System\",\"Single Transferable Vote\",\"Majority Runoff\",\"Pure Proportional System\"],\"answer\":0,\"explanation\":\"Nepal uses a Mixed Electoral System (60% FPTP and 40% PR in House of Representatives).\"},{\"question\":\"What minimum percentage of women representation is constitutionally mandated in Federal and Provincial Parliaments?\",\"options\":[\"25%\",\"33% (One-third)\",\"40%\",\"50%\"],\"answer\":1,\"explanation\":\"The Constitution mandates at least 33% female representation in federal and provincial legislatures.\"},{\"question\":\"Which commission was established to protect the rights and identity of Indigenous Nationalities in Nepal?\",\"options\":[\"National Women Commission\",\"National Inclusion Commission\",\"Indigenous Nationalities Commission\",\"Tharu Commission\"],\"answer\":2,\"explanation\":\"The Indigenous Nationalities Commission is a constitutional body under Part 27.\"},{\"question\":\"Which Article of the Constitution prohibits untouchability and caste discrimination in public and private life?\",\"options\":[\"Article 16\",\"Article 24\",\"Article 32\",\"Article 40\"],\"answer\":1,\"explanation\":\"Article 24 prohibits untouchability and caste-based discrimination.\"}]', 'text', 3, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(723, 146, 195, '1.14 General Knowledge Assessment Quiz', '114-general-knowledge-assessment-quiz-195', '[{\"question\":\"What is the primary statutory responsibility of Nepal Electricity Authority (NEA)?\",\"options\":[\"Generation, Transmission, and Distribution of electricity across Nepal\",\"Road construction\",\"Mining coal\",\"Operating domestic airlines\"],\"answer\":0,\"explanation\":\"NEA manages generation, transmission, and distribution of electricity throughout Nepal.\"},{\"question\":\"When was Nepal Electricity Authority (NEA) established in Bikram Sambat?\",\"options\":[\"2041 Poush 1\",\"2042 Bhadra 1\",\"2046 Baishakh 1\",\"2050 Chaitra 30\"],\"answer\":1,\"explanation\":\"NEA was formally founded on Bhadra 1, 2042 BS under the NEA Act 2041.\"},{\"question\":\"What is the full mark score of Phase 1 Written Examination for NEA Level 4?\",\"options\":[\"100 Marks\",\"200 Marks (Paper I: 100 + Paper II: 100)\",\"300 Marks\",\"50 Marks\"],\"answer\":1,\"explanation\":\"The written exam comprises 200 marks (Paper I 100 marks + Paper II 100 marks).\"},{\"question\":\"What is the pass mark percentage required in each paper of the written exam?\",\"options\":[\"32%\",\"40%\",\"50%\",\"60%\"],\"answer\":1,\"explanation\":\"40 marks out of 100 is the minimum pass mark for each paper.\"},{\"question\":\"Negative marking in Loksewa multiple choice objective questions is deducted at what rate for wrong answers?\",\"options\":[\"10%\",\"20% (0.2 marks per 1 mark question)\",\"33%\",\"50%\"],\"answer\":1,\"explanation\":\"20% marks are deducted for every incorrect MCQ answer.\"},{\"question\":\"What is the theoretical hydropower potential of Nepal?\",\"options\":[\"42,000 MW\",\"83,000 MW\",\"100,000 MW\",\"20,000 MW\"],\"answer\":1,\"explanation\":\"Theoretical hydropower potential is 83,000 MW (economically feasible ~42,000 MW).\"},{\"question\":\"Which constitutional organ conducts the recruitment exams for NEA Level 4 posts?\",\"options\":[\"Public Service Commission (Lok Sewa Aayog)\",\"Ministry of Energy\",\"Tribhuvan University\",\"Private Board\"],\"answer\":0,\"explanation\":\"The Public Service Commission conducts selection examinations for public enterprises.\"},{\"question\":\"What is the fundamental accounting equation?\",\"options\":[\"Assets = Liabilities + Capital\",\"Assets = Liabilities - Capital\",\"Capital = Liabilities + Revenues\",\"Profit = Assets + Cash\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Owner\'s Equity.\"},{\"question\":\"Under the Constitution of Nepal, how many fundamental rights are guaranteed in Part 3?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"31 Fundamental Rights are guaranteed from Article 16 to Article 46.\"},{\"question\":\"What penalty is levied on power theft under Electricity Theft Control Rules 2059?\",\"options\":[\"Assessed loss amount plus 100% fine (शतप्रतिशत जरिवाना)\",\"25% fine\",\"Written warning only\",\"No fine\"],\"answer\":0,\"explanation\":\"Assessed unmetered consumption is recovered along with a 100% fine.\"}]', NULL, NULL, '[{\"question\":\"What is the primary statutory responsibility of Nepal Electricity Authority (NEA)?\",\"options\":[\"Generation, Transmission, and Distribution of electricity across Nepal\",\"Road construction\",\"Mining coal\",\"Operating domestic airlines\"],\"answer\":0,\"explanation\":\"NEA manages generation, transmission, and distribution of electricity throughout Nepal.\"},{\"question\":\"When was Nepal Electricity Authority (NEA) established in Bikram Sambat?\",\"options\":[\"2041 Poush 1\",\"2042 Bhadra 1\",\"2046 Baishakh 1\",\"2050 Chaitra 30\"],\"answer\":1,\"explanation\":\"NEA was formally founded on Bhadra 1, 2042 BS under the NEA Act 2041.\"},{\"question\":\"What is the full mark score of Phase 1 Written Examination for NEA Level 4?\",\"options\":[\"100 Marks\",\"200 Marks (Paper I: 100 + Paper II: 100)\",\"300 Marks\",\"50 Marks\"],\"answer\":1,\"explanation\":\"The written exam comprises 200 marks (Paper I 100 marks + Paper II 100 marks).\"},{\"question\":\"What is the pass mark percentage required in each paper of the written exam?\",\"options\":[\"32%\",\"40%\",\"50%\",\"60%\"],\"answer\":1,\"explanation\":\"40 marks out of 100 is the minimum pass mark for each paper.\"},{\"question\":\"Negative marking in Loksewa multiple choice objective questions is deducted at what rate for wrong answers?\",\"options\":[\"10%\",\"20% (0.2 marks per 1 mark question)\",\"33%\",\"50%\"],\"answer\":1,\"explanation\":\"20% marks are deducted for every incorrect MCQ answer.\"},{\"question\":\"What is the theoretical hydropower potential of Nepal?\",\"options\":[\"42,000 MW\",\"83,000 MW\",\"100,000 MW\",\"20,000 MW\"],\"answer\":1,\"explanation\":\"Theoretical hydropower potential is 83,000 MW (economically feasible ~42,000 MW).\"},{\"question\":\"Which constitutional organ conducts the recruitment exams for NEA Level 4 posts?\",\"options\":[\"Public Service Commission (Lok Sewa Aayog)\",\"Ministry of Energy\",\"Tribhuvan University\",\"Private Board\"],\"answer\":0,\"explanation\":\"The Public Service Commission conducts selection examinations for public enterprises.\"},{\"question\":\"What is the fundamental accounting equation?\",\"options\":[\"Assets = Liabilities + Capital\",\"Assets = Liabilities - Capital\",\"Capital = Liabilities + Revenues\",\"Profit = Assets + Cash\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Owner\'s Equity.\"},{\"question\":\"Under the Constitution of Nepal, how many fundamental rights are guaranteed in Part 3?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"31 Fundamental Rights are guaranteed from Article 16 to Article 46.\"},{\"question\":\"What penalty is levied on power theft under Electricity Theft Control Rules 2059?\",\"options\":[\"Assessed loss amount plus 100% fine (\\u0936\\u0924\\u092a\\u094d\\u0930\\u0924\\u093f\\u0936\\u0924 \\u091c\\u0930\\u093f\\u0935\\u093e\\u0928\\u093e)\",\"25% fine\",\"Written warning only\",\"No fine\"],\"answer\":0,\"explanation\":\"Assessed unmetered consumption is recovered along with a 100% fine.\"}]', 'quiz', 4, 15, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(724, 147, 196, '2.1 Fundamental Features of the Constitution of Nepal', '21-fundamental-features-of-the-constitution-of-nepal-196', '<h3>1. Promulgation and Historical Context</h3>\n<p>The present Constitution of Nepal was promulgated by the elected Constituent Assembly on <strong>Ashwin 3, 2072 BS (September 20, 2015 AD)</strong>. It is the <strong>7th written constitution</strong> in Nepal\'s constitutional history (preceded by 2004, 2007, 2015, 2019, 2047, and 2063 Interim constitutions).</p>\n\n<h3>2. Salient Characteristics</h3>\n<ul>\n    <li><strong>Structure:</strong> Comprises <strong>35 Parts, 308 Articles, and 9 Schedules</strong>.</li>\n    <li><strong>Sovereignty & State Power (Article 2):</strong> Inherent in the Nepali people.</li>\n    <li><strong>Form of State (Article 4):</strong> Nepal is an independent, indivisible, sovereign, secular, inclusive, democratic, socialism-oriented, federal democratic republican state.</li>\n    <li><strong>Secularism Defined:</strong> \"Secular\" means religious and cultural freedom, along with the protection of religion and culture practiced from ancient times (Sanatan Dharma).</li>\n    <li><strong>Form of Government (Article 74):</strong> Multi-party, competitive, federal democratic republican parliamentary system of governance based on pluralism.</li>\n    <li><strong>Constitutional Supremacy (Article 1):</strong> This Constitution is the fundamental law of Nepal. Any law inconsistent with this Constitution shall, to the extent of such inconsistency, be void.</li>\n    <li><strong>Three Tiers of Federation:</strong> Federation, 7 Provinces, and 753 Local Levels.</li>\n    <li><strong>Independent Judiciary:</strong> Three-tier court system (Supreme Court, High Courts in 7 provinces, District Courts in 77 districts). Supreme Court has constitutional bench and power of judicial review (Article 133).</li>\n</ul>', NULL, NULL, '[{\"question\":\"On which exact date was the Constitution of Nepal 2072 promulgated?\",\"options\":[\"2072 Bhadra 1\",\"2072 Ashwin 3 (Sept 20, 2015)\",\"2072 Kartik 1\",\"2073 Baishakh 1\"],\"answer\":1,\"explanation\":\"Promulgated on Ashwin 3, 2072 BS by President Dr. Ram Baran Yadav on behalf of the Constituent Assembly.\"},{\"question\":\"How many Parts, Articles, and Schedules are in the Constitution of Nepal?\",\"options\":[\"25 Parts, 200 Articles, 5 Schedules\",\"35 Parts, 308 Articles, 9 Schedules\",\"30 Parts, 250 Articles, 7 Schedules\",\"38 Parts, 320 Articles, 10 Schedules\"],\"answer\":1,\"explanation\":\"The constitution consists of 35 Parts, 308 Articles, and 9 Schedules.\"},{\"question\":\"According to Article 1 of the Constitution, what is the fundamental law of the land?\",\"options\":[\"Act of Parliament\",\"The Constitution itself\",\"Supreme Court Precedent\",\"Civil Code\"],\"answer\":1,\"explanation\":\"The Constitution is the fundamental law; inconsistent laws are void.\"},{\"question\":\"Where is state sovereignty vested under Article 2 of the Constitution of Nepal?\",\"options\":[\"In the President\",\"In the Prime Minister\",\"In the Nepali People\",\"In Parliament\"],\"answer\":2,\"explanation\":\"Article 2 vests sovereignty and state power inherently in the Nepali people.\"},{\"question\":\"What is the form of government established under Article 74 of the Constitution?\",\"options\":[\"Presidential system\",\"Multi-party, competitive federal democratic republican parliamentary system\",\"Monarchical system\",\"Unitary assembly system\"],\"answer\":1,\"explanation\":\"Article 74 establishes a parliamentary system based on pluralism and competitive multi-party democracy.\"},{\"question\":\"How many members make up the House of Representatives (Pratinidhi Sabha) in Federal Parliament?\",\"options\":[\"205\",\"240\",\"275 (165 FPTP + 110 PR)\",\"334\"],\"answer\":2,\"explanation\":\"The House of Representatives has 275 members (165 elected via FPTP, 110 via PR).\"},{\"question\":\"How many members comprise the National Assembly (Rastriya Sabha)?\",\"options\":[\"50\",\"59 (56 elected from 7 provinces + 3 nominated by President)\",\"65\",\"75\"],\"answer\":1,\"explanation\":\"National Assembly consists of 59 members.\"},{\"question\":\"What is the total strength of the Federal Parliament of Nepal (Lower + Upper House)?\",\"options\":[\"275\",\"334 (275 + 59)\",\"601\",\"350\"],\"answer\":1,\"explanation\":\"Total Federal Parliament membership is 334 (275 + 59).\"},{\"question\":\"Which special bench in the Supreme Court is created under Article 137 to adjudicate constitutional disputes?\",\"options\":[\"Full Bench\",\"Constitutional Bench\",\"Commercial Bench\",\"Administrative Bench\"],\"answer\":1,\"explanation\":\"The Constitutional Bench comprises the Chief Justice and 4 senior judges.\"},{\"question\":\"What majority in both houses of Federal Parliament is required to amend the Constitution (Article 274)?\",\"options\":[\"Simple majority\",\"Two-thirds (2\\/3rd) majority of total existing members\",\"Three-fourths majority\",\"Unanimous vote\"],\"answer\":1,\"explanation\":\"Article 274 requires a two-thirds majority in each house to pass constitutional amendments.\"}]', 'text', 1, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(725, 147, 196, '2.2 Preliminary Provisions (Part-1: Articles 1-9)', '22-preliminary-provisions-part-1-articles-1-9-196', '<h3>Analysis of Part 1 (Articles 1 - 9)</h3>\n<ol>\n    <li><strong>Article 1 (Constitution as the Fundamental Law):</strong> Every person must abide by the constitution. Laws in conflict are invalid.</li>\n    <li><strong>Article 2 (Sovereignty and State Authority):</strong> The sovereignty and state authority of Nepal are vested in the Nepali people.</li>\n    <li><strong>Article 3 (The Nation):</strong> All Nepali people multi-ethnic, multi-lingual, multi-religious, multi-cultural, having common aspirations and united by a bond of allegiance to national independence, integrity, national interest, and prosperity constitute the nation.</li>\n    <li><strong>Article 4 (State of Nepal):</strong> Definition of the Federal Democratic Republican state.</li>\n    <li><strong>Article 5 (National Interest):</strong> Safeguarding independence, sovereignty, territorial integrity, nationality, freedom, self-respect, border security, economic prosperity.</li>\n    <li><strong>Article 6 (Languages of the Nation):</strong> All mother tongues spoken in Nepal are the languages of the nation.</li>\n    <li><strong>Article 7 (Official Language):</strong> The Nepali language in Devanagari script is the official working language of Nepal. Provinces may determine one or more languages spoken by majority as provincial official language.</li>\n    <li><strong>Article 8 (National Flag):</strong> Crimson color with blue border, two juxtaposed triangular figures with white crescent moon (upper) and 12-rayed white sun (lower). Specification detailed in Schedule 1.</li>\n    <li><strong>Article 9 (National Anthem, Coat-of-Arms, Flower, Color, Animal & Bird):</strong>\n        <ul>\n            <li>National Anthem: <em>\"Sayaun Thunga Phool Ka Hami...\"</em> (Schedule 2).</li>\n            <li>National Emblem / Coat-of-Arms: Detailed in Schedule 3.</li>\n            <li>National Flower: Rhododendron (Lali Gurans).</li>\n            <li>National Color: Crimson (Simrik).</li>\n            <li>National Animal: Cow (Gai).</li>\n            <li>National Bird: Danphe (Lophophorus / Impeyan Pheasant).</li>\n        </ul>\n    </li>\n</ol>', NULL, NULL, '[{\"question\":\"Which Article of the Constitution defines the State of Nepal?\",\"options\":[\"Article 1\",\"Article 2\",\"Article 4\",\"Article 7\"],\"answer\":2,\"explanation\":\"Article 4 defines Nepal as an independent, indivisible, sovereign, secular, federal democratic republican state.\"},{\"question\":\"According to Article 6, what are the languages of the nation in Nepal?\",\"options\":[\"Only Nepali\",\"Nepali and English\",\"All mother tongues spoken in Nepal\",\"Sanskrit and Nepali\"],\"answer\":2,\"explanation\":\"Article 6 states all mother tongues spoken in Nepal are the languages of the nation.\"},{\"question\":\"Which language and script is designated as the official working language of the Federal Government (Article 7)?\",\"options\":[\"Nepali language in Devanagari script\",\"Nepali and Maithili\",\"Nepali and English\",\"Roman Nepali\"],\"answer\":0,\"explanation\":\"Article 7(1) specifies Nepali in Devanagari script as the official language.\"},{\"question\":\"Which Schedule of the Constitution provides the mathematical and geometric specifications of the National Flag?\",\"options\":[\"Schedule 1\",\"Schedule 2\",\"Schedule 3\",\"Schedule 4\"],\"answer\":0,\"explanation\":\"Schedule 1 details the geometry and proportions of the National Flag.\"},{\"question\":\"Which Schedule contains the lyrics and notation of the National Anthem of Nepal?\",\"options\":[\"Schedule 1\",\"Schedule 2\",\"Schedule 3\",\"Schedule 5\"],\"answer\":1,\"explanation\":\"Schedule 2 contains the National Anthem text.\"},{\"question\":\"Who wrote the lyrics of the current National Anthem (\\\"Sayaun Thunga Phool Ka...\\\")?\",\"options\":[\"Amber Gurung\",\"Byakul Maila (Pradeep Kumar Rai)\",\"Madhav Ghimire\",\"Laxmi Prasad Devkota\"],\"answer\":1,\"explanation\":\"Byakul Maila penned the lyrics; music was composed by late Amber Gurung.\"},{\"question\":\"What is the national animal of Nepal according to Article 9?\",\"options\":[\"Rhino\",\"Cow (Gai)\",\"Snow Leopard\",\"Tiger\"],\"answer\":1,\"explanation\":\"The Cow (Gai) is declared the national animal.\"},{\"question\":\"What is the national color of Nepal mentioned in the Constitution?\",\"options\":[\"Crimson (Simrik)\",\"Navy Blue\",\"Golden Yellow\",\"Green\"],\"answer\":0,\"explanation\":\"Crimson (Simrik) is the official national color.\"},{\"question\":\"Which Article declares matters of national interest including sovereignty, territorial integrity, and prosperity?\",\"options\":[\"Article 3\",\"Article 5\",\"Article 8\",\"Article 10\"],\"answer\":1,\"explanation\":\"Article 5 lists the core components of national interest.\"},{\"question\":\"Which part of the Constitution deals with Citizenship provisions (Articles 10 to 15)?\",\"options\":[\"Part 1\",\"Part 2\",\"Part 3\",\"Part 4\"],\"answer\":1,\"explanation\":\"Part 2 contains citizenship provisions (Citizenship by descent, naturalization, non-resident citizenship).\"}]', 'text', 2, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(726, 147, 197, '2.3 Fundamental Rights and Duties (Part-3: Articles 16-48)', '23-fundamental-rights-and-duties-part-3-articles-16-48-197', '<h3>1. The 31 Fundamental Rights (Articles 16 - 46)</h3>\n<p>Part 3 guarantees 31 fundamental rights directly enforceable by the Supreme Court and High Courts under Articles 46, 133, and 144:</p>\n<ol start=\"16\">\n    <li><strong>Art. 16:</strong> Right to live with dignity.</li>\n    <li><strong>Art. 17:</strong> Right to freedom (opinion & expression, peaceful assembly, freedom to form associations, freedom to move & reside, practice any occupation/business).</li>\n    <li><strong>Art. 18:</strong> Right to equality (no discrimination on ground of religion, race, caste, sex, origin, language).</li>\n    <li><strong>Art. 19:</strong> Right to communication (no censorship of press).</li>\n    <li><strong>Art. 20:</strong> Right relating to justice (right to be informed of arrest, consult legal practitioner, fair trial, no double jeopardy).</li>\n    <li><strong>Art. 21:</strong> Right of victim of crime.</li>\n    <li><strong>Art. 22:</strong> Right against torture.</li>\n    <li><strong>Art. 23:</strong> Right against preventive detention.</li>\n    <li><strong>Art. 24:</strong> Right against untouchability and discrimination.</li>\n    <li><strong>Art. 25:</strong> Right relating to property.</li>\n    <li><strong>Art. 26:</strong> Right to freedom of religion.</li>\n    <li><strong>Art. 27:</strong> Right to information.</li>\n    <li><strong>Art. 28:</strong> Right to privacy.</li>\n    <li><strong>Art. 29:</strong> Right against exploitation (prohibition of human trafficking, forced labor).</li>\n    <li><strong>Art. 30:</strong> Right to clean environment.</li>\n    <li><strong>Art. 31:</strong> Right relating to education (free compulsory basic education, free secondary education).</li>\n    <li><strong>Art. 32:</strong> Right to language and culture.</li>\n    <li><strong>Art. 33:</strong> Right to employment.</li>\n    <li><strong>Art. 34:</strong> Right to labor (proper wages, trade union rights).</li>\n    <li><strong>Art. 35:</strong> Right relating to health (free basic healthcare, emergency medical services).</li>\n    <li><strong>Art. 36:</strong> Right relating to food (food sovereignty).</li>\n    <li><strong>Art. 37:</strong> Right to housing.</li>\n    <li><strong>Art. 38:</strong> Rights of women (equal lineage rights, reproductive health, property rights).</li>\n    <li><strong>Art. 39:</strong> Rights of the child.</li>\n    <li><strong>Art. 40:</strong> Rights of Dalit.</li>\n    <li><strong>Art. 41:</strong> Rights of senior citizens.</li>\n    <li><strong>Art. 42:</strong> Right to social justice (inclusive representation).</li>\n    <li><strong>Art. 43:</strong> Right to social security.</li>\n    <li><strong>Art. 44:</strong> Rights of the consumer (quality goods/services, compensation).</li>\n    <li><strong>Art. 45:</strong> Right against exile.</li>\n    <li><strong>Art. 46:</strong> Right to constitutional remedies (Writ petitions: Habeas Corpus, Mandamus, Prohibition, Quo Warranto, Certiorari).</li>\n</ol>\n\n<h3>2. Duties of Citizens (Article 48)</h3>\n<ul>\n    <li>Safeguard nationality, sovereignty, and integrity of Nepal.</li>\n    <li>Abide by the Constitution and laws.</li>\n    <li>Render compulsory service to the nation when required.</li>\n    <li>Protect and preserve public property.</li>\n</ul>', NULL, NULL, '[{\"question\":\"How many Fundamental Rights are guaranteed in Part 3 of the Constitution of Nepal?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"There are 31 Fundamental Rights provided from Article 16 to Article 46.\"},{\"question\":\"Which Article guarantees the \\\"Right to live with dignity\\\"?\",\"options\":[\"Article 16\",\"Article 17\",\"Article 18\",\"Article 20\"],\"answer\":0,\"explanation\":\"Article 16 guarantees the right to live with dignity (no death penalty allowed).\"},{\"question\":\"Which Article protects the \\\"Right to Freedom\\\" including expression, movement, and assembly?\",\"options\":[\"Article 16\",\"Article 17\",\"Article 19\",\"Article 25\"],\"answer\":1,\"explanation\":\"Article 17 outlines the fundamental freedoms.\"},{\"question\":\"Which Article guarantees the \\\"Right to Information\\\" from public bodies?\",\"options\":[\"Article 19\",\"Article 27\",\"Article 30\",\"Article 33\"],\"answer\":1,\"explanation\":\"Article 27 provides every citizen the right to demand and receive information on public matters.\"},{\"question\":\"Which Article protects the \\\"Right to Clean Environment\\\"?\",\"options\":[\"Article 25\",\"Article 30\",\"Article 35\",\"Article 44\"],\"answer\":1,\"explanation\":\"Article 30 guarantees the right to a clean and healthy environment with victim compensation.\"},{\"question\":\"Under Article 31, basic education is constitutionally declared to be:\",\"options\":[\"Optional and paid\",\"Compulsory and free\",\"Privatized\",\"Higher level only\"],\"answer\":1,\"explanation\":\"Basic education is compulsory and free; secondary education is free.\"},{\"question\":\"Which Article provides the \\\"Right of the Consumer\\\" to quality goods, services, and compensation for damages?\",\"options\":[\"Article 36\",\"Article 40\",\"Article 44\",\"Article 46\"],\"answer\":2,\"explanation\":\"Article 44 guarantees consumer rights to quality supplies and compensation.\"},{\"question\":\"Which Article guarantees the \\\"Right to Constitutional Remedies\\\" via writ petitions?\",\"options\":[\"Article 46\",\"Article 48\",\"Article 50\",\"Article 55\"],\"answer\":0,\"explanation\":\"Article 46 provides constitutional remedies through Supreme Court (Art 133) and High Court (Art 144).\"},{\"question\":\"Which writ is issued to produce a person unlawfully detained before the court?\",\"options\":[\"Mandamus\",\"Habeas Corpus (Bandi Pratyakshikaran)\",\"Quo Warranto\",\"Prohibition\"],\"answer\":1,\"explanation\":\"Habeas Corpus is issued to release an illegally detained person.\"},{\"question\":\"Which Article specifies the fundamental \\\"Duties of Citizens\\\"?\",\"options\":[\"Article 45\",\"Article 48\",\"Article 52\",\"Article 54\"],\"answer\":1,\"explanation\":\"Article 48 outlines 4 key duties of citizens.\"}]', 'text', 1, 30, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(727, 147, 197, '2.4 Directive Principles, Policies and Obligations of the State (Part-4)', '24-directive-principles-policies-and-obligations-of-the-state-part-4-197', '<h3>1. Nature of Part 4 (Articles 49 - 55)</h3>\n<p>Article 55 explicitly states that no question shall be raised in any court as to whether any provision contained in Part-4 has been implemented or not (non-justiciable in court), but they serve as the fundamental guiding principles for governance, legislation, and annual budgeting.</p>\n\n<h3>2. Directive Principles of the State (Article 50)</h3>\n<ul>\n    <li><strong>Political Objective:</strong> Establish a just system based on democratic values, rule of law, fundamental rights, and federal democratic governance.</li>\n    <li><strong>Socio-Cultural Objective:</strong> Build a civilized and egalitarian society by eliminating all forms of discrimination, inequality, and untouchability.</li>\n    <li><strong>Economic Objective:</strong> Develop an independent, self-reliant, and socialism-oriented economy through equitable distribution of national income and public, private, and cooperative participation.</li>\n    <li><strong>International Relations:</strong> Safeguard national sovereignty and territorial integrity based on the UN Charter, non-alignment, Panchasheel, and international law.</li>\n</ul>\n\n<h3>3. Key State Policies (Article 51)</h3>\n<ul>\n    <li><strong>Policy on Protection, Promotion & Utilization of Natural Resources [Art. 51(g)]:</strong>\n        <ul>\n            <li>Protection and sustainable utilization of water resources, forests, wildlife, and minerals.</li>\n            <li>Priority to domestic investment in hydropower development, multi-purpose river basin planning, and environmental impact mitigation.</li>\n            <li>Ensuring local communities benefit equitably from natural resource utilization (royalty sharing).</li>\n        </ul>\n    </li>\n    <li><strong>Policy on Labor and Employment [Art. 51(i)]:</strong>\n        <ul>\n            <li>Guaranteeing productive employment for all citizens, social security for laborers, elimination of child labor, and safeguarding rights of migrant workers.</li>\n        </ul>\n    </li>\n</ul>\n\n<h3>4. Obligations of the State (Article 52)</h3>\n<p>It is the duty of the state to maintain independence, sovereignty, and territorial integrity, protect fundamental rights and human rights, promote rule of law, and achieve sustainable prosperity.</p>', NULL, NULL, '[{\"question\":\"Which Part of the Constitution sets out Directive Principles, Policies, and Obligations of the State?\",\"options\":[\"Part 2\",\"Part 3\",\"Part 4 (Articles 49-55)\",\"Part 5\"],\"answer\":2,\"explanation\":\"Part 4 covers Directive Principles, Policies, and Obligations.\"},{\"question\":\"Can provisions contained in Part 4 (Directive Principles) be enforced or challenged directly in a court of law (Article 55)?\",\"options\":[\"Yes, fully justiciable like fundamental rights\",\"No question shall be raised in any court (non-justiciable)\",\"Only with Prime Minister\'s permission\",\"Only in the Supreme Court full bench\"],\"answer\":1,\"explanation\":\"Article 55 states Part 4 provisions are non-justiciable in court.\"},{\"question\":\"Which Article lays down the overarching Directive Principles of the State (Political, Socio-cultural, Economic & International)?\",\"options\":[\"Article 49\",\"Article 50\",\"Article 51\",\"Article 53\"],\"answer\":1,\"explanation\":\"Article 50 defines the 4 core directive principles.\"},{\"question\":\"How many broad areas of State Policies are outlined under Article 51 of the Constitution?\",\"options\":[\"6 categories\",\"10 categories\",\"13 categories (Clause a to m)\",\"20 categories\"],\"answer\":2,\"explanation\":\"Article 51 contains 13 sub-clauses covering state policies.\"},{\"question\":\"Under Article 51(g), what is the priority for developing energy and water resources in Nepal?\",\"options\":[\"Exclusive foreign privatization\",\"Priority to domestic investment, multi-purpose river planning, and environmental conservation\",\"Banning all hydropower\",\"Exporting all energy without domestic electrification\"],\"answer\":1,\"explanation\":\"Article 51(g) mandates prioritizing domestic investment and sustainable conservation.\"},{\"question\":\"Which Article outlines the general Responsibilities and Obligations of the State?\",\"options\":[\"Article 48\",\"Article 50\",\"Article 52\",\"Article 55\"],\"answer\":2,\"explanation\":\"Article 52 defines the state\'s fundamental obligations.\"},{\"question\":\"To whom does the Government of Nepal submit its annual report regarding the implementation of Directive Principles (Article 53)?\",\"options\":[\"To the President of Nepal\",\"To the Chief Justice\",\"To the Federal Parliament Speaker alone\",\"To the President, who causes it to be submitted to Parliament\"],\"answer\":3,\"explanation\":\"Article 53 requires submitting the report to the President, which is placed before Parliament.\"},{\"question\":\"Under Article 54, what parliamentary mechanism monitors the progressive realization of Part 4 provisions?\",\"options\":[\"A dedicated Joint Parliamentary Committee\",\"Public Accounts Committee alone\",\"Judicial Council\",\"CIAA\"],\"answer\":0,\"explanation\":\"Article 54 provides for a joint committee of Parliament to monitor implementation.\"},{\"question\":\"What is the constitutional economic policy model promoted under Article 50 and 51?\",\"options\":[\"Pure free market without state intervention\",\"Three-pillar economy (Public, Private, and Cooperatives)\",\"Centrally planned command economy\",\"Strict feudal monopoly\"],\"answer\":1,\"explanation\":\"Nepal\'s constitution promotes a three-pillar economic model (Public, Private, Cooperative).\"},{\"question\":\"What principle guides Nepal\'s international relations under Article 50(4)?\",\"options\":[\"Military alliance\",\"UN Charter, Non-alignment, Panchasheel, international law, and world peace\",\"Expansionism\",\"Isolationism\"],\"answer\":1,\"explanation\":\"Foreign policy is guided by Panchasheel, non-alignment, and the UN Charter.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(728, 147, 198, '2.5 Functions of Constitutional Organs (Parts 21, 22, 23, 24 & 26)', '25-functions-of-constitutional-organs-parts-21-22-23-24-26-198', '<h3>1. Commission for the Investigation of Abuse of Authority - CIAA (Part 21: Arts. 238-239)</h3>\n<ul>\n    <li><strong>Composition:</strong> Chief Commissioner and 4 Commissioners appointed by the President upon recommendation of the Constitutional Council for a term of <strong>6 years</strong> (retirement age: 65).</li>\n    <li><strong>Powers & Functions:</strong> Conduct investigations into improper conduct and corruption committed by any person holding public office. File corruption cases in the Special Court (Vishesh Adalat).</li>\n</ul>\n\n<h3>2. Auditor General of Nepal (Part 22: Arts. 240-241)</h3>\n<ul>\n    <li><strong>Appointment & Tenure:</strong> Auditor General appointed by President for a 6-year term.</li>\n    <li><strong>Functions:</strong> Audit the accounts of all Federal and Provincial government offices, Courts, Parliament, Armed Forces, Police, and <strong>Corporate Bodies / Public Enterprises wholly or majority (50%+) owned by Government (including Nepal Electricity Authority)</strong> with due regard to regularity, economy, efficiency, effectiveness, and propriety.</li>\n    <li>Submits annual audit report to the President (Federal) and Province Chiefs (Provincial).</li>\n</ul>\n\n<h3>3. Public Service Commission - PSC / Lok Sewa Aayog (Part 23: Arts. 242-243)</h3>\n<ul>\n    <li><strong>Composition:</strong> Chairperson and members appointed for 6 years.</li>\n    <li><strong>Functions:</strong> Conduct examinations for selection of suitable candidates to civil service posts and <strong>Public Enterprises / Organized Entities (including NEA)</strong>. Consulted on promotions, transfers, and departmental actions.</li>\n</ul>\n\n<h3>4. Election Commission of Nepal (Part 24: Arts. 245-247)</h3>\n<ul>\n    <li>Conducts, supervises, directs, and controls elections for President, Vice-President, Federal Parliament, Provincial Assemblies, and Local Levels, as well as Referendums. Maintains voter registers.</li>\n</ul>\n\n<h3>5. National Human Rights Commission - NHRC (Part 26: Arts. 248-249)</h3>\n<ul>\n    <li>Ensures respect, protection, and promotion of human rights. Investigates human rights violations and recommends compensation and legal prosecution.</li>\n</ul>', NULL, NULL, '[{\"question\":\"Which Part of the Constitution provides for the Commission for the Investigation of Abuse of Authority (CIAA)?\",\"options\":[\"Part 19\",\"Part 21 (Articles 238-239)\",\"Part 22\",\"Part 23\"],\"answer\":1,\"explanation\":\"Part 21 covers CIAA composition and investigatory powers.\"},{\"question\":\"What is the tenure of the Chief Commissioner and Commissioners of CIAA?\",\"options\":[\"4 years\",\"5 years\",\"6 years\",\"7 years\"],\"answer\":2,\"explanation\":\"The term of office is 6 years from appointment date (max age limit: 65).\"},{\"question\":\"Which Article mandates the Auditor General to audit accounts of Public Enterprises like NEA?\",\"options\":[\"Article 239\",\"Article 241\",\"Article 243\",\"Article 246\"],\"answer\":1,\"explanation\":\"Article 241 mandates the Auditor General to audit government offices and 50%+ state-owned entities.\"},{\"question\":\"Which Part establishes the Public Service Commission (Lok Sewa Aayog)?\",\"options\":[\"Part 20\",\"Part 21\",\"Part 23 (Articles 242-244)\",\"Part 25\"],\"answer\":2,\"explanation\":\"Part 23 governs the Public Service Commission.\"},{\"question\":\"Which body is constitutionally required to conduct written examinations for recruitment in Public Enterprises like NEA?\",\"options\":[\"Ministry of Energy\",\"Public Service Commission (Lok Sewa Aayog)\",\"Private Agency\",\"Trade Union\"],\"answer\":1,\"explanation\":\"Article 243 mandates PSC to conduct recruitment examinations for public enterprises.\"},{\"question\":\"Which Part establishes the Election Commission of Nepal?\",\"options\":[\"Part 22\",\"Part 24 (Articles 245-247)\",\"Part 26\",\"Part 28\"],\"answer\":1,\"explanation\":\"Part 24 governs the Election Commission.\"},{\"question\":\"Which Part establishes the National Human Rights Commission (NHRC)?\",\"options\":[\"Part 21\",\"Part 24\",\"Part 26 (Articles 248-249)\",\"Part 27\"],\"answer\":2,\"explanation\":\"Part 26 establishes NHRC.\"},{\"question\":\"Who heads the Constitutional Council that recommends heads of constitutional organs in Nepal?\",\"options\":[\"President of Nepal\",\"Prime Minister\",\"Chief Justice\",\"Speaker of House of Representatives\"],\"answer\":1,\"explanation\":\"Article 284 establishes the Constitutional Council headed by the Prime Minister.\"},{\"question\":\"Constitutional body heads can be removed from office prior to tenure expiry through which process?\",\"options\":[\"Impeachment (Mahabhiyog) passed by 2\\/3rd majority in House of Representatives\",\"Simple cabinet decision\",\"Presidential decree alone\",\"Supreme Court administrative order\"],\"answer\":0,\"explanation\":\"Article 101 provides for impeachment by a two-thirds majority in the House of Representatives.\"},{\"question\":\"To whom does the Auditor General submit the annual national audit report?\",\"options\":[\"Directly to the President of Nepal\",\"To the Prime Minister\",\"To the Chief Justice\",\"To the CIAA\"],\"answer\":0,\"explanation\":\"The Auditor General submits the annual report to the President under Article 241.\"}]', 'text', 1, 30, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(729, 147, 198, '2.6 Schedules of the Constitution (Schedules 1 to 9)', '26-schedules-of-the-constitution-schedules-1-to-9-198', '<h3>Complete Breakdown of the 9 Constitutional Schedules</h3>\n<table border=\"1\" cellpadding=\"8\" style=\"border-collapse: collapse; width: 100%;\">\n    <thead>\n        <tr style=\"background-color: #f1f5f9;\">\n            <th>Schedule</th>\n            <th>Title & Constitutional Subject Matter</th>\n        </tr>\n    </thead>\n    <tbody>\n        <tr>\n            <td><strong>Schedule 1</strong></td>\n            <td>National Flag of Nepal (Method of making flag, geometric proportions, colors).</td>\n        </tr>\n        <tr>\n            <td><strong>Schedule 2</strong></td>\n            <td>National Anthem of Nepal (<em>\"Sayaun Thunga Phool Ka...\"</em>).</td>\n        </tr>\n        <tr>\n            <td><strong>Schedule 3</strong></td>\n            <td>Coat-of-Arms / National Emblem of Nepal.</td>\n        </tr>\n        <tr>\n            <td><strong>Schedule 4</strong></td>\n            <td>Provinces and Districts included in each of the 7 Provinces.</td>\n        </tr>\n        <tr>\n            <td><strong>Schedule 5</strong></td>\n            <td><strong>List of Federal Powers (35 exclusive subjects):</strong> Defense, Foreign affairs, Currency & Banking, National Highways, Central Mega Power Projects & Mega Transmission Grids, Customs.</td>\n        </tr>\n        <tr>\n            <td><strong>Schedule 6</strong></td>\n            <td><strong>List of Provincial Powers (21 exclusive subjects):</strong> Provincial police, Provincial health, Provincial roads, Provincial electricity projects.</td>\n        </tr>\n        <tr>\n            <td><strong>Schedule 7</strong></td>\n            <td><strong>List of Concurrent Powers of Federation and Province (25 subjects):</strong> Civil & criminal law, Electricity & irrigation regulation, Supply of essential goods, Higher education.</td>\n        </tr>\n        <tr>\n            <td><strong>Schedule 8</strong></td>\n            <td><strong>List of Local Level Powers (22 exclusive subjects):</strong> Municipal police, Local tax collection, Basic & secondary education, Basic healthcare, Local roads, Micro-hydro projects.</td>\n        </tr>\n        <tr>\n            <td><strong>Schedule 9</strong></td>\n            <td><strong>List of Concurrent Powers of Federation, Province, and Local Level (15 subjects):</strong> Cooperatives, Education, Health, Agriculture, Electricity/water services, Disaster management.</td>\n        </tr>\n    </tbody>\n</table>', NULL, NULL, '[{\"question\":\"How many Schedules are attached to the Constitution of Nepal?\",\"options\":[\"5\",\"7\",\"9\",\"12\"],\"answer\":2,\"explanation\":\"There are 9 Schedules defining state symbols and power divisions.\"},{\"question\":\"Which Schedule contains the exclusive legislative and executive powers of the Federal Government (35 subjects)?\",\"options\":[\"Schedule 4\",\"Schedule 5\",\"Schedule 6\",\"Schedule 7\"],\"answer\":1,\"explanation\":\"Schedule 5 lists the 35 exclusive federal powers.\"},{\"question\":\"Which Schedule lists the 21 exclusive powers of Provincial Governments?\",\"options\":[\"Schedule 5\",\"Schedule 6\",\"Schedule 7\",\"Schedule 8\"],\"answer\":1,\"explanation\":\"Schedule 6 contains the 21 exclusive provincial matters.\"},{\"question\":\"Which Schedule lists the Concurrent Powers of the Federation and Province (25 subjects)?\",\"options\":[\"Schedule 5\",\"Schedule 6\",\"Schedule 7\",\"Schedule 9\"],\"answer\":2,\"explanation\":\"Schedule 7 details the concurrent federal-provincial powers.\"},{\"question\":\"Which Schedule lists the 22 exclusive powers of Local Governments (Municipalities\\/Rural Municipalities)?\",\"options\":[\"Schedule 6\",\"Schedule 7\",\"Schedule 8\",\"Schedule 9\"],\"answer\":2,\"explanation\":\"Schedule 8 details local government exclusive powers.\"},{\"question\":\"Which Schedule lists the Concurrent Powers of Federation, Province, and Local Level (15 subjects)?\",\"options\":[\"Schedule 5\",\"Schedule 7\",\"Schedule 8\",\"Schedule 9\"],\"answer\":3,\"explanation\":\"Schedule 9 lists the 15 concurrent subjects among all three levels.\"},{\"question\":\"Which Schedule lists the names of Districts grouped under each of the 7 Provinces?\",\"options\":[\"Schedule 2\",\"Schedule 3\",\"Schedule 4\",\"Schedule 5\"],\"answer\":2,\"explanation\":\"Schedule 4 lists the districts in each province.\"},{\"question\":\"Mega transmission electricity grids and central power generation fall under which Schedule?\",\"options\":[\"Schedule 5 (Federal List)\",\"Schedule 6 (Provincial List)\",\"Schedule 8 (Local List)\",\"Schedule 4\"],\"answer\":0,\"explanation\":\"Mega power and high-voltage transmission networks fall under Schedule 5.\"},{\"question\":\"Micro-hydro projects and local electricity distribution services fall under which Schedule?\",\"options\":[\"Schedule 5\",\"Schedule 6\",\"Schedule 8 (Local Level List)\",\"Schedule 1\"],\"answer\":2,\"explanation\":\"Micro-hydro and local distribution are listed in Schedule 8.\"},{\"question\":\"In case of a conflict between a Federal law and a Provincial law on a Schedule 7 concurrent matter, which law prevails?\",\"options\":[\"Provincial Law\",\"Federal Law (to the extent of inconsistency)\",\"Both are cancelled\",\"Local Law\"],\"answer\":1,\"explanation\":\"Article 57(5) states Federal law prevails over inconsistent provincial\\/local laws.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(730, 147, 198, '2.7 Constitution of Nepal Assessment Quiz', '27-constitution-of-nepal-assessment-quiz-198', '[{\"question\":\"What is the primary statutory responsibility of Nepal Electricity Authority (NEA)?\",\"options\":[\"Generation, Transmission, and Distribution of electricity across Nepal\",\"Road construction\",\"Mining coal\",\"Operating domestic airlines\"],\"answer\":0,\"explanation\":\"NEA manages generation, transmission, and distribution of electricity throughout Nepal.\"},{\"question\":\"When was Nepal Electricity Authority (NEA) established in Bikram Sambat?\",\"options\":[\"2041 Poush 1\",\"2042 Bhadra 1\",\"2046 Baishakh 1\",\"2050 Chaitra 30\"],\"answer\":1,\"explanation\":\"NEA was formally founded on Bhadra 1, 2042 BS under the NEA Act 2041.\"},{\"question\":\"What is the full mark score of Phase 1 Written Examination for NEA Level 4?\",\"options\":[\"100 Marks\",\"200 Marks (Paper I: 100 + Paper II: 100)\",\"300 Marks\",\"50 Marks\"],\"answer\":1,\"explanation\":\"The written exam comprises 200 marks (Paper I 100 marks + Paper II 100 marks).\"},{\"question\":\"What is the pass mark percentage required in each paper of the written exam?\",\"options\":[\"32%\",\"40%\",\"50%\",\"60%\"],\"answer\":1,\"explanation\":\"40 marks out of 100 is the minimum pass mark for each paper.\"},{\"question\":\"Negative marking in Loksewa multiple choice objective questions is deducted at what rate for wrong answers?\",\"options\":[\"10%\",\"20% (0.2 marks per 1 mark question)\",\"33%\",\"50%\"],\"answer\":1,\"explanation\":\"20% marks are deducted for every incorrect MCQ answer.\"},{\"question\":\"What is the theoretical hydropower potential of Nepal?\",\"options\":[\"42,000 MW\",\"83,000 MW\",\"100,000 MW\",\"20,000 MW\"],\"answer\":1,\"explanation\":\"Theoretical hydropower potential is 83,000 MW (economically feasible ~42,000 MW).\"},{\"question\":\"Which constitutional organ conducts the recruitment exams for NEA Level 4 posts?\",\"options\":[\"Public Service Commission (Lok Sewa Aayog)\",\"Ministry of Energy\",\"Tribhuvan University\",\"Private Board\"],\"answer\":0,\"explanation\":\"The Public Service Commission conducts selection examinations for public enterprises.\"},{\"question\":\"What is the fundamental accounting equation?\",\"options\":[\"Assets = Liabilities + Capital\",\"Assets = Liabilities - Capital\",\"Capital = Liabilities + Revenues\",\"Profit = Assets + Cash\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Owner\'s Equity.\"},{\"question\":\"Under the Constitution of Nepal, how many fundamental rights are guaranteed in Part 3?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"31 Fundamental Rights are guaranteed from Article 16 to Article 46.\"},{\"question\":\"What penalty is levied on power theft under Electricity Theft Control Rules 2059?\",\"options\":[\"Assessed loss amount plus 100% fine (शतप्रतिशत जरिवाना)\",\"25% fine\",\"Written warning only\",\"No fine\"],\"answer\":0,\"explanation\":\"Assessed unmetered consumption is recovered along with a 100% fine.\"}]', NULL, NULL, '[{\"question\":\"What is the primary statutory responsibility of Nepal Electricity Authority (NEA)?\",\"options\":[\"Generation, Transmission, and Distribution of electricity across Nepal\",\"Road construction\",\"Mining coal\",\"Operating domestic airlines\"],\"answer\":0,\"explanation\":\"NEA manages generation, transmission, and distribution of electricity throughout Nepal.\"},{\"question\":\"When was Nepal Electricity Authority (NEA) established in Bikram Sambat?\",\"options\":[\"2041 Poush 1\",\"2042 Bhadra 1\",\"2046 Baishakh 1\",\"2050 Chaitra 30\"],\"answer\":1,\"explanation\":\"NEA was formally founded on Bhadra 1, 2042 BS under the NEA Act 2041.\"},{\"question\":\"What is the full mark score of Phase 1 Written Examination for NEA Level 4?\",\"options\":[\"100 Marks\",\"200 Marks (Paper I: 100 + Paper II: 100)\",\"300 Marks\",\"50 Marks\"],\"answer\":1,\"explanation\":\"The written exam comprises 200 marks (Paper I 100 marks + Paper II 100 marks).\"},{\"question\":\"What is the pass mark percentage required in each paper of the written exam?\",\"options\":[\"32%\",\"40%\",\"50%\",\"60%\"],\"answer\":1,\"explanation\":\"40 marks out of 100 is the minimum pass mark for each paper.\"},{\"question\":\"Negative marking in Loksewa multiple choice objective questions is deducted at what rate for wrong answers?\",\"options\":[\"10%\",\"20% (0.2 marks per 1 mark question)\",\"33%\",\"50%\"],\"answer\":1,\"explanation\":\"20% marks are deducted for every incorrect MCQ answer.\"},{\"question\":\"What is the theoretical hydropower potential of Nepal?\",\"options\":[\"42,000 MW\",\"83,000 MW\",\"100,000 MW\",\"20,000 MW\"],\"answer\":1,\"explanation\":\"Theoretical hydropower potential is 83,000 MW (economically feasible ~42,000 MW).\"},{\"question\":\"Which constitutional organ conducts the recruitment exams for NEA Level 4 posts?\",\"options\":[\"Public Service Commission (Lok Sewa Aayog)\",\"Ministry of Energy\",\"Tribhuvan University\",\"Private Board\"],\"answer\":0,\"explanation\":\"The Public Service Commission conducts selection examinations for public enterprises.\"},{\"question\":\"What is the fundamental accounting equation?\",\"options\":[\"Assets = Liabilities + Capital\",\"Assets = Liabilities - Capital\",\"Capital = Liabilities + Revenues\",\"Profit = Assets + Cash\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Owner\'s Equity.\"},{\"question\":\"Under the Constitution of Nepal, how many fundamental rights are guaranteed in Part 3?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"31 Fundamental Rights are guaranteed from Article 16 to Article 46.\"},{\"question\":\"What penalty is levied on power theft under Electricity Theft Control Rules 2059?\",\"options\":[\"Assessed loss amount plus 100% fine (\\u0936\\u0924\\u092a\\u094d\\u0930\\u0924\\u093f\\u0936\\u0924 \\u091c\\u0930\\u093f\\u0935\\u093e\\u0928\\u093e)\",\"25% fine\",\"Written warning only\",\"No fine\"],\"answer\":0,\"explanation\":\"Assessed unmetered consumption is recovered along with a 100% fine.\"}]', 'quiz', 3, 15, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(731, 148, 199, '3.1 Unitary Method and Proportion', '31-unitary-method-and-proportion-199', '<h3>1. Concept of Unitary Method</h3>\n<p>The unitary method is a technique for solving problems by first finding the value of a single unit (1 item/day/person), and then finding the necessary value by multiplying the single unit value.</p>\n\n<h3>2. Direct vs Inverse Variation</h3>\n<ul>\n    <li><strong>Direct Proportion:</strong> As one quantity increases, the other increases in the same ratio (e.g., number of electricity units consumed vs total electricity bill amount). Formula: <code>y = kx</code>.</li>\n    <li><strong>Inverse / Indirect Proportion:</strong> As one quantity increases, the other decreases proportionally (e.g., number of workers on a transmission line construction project vs days required to complete). Formula: <code>x * y = k</code>.</li>\n</ul>\n\n<h3>3. Sample Practical Problems</h3>\n<div style=\"background-color: #f8fafc; padding: 12px; border-left: 4px solid #3b82f6; margin-bottom: 12px;\">\n    <p><strong>Example 1 (Direct):</strong> If 15 electrical meters cost Rs. 45,000, what will be the cost of 28 electrical meters?</p>\n    <p><em>Solution:</em> Cost of 1 meter = 45,000 / 15 = Rs. 3,000. Cost of 28 meters = 28 * 3,000 = <strong>Rs. 84,000</strong>.</p>\n</div>\n<div style=\"background-color: #f8fafc; padding: 12px; border-left: 4px solid #10b981;\">\n    <p><strong>Example 2 (Inverse - Time & Work):</strong> If 12 technicians can string an electric cable section in 10 days, how many days will 8 technicians take to complete the same work?</p>\n    <p><em>Solution:</em> 1 technician takes 12 * 10 = 120 days. 8 technicians take 120 / 8 = <strong>15 days</strong>.</p>\n</div>', NULL, NULL, '[{\"question\":\"If 15 energy meters cost Rs. 45,000, what is the cost of 24 energy meters?\",\"options\":[\"Rs. 60,000\",\"Rs. 72,000\",\"Rs. 80,000\",\"Rs. 90,000\"],\"answer\":1,\"explanation\":\"Unit cost = 45,000 \\/ 15 = Rs. 3,000. For 24 meters = 24 * 3,000 = Rs. 72,000.\"},{\"question\":\"If 8 technicians can install a transmission section in 12 days, how many days will 6 technicians take?\",\"options\":[\"14 days\",\"16 days\",\"18 days\",\"20 days\"],\"answer\":1,\"explanation\":\"Total work = 8 * 12 = 96 worker-days. Days for 6 technicians = 96 \\/ 6 = 16 days.\"},{\"question\":\"If 5 office clerks can type 100 documents in 4 hours, how many documents can 8 clerks type in 4 hours?\",\"options\":[\"120\",\"140\",\"160\",\"200\"],\"answer\":2,\"explanation\":\"1 clerk types 100 \\/ 5 = 20 documents. 8 clerks type 8 * 20 = 160 documents.\"},{\"question\":\"A vehicle consumes 12 liters of petrol to travel 180 km. How many liters are needed for 300 km?\",\"options\":[\"18 liters\",\"20 liters\",\"22 liters\",\"25 liters\"],\"answer\":1,\"explanation\":\"Mileage = 180 \\/ 12 = 15 km\\/liter. Petrol for 300 km = 300 \\/ 15 = 20 liters.\"},{\"question\":\"If 20 workers build a wall in 15 days, how many extra workers are required to complete it in 10 days?\",\"options\":[\"5 workers\",\"10 workers\",\"15 workers\",\"30 workers\"],\"answer\":1,\"explanation\":\"Total worker-days = 20 * 15 = 300. Workers needed for 10 days = 300 \\/ 10 = 30. Extra needed = 30 - 20 = 10.\"},{\"question\":\"If 3 machines produce 450 electrical switches in 5 hours, how many switches will 1 machine produce in 1 hour?\",\"options\":[\"15\",\"25\",\"30\",\"45\"],\"answer\":2,\"explanation\":\"Output per machine in 5 hrs = 450 \\/ 3 = 150. Output per machine in 1 hr = 150 \\/ 5 = 30.\"},{\"question\":\"If the monthly electricity bill for 250 units is Rs. 2,250, what is the cost of 400 units at the same uniform rate?\",\"options\":[\"Rs. 3,200\",\"Rs. 3,600\",\"Rs. 4,000\",\"Rs. 4,200\"],\"answer\":1,\"explanation\":\"Rate per unit = 2,250 \\/ 250 = Rs. 9. For 400 units = 400 * 9 = Rs. 3,600.\"},{\"question\":\"If 12 men or 18 women can do a piece of work in 14 days, in how many days can 8 men and 16 women do it?\",\"options\":[\"7 days\",\"9 days\",\"10 days\",\"12 days\"],\"answer\":1,\"explanation\":\"12 Men = 18 Women => 1 Man = 1.5 Women. 8 Men + 16 Women = 12 + 16 = 28 Women. Days = (18 * 14) \\/ 28 = 9 days.\"},{\"question\":\"A pipe fills a reservoir tank in 6 hours. What fraction of the tank does it fill in 2 hours?\",\"options\":[\"1\\/2\",\"1\\/3\",\"1\\/4\",\"2\\/5\"],\"answer\":1,\"explanation\":\"Fraction filled in 2 hours = 2 \\/ 6 = 1\\/3.\"},{\"question\":\"If 10 men take 20 days to complete a job working 6 hours a day, how many days will 15 men take working 8 hours a day?\",\"options\":[\"8 days\",\"10 days\",\"12 days\",\"15 days\"],\"answer\":1,\"explanation\":\"Total man-hours = 10 * 20 * 6 = 1200. Days = 1200 \\/ (15 * 8) = 1200 \\/ 120 = 10 days.\"}]', 'text', 1, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(732, 148, 199, '3.2 Percentages, Fractions and Decimals', '32-percentages-fractions-and-decimals-199', '<h3>1. Percentages</h3>\n<p>Percentage means \"per hundred\" (out of 100). Represented by symbol <code>%</code>.</p>\n<ul>\n    <li>Convert Fraction to Percentage: Multiply by 100 (e.g., 3/5 * 100 = 60%).</li>\n    <li>Convert Percentage to Fraction: Divide by 100 (e.g., 25% = 25/100 = 1/4).</li>\n    <li>Percentage Increase / Decrease = <code>(Change / Original Value) * 100%</code>.</li>\n</ul>\n\n<h3>2. Fractions and Operations</h3>\n<ul>\n    <li><strong>Proper Fraction:</strong> Numerator < Denominator (e.g., 3/7).</li>\n    <li><strong>Improper Fraction:</strong> Numerator >= Denominator (e.g., 9/4).</li>\n    <li><strong>Mixed Fraction:</strong> Whole number + Proper fraction (e.g., 2 1/4).</li>\n    <li><strong>Addition/Subtraction:</strong> Requires finding the Least Common Multiple (LCM) of denominators.</li>\n</ul>\n\n<h3>3. Practical Business Math Application</h3>\n<p>If NEA reduces transmission distribution system loss from 15.38% to 13.46%, what is the percentage point reduction? Difference = 15.38% - 13.46% = <strong>1.92 percentage points</strong>.</p>', NULL, NULL, '[{\"question\":\"What is 35% of Rs. 80,000?\",\"options\":[\"Rs. 24,000\",\"Rs. 28,000\",\"Rs. 30,000\",\"Rs. 32,000\"],\"answer\":1,\"explanation\":\"35% of 80,000 = (35\\/100) * 80,000 = Rs. 28,000.\"},{\"question\":\"Convert the fraction 3\\/8 into a percentage:\",\"options\":[\"30.5%\",\"37.5%\",\"42.5%\",\"45.0%\"],\"answer\":1,\"explanation\":\"(3\\/8) * 100% = 37.5%.\"},{\"question\":\"If a quantity increases from 400 to 500, what is the percentage increase?\",\"options\":[\"20%\",\"25%\",\"30%\",\"50%\"],\"answer\":1,\"explanation\":\"Increase = 100. Percentage increase = (100 \\/ 400) * 100% = 25%.\"},{\"question\":\"If an employee salary of Rs. 40,000 is increased by 15%, what is the new salary?\",\"options\":[\"Rs. 44,000\",\"Rs. 46,000\",\"Rs. 48,000\",\"Rs. 50,000\"],\"answer\":1,\"explanation\":\"New salary = 40,000 * 1.15 = Rs. 46,000.\"},{\"question\":\"What percentage of 2.5 kg is 250 grams?\",\"options\":[\"5%\",\"10%\",\"15%\",\"25%\"],\"answer\":1,\"explanation\":\"2.5 kg = 2,500g. (250 \\/ 2,500) * 100% = 10%.\"},{\"question\":\"If 20% of a number is 160, what is the original number?\",\"options\":[\"640\",\"800\",\"900\",\"1,000\"],\"answer\":1,\"explanation\":\"Number = 160 \\/ 0.20 = 800.\"},{\"question\":\"Simplify the fraction addition: 1\\/4 + 2\\/3 = ?\",\"options\":[\"3\\/7\",\"7\\/12\",\"11\\/12\",\"5\\/12\"],\"answer\":2,\"explanation\":\"LCM = 12. (3 + 8)\\/12 = 11\\/12.\"},{\"question\":\"Subtract 3\\/5 from 7\\/10: 7\\/10 - 3\\/5 = ?\",\"options\":[\"1\\/10\",\"2\\/5\",\"4\\/5\",\"1\\/2\"],\"answer\":0,\"explanation\":\"7\\/10 - 6\\/10 = 1\\/10.\"},{\"question\":\"In an office of 120 employees, 45% are female. How many male employees work there?\",\"options\":[\"54\",\"66\",\"70\",\"72\"],\"answer\":1,\"explanation\":\"Male % = 55%. Males = 0.55 * 120 = 66.\"},{\"question\":\"If the price of electricity is reduced by 10% and consumption increases by 10%, what is the net revenue change?\",\"options\":[\"No change\",\"1% decrease\",\"1% increase\",\"2% decrease\"],\"answer\":1,\"explanation\":\"Net change = (-10 + 10 - (10*10)\\/100)% = -1% (1% decrease).\"}]', 'text', 2, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(733, 148, 199, '3.3 Average (Arithmetic Mean) and Statistical Central Tendency', '33-average-arithmetic-mean-and-statistical-central-tendency-199', '<h3>1. Formula for Average</h3>\n<p><code>Average (Mean) = (Sum of all observations) / (Total number of observations)</code></p>\n<p><code>Sum of Observations = Average * Total Number</code></p>\n\n<h3>2. Weighted Average</h3>\n<p><code>Weighted Mean = Σ(w * x) / Σ(w)</code> where w represents weight/frequency and x represents the data values.</p>\n\n<h3>3. High-Yield Examination Problems</h3>\n<div style=\"background-color: #f8fafc; padding: 12px; border-left: 4px solid #3b82f6;\">\n    <p><strong>Problem:</strong> The average monthly salary of 10 assistants in an NEA distribution center is Rs. 35,000. When the branch manager\'s salary is added, the average increases to Rs. 38,000. What is the manager\'s salary?</p>\n    <p><em>Solution:</em></p>\n    <ul>\n        <li>Total salary of 10 assistants = 10 * 35,000 = Rs. 350,000.</li>\n        <li>Total salary of 11 employees = 11 * 38,000 = Rs. 418,000.</li>\n        <li>Manager\'s Salary = 418,000 - 350,000 = <strong>Rs. 68,000</strong>.</li>\n    </ul>\n</div>', NULL, NULL, '[{\"question\":\"Find the average of the numbers: 12, 18, 24, 30, and 36:\",\"options\":[\"22\",\"24\",\"26\",\"28\"],\"answer\":1,\"explanation\":\"Sum = 120. Average = 120 \\/ 5 = 24.\"},{\"question\":\"The average of 6 numbers is 25. If one number is excluded, the average becomes 22. What was the excluded number?\",\"options\":[\"35\",\"40\",\"42\",\"45\"],\"answer\":1,\"explanation\":\"Total of 6 = 150. Total of 5 = 110. Excluded number = 150 - 110 = 40.\"},{\"question\":\"The average monthly salary of 10 employees is Rs. 30,000. When the officer\'s salary is added, the average becomes Rs. 33,000. What is the officer\'s salary?\",\"options\":[\"Rs. 50,000\",\"Rs. 60,000\",\"Rs. 63,000\",\"Rs. 70,000\"],\"answer\":2,\"explanation\":\"Total 10 = 300,000. Total 11 = 363,000. Officer salary = 363,000 - 300,000 = Rs. 63,000.\"},{\"question\":\"The average of first 50 natural numbers (1, 2, 3, ... 50) is:\",\"options\":[\"25.0\",\"25.5\",\"26.0\",\"50.0\"],\"answer\":1,\"explanation\":\"Average = (n + 1) \\/ 2 = 51 \\/ 2 = 25.5.\"},{\"question\":\"A batsman scores 45, 62, 78, 85, and 0 in 5 innings. What is his batting average?\",\"options\":[\"54\",\"67.5\",\"50\",\"60\"],\"answer\":0,\"explanation\":\"Sum = 270. Average = 270 \\/ 5 = 54.\"},{\"question\":\"Find the average of all prime numbers between 10 and 25 (11, 13, 17, 19, 23):\",\"options\":[\"15.4\",\"16.6\",\"17.0\",\"18.2\"],\"answer\":1,\"explanation\":\"Sum = 11 + 13 + 17 + 19 + 23 = 83. Average = 83 \\/ 5 = 16.6.\"},{\"question\":\"In a class of 30 boys and 20 girls, average weight of boys is 50 kg and girls is 40 kg. What is the class average weight?\",\"options\":[\"44 kg\",\"45 kg\",\"46 kg\",\"48 kg\"],\"answer\":2,\"explanation\":\"Total weight = (30 * 50) + (20 * 40) = 1500 + 800 = 2300 kg. Average = 2300 \\/ 50 = 46 kg.\"},{\"question\":\"The average age of 4 family members is 28 years. If a child aged 3 is added, what is the new average age?\",\"options\":[\"21 years\",\"23 years\",\"25 years\",\"26 years\"],\"answer\":1,\"explanation\":\"Sum = 4 * 28 = 112. New sum = 112 + 3 = 115. New average = 115 \\/ 5 = 23 years.\"},{\"question\":\"The average of 5 consecutive odd integers starting from x is:\",\"options\":[\"x + 2\",\"x + 4\",\"x + 5\",\"x + 6\"],\"answer\":1,\"explanation\":\"Numbers: x, x+2, x+4, x+6, x+8. Average is the middle term: x + 4.\"},{\"question\":\"If the average temperature of Monday, Tuesday, and Wednesday was 32\\u00b0C, and total of Mon and Tue was 60\\u00b0C, what was Wednesday\'s temperature?\",\"options\":[\"32\\u00b0C\",\"34\\u00b0C\",\"36\\u00b0C\",\"38\\u00b0C\"],\"answer\":2,\"explanation\":\"Total 3 days = 3 * 32 = 96\\u00b0C. Wed = 96 - 60 = 36\\u00b0C.\"}]', 'text', 3, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(734, 148, 199, '3.4 Profit, Loss, Discount and Simple Interest', '34-profit-loss-discount-and-simple-interest-199', '<h3>1. Profit and Loss Formulas</h3>\n<ul>\n    <li><code>Profit = Selling Price (SP) - Cost Price (CP)</code> (when SP > CP)</li>\n    <li><code>Loss = Cost Price (CP) - Selling Price (SP)</code> (when CP > SP)</li>\n    <li><code>Profit % = (Profit / CP) * 100%</code></li>\n    <li><code>Loss % = (Loss / CP) * 100%</code></li>\n    <li><code>SP = CP * (1 + Profit% / 100)</code> or <code>SP = CP * (1 - Loss% / 100)</code></li>\n</ul>\n\n<h3>2. Marked Price & Discount</h3>\n<ul>\n    <li><code>Discount Amount = Marked Price (MP) - Selling Price (SP)</code></li>\n    <li><code>Discount % = (Discount Amount / MP) * 100%</code></li>\n    <li><code>SP = MP * (1 - Discount% / 100)</code></li>\n</ul>\n\n<h3>3. Simple Interest</h3>\n<ul>\n    <li><code>Simple Interest (I) = (P * T * R) / 100</code>\n        <ul>\n            <li><strong>P:</strong> Principal sum</li>\n            <li><strong>T:</strong> Time in years</li>\n            <li><strong>R:</strong> Rate of interest per annum (%)</li>\n        </ul>\n    </li>\n    <li><code>Total Amount (A) = Principal (P) + Interest (I)</code></li>\n</ul>\n\n<div style=\"background-color: #f8fafc; padding: 12px; border-left: 4px solid #10b981;\">\n    <p><strong>Example:</strong> Find the simple interest and total maturity amount on Rs. 80,000 invested at an annual interest rate of 8.5% for 3 years.</p>\n    <p><em>Solution:</em> <code>I = (80,000 * 3 * 8.5) / 100 = Rs. 20,400</code>. Total Amount = 80,000 + 20,400 = <strong>Rs. 100,400</strong>.</p>\n</div>', NULL, NULL, '[{\"question\":\"An electrical item bought for Rs. 4,000 is sold for Rs. 4,800. What is the profit percentage?\",\"options\":[\"15%\",\"20%\",\"25%\",\"30%\"],\"answer\":1,\"explanation\":\"Profit = 800. Profit % = (800 \\/ 4,000) * 100% = 20%.\"},{\"question\":\"A generator bought for Rs. 50,000 is sold at a loss of 12%. What is the Selling Price?\",\"options\":[\"Rs. 42,000\",\"Rs. 44,000\",\"Rs. 46,000\",\"Rs. 48,000\"],\"answer\":1,\"explanation\":\"SP = 50,000 * (1 - 0.12) = 50,000 * 0.88 = Rs. 44,000.\"},{\"question\":\"An article with Marked Price Rs. 2,500 is sold with a 15% discount. What is the cash selling price?\",\"options\":[\"Rs. 2,100\",\"Rs. 2,125\",\"Rs. 2,150\",\"Rs. 2,200\"],\"answer\":1,\"explanation\":\"Discount = 0.15 * 2,500 = Rs. 375. SP = 2,500 - 375 = Rs. 2,125.\"},{\"question\":\"What is the Simple Interest on a principal of Rs. 60,000 at 8% per annum for 3 years?\",\"options\":[\"Rs. 12,000\",\"Rs. 14,400\",\"Rs. 16,000\",\"Rs. 18,200\"],\"answer\":1,\"explanation\":\"I = (60,000 * 3 * 8) \\/ 100 = Rs. 14,400.\"},{\"question\":\"What is the total maturity amount (Principal + Interest) on Rs. 100,000 at 10% simple interest for 2.5 years?\",\"options\":[\"Rs. 120,000\",\"Rs. 125,000\",\"Rs. 130,000\",\"Rs. 135,000\"],\"answer\":1,\"explanation\":\"Interest = (100,000 * 2.5 * 10)\\/100 = Rs. 25,000. Total = 100,000 + 25,000 = Rs. 125,000.\"},{\"question\":\"In how many years will a sum of money double itself at 10% per annum simple interest?\",\"options\":[\"5 years\",\"8 years\",\"10 years\",\"12 years\"],\"answer\":2,\"explanation\":\"Time T = 100 \\/ R = 100 \\/ 10 = 10 years.\"},{\"question\":\"If Cost Price is Rs. 800 and Loss is 25%, what is the Selling Price?\",\"options\":[\"Rs. 500\",\"Rs. 600\",\"Rs. 650\",\"Rs. 700\"],\"answer\":1,\"explanation\":\"SP = 800 * 0.75 = Rs. 600.\"},{\"question\":\"A shopkeeper marks an item 30% above cost and offers a 10% discount. What is his net profit percentage?\",\"options\":[\"15%\",\"17%\",\"20%\",\"22%\"],\"answer\":1,\"explanation\":\"Let CP = 100, MP = 130. SP = 130 * 0.90 = 117. Profit = 17%.\"},{\"question\":\"At what rate percent per annum will Rs. 40,000 yield a simple interest of Rs. 9,600 in 3 years?\",\"options\":[\"6%\",\"7.5%\",\"8%\",\"10%\"],\"answer\":2,\"explanation\":\"Rate R = (9,600 * 100) \\/ (40,000 * 3) = 960,000 \\/ 120,000 = 8%.\"},{\"question\":\"Two successive discounts of 20% and 10% are equivalent to a single discount of:\",\"options\":[\"28%\",\"30%\",\"32%\",\"25%\"],\"answer\":0,\"explanation\":\"Equivalent discount = (20 + 10 - (20*10)\\/100)% = 28%.\"}]', 'text', 4, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(735, 148, 200, '3.5 Computer Fundamentals and Operating Systems', '35-computer-fundamentals-and-operating-systems-200', '<h3>1. Computer Hardware Architecture</h3>\n<ul>\n    <li><strong>Input Devices:</strong> Keyboard, Mouse, Scanner, Barcode Reader, Optical Mark Reader (OMR - used in Loksewa checking).</li>\n    <li><strong>Central Processing Unit (CPU):</strong> ALU (Arithmetic Logic Unit), CU (Control Unit), and Registers.</li>\n    <li><strong>Primary Memory:</strong> RAM (Random Access Memory - volatile), ROM (Read Only Memory - non-volatile containing BIOS/firmware).</li>\n    <li><strong>Secondary Storage:</strong> Hard Disk Drive (HDD), Solid State Drive (SSD), Optical discs, Flash drives.</li>\n    <li><strong>Output Devices:</strong> Monitor (VDU), Printers (Laser, Inkjet, Dot Matrix), Plotters.</li>\n</ul>\n\n<h3>2. Software Classifications</h3>\n<ul>\n    <li><strong>System Software:</strong> Operating Systems (Windows 10/11, Linux, macOS) managing hardware, CPU scheduling, file storage, and peripheral interfaces.</li>\n    <li><strong>Application Software:</strong> Specialized end-user tools (MS Office Suite, Web browsers, ERP accounting software).</li>\n    <li><strong>Utility Software:</strong> Antivirus, disk defragmenter, file compression (ZIP, RAR).</li>\n</ul>', NULL, NULL, '[{\"question\":\"Which component is considered the \\\"Brain of the Computer\\\"?\",\"options\":[\"RAM\",\"Central Processing Unit (CPU)\",\"Hard Disk\",\"Motherboard\"],\"answer\":1,\"explanation\":\"The Central Processing Unit (CPU) performs all processing and controls operations.\"},{\"question\":\"Which type of computer memory is volatile and loses its data when power is turned off?\",\"options\":[\"ROM\",\"RAM (Random Access Memory)\",\"Hard Disk\",\"Flash Drive\"],\"answer\":1,\"explanation\":\"RAM is volatile primary working memory.\"},{\"question\":\"What type of software is an Operating System (e.g., Windows, Linux)?\",\"options\":[\"System Software\",\"Application Software\",\"Utility Software\",\"Malware\"],\"answer\":0,\"explanation\":\"Operating systems are fundamental System Software.\"},{\"question\":\"Which of the following is an input device used for reading marked objective exam sheets?\",\"options\":[\"Laser Printer\",\"Optical Mark Reader (OMR)\",\"Plotter\",\"Speaker\"],\"answer\":1,\"explanation\":\"OMR is used to evaluate multiple choice question sheets.\"},{\"question\":\"How many bits make up 1 Byte?\",\"options\":[\"4 bits\",\"8 bits\",\"16 bits\",\"32 bits\"],\"answer\":1,\"explanation\":\"1 Byte = 8 bits. (4 bits = 1 Nibble).\"},{\"question\":\"How many Kilobytes (KB) are in 1 Megabyte (MB)?\",\"options\":[\"100 KB\",\"1,000 KB\",\"1,024 KB\",\"2,048 KB\"],\"answer\":2,\"explanation\":\"1 MB = 1,024 KB (in binary system).\"},{\"question\":\"What does BIOS stand for in computer hardware boot-up?\",\"options\":[\"Basic Input Output System\",\"Binary Integrated Operating System\",\"Broadband Internal Optical Sensor\",\"Base Instruction Operating Socket\"],\"answer\":0,\"explanation\":\"BIOS stands for Basic Input Output System.\"},{\"question\":\"Which storage drive offers the fastest read\\/write speeds using flash memory?\",\"options\":[\"Floppy Disk\",\"HDD (Hard Disk Drive)\",\"SSD (Solid State Drive)\",\"CD-ROM\"],\"answer\":2,\"explanation\":\"SSDs have no moving parts and offer significantly faster read\\/write speeds than HDDs.\"},{\"question\":\"Which shortcut key combination is commonly used to permanently delete a file in Windows without sending it to Recycle Bin?\",\"options\":[\"Ctrl + Delete\",\"Shift + Delete\",\"Alt + Delete\",\"Ctrl + Shift + D\"],\"answer\":1,\"explanation\":\"Shift + Delete permanently deletes files.\"},{\"question\":\"Which unit of the CPU coordinates and directs operations of the other computer units?\",\"options\":[\"ALU (Arithmetic Logic Unit)\",\"Control Unit (CU)\",\"Registers\",\"Cache Memory\"],\"answer\":1,\"explanation\":\"The Control Unit (CU) directs and supervises operations within the CPU.\"}]', 'text', 1, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(736, 148, 200, '3.6 Office Applications: Word Processing, Excel & PowerPoint', '36-office-applications-word-processing-excel-powerpoint-200', '<h3>1. MS Word (Word Processing)</h3>\n<ul>\n    <li>Document creation, formatting (font styles, line spacing, margins, header & footer).</li>\n    <li>Tables, page breaks, watermarks, track changes, spell check, and <strong>Mail Merge</strong> (generating mass personalized letters).</li>\n    <li>Shortcuts: Ctrl+C (Copy), Ctrl+V (Paste), Ctrl+Z (Undo), Ctrl+Y (Redo), Ctrl+B (Bold), Ctrl+F (Find), Ctrl+H (Replace), Ctrl+S (Save), Ctrl+P (Print).</li>\n</ul>\n\n<h3>2. MS Excel (Spreadsheets & Data Analysis)</h3>\n<ul>\n    <li>Worksheet structure: Rows (numbered 1, 2, 3...) and Columns (lettered A, B, C...). Cell address: e.g., A1, C10.</li>\n    <li>Essential Formulas & Functions:\n        <ul>\n            <li><code>=SUM(A1:A10)</code>: Calculates total sum.</li>\n            <li><code>=AVERAGE(B1:B20)</code>: Computes arithmetic mean.</li>\n            <li><code>=COUNT(range)</code> and <code>=COUNTA(range)</code>: Counts numeric and non-empty cells.</li>\n            <li><code>=IF(logical_test, value_if_true, value_if_false)</code>: Conditional evaluation.</li>\n            <li><code>=VLOOKUP(lookup_value, table_array, col_index, [exact_match])</code>: Data search.</li>\n        </ul>\n    </li>\n    <li>Charts (Column, Bar, Pie charts), sorting, filtering, and Pivot Tables.</li>\n</ul>\n\n<h3>3. MS PowerPoint (Presentations)</h3>\n<ul>\n    <li>Slide layouts, slide master, transitions, custom animations, presenter notes, slide show shortcut (F5).</li>\n</ul>', NULL, NULL, '[{\"question\":\"Which feature in MS Word is used to create mass personalized letters or notices to multiple recipients?\",\"options\":[\"Spell Check\",\"Mail Merge\",\"Track Changes\",\"WordArt\"],\"answer\":1,\"explanation\":\"Mail Merge merges a letter template with a recipient database.\"},{\"question\":\"What is the default file extension for documents saved in modern MS Word?\",\"options\":[\".txt\",\".docx\",\".xlsx\",\".pptx\"],\"answer\":1,\"explanation\":\".docx is the standard XML-based format for MS Word.\"},{\"question\":\"In MS Excel, which formula symbol must precede every calculation or function?\",\"options\":[\"@\",\"#\",\"=\",\"$\"],\"answer\":2,\"explanation\":\"All Excel formulas must begin with an equal sign (=).\"},{\"question\":\"Which Excel function calculates the arithmetic average of a specified range of cells?\",\"options\":[\"=AVG()\",\"=AVERAGE()\",\"=MEAN()\",\"=SUMAVG()\"],\"answer\":1,\"explanation\":\"=AVERAGE() calculates the arithmetic mean.\"},{\"question\":\"In MS Excel, what is cell address \\\"C5\\\"?\",\"options\":[\"Row C, Column 5\",\"Column C, Row 5\",\"Sheet C, Cell 5\",\"Book 5, Page C\"],\"answer\":1,\"explanation\":\"C5 refers to the intersection of Column C and Row 5.\"},{\"question\":\"Which keyboard shortcut initiates a PowerPoint slide show from the very first slide?\",\"options\":[\"F1\",\"F5\",\"Shift + F5\",\"Ctrl + F5\"],\"answer\":1,\"explanation\":\"F5 starts the presentation from Slide 1.\"},{\"question\":\"What is the shortcut to start a slide show from the currently active slide in PowerPoint?\",\"options\":[\"F5\",\"Shift + F5\",\"Ctrl + P\",\"Alt + S\"],\"answer\":1,\"explanation\":\"Shift + F5 launches the slide show from the current slide.\"},{\"question\":\"In MS Word, which shortcut key centers the selected text paragraph?\",\"options\":[\"Ctrl + L\",\"Ctrl + C\",\"Ctrl + E\",\"Ctrl + J\"],\"answer\":2,\"explanation\":\"Ctrl + E centers text (Ctrl+L left aligns, Ctrl+R right aligns, Ctrl+J justifies).\"},{\"question\":\"What is the shortcut key to search\\/find text within an MS Office document?\",\"options\":[\"Ctrl + F\",\"Ctrl + H\",\"Ctrl + S\",\"Ctrl + K\"],\"answer\":0,\"explanation\":\"Ctrl + F opens the Find dialog; Ctrl + H opens Find & Replace.\"},{\"question\":\"Which Excel function is used to look up a value in the leftmost column of a table and return a corresponding value from another column?\",\"options\":[\"=LOOKUP()\",\"=VLOOKUP()\",\"=HLOOKUP()\",\"=INDEX()\"],\"answer\":1,\"explanation\":\"=VLOOKUP() performs vertical table searches.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(737, 148, 200, '3.7 Email, Internet and Cyber Security Basics', '37-email-internet-and-cyber-security-basics-200', '<h3>1. Internet and Networking Protocols</h3>\n<ul>\n    <li><strong>IP Address:</strong> Unique numerical identifier assigned to every device connected to a network (IPv4: 32-bit, IPv6: 128-bit).</li>\n    <li><strong>DNS (Domain Name System):</strong> Translates human-readable domain names (e.g., www.nea.org.np) into IP addresses.</li>\n    <li><strong>HTTP / HTTPS:</strong> HyperText Transfer Protocol (HTTPS is secured with SSL/TLS encryption).</li>\n    <li><strong>URL (Uniform Resource Locator):</strong> Complete web address specifying location and protocol.</li>\n</ul>\n\n<h3>2. Electronic Mail (Email) Protocols & Etiquette</h3>\n<ul>\n    <li><strong>SMTP (Simple Mail Transfer Protocol):</strong> Protocol used for sending outgoing emails.</li>\n    <li><strong>POP3 / IMAP:</strong> Protocols used for receiving and retrieving incoming emails from mail servers.</li>\n    <li><strong>Email Fields:</strong> To (primary recipient), CC (Carbon Copy - visible to all), BCC (Blind Carbon Copy - hidden from other recipients), Subject, Attachments.</li>\n</ul>\n\n<h3>3. Cyber Security in Public Offices</h3>\n<ul>\n    <li>Threats: Phishing, malware, viruses, ransomware, trojans, social engineering.</li>\n    <li>Protection: Strong passwords, two-factor authentication (2FA), regular backups, licensed antivirus, Electronic Transactions Act (ETA 2063).</li>\n</ul>', NULL, NULL, '[{\"question\":\"What protocol is used to transmit outgoing email messages across the internet?\",\"options\":[\"POP3\",\"IMAP\",\"SMTP (Simple Mail Transfer Protocol)\",\"HTTP\"],\"answer\":2,\"explanation\":\"SMTP is the standard protocol for sending outgoing emails.\"},{\"question\":\"Which email protocol downloads messages to a local client and deletes them from the server by default?\",\"options\":[\"SMTP\",\"POP3 (Post Office Protocol 3)\",\"IMAP\",\"FTP\"],\"answer\":1,\"explanation\":\"POP3 downloads messages locally, while IMAP syncs across multiple devices.\"},{\"question\":\"In an email, what does BCC stand for?\",\"options\":[\"Blind Carbon Copy\",\"Back Carbon Copy\",\"Broad Client Communication\",\"Basic Contact Code\"],\"answer\":0,\"explanation\":\"BCC stands for Blind Carbon Copy (recipients hidden from others).\"},{\"question\":\"What system translates domain names (e.g. www.nea.org.np) into IP addresses?\",\"options\":[\"DHCP\",\"DNS (Domain Name System)\",\"FTP\",\"VPN\"],\"answer\":1,\"explanation\":\"DNS resolves domain names into machine-readable IP addresses.\"},{\"question\":\"What does HTTPS stand for, and what indicates security in a web address?\",\"options\":[\"HyperText Transfer Protocol Secure (SSL\\/TLS encryption)\",\"High Text Technology Protocol Source\",\"Hyperlink Transmission Private Service\",\"Home Telecom Public Server\"],\"answer\":0,\"explanation\":\"HTTPS encrypts communications using SSL\\/TLS.\"},{\"question\":\"What is the length of an IPv4 address in bits?\",\"options\":[\"16 bits\",\"32 bits\",\"64 bits\",\"128 bits\"],\"answer\":1,\"explanation\":\"IPv4 addresses are 32 bits long (IPv6 addresses are 128 bits).\"},{\"question\":\"What is fraudulent email designed to steal passwords or financial credentials called?\",\"options\":[\"Phishing\",\"Spamming\",\"Blogging\",\"Caching\"],\"answer\":0,\"explanation\":\"Phishing is a social engineering cyberattack masquerading as a trustworthy entity.\"},{\"question\":\"Which Act governs cybercrimes and electronic signatures in Nepal?\",\"options\":[\"Electronic Transactions Act, 2063 (2008)\",\"Telecommunications Act 2053\",\"Information Act 2064\",\"Banking Act 2064\"],\"answer\":0,\"explanation\":\"The Electronic Transactions Act (ETA 2063) regulates cyber crimes in Nepal.\"},{\"question\":\"What does URL stand for in web browsing?\",\"options\":[\"Uniform Resource Locator\",\"Universal Record Line\",\"United Remote Link\",\"Uniform Retrieval Language\"],\"answer\":0,\"explanation\":\"URL stands for Uniform Resource Locator.\"},{\"question\":\"What security measure requires entering a one-time code (OTP) in addition to a password?\",\"options\":[\"Two-Factor Authentication (2FA \\/ MFA)\",\"Firewall rule\",\"Data compression\",\"Proxy server\"],\"answer\":0,\"explanation\":\"2FA\\/MFA provides an extra layer of authentication beyond passwords.\"}]', 'text', 3, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(738, 148, 200, '3.8 Mathematics & Computer Assessment Quiz', '38-mathematics-computer-assessment-quiz-200', '[{\"question\":\"What is the primary statutory responsibility of Nepal Electricity Authority (NEA)?\",\"options\":[\"Generation, Transmission, and Distribution of electricity across Nepal\",\"Road construction\",\"Mining coal\",\"Operating domestic airlines\"],\"answer\":0,\"explanation\":\"NEA manages generation, transmission, and distribution of electricity throughout Nepal.\"},{\"question\":\"When was Nepal Electricity Authority (NEA) established in Bikram Sambat?\",\"options\":[\"2041 Poush 1\",\"2042 Bhadra 1\",\"2046 Baishakh 1\",\"2050 Chaitra 30\"],\"answer\":1,\"explanation\":\"NEA was formally founded on Bhadra 1, 2042 BS under the NEA Act 2041.\"},{\"question\":\"What is the full mark score of Phase 1 Written Examination for NEA Level 4?\",\"options\":[\"100 Marks\",\"200 Marks (Paper I: 100 + Paper II: 100)\",\"300 Marks\",\"50 Marks\"],\"answer\":1,\"explanation\":\"The written exam comprises 200 marks (Paper I 100 marks + Paper II 100 marks).\"},{\"question\":\"What is the pass mark percentage required in each paper of the written exam?\",\"options\":[\"32%\",\"40%\",\"50%\",\"60%\"],\"answer\":1,\"explanation\":\"40 marks out of 100 is the minimum pass mark for each paper.\"},{\"question\":\"Negative marking in Loksewa multiple choice objective questions is deducted at what rate for wrong answers?\",\"options\":[\"10%\",\"20% (0.2 marks per 1 mark question)\",\"33%\",\"50%\"],\"answer\":1,\"explanation\":\"20% marks are deducted for every incorrect MCQ answer.\"},{\"question\":\"What is the theoretical hydropower potential of Nepal?\",\"options\":[\"42,000 MW\",\"83,000 MW\",\"100,000 MW\",\"20,000 MW\"],\"answer\":1,\"explanation\":\"Theoretical hydropower potential is 83,000 MW (economically feasible ~42,000 MW).\"},{\"question\":\"Which constitutional organ conducts the recruitment exams for NEA Level 4 posts?\",\"options\":[\"Public Service Commission (Lok Sewa Aayog)\",\"Ministry of Energy\",\"Tribhuvan University\",\"Private Board\"],\"answer\":0,\"explanation\":\"The Public Service Commission conducts selection examinations for public enterprises.\"},{\"question\":\"What is the fundamental accounting equation?\",\"options\":[\"Assets = Liabilities + Capital\",\"Assets = Liabilities - Capital\",\"Capital = Liabilities + Revenues\",\"Profit = Assets + Cash\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Owner\'s Equity.\"},{\"question\":\"Under the Constitution of Nepal, how many fundamental rights are guaranteed in Part 3?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"31 Fundamental Rights are guaranteed from Article 16 to Article 46.\"},{\"question\":\"What penalty is levied on power theft under Electricity Theft Control Rules 2059?\",\"options\":[\"Assessed loss amount plus 100% fine (शतप्रतिशत जरिवाना)\",\"25% fine\",\"Written warning only\",\"No fine\"],\"answer\":0,\"explanation\":\"Assessed unmetered consumption is recovered along with a 100% fine.\"}]', NULL, NULL, '[{\"question\":\"What is the primary statutory responsibility of Nepal Electricity Authority (NEA)?\",\"options\":[\"Generation, Transmission, and Distribution of electricity across Nepal\",\"Road construction\",\"Mining coal\",\"Operating domestic airlines\"],\"answer\":0,\"explanation\":\"NEA manages generation, transmission, and distribution of electricity throughout Nepal.\"},{\"question\":\"When was Nepal Electricity Authority (NEA) established in Bikram Sambat?\",\"options\":[\"2041 Poush 1\",\"2042 Bhadra 1\",\"2046 Baishakh 1\",\"2050 Chaitra 30\"],\"answer\":1,\"explanation\":\"NEA was formally founded on Bhadra 1, 2042 BS under the NEA Act 2041.\"},{\"question\":\"What is the full mark score of Phase 1 Written Examination for NEA Level 4?\",\"options\":[\"100 Marks\",\"200 Marks (Paper I: 100 + Paper II: 100)\",\"300 Marks\",\"50 Marks\"],\"answer\":1,\"explanation\":\"The written exam comprises 200 marks (Paper I 100 marks + Paper II 100 marks).\"},{\"question\":\"What is the pass mark percentage required in each paper of the written exam?\",\"options\":[\"32%\",\"40%\",\"50%\",\"60%\"],\"answer\":1,\"explanation\":\"40 marks out of 100 is the minimum pass mark for each paper.\"},{\"question\":\"Negative marking in Loksewa multiple choice objective questions is deducted at what rate for wrong answers?\",\"options\":[\"10%\",\"20% (0.2 marks per 1 mark question)\",\"33%\",\"50%\"],\"answer\":1,\"explanation\":\"20% marks are deducted for every incorrect MCQ answer.\"},{\"question\":\"What is the theoretical hydropower potential of Nepal?\",\"options\":[\"42,000 MW\",\"83,000 MW\",\"100,000 MW\",\"20,000 MW\"],\"answer\":1,\"explanation\":\"Theoretical hydropower potential is 83,000 MW (economically feasible ~42,000 MW).\"},{\"question\":\"Which constitutional organ conducts the recruitment exams for NEA Level 4 posts?\",\"options\":[\"Public Service Commission (Lok Sewa Aayog)\",\"Ministry of Energy\",\"Tribhuvan University\",\"Private Board\"],\"answer\":0,\"explanation\":\"The Public Service Commission conducts selection examinations for public enterprises.\"},{\"question\":\"What is the fundamental accounting equation?\",\"options\":[\"Assets = Liabilities + Capital\",\"Assets = Liabilities - Capital\",\"Capital = Liabilities + Revenues\",\"Profit = Assets + Cash\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Owner\'s Equity.\"},{\"question\":\"Under the Constitution of Nepal, how many fundamental rights are guaranteed in Part 3?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"31 Fundamental Rights are guaranteed from Article 16 to Article 46.\"},{\"question\":\"What penalty is levied on power theft under Electricity Theft Control Rules 2059?\",\"options\":[\"Assessed loss amount plus 100% fine (\\u0936\\u0924\\u092a\\u094d\\u0930\\u0924\\u093f\\u0936\\u0924 \\u091c\\u0930\\u093f\\u0935\\u093e\\u0928\\u093e)\",\"25% fine\",\"Written warning only\",\"No fine\"],\"answer\":0,\"explanation\":\"Assessed unmetered consumption is recovered along with a 100% fine.\"}]', 'quiz', 4, 15, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(739, 149, 201, '4.1 Bookkeeping and Double Entry Accounting System', '41-bookkeeping-and-double-entry-accounting-system-201', '<h3>1. Definition of Bookkeeping & Accounting</h3>\n<p><strong>Bookkeeping:</strong> The systematic recording of day-to-day financial transactions in the books of original entry in chronological order.</p>\n<p><strong>Accounting:</strong> The comprehensive process of identifying, measuring, recording, classifying, summarizing, analyzing, interpreting, and communicating financial information to stakeholders.</p>\n\n<h3>2. Double Entry Bookkeeping System (दोहोरो लेखा प्रणाली)</h3>\n<p>First codified by Franciscan friar <strong>Luca Pacioli in 1494 AD</strong> in Venice, Italy (\"Father of Accounting\").</p>\n<h4>Fundamental Rules of Double Entry:</h4>\n<ul>\n    <li>Every financial transaction affects at least two accounts (one debited, one credited).</li>\n    <li>Total Debit Amount must always equal Total Credit Amount (<code>Debit = Credit</code>).</li>\n</ul>\n\n<h3>3. Traditional Golden Rules of Accounting</h3>\n<table border=\"1\" cellpadding=\"8\" style=\"border-collapse: collapse; width: 100%;\">\n    <thead>\n        <tr style=\"background-color: #f1f5f9;\">\n            <th>Account Category</th>\n            <th>Debit Rule</th>\n            <th>Credit Rule</th>\n        </tr>\n    </thead>\n    <tbody>\n        <tr>\n            <td><strong>Personal Accounts</strong> (Persons, Firms, Bank, NEA)</td>\n            <td>Debit the Receiver</td>\n            <td>Credit the Giver</td>\n        </tr>\n        <tr>\n            <td><strong>Real Accounts</strong> (Tangible & Intangible Assets: Cash, Building, Machinery)</td>\n            <td>Debit what comes in</td>\n            <td>Credit what goes out</td>\n        </tr>\n        <tr>\n            <td><strong>Nominal Accounts</strong> (Expenses, Losses, Incomes, Gains)</td>\n            <td>Debit all expenses & losses</td>\n            <td>Credit all incomes & gains</td>\n        </tr>\n    </tbody>\n</table>\n\n<h3>4. Modern Classification of Accounts</h3>\n<ul>\n    <li><strong>Assets & Expenses:</strong> Normal balance is Debit. Increase is Debited (+), Decrease is Credited (-).</li>\n    <li><strong>Liabilities, Capital/Equity & Revenues:</strong> Normal balance is Credit. Increase is Credited (+), Decrease is Debited (-).</li>\n</ul>', NULL, NULL, '[{\"question\":\"Who is recognized as the \\\"Father of Modern Accounting\\\" for publishing the double entry principles in 1494?\",\"options\":[\"Adam Smith\",\"Luca Pacioli\",\"Alfred Marshall\",\"F.W. Taylor\"],\"answer\":1,\"explanation\":\"Italian mathematician Luca Pacioli published the first treatise on double-entry accounting in 1494.\"},{\"question\":\"What is the fundamental rule of double entry bookkeeping regarding every transaction?\",\"options\":[\"Only cash is recorded\",\"Every debit must have an equal and corresponding credit\",\"Assets are always equal to profits\",\"Only sales are recorded\"],\"answer\":1,\"explanation\":\"Total Debits must always equal Total Credits in every transaction.\"},{\"question\":\"According to traditional accounting rules, what is the rule for Personal Accounts?\",\"options\":[\"Debit what comes in, Credit what goes out\",\"Debit the Receiver, Credit the Giver\",\"Debit all expenses, Credit all incomes\",\"Debit assets, Credit liabilities\"],\"answer\":1,\"explanation\":\"Personal Account rule: Debit the Receiver, Credit the Giver.\"},{\"question\":\"What is the Golden Rule for Nominal Accounts (Expenses, Incomes, Losses, Gains)?\",\"options\":[\"Debit the Receiver, Credit the Giver\",\"Debit what comes in, Credit what goes out\",\"Debit all Expenses and Losses, Credit all Incomes and Gains\",\"Credit all assets, Debit all liabilities\"],\"answer\":2,\"explanation\":\"Nominal Account rule: Debit all expenses\\/losses, Credit all incomes\\/gains.\"},{\"question\":\"Which of the following is classified as a Real Account?\",\"options\":[\"Salary Account\",\"Ram\'s Account\",\"Building \\/ Machinery Account\",\"Rent Received Account\"],\"answer\":2,\"explanation\":\"Building and machinery are tangible property (Real Accounts).\"},{\"question\":\"In modern classification, what is the normal balance of an Asset account?\",\"options\":[\"Debit balance\",\"Credit balance\",\"Zero balance\",\"Neutral balance\"],\"answer\":0,\"explanation\":\"Assets and Expenses have normal Debit balances; increases are debited.\"},{\"question\":\"What is the normal balance of a Liability account?\",\"options\":[\"Debit balance\",\"Credit balance\",\"Overdraft balance\",\"Contingent balance\"],\"answer\":1,\"explanation\":\"Liabilities, Equity, and Revenue accounts have normal Credit balances.\"},{\"question\":\"The book of original entry where financial transactions are first recorded in chronological order is called:\",\"options\":[\"Ledger\",\"Journal (Goswara Voucher)\",\"Trial Balance\",\"Balance Sheet\"],\"answer\":1,\"explanation\":\"The Journal is the primary book of original entry.\"},{\"question\":\"The process of transferring journal entries into respective ledger accounts is known as:\",\"options\":[\"Journalizing\",\"Posting (Khatauni)\",\"Balancing\",\"Auditing\"],\"answer\":1,\"explanation\":\"Posting is transferring journal debit\\/credit amounts to respective ledger accounts.\"},{\"question\":\"A brief explanatory note written beneath every journal entry explaining the transaction is called:\",\"options\":[\"Ledger Folio\",\"Narration\",\"Contra note\",\"Voucher index\"],\"answer\":1,\"explanation\":\"Narration explains the background and purpose of the journal entry.\"}]', 'text', 1, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(740, 149, 201, '4.2 Accounting Terminology and the Accounting Equation', '42-accounting-terminology-and-the-accounting-equation-201', '<h3>1. Key Accounting Terminology</h3>\n<ul>\n    <li><strong>Assets (सम्पत्ति):</strong> Economic resources owned by the entity that are expected to yield future economic benefits (Current assets: Cash, debtors, inventory; Non-current assets: Plant, transmission lines, land).</li>\n    <li><strong>Liabilities (दायित्व):</strong> Present obligations of the enterprise arising from past events, the settlement of which is expected to result in an outflow of resources (Creditors, loans, bank overdraft, unpaid bills).</li>\n    <li><strong>Capital / Owner\'s Equity (पुँजी):</strong> The residual interest in the assets of the enterprise after deducting all its liabilities (<code>Equity = Assets - Liabilities</code>).</li>\n    <li><strong>Revenues / Income (आम्दानी):</strong> Inflows of economic benefits generated from normal business operations (Electricity sales, meter rent, service connection charges).</li>\n    <li><strong>Expenses (खर्च):</strong> Outflows or consumption of assets incurred in the process of generating revenue (Fuel, employee salaries, repairs, interest expense).</li>\n    <li><strong>Journal Voucher / Goswara Voucher (गोश्वारा भौचर):</strong> The primary document containing chronological records of financial transactions with debit/credit entries, account codes, and narration.</li>\n</ul>\n\n<h3>2. The Fundamental Accounting Equation</h3>\n<p style=\"font-size: 1.15em; font-weight: bold; background-color: #e0f2fe; padding: 10px; border-radius: 6px;\">\n    Assets = Liabilities + Capital (Owner\'s Equity)\n</p>\n<p>Expanded Accounting Equation: <code>Assets = Liabilities + Initial Capital + (Revenues - Expenses) - Drawings</code></p>', NULL, NULL, '[{\"question\":\"What is the fundamental Accounting Equation?\",\"options\":[\"Assets = Liabilities + Capital (Owner\'s Equity)\",\"Assets = Liabilities - Capital\",\"Capital = Assets + Liabilities\",\"Liabilities = Assets + Capital\"],\"answer\":0,\"explanation\":\"The core accounting equation is Assets = Liabilities + Capital.\"},{\"question\":\"If a business entity has total Assets of Rs. 1,500,000 and Liabilities of Rs. 600,000, what is its Capital\\/Equity?\",\"options\":[\"Rs. 2,100,000\",\"Rs. 900,000\",\"Rs. 600,000\",\"Rs. 1,500,000\"],\"answer\":1,\"explanation\":\"Capital = Assets - Liabilities = 1,500,000 - 600,000 = Rs. 900,000.\"},{\"question\":\"Purchasing office equipment for Rs. 50,000 in cash affects the accounting equation by:\",\"options\":[\"Increasing total assets\",\"Decreasing total assets\",\"Increasing one asset (Equipment) and decreasing another asset (Cash) with no net change in total assets\",\"Increasing liabilities\"],\"answer\":2,\"explanation\":\"Equipment increases by 50k and Cash decreases by 50k (total assets remain unchanged).\"},{\"question\":\"Paying staff salaries of Rs. 30,000 in cash impacts the accounting equation by:\",\"options\":[\"Decreasing Assets (Cash) and decreasing Capital (Expense)\",\"Increasing Assets and increasing Liabilities\",\"Increasing Liabilities only\",\"No change\"],\"answer\":0,\"explanation\":\"Cash decreases by 30k (Asset -30k) and Capital decreases by 30k (Expense -30k).\"},{\"question\":\"What is the term for obligations owed by an enterprise to external third parties (creditors, lenders)?\",\"options\":[\"Assets\",\"Liabilities\",\"Capital\",\"Retained Earnings\"],\"answer\":1,\"explanation\":\"Liabilities represent legal financial obligations owed to outsiders.\"},{\"question\":\"What is the term for customers from whom payment for goods\\/services supplied on credit is receivable?\",\"options\":[\"Creditors\",\"Debtors \\/ Accounts Receivable\",\"Suppliers\",\"Shareholders\"],\"answer\":1,\"explanation\":\"Debtors \\/ Receivables are customers who owe money to the entity.\"},{\"question\":\"What type of asset is Goodwill, Patents, and Computer Software?\",\"options\":[\"Current Assets\",\"Tangible Fixed Assets\",\"Intangible Fixed Assets\",\"Fictitious Assets\"],\"answer\":2,\"explanation\":\"Goodwill and patents are Intangible Assets possessing economic value without physical substance.\"},{\"question\":\"What are assets that are expected to be converted into cash within one normal operating cycle\\/year called?\",\"options\":[\"Fixed Assets\",\"Current Assets\",\"Non-current Assets\",\"Wasting Assets\"],\"answer\":1,\"explanation\":\"Current Assets (cash, inventory, debtors) are liquid within 1 year.\"},{\"question\":\"When electricity revenue is billed to customers on credit, how is the accounting equation affected?\",\"options\":[\"Assets (Debtors) increase and Equity (Revenue) increases\",\"Liabilities increase and Assets decrease\",\"Only Cash increases\",\"Capital decreases\"],\"answer\":0,\"explanation\":\"Debtors increase (+Asset) and Revenue increases (+Capital).\"},{\"question\":\"What is the expanded accounting equation incorporating revenues and expenses?\",\"options\":[\"Assets = Liabilities + Capital + Revenues - Expenses - Drawings\",\"Assets = Liabilities - Revenues + Expenses\",\"Capital = Assets + Liabilities + Expenses\",\"Assets + Liabilities = Capital + Profits\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Beginning Capital + Revenues - Expenses - Drawings.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(741, 149, 201, '4.3 Capital vs Revenue Expenditure and Bases of Accounting', '43-capital-vs-revenue-expenditure-and-bases-of-accounting-201', '<h3>1. Capital Expenditure vs Revenue Expenditure</h3>\n<table border=\"1\" cellpadding=\"8\" style=\"border-collapse: collapse; width: 100%;\">\n    <thead>\n        <tr style=\"background-color: #f1f5f9;\">\n            <th>Feature</th>\n            <th>Capital Expenditure (पुँजीगत खर्च)</th>\n            <th>Revenue Expenditure (आयगत खर्च)</th>\n        </tr>\n    </thead>\n    <tbody>\n        <tr>\n            <td><strong>Definition</strong></td>\n            <td>Expenditure incurred to acquire, improve, or extend the useful life of fixed assets.</td>\n            <td>Expenditure incurred in the day-to-day operation and maintenance of business.</td>\n        </tr>\n        <tr>\n            <td><strong>Benefit Period</strong></td>\n            <td>Yields economic benefits across multiple accounting years (> 1 year).</td>\n            <td>Benefit consumed within the current accounting year (<= 1 year).</td>\n        </tr>\n        <tr>\n            <td><strong>Accounting Treatment</strong></td>\n            <td>Debited to Asset Account; capitalized in Balance Sheet.</td>\n            <td>Debited to Expense Account; charged to Profit & Loss Account.</td>\n        </tr>\n        <tr>\n            <td><strong>Examples</strong></td>\n            <td>Purchase of power transformers, construction of substation, transmission line towers.</td>\n            <td>Staff salaries, office rent, transformer oil replacement, routine line maintenance.</td>\n        </tr>\n    </tbody>\n</table>\n\n<h3>2. Bases of Accounting</h3>\n<ul>\n    <li><strong>Cash Basis of Accounting:</strong> Transactions are recorded only when cash is actually received or paid. Accrued incomes and unpaid expenses are ignored. Simple but fails matching principle.</li>\n    <li><strong>Accrual / Mercantile Basis of Accounting (प्रोद्भावी लेखा):</strong> Transactions are recognized when they occur (earned or incurred), irrespective of the actual cash flow. Mandated by Nepal Accounting Standards (NAS) / NFRS and NEA financial rules.</li>\n</ul>', NULL, NULL, '[{\"question\":\"Which of the following is the best example of Capital Expenditure?\",\"options\":[\"Monthly office rent\",\"Purchase and erection of a 33 kV substation power transformer\",\"Office stationery purchase\",\"Transformer oil refilling\"],\"answer\":1,\"explanation\":\"Purchasing and installing a substation transformer provides long-term operational benefit (>1 yr).\"},{\"question\":\"Where is Revenue Expenditure charged in the annual financial statements?\",\"options\":[\"Balance Sheet Asset side\",\"Profit and Loss Account (Income Statement)\",\"Capital Reserves\",\"Cash Book Contra\"],\"answer\":1,\"explanation\":\"Revenue expenditures are charged against annual revenue in the Profit & Loss Account.\"},{\"question\":\"Heavy advertising or software development expense whose benefit extends over 3-5 years is known as:\",\"options\":[\"Deferred Revenue Expenditure\",\"Capital Receipt\",\"Current Liability\",\"Revenue Loss\"],\"answer\":0,\"explanation\":\"Deferred Revenue Expenditure is written off over multiple financial periods.\"},{\"question\":\"Which accounting concept requires transactions to be recorded when earned or incurred regardless of cash settlement?\",\"options\":[\"Cash Basis\",\"Accrual \\/ Mercantile Basis\",\"Cost Concept\",\"Dual Aspect\"],\"answer\":1,\"explanation\":\"Accrual accounting recognizes revenue when earned and expenses when incurred.\"},{\"question\":\"In Cash Basis of Accounting, when is electricity revenue recorded in the books?\",\"options\":[\"When the meter is read\",\"When the bill is generated\",\"Only when cash\\/online payment is actually received\",\"At the end of fiscal year\"],\"answer\":2,\"explanation\":\"Cash basis strictly records transactions upon actual cash receipt\\/disbursement.\"},{\"question\":\"Which standard accounting framework is followed by public enterprises in Nepal for financial presentation?\",\"options\":[\"Nepal Financial Reporting Standards (NFRS \\/ NAS)\",\"US GAAP exclusively\",\"Single Entry code\",\"Treasury Code\"],\"answer\":0,\"explanation\":\"Nepal Financial Reporting Standards (NFRS) aligned with IFRS is mandated in Nepal.\"},{\"question\":\"Wages paid for the installation and foundation construction of a new hydro generator are classified as:\",\"options\":[\"Revenue Expenditure\",\"Capital Expenditure (added to the cost of the generator)\",\"Deferred Expense\",\"Administrative Overhead\"],\"answer\":1,\"explanation\":\"Installation costs directly attributable to bringing an asset to working condition are capitalized.\"},{\"question\":\"Routine servicing and annual repairs of office pickup vehicles are classified as:\",\"options\":[\"Capital Expenditure\",\"Revenue Expenditure\",\"Deferred Revenue\",\"Capital Loss\"],\"answer\":1,\"explanation\":\"Routine repairs maintain the existing operating condition and are revenue expenses.\"},{\"question\":\"Money received from selling electricity to consumers during normal operations is called:\",\"options\":[\"Capital Receipt\",\"Revenue Receipt\",\"Deferred Income\",\"Contingent Receipt\"],\"answer\":1,\"explanation\":\"Revenue Receipts arise from core ongoing operating activities.\"},{\"question\":\"Money received from issuing long-term corporate bonds or taking long-term bank loans is classified as:\",\"options\":[\"Capital Receipt\",\"Revenue Receipt\",\"Operating Profit\",\"Deferred Expense\"],\"answer\":0,\"explanation\":\"Long-term borrowings and share capital are Capital Receipts.\"}]', 'text', 3, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(742, 149, 202, '4.4 Books of Accounts, Petty Cash and Subsidiary Ledgers', '44-books-of-accounts-petty-cash-and-subsidiary-ledgers-202', '<h3>1. Cash Book Types</h3>\n<ul>\n    <li><strong>Single Column Cash Book:</strong> Records only cash receipts and cash payments.</li>\n    <li><strong>Double Column Cash Book:</strong> Contains Cash and Bank columns (or Cash and Discount columns).</li>\n    <li><strong>Triple Column Cash Book:</strong> Contains Cash, Bank, and Discount columns on both debit and credit sides. Handles contra entries (depositing cash in bank or withdrawing cash for office use).</li>\n</ul>\n\n<h3>2. Petty Cash Fund (सानो नगदी कोष) & Imprest System</h3>\n<p>Used to handle minor, recurring office expenses (tea/hospitality, stationery, stamps, local taxi fares) to avoid writing bank cheques for small amounts.</p>\n<ul>\n    <li><strong>Imprest System:</strong> A fixed advance float (e.g., Rs. 20,000) is provided to the petty cashier. At the end of the period, upon submitting authorized receipts and expense vouchers, the exact amount spent is reimbursed, restoring the fund back to its original float level.</li>\n</ul>\n\n<h3>3. Subsidiary Ledgers (सहायक खाता)</h3>\n<p>Specialized sub-ledgers maintaining detailed individual accounts: Debtor Ledger (Customer electricity consumption dues), Creditor Ledger (Equipment and contractor payables), and Asset Register.</p>', NULL, NULL, '[{\"question\":\"Which type of Cash Book records cash transactions, bank transactions, and cash discounts on both sides?\",\"options\":[\"Single Column Cash Book\",\"Double Column Cash Book\",\"Triple Column Cash Book\",\"Petty Cash Book\"],\"answer\":2,\"explanation\":\"Triple Column Cash Book includes Cash, Bank, and Discount columns.\"},{\"question\":\"What is a \\\"Contra Entry\\\" in a Double\\/Triple Column Cash Book?\",\"options\":[\"An entry involving both Cash and Bank accounts recorded on opposite sides of the same cash book\",\"An entry between two suppliers\",\"An error correction note\",\"A year-end closing entry\"],\"answer\":0,\"explanation\":\"Contra entries (depositing cash in bank or withdrawing cash for office) affect both cash & bank.\"},{\"question\":\"In an Imprest Petty Cash System, what happens at the end of the reimbursement period?\",\"options\":[\"The fund is closed\",\"The petty cashier is reimbursed the exact amount spent to restore the float\",\"The fund is doubled\",\"A new cashier is appointed\"],\"answer\":1,\"explanation\":\"Reimbursement equal to total validated expenses restores the petty cash balance to its fixed imprest float.\"},{\"question\":\"Who maintains the Petty Cash Book in an organization?\",\"options\":[\"Chief Accountant\",\"Petty Cashier\",\"External Auditor\",\"Bank Manager\"],\"answer\":1,\"explanation\":\"The Petty Cashier handles small day-to-day office expenses.\"},{\"question\":\"What is the primary objective of maintaining a Petty Cash Fund?\",\"options\":[\"To avoid writing bank cheques for small, recurring office expenses (tea, stamps, minor repairs)\",\"To hide audit expenses\",\"To purchase major equipment\",\"To pay staff monthly salaries\"],\"answer\":0,\"explanation\":\"Petty cash prevents administrative bottlenecks from writing cheques for minor expenses.\"},{\"question\":\"What is recorded in a Purchase Book (Subsidiary Ledger)?\",\"options\":[\"All cash purchases of goods\",\"Credit purchases of goods\\/inventory\",\"Purchase of fixed assets on cash\",\"All cash payments\"],\"answer\":1,\"explanation\":\"Purchase Book records credit purchases of trading goods\\/inventory.\"},{\"question\":\"What is recorded in a Sales Book (Subsidiary Ledger)?\",\"options\":[\"All cash sales\",\"Credit sales of goods\\/services to customers\",\"Sale of old fixed assets\",\"All revenue receipts\"],\"answer\":1,\"explanation\":\"Sales Book strictly records credit sales of merchandise\\/services.\"},{\"question\":\"Where are transactions that cannot be entered in any specific subsidiary book recorded?\",\"options\":[\"Cash Book\",\"Journal Proper (General Journal)\",\"Bank Ledger\",\"Petty Cash Book\"],\"answer\":1,\"explanation\":\"Journal Proper records opening\\/closing entries, rectifications, and asset credit purchases.\"},{\"question\":\"Which column of the Triple Column Cash Book is not balanced at the end of the period, but simply totaled?\",\"options\":[\"Cash column\",\"Bank column\",\"Discount column\",\"Date column\"],\"answer\":2,\"explanation\":\"Discount columns are totaled and posted to Discount Allowed (Dr) and Discount Received (Cr) accounts.\"},{\"question\":\"What letter is marked in the L.F. (Ledger Folio) column against a Contra entry in the cash book?\",\"options\":[\"\\\"P\\\"\",\"\\\"C\\\"\",\"\\\"B\\\"\",\"\\\"J\\\"\"],\"answer\":1,\"explanation\":\"The letter \\\"C\\\" indicates a Contra entry.\"}]', 'text', 1, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(743, 149, 202, '4.5 Bank Reconciliation Statement and Depreciation Accounting', '45-bank-reconciliation-statement-and-depreciation-accounting-202', '<h3>1. Bank Reconciliation Statement (BRS - बैंक हिसाब मिलान विवरण)</h3>\n<p>A statement prepared periodically by an accountant to reconcile the difference between the bank balance shown in the Cash Book and the balance shown in the Bank Statement / Passbook.</p>\n<h4>Causes of Differences:</h4>\n<ul>\n    <li>Cheques issued but not yet presented for payment in bank (Add to Cash Book balance).</li>\n    <li>Cheques deposited but not yet cleared/credited by bank (Deduct from Cash Book balance).</li>\n    <li>Direct bank charges, interest debited by bank not recorded in cash book (Deduct).</li>\n    <li>Direct collections by bank (customer electricity bill online deposit) not recorded in cash book (Add).</li>\n    <li>Errors in recording transactions by office or bank.</li>\n</ul>\n\n<h3>2. Depreciation Accounting (ह्रासकट्टी)</h3>\n<p>The systematic allocation of the depreciable amount of a tangible fixed asset over its estimated useful economic life due to wear and tear, obsolescence, or passage of time.</p>\n<h4>Depreciation Computation Methods:</h4>\n<ol>\n    <li><strong>Straight-Line Method - SLM (स्थिर किस्ताबन्दी विधि):</strong> Equal amount of depreciation is charged every year.\n        <p><code>Annual Depreciation = (Cost of Asset - Estimated Scrap Value) / Useful Life in Years</code></p>\n    </li>\n    <li><strong>Diminishing / Written Down Value / Declining Balance Method (घट्दो दर ह्रासकट्टी विधि):</strong> Depreciation is calculated at a fixed percentage on the opening book value (Written Down Value) of the asset each year. Depreciation amount decreases year after year.</li>\n</ol>', NULL, NULL, '[{\"question\":\"What is the primary purpose of preparing a Bank Reconciliation Statement (BRS)?\",\"options\":[\"To calculate corporate tax\",\"To reconcile differences between bank balance in Cash Book and balance in Bank Statement\\/Passbook\",\"To calculate asset depreciation\",\"To apply for bank loans\"],\"answer\":1,\"explanation\":\"BRS reconciles differences between the organization\'s cash book and bank passbook.\"},{\"question\":\"A cheque of Rs. 15,000 issued to a supplier was not presented to the bank for payment. How is this treated when starting from Cash Book balance in BRS?\",\"options\":[\"Deducted from Cash Book balance\",\"Added to Cash Book balance\",\"Ignored completely\",\"Multiplied by interest\"],\"answer\":1,\"explanation\":\"Cheques issued but not presented must be Added to the Cash Book balance.\"},{\"question\":\"Bank charges of Rs. 500 debited by the bank were not recorded in the Cash Book. How is this treated in BRS starting from Cash Book balance?\",\"options\":[\"Deducted from Cash Book balance\",\"Added to Cash Book balance\",\"Recorded as asset\",\"No adjustment\"],\"answer\":0,\"explanation\":\"Bank charges reduce the bank balance and must be Deducted from Cash Book balance.\"},{\"question\":\"What is Depreciation in accounting?\",\"options\":[\"Increase in asset value due to inflation\",\"Systematic allocation of the cost of a tangible fixed asset over its useful life\",\"Cash outflow for loan repayment\",\"Insurance payment\"],\"answer\":1,\"explanation\":\"Depreciation is the gradual reduction in book value of tangible fixed assets.\"},{\"question\":\"Under the Straight-Line Method (SLM), what is the annual depreciation on a machine costing Rs. 100,000 with scrap value Rs. 10,000 and useful life 5 years?\",\"options\":[\"Rs. 15,000\",\"Rs. 18,000\",\"Rs. 20,000\",\"Rs. 22,500\"],\"answer\":1,\"explanation\":\"Depreciation = (100,000 - 10,000) \\/ 5 = 90,000 \\/ 5 = Rs. 18,000\\/year.\"},{\"question\":\"Under the Diminishing \\/ Declining Balance Method, how is depreciation calculated each year?\",\"options\":[\"On original cost every year\",\"At a fixed rate on the opening Written Down Value (Book Value) of the asset\",\"On market resale price\",\"On replacement cost\"],\"answer\":1,\"explanation\":\"Depreciation is calculated on the reducing book balance (Written Down Value) each year.\"},{\"question\":\"Which tangible asset is generally not depreciated because it does not lose useful life or wear out?\",\"options\":[\"Building\",\"Plant & Machinery\",\"Freehold Land\",\"Vehicles\"],\"answer\":2,\"explanation\":\"Freehold Land has an unlimited useful economic life and is not depreciated.\"},{\"question\":\"What is the term for writing off the value of Intangible assets like patents or software?\",\"options\":[\"Depreciation\",\"Amortization\",\"Depletion\",\"Obsolescence\"],\"answer\":1,\"explanation\":\"Amortization refers to the systematic write-off of intangible assets.\"},{\"question\":\"What is the term for the extraction and exhaustion of natural resources (mines, oil wells, quarries)?\",\"options\":[\"Amortization\",\"Depreciation\",\"Depletion\",\"Devaluation\"],\"answer\":2,\"explanation\":\"Depletion applies to wasting natural assets like mineral mines.\"},{\"question\":\"Where is accumulated depreciation shown in the Balance Sheet?\",\"options\":[\"As a liability or deducted directly from the gross cost of the respective fixed asset\",\"Under Current Assets\",\"As Operating Revenue\",\"Under Cash & Bank\"],\"answer\":0,\"explanation\":\"Accumulated depreciation is shown as a contra-asset deduction from fixed assets.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(744, 149, 203, '4.6 Trial Balance and Financial Reporting', '46-trial-balance-and-financial-reporting-203', '<h3>1. Trial Balance (सन्तुलन परीक्षण)</h3>\n<p>A schedule of debit and credit balances extracted from all ledger accounts on a specific date to verify the arithmetic accuracy of double-entry postings.</p>\n<ul>\n    <li><strong>Objectives:</strong> Check arithmetic accuracy, facilitate financial statement preparation, summarize ledger balances.</li>\n    <li><strong>Errors not detected by Trial Balance:</strong> Error of principle, error of complete omission, compensating errors, error of commission with balanced amount, error of original entry.</li>\n</ul>\n\n<h3>2. Final Financial Statements</h3>\n<ul>\n    <li><strong>Profit and Loss Account (नाफा नोक्सान हिसाब):</strong> Prepared for an accounting period to determine the Net Profit or Net Loss by matching total revenues against total expenses.</li>\n    <li><strong>Balance Sheet (वासलात):</strong> A statement of financial position as of a specific date showing total Assets on one side and Liabilities + Equity on the other side.</li>\n</ul>\n\n<h3>3. NEA Operational Offices Financial Reporting & Consolidation</h3>\n<p>NEA operates through Regional Offices and Distribution & Consumer Services Centers (DCSCs). Branch offices maintain cash books, revenue ledgers, and expenditure registers, submitting monthly trial balances, bank reconciliations, and budget utilization statements to Central Accounts for consolidation.</p>', NULL, NULL, '[{\"question\":\"What is a Trial Balance?\",\"options\":[\"A list of all ledger account balances on a specific date to verify arithmetic accuracy of double entry\",\"A final legal document\",\"A bank document\",\"An inventory list\"],\"answer\":0,\"explanation\":\"Trial balance summarizes debit and credit balances to check mathematical accuracy.\"},{\"question\":\"Which accounting error is NOT revealed by a Trial Balance agreement?\",\"options\":[\"Error of Principle (treating capital expense as revenue)\",\"Single-sided posting omission\",\"Mathematical addition error in trial balance\",\"Posting different amounts on debit and credit\"],\"answer\":0,\"explanation\":\"Error of principle affects debits and credits equally, keeping the trial balance in balance.\"},{\"question\":\"What type of error occurs when a transaction is completely omitted from being recorded in the books?\",\"options\":[\"Error of Commission\",\"Error of Complete Omission\",\"Compensating Error\",\"Error of Principle\"],\"answer\":1,\"explanation\":\"Error of complete omission leaves both debit and credit unrecorded, so trial balance agrees.\"},{\"question\":\"Which financial statement is prepared to compute the Net Profit or Net Loss for an accounting period?\",\"options\":[\"Balance Sheet\",\"Profit and Loss Account (Income Statement)\",\"Trial Balance\",\"Cash Book\"],\"answer\":1,\"explanation\":\"The Profit & Loss Account measures operational profitability for the period.\"},{\"question\":\"Which financial statement reveals the financial position (Assets, Liabilities, Equity) on a specific date?\",\"options\":[\"Trial Balance\",\"Profit & Loss Statement\",\"Balance Sheet (Statement of Financial Position)\",\"Bank Statement\"],\"answer\":2,\"explanation\":\"The Balance Sheet shows assets and liabilities on a specified closing date.\"},{\"question\":\"In a Trading Account, what is the formula to calculate Gross Profit?\",\"options\":[\"Net Sales - Cost of Goods Sold (COGS)\",\"Net Sales + Operating Expenses\",\"Total Assets - Liabilities\",\"Purchases - Closing Stock\"],\"answer\":0,\"explanation\":\"Gross Profit = Net Sales Revenue - Cost of Goods Sold.\"},{\"question\":\"How is Cost of Goods Sold (COGS) calculated?\",\"options\":[\"Opening Stock + Net Purchases + Direct Expenses - Closing Stock\",\"Sales + Closing Stock\",\"Purchases + Indirect Expenses\",\"Fixed Costs + Depreciation\"],\"answer\":0,\"explanation\":\"COGS = Opening Stock + Purchases + Direct Factory Expenses - Closing Stock.\"},{\"question\":\"What temporary account is opened when a Trial Balance does not balance at year-end pending investigation of errors?\",\"options\":[\"Drawings Account\",\"Suspense Account\",\"Reserve Account\",\"Petty Cash Account\"],\"answer\":1,\"explanation\":\"The Suspense Account holds the difference until errors are identified and rectified.\"},{\"question\":\"How are electricity sales revenues collected by NEA branch offices consolidated into the central balance sheet?\",\"options\":[\"Branch Trial Balances and inter-office accounts are merged and reconciled with Head Office\",\"Ignored until 5 years\",\"Reported only to banks\",\"Branches keep separate private sheets\"],\"answer\":0,\"explanation\":\"Branch trial balances are submitted monthly and consolidated into the corporate accounts.\"},{\"question\":\"Where are prepaid expenses (expenses paid in advance) shown in the Balance Sheet?\",\"options\":[\"Current Liabilities\",\"Current Assets\",\"Fixed Assets\",\"Long-term Debts\"],\"answer\":1,\"explanation\":\"Prepaid expenses represent future economic benefits and are Current Assets.\"}]', 'text', 1, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(745, 149, 203, '4.7 Cost Accounting and Store Inventory Valuation', '47-cost-accounting-and-store-inventory-valuation-203', '<h3>1. Cost Accounting Basics</h3>\n<p>The specialized branch of accounting dedicated to ascertaining, analyzing, controlling, and optimizing costs of products, services, or projects.</p>\n<ul>\n    <li><strong>Cost Classification:</strong> Fixed Costs (do not vary with electricity generation volume e.g., plant depreciation), Variable Costs (vary directly e.g., fuel/consumables), Semi-Variable Costs.</li>\n    <li><strong>Direct vs Indirect Costs:</strong> Direct material, direct labor, direct expenses (Prime Cost) vs Production, Administrative, and Selling Overheads.</li>\n</ul>\n\n<h3>2. Public Procurement & Store Management (सार्वजनिक खरिद र भण्डार व्यवस्थापन)</h3>\n<p>Store management ensures uninterrupted supply of materials while minimizing holding costs and preventing pilferage or damage. Maintained via Bin Cards and Store Ledgers.</p>\n\n<h3>3. Material Issue Pricing / Valuation Methods</h3>\n<table border=\"1\" cellpadding=\"8\" style=\"border-collapse: collapse; width: 100%;\">\n    <thead>\n        <tr style=\"background-color: #f1f5f9;\">\n            <th>Valuation Method</th>\n            <th>Operating Principle</th>\n            <th>Impact during Inflation</th>\n        </tr>\n    </thead>\n    <tbody>\n        <tr>\n            <td><strong>FIFO (First-In, First-Out)</strong></td>\n            <td>Oldest inventory purchased is issued first. Closing inventory valued at latest prices.</td>\n            <td>Higher reported profit; closing stock reflects current market value.</td>\n        </tr>\n        <tr>\n            <td><strong>LIFO (Last-In, First-Out)</strong></td>\n            <td>Most recently acquired goods issued first. Older inventory remains in stock.</td>\n            <td>Lower reported profit; tax benefits during rising prices (rarely allowed by NAS).</td>\n        </tr>\n        <tr>\n            <td><strong>Simple Average Method</strong></td>\n            <td>Issue price = Sum of unit prices of batches / Number of batches (quantities ignored).</td>\n            <td>Simple calculation but distorts cost if lot sizes vary significantly.</td>\n        </tr>\n        <tr>\n            <td><strong>Weighted Average Method</strong></td>\n            <td><code>Issue Rate = Total Cost of Available Stock / Total Quantity Available</code></td>\n            <td>Smooths price fluctuations; standard method used in NEA store accounting.</td>\n        </tr>\n    </tbody>\n</table>', NULL, NULL, '[{\"question\":\"What is the primary objective of Cost Accounting?\",\"options\":[\"Calculating and controlling costs of products, services, and operations to aid managerial decision making\",\"Filing income tax alone\",\"Calculating dividend for shareholders\",\"Managing bank accounts\"],\"answer\":0,\"explanation\":\"Cost accounting ascertains and controls operational costs for management.\"},{\"question\":\"What is the sum of Direct Material, Direct Labor, and Direct Expenses called?\",\"options\":[\"Prime Cost\",\"Works Cost\",\"Cost of Production\",\"Total Overhead\"],\"answer\":0,\"explanation\":\"Prime Cost = Direct Materials + Direct Labor + Direct Expenses.\"},{\"question\":\"Costs that remain constant in total regardless of changes in electricity production volume are called:\",\"options\":[\"Variable Costs\",\"Fixed Costs (e.g. plant depreciation, permanent salaries)\",\"Semi-variable Costs\",\"Marginal Costs\"],\"answer\":1,\"explanation\":\"Fixed costs do not fluctuate with output volume within a relevant range.\"},{\"question\":\"Under which inventory valuation method are the earliest received materials assumed to be issued first?\",\"options\":[\"LIFO\",\"FIFO (First-In, First-Out)\",\"Simple Average\",\"Base Stock\"],\"answer\":1,\"explanation\":\"FIFO issues the oldest inventory stock first; closing stock reflects recent purchase prices.\"},{\"question\":\"In a period of rising prices (inflation), which inventory valuation method results in higher reported net profit?\",\"options\":[\"FIFO\",\"LIFO\",\"Weighted Average\",\"Depleted Cost\"],\"answer\":0,\"explanation\":\"FIFO charges older, lower costs to production, resulting in higher reported gross profits.\"},{\"question\":\"Under which method is material issue price computed as: Total Cost of Stock \\/ Total Quantity of Stock?\",\"options\":[\"Simple Average Method\",\"Weighted Average Method\",\"FIFO\",\"LIFO\"],\"answer\":1,\"explanation\":\"The Weighted Average Method divides total stock value by total stock units.\"},{\"question\":\"What document is maintained inside the warehouse attached to the storage rack showing physical inventory quantities?\",\"options\":[\"Store Ledger\",\"Bin Card\",\"Purchase Order\",\"Journal Voucher\"],\"answer\":1,\"explanation\":\"Bin Cards track physical stock quantities and movements in the warehouse.\"},{\"question\":\"Who maintains the Store Ledger containing both quantities and monetary values of inventory?\",\"options\":[\"Storekeeper in the warehouse\",\"Cost \\/ Finance Accounting Department\",\"Auditor General\",\"Supplier\"],\"answer\":1,\"explanation\":\"The Cost\\/Accounts department maintains the monetary Store Ledger.\"},{\"question\":\"What is the optimum order quantity that minimizes total ordering costs and holding\\/carrying costs called?\",\"options\":[\"Safety Stock\",\"Economic Order Quantity (EOQ)\",\"Maximum Stock Level\",\"Danger Level\"],\"answer\":1,\"explanation\":\"EOQ is the optimal purchase quantity minimizing total inventory costs.\"},{\"question\":\"What inventory control classification categorizes items based on monetary value (A: High value 70%, B: Medium 20%, C: Low 10%)?\",\"options\":[\"ABC Analysis\",\"VED Analysis\",\"FIFO Analysis\",\"FSN Analysis\"],\"answer\":0,\"explanation\":\"ABC Analysis controls inventory based on the Pareto value principle.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(746, 149, 204, '4.8 Internal Control and Auditing Systems', '48-internal-control-and-auditing-systems-204', '<h3>1. Internal Control System (आन्तरिक नियन्त्रण)</h3>\n<p>The whole system of financial and operational controls established by management to conduct business smoothly, safeguard assets, ensure data accuracy, and prevent fraud/errors.</p>\n<ul>\n    <li><strong>Internal Check (आन्तरिक जाँच):</strong> Division of office work among staff such that no single employee handles a transaction from beginning to end without independent verification by another.</li>\n    <li><strong>Internal Audit (आन्तरिक लेखापरीक्षण):</strong> An independent appraisal activity established within the organization (e.g., NEA Internal Audit Directorate) to review financial operations, compliance, and internal controls on a continuous basis.</li>\n</ul>\n\n<h3>2. Statutory / Final Audit (अन्तिम लेखापरीक्षण)</h3>\n<p>An external, independent examination of books of accounts and financial statements conducted by qualified independent auditors (Auditor General of Nepal or designated Chartered Accountants) to express a professional opinion on whether the financial statements present a <strong>true and fair view</strong>.</p>', NULL, NULL, '[{\"question\":\"What is Internal Control in an organization?\",\"options\":[\"The overall system of financial and operational controls instituted by management to ensure orderly business, safeguard assets, and prevent fraud\",\"Government police inspection\",\"External audit checks\",\"Customer feedback survey\"],\"answer\":0,\"explanation\":\"Internal control is the comprehensive administrative and financial checks established by management.\"},{\"question\":\"What is the arrangement of office duties where the work of one employee is automatically and independently checked by another called?\",\"options\":[\"Internal Audit\",\"Internal Check (\\u0906\\u0928\\u094d\\u0924\\u0930\\u093f\\u0915 \\u091c\\u093e\\u0901\\u091a)\",\"Statutory Audit\",\"Management Audit\"],\"answer\":1,\"explanation\":\"Internal check distributes tasks so no single person handles a full transaction unchecked.\"},{\"question\":\"Who appoints and conducts the Internal Audit in public entities like Nepal Electricity Authority?\",\"options\":[\"Auditor General of Nepal\",\"NEA Management \\/ Internal Audit Directorate\",\"Parliament Public Accounts Committee\",\"Public Service Commission\"],\"answer\":1,\"explanation\":\"Internal Audit is established by NEA Management for continuous internal operational review.\"},{\"question\":\"What is the main objective of Statutory \\/ Final Audit (\\u0905\\u0928\\u094d\\u0924\\u093f\\u092e \\u0932\\u0947\\u0916\\u093e\\u092a\\u0930\\u0940\\u0915\\u094d\\u0937\\u0923)?\",\"options\":[\"To express an independent professional opinion on whether financial statements reflect a True and Fair view\",\"To hire and fire employees\",\"To prepare daily vouchers\",\"To collect unpaid electricity bills\"],\"answer\":0,\"explanation\":\"Final audit provides an independent opinion on the truth and fairness of financial statements.\"},{\"question\":\"Under the Constitution of Nepal, which authority is mandated to conduct final audit of NEA accounts?\",\"options\":[\"Ministry of Finance Internal Unit\",\"Auditor General of Nepal (Article 241)\",\"CIAA\",\"Commercial Banks\"],\"answer\":1,\"explanation\":\"The Auditor General conducts final audit of government bodies and majority-owned public enterprises.\"},{\"question\":\"What is an \\\"Audit Query \\/ Irregularity\\\" (\\u092c\\u0947\\u0930\\u0941\\u091c\\u0941) in public audit terminology?\",\"options\":[\"A transaction conducted without following prevailing laws, rules, or budget authorizations, or lacking required supporting documentation\",\"A normal cash payment\",\"A bank deposit\",\"An approved bonus\"],\"answer\":0,\"explanation\":\"Beruju is any transaction inconsistent with legal rules or lacking authorization.\"},{\"question\":\"Which committee of the Federal Parliament examines the annual report of the Auditor General regarding public enterprise irregularities?\",\"options\":[\"Finance Committee\",\"Public Accounts Committee (PAC \\/ \\u0938\\u093e\\u0930\\u094d\\u0935\\u091c\\u0928\\u093f\\u0915 \\u0932\\u0947\\u0916\\u093e \\u0938\\u092e\\u093f\\u0924\\u093f)\",\"State Affairs Committee\",\"Development Committee\"],\"answer\":1,\"explanation\":\"The Public Accounts Committee (PAC) reviews the Auditor General\'s reports.\"},{\"question\":\"What is a voucher in auditing?\",\"options\":[\"Any documentary evidence (receipt, bill, invoice, contract) supporting the accuracy of a recorded financial transaction\",\"A bank debit card\",\"A secret note\",\"An invitation card\"],\"answer\":0,\"explanation\":\"A voucher is the primary documentary proof supporting a transaction.\"},{\"question\":\"The process of examining documentary evidence in support of entries in the books of account is termed:\",\"options\":[\"Posting\",\"Vouching (\\u092d\\u094c\\u091a\\u0930 \\u091c\\u093e\\u0901\\u091a)\",\"Depreciation\",\"Reconciliation\"],\"answer\":1,\"explanation\":\"Vouching is regarded as the backbone of auditing.\"},{\"question\":\"What type of audit opinion is issued when the auditor finds the financial statements are true and fair in all material respects without reservations?\",\"options\":[\"Qualified Opinion\",\"Unqualified \\/ Clean Opinion\",\"Adverse Opinion\",\"Disclaimer of Opinion\"],\"answer\":1,\"explanation\":\"An Unqualified (Clean) Opinion indicates statements are reliable and compliant.\"}]', 'text', 1, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(747, 149, 204, '4.9 Banking Operations, Instruments and Guarantees', '49-banking-operations-instruments-and-guarantees-204', '<h3>1. Negotiable Instruments in Commercial Operations</h3>\n<ul>\n    <li><strong>Cheques:</strong> Bearer cheque, Order cheque, and Crossed cheque (Account Payee - most secure for official government/utility payments).</li>\n    <li><strong>Bank Draft:</strong> A financial instrument issued by a bank guaranteeing payment to the payee upon presentation.</li>\n    <li><strong>Letter of Credit (LC - प्रतित-पत्र):</strong> A financial commitment letter issued by a buyer\'s bank guaranteeing that payment will be made to the international seller upon delivery of compliant shipping documents (essential in NEA procurement of generators, turbines, cables).</li>\n</ul>\n\n<h3>2. Bank Guarantees (बैंक जमानी) in Public Utilities</h3>\n<ul>\n    <li><strong>Bid Bond (बोली जमानी):</strong> Guarantees that the bidder will not withdraw the tender during the bid validity period and will sign the contract if awarded (typically 2-3% of bid amount).</li>\n    <li><strong>Performance Bond (कार्यसम्पादन जमानत):</strong> Guarantees satisfactory performance and completion of the contract according to technical specifications (typically 5% of contract value).</li>\n    <li><strong>Advance Payment Guarantee:</strong> Submitted by contractor to claim mobilization advance.</li>\n    <li><strong>Release of Guarantee:</strong> Formal release letter issued upon successful contract completion and expiry of defect liability period (DLP).</li>\n</ul>', NULL, NULL, '[{\"question\":\"Which bank guarantee is submitted by contractors during tendering to ensure they will not withdraw their bid?\",\"options\":[\"Bid Bond (\\u092c\\u094b\\u0932\\u0940 \\u091c\\u092e\\u093e\\u0928\\u0940 - 2% to 3% of bid amount)\",\"Performance Bond\",\"Advance Payment Guarantee\",\"Retention Money Guarantee\"],\"answer\":0,\"explanation\":\"A Bid Bond prevents bidders from withdrawing tenders during bid validity.\"},{\"question\":\"Which bank guarantee is submitted by the winning contractor to ensure satisfactory performance and project completion?\",\"options\":[\"Bid Bond\",\"Performance Security \\/ Performance Bond (typically 5% of contract value)\",\"Customs Bond\",\"Travel Guarantee\"],\"answer\":1,\"explanation\":\"Performance Security guarantees faithful execution of contract specifications.\"},{\"question\":\"What financial instrument is issued by a buyer\'s bank guaranteeing payment to a foreign supplier upon presentation of specified shipping documents?\",\"options\":[\"Letter of Credit (LC \\/ \\u092a\\u094d\\u0930\\u0924\\u093f\\u0924-\\u092a\\u0924\\u094d\\u0930)\",\"Promissory Note\",\"Treasury Bill\",\"Cheque\"],\"answer\":0,\"explanation\":\"A Letter of Credit (LC) is standard in international procurement of equipment and parts.\"},{\"question\":\"Which type of cheque provides the highest payment security and can only be deposited directly into the payee\'s bank account?\",\"options\":[\"Bearer Cheque\",\"Order Cheque\",\"Account Payee Crossed Cheque\",\"Open Cheque\"],\"answer\":2,\"explanation\":\"Account Payee crossing restricts encashment solely to the designated payee bank account.\"},{\"question\":\"What is a Bank Draft?\",\"options\":[\"A negotiable instrument drawn by a bank upon itself or another branch, payable on demand to the named payee\",\"A loan application\",\"A debit card receipt\",\"An unapproved cheque\"],\"answer\":0,\"explanation\":\"A Bank Draft is a guaranteed payment instrument issued by a bank.\"},{\"question\":\"What guarantee allows a contractor to receive mobilization advance funds before commencing construction works?\",\"options\":[\"Bid Bond\",\"Advance Payment Guarantee (APG)\",\"Defect Liability Bond\",\"Customs Guarantee\"],\"answer\":1,\"explanation\":\"An Advance Payment Guarantee secures the mobilization funds released to contractors.\"},{\"question\":\"When is a Performance Guarantee formally released and returned to the contractor?\",\"options\":[\"Immediately upon contract signing\",\"Upon successful project handover, completion of work, and expiry of the Defect Liability Period (DLP)\",\"When 50% of the project is done\",\"It is never returned\"],\"answer\":1,\"explanation\":\"Performance guarantees are released upon final acceptance and defect liability expiry.\"},{\"question\":\"What is the standard validity period of a commercial bank cheque in Nepal from its date of issue?\",\"options\":[\"1 month\",\"3 months\",\"6 months\",\"1 year\"],\"answer\":2,\"explanation\":\"Under banking practices in Nepal, cheques remain valid for 6 months from the date of issue.\"},{\"question\":\"What happens when an account holder issues a cheque without having sufficient balance in their bank account?\",\"options\":[\"Cheque Bounce \\/ Dishonor of Cheque (punishable under Banking Offence and Punishment Act 2064)\",\"The bank pays from its reserve\",\"The cheque is framed\",\"The government covers the sum\"],\"answer\":0,\"explanation\":\"Dishonor of cheques due to insufficient funds is a crime under the Banking Offence Act.\"},{\"question\":\"Who operates the official expenditure bank accounts in NEA branch offices?\",\"options\":[\"Joint signature of the Office Chief and Finance\\/Account Officer\",\"Office peon alone\",\"Auditor General\",\"Managing Director alone\"],\"answer\":0,\"explanation\":\"Operational bank accounts require joint signatures of the Office Chief and Account Head.\"}]', 'text', 2, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(748, 149, 204, '4.10 Accounting & Auditing Assessment Quiz', '410-accounting-auditing-assessment-quiz-204', '[{\"question\":\"What is the primary statutory responsibility of Nepal Electricity Authority (NEA)?\",\"options\":[\"Generation, Transmission, and Distribution of electricity across Nepal\",\"Road construction\",\"Mining coal\",\"Operating domestic airlines\"],\"answer\":0,\"explanation\":\"NEA manages generation, transmission, and distribution of electricity throughout Nepal.\"},{\"question\":\"When was Nepal Electricity Authority (NEA) established in Bikram Sambat?\",\"options\":[\"2041 Poush 1\",\"2042 Bhadra 1\",\"2046 Baishakh 1\",\"2050 Chaitra 30\"],\"answer\":1,\"explanation\":\"NEA was formally founded on Bhadra 1, 2042 BS under the NEA Act 2041.\"},{\"question\":\"What is the full mark score of Phase 1 Written Examination for NEA Level 4?\",\"options\":[\"100 Marks\",\"200 Marks (Paper I: 100 + Paper II: 100)\",\"300 Marks\",\"50 Marks\"],\"answer\":1,\"explanation\":\"The written exam comprises 200 marks (Paper I 100 marks + Paper II 100 marks).\"},{\"question\":\"What is the pass mark percentage required in each paper of the written exam?\",\"options\":[\"32%\",\"40%\",\"50%\",\"60%\"],\"answer\":1,\"explanation\":\"40 marks out of 100 is the minimum pass mark for each paper.\"},{\"question\":\"Negative marking in Loksewa multiple choice objective questions is deducted at what rate for wrong answers?\",\"options\":[\"10%\",\"20% (0.2 marks per 1 mark question)\",\"33%\",\"50%\"],\"answer\":1,\"explanation\":\"20% marks are deducted for every incorrect MCQ answer.\"},{\"question\":\"What is the theoretical hydropower potential of Nepal?\",\"options\":[\"42,000 MW\",\"83,000 MW\",\"100,000 MW\",\"20,000 MW\"],\"answer\":1,\"explanation\":\"Theoretical hydropower potential is 83,000 MW (economically feasible ~42,000 MW).\"},{\"question\":\"Which constitutional organ conducts the recruitment exams for NEA Level 4 posts?\",\"options\":[\"Public Service Commission (Lok Sewa Aayog)\",\"Ministry of Energy\",\"Tribhuvan University\",\"Private Board\"],\"answer\":0,\"explanation\":\"The Public Service Commission conducts selection examinations for public enterprises.\"},{\"question\":\"What is the fundamental accounting equation?\",\"options\":[\"Assets = Liabilities + Capital\",\"Assets = Liabilities - Capital\",\"Capital = Liabilities + Revenues\",\"Profit = Assets + Cash\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Owner\'s Equity.\"},{\"question\":\"Under the Constitution of Nepal, how many fundamental rights are guaranteed in Part 3?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"31 Fundamental Rights are guaranteed from Article 16 to Article 46.\"},{\"question\":\"What penalty is levied on power theft under Electricity Theft Control Rules 2059?\",\"options\":[\"Assessed loss amount plus 100% fine (शतप्रतिशत जरिवाना)\",\"25% fine\",\"Written warning only\",\"No fine\"],\"answer\":0,\"explanation\":\"Assessed unmetered consumption is recovered along with a 100% fine.\"}]', NULL, NULL, '[{\"question\":\"What is the primary statutory responsibility of Nepal Electricity Authority (NEA)?\",\"options\":[\"Generation, Transmission, and Distribution of electricity across Nepal\",\"Road construction\",\"Mining coal\",\"Operating domestic airlines\"],\"answer\":0,\"explanation\":\"NEA manages generation, transmission, and distribution of electricity throughout Nepal.\"},{\"question\":\"When was Nepal Electricity Authority (NEA) established in Bikram Sambat?\",\"options\":[\"2041 Poush 1\",\"2042 Bhadra 1\",\"2046 Baishakh 1\",\"2050 Chaitra 30\"],\"answer\":1,\"explanation\":\"NEA was formally founded on Bhadra 1, 2042 BS under the NEA Act 2041.\"},{\"question\":\"What is the full mark score of Phase 1 Written Examination for NEA Level 4?\",\"options\":[\"100 Marks\",\"200 Marks (Paper I: 100 + Paper II: 100)\",\"300 Marks\",\"50 Marks\"],\"answer\":1,\"explanation\":\"The written exam comprises 200 marks (Paper I 100 marks + Paper II 100 marks).\"},{\"question\":\"What is the pass mark percentage required in each paper of the written exam?\",\"options\":[\"32%\",\"40%\",\"50%\",\"60%\"],\"answer\":1,\"explanation\":\"40 marks out of 100 is the minimum pass mark for each paper.\"},{\"question\":\"Negative marking in Loksewa multiple choice objective questions is deducted at what rate for wrong answers?\",\"options\":[\"10%\",\"20% (0.2 marks per 1 mark question)\",\"33%\",\"50%\"],\"answer\":1,\"explanation\":\"20% marks are deducted for every incorrect MCQ answer.\"},{\"question\":\"What is the theoretical hydropower potential of Nepal?\",\"options\":[\"42,000 MW\",\"83,000 MW\",\"100,000 MW\",\"20,000 MW\"],\"answer\":1,\"explanation\":\"Theoretical hydropower potential is 83,000 MW (economically feasible ~42,000 MW).\"},{\"question\":\"Which constitutional organ conducts the recruitment exams for NEA Level 4 posts?\",\"options\":[\"Public Service Commission (Lok Sewa Aayog)\",\"Ministry of Energy\",\"Tribhuvan University\",\"Private Board\"],\"answer\":0,\"explanation\":\"The Public Service Commission conducts selection examinations for public enterprises.\"},{\"question\":\"What is the fundamental accounting equation?\",\"options\":[\"Assets = Liabilities + Capital\",\"Assets = Liabilities - Capital\",\"Capital = Liabilities + Revenues\",\"Profit = Assets + Cash\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Owner\'s Equity.\"},{\"question\":\"Under the Constitution of Nepal, how many fundamental rights are guaranteed in Part 3?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"31 Fundamental Rights are guaranteed from Article 16 to Article 46.\"},{\"question\":\"What penalty is levied on power theft under Electricity Theft Control Rules 2059?\",\"options\":[\"Assessed loss amount plus 100% fine (\\u0936\\u0924\\u092a\\u094d\\u0930\\u0924\\u093f\\u0936\\u0924 \\u091c\\u0930\\u093f\\u0935\\u093e\\u0928\\u093e)\",\"25% fine\",\"Written warning only\",\"No fine\"],\"answer\":0,\"explanation\":\"Assessed unmetered consumption is recovered along with a 100% fine.\"}]', 'quiz', 3, 15, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(749, 150, 205, '5.1 Nepal Electricity Authority Act, 2041 (1984)', '51-nepal-electricity-authority-act-2041-1984-205', '<h3>1. Enactment, Scope and Objectives</h3>\n<p>The <em>Nepal Electricity Authority Act, 2041</em> was enacted to manage generation, transmission, and distribution of electricity throughout the Kingdom of Nepal in an efficient, safe, and easily accessible manner.</p>\n\n<h3>2. Capital and Corporate Character (Section 4 & 5)</h3>\n<ul>\n    <li>NEA is a body corporate with perpetual succession, an autonomous seal, power to acquire/dispose of property, and sue or be sued in its corporate name.</li>\n    <li>Authorized capital is determined by the Government of Nepal (GoN), with GoN holding equity shares.</li>\n</ul>\n\n<h3>3. Board of Directors (Section 8)</h3>\n<p>The Board of Directors consists of <strong>8 members</strong>:</p>\n<ol>\n    <li>Minister / State Minister for Energy, Water Resources and Irrigation - <strong>Chairperson</strong></li>\n    <li>Secretary, Ministry of Energy, Water Resources and Irrigation - Member</li>\n    <li>Secretary, Ministry of Finance - Member</li>\n    <li>One expert appointed from commerce, finance, or power sector - Member</li>\n    <li>Two individuals representing agriculture, industry, or consumer groups - Members</li>\n    <li>One representative from among non-governmental electricity producers / consumers - Member</li>\n    <li>Managing Director (MD) of NEA - <strong>Member Secretary</strong></li>\n</ol>\n\n<h3>4. Functions, Duties and Powers (Section 19 & 20)</h3>\n<ul>\n    <li>Formulate power development plans, construct generation plants, transmission lines, and sub-stations.</li>\n    <li>Supply electricity to consumers, fix electricity tariffs with approval of Electricity Regulatory Commission (ERC).</li>\n    <li>Maintain accounts in accordance with commercial principles and submit to Auditor General for audit.</li>\n</ul>', NULL, NULL, '[{\"question\":\"Under which Act of Parliament was Nepal Electricity Authority (NEA) established?\",\"options\":[\"Electricity Act 2049\",\"Nepal Electricity Authority Act, 2041 (1984)\",\"Company Act 2063\",\"Public Enterprise Act 2030\"],\"answer\":1,\"explanation\":\"NEA was established under the statutory Nepal Electricity Authority Act 2041.\"},{\"question\":\"Who is the ex-officio Chairperson of the Board of Directors of NEA under Section 8 of the Act?\",\"options\":[\"Managing Director of NEA\",\"Minister or State Minister for Energy, Water Resources and Irrigation\",\"Secretary of Energy\",\"Finance Secretary\"],\"answer\":1,\"explanation\":\"The Minister \\/ State Minister for Energy serves as Board Chairperson.\"},{\"question\":\"How many members comprise the Board of Directors of Nepal Electricity Authority?\",\"options\":[\"5 members\",\"7 members\",\"8 members\",\"11 members\"],\"answer\":2,\"explanation\":\"Section 8 of the Act specifies an 8-member Board of Directors.\"},{\"question\":\"Who serves as the Member Secretary of the Board of Directors of NEA?\",\"options\":[\"Energy Joint Secretary\",\"Managing Director of NEA\",\"Chief Accountant of NEA\",\"Legal Officer\"],\"answer\":1,\"explanation\":\"The Managing Director of NEA serves as Member Secretary.\"},{\"question\":\"What is the corporate legal character of NEA under Section 5 of the NEA Act 2041?\",\"options\":[\"An autonomous body corporate with perpetual succession, its own seal, and power to sue and be sued\",\"A temporary government department\",\"A private partnership firm\",\"A cooperative\"],\"answer\":0,\"explanation\":\"NEA is an autonomous body corporate with perpetual succession and common seal.\"},{\"question\":\"What are the three core statutory functions of NEA under the Act?\",\"options\":[\"Generation, Transmission, and Distribution of electricity\",\"Mining, refining, and selling oil\",\"Constructing highways and railways\",\"Collecting income tax\"],\"answer\":0,\"explanation\":\"NEA\'s primary mandates are Generation, Transmission, and Distribution of power.\"},{\"question\":\"Who determines and provides the authorized equity capital of Nepal Electricity Authority?\",\"options\":[\"Private Banks\",\"Government of Nepal (GoN)\",\"Foreign Investors alone\",\"Consumers\"],\"answer\":1,\"explanation\":\"Authorized capital is determined and held by the Government of Nepal.\"},{\"question\":\"Under the NEA Act, in accordance with what principles must NEA maintain its accounts?\",\"options\":[\"Government cash single entry\",\"Commercial double-entry accounting principles\",\"Informal single entry\",\"No accounts needed\"],\"answer\":1,\"explanation\":\"NEA maintains accounts based on commercial principles and international standards.\"},{\"question\":\"Under Section 28 of the Act, which authority is empowered to audit NEA\'s annual accounts?\",\"options\":[\"Auditor General of Nepal\",\"Private Foreign Company\",\"Local Ward Office\",\"Energy Department\"],\"answer\":0,\"explanation\":\"Accounts are audited annually by the Auditor General of Nepal.\"},{\"question\":\"Who appoints the Managing Director of Nepal Electricity Authority?\",\"options\":[\"NEA Employees Union\",\"Government of Nepal (Cabinet \\/ Council of Ministers)\",\"Auditor General\",\"Public Service Commission\"],\"answer\":1,\"explanation\":\"The Government of Nepal (Cabinet) appoints the Managing Director.\"}]', 'text', 1, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(750, 150, 205, '5.2 NEA Employee Service Terms and Conditions Bylaws', '52-nea-employee-service-terms-and-conditions-bylaws-205', '<h3>Key Provisions of NEA Employees Service Bylaws (कर्मचारी सेवा, शर्त विनियमावली)</h3>\n\n<h4>1. Transfer and Promotion (सरुवा, बढुवा तथा पदस्थापन)</h4>\n<ul>\n    <li><strong>Levels:</strong> Level 1 to Level 12 (Level 1-5 Non-Officer / Assistant, Level 6-10 Officer, Level 11-12 Executive Director / DMD).</li>\n    <li><strong>Transfer Principles:</strong> Conducted periodically based on geographical classification of stations (A, B, C, D classes) ensuring staff gain experience across geographic regions.</li>\n    <li><strong>Promotion Evaluation:</strong> Based on Performance Appraisal (कार्यसम्पादन मूल्याङ्कन - 40 marks), Seniority (ज्येष्ठता - 30 marks), Academic Qualifications (शैक्षिक योग्यता - 12 marks), Geographical Service in remote stations (भौगोलिक अंक - 16 marks), and Training (2 marks).</li>\n</ul>\n\n<h4>2. Leave Regulations (बिदा सम्बन्धी व्यवस्था)</h4>\n<ul>\n    <li>Casual Leave (पर्व/भैपरी बिदा): 12 days annually with full pay.</li>\n    <li>Home Leave (घर बिदा): Earned at 1 day for every 10 days worked (up to 30 days/year); can be accumulated up to 180 days for encashment upon retirement.</li>\n    <li>Sick Leave (बिरामी बिदा): 12 days per year with full pay; accumulable without limit.</li>\n    <li>Maternity Leave: 98 days for female employees; Paternity Leave: 15 days for male employees.</li>\n    <li>Study Leave and Extra-ordinary (Unpaid) Leave provisions.</li>\n</ul>\n\n<h4>3. Discipline, Conduct & Penalties (अनुशासन, आचरण र सजाय)</h4>\n<ul>\n    <li><strong>Minor Penalties:</strong> Censure (नसिहत), withholding of annual grade increment for up to 2 years, withholding of promotion for up to 2 years.</li>\n    <li><strong>Major Penalties:</strong> Demotion to a lower post/pay scale, removal from service (eligible for future employment), dismissal from service (disqualified from future government/public employment).</li>\n</ul>\n\n<h4>4. Salary, Allowances and Retirement Benefits</h4>\n<ul>\n    <li>Monthly salary, dearness allowance, Dashain allowance (1 month basic pay), local remote area allowance.</li>\n    <li>Pension (निवृत्तिभरण), Gratuity (उपदान), Provident Fund (EPF), Medical Treatment Facility (उपचार सुविधा), and Accidental Insurance.</li>\n</ul>', NULL, NULL, '[{\"question\":\"How many levels (\\u0924\\u0939) of employee posts are structured in Nepal Electricity Authority?\",\"options\":[\"Level 1 to Level 5\",\"Level 1 to Level 10\",\"Level 1 to Level 12\",\"Level 1 to Level 15\"],\"answer\":2,\"explanation\":\"NEA has positions from Level 1 (Helper\\/Assistant) up to Level 12 (Deputy Managing Director).\"},{\"question\":\"Level 4 in NEA (e.g. Assistant Accountant \\/ Admin Assistant) belongs to which service category?\",\"options\":[\"Officer Class III\",\"Non-Officer \\/ Assistant Level (\\u0938\\u0939\\u093e\\u092f\\u0915 \\u0938\\u094d\\u0924\\u0930)\",\"Executive Level\",\"Special Class\"],\"answer\":1,\"explanation\":\"Levels 1 through 5 belong to the Assistant\\/Non-Officer cadre.\"},{\"question\":\"How many days of paid Casual \\/ Festival Leave (\\u092a\\u0930\\u094d\\u0935\\/\\u092d\\u0948\\u092a\\u0930\\u0940 \\u092c\\u093f\\u0926\\u093e) are granted to NEA employees annually?\",\"options\":[\"6 days\",\"12 days\",\"18 days\",\"30 days\"],\"answer\":1,\"explanation\":\"12 days of paid casual\\/festival leave are provided per calendar year.\"},{\"question\":\"At what rate is Home Leave (\\u0918\\u0930 \\u092c\\u093f\\u0926\\u093e) accumulated by permanent NEA employees?\",\"options\":[\"1 day for every 10 days worked (up to 30 days per year)\",\"1 day per month\",\"15 days per year\",\"45 days per year\"],\"answer\":0,\"explanation\":\"Home leave is earned at 1 day for every 10 days worked (max 30 days\\/yr, accumulable up to 180 days).\"},{\"question\":\"How many days of paid Sick Leave (\\u092c\\u093f\\u0930\\u093e\\u092e\\u0940 \\u092c\\u093f\\u0926\\u093e) are entitled to NEA employees per year?\",\"options\":[\"6 days\",\"12 days\",\"20 days\",\"30 days\"],\"answer\":1,\"explanation\":\"12 days of paid sick leave are provided annually, which can be accumulated indefinitely.\"},{\"question\":\"What is the duration of paid Maternity Leave entitled to female employees in NEA?\",\"options\":[\"60 days\",\"90 days\",\"98 days\",\"120 days\"],\"answer\":2,\"explanation\":\"98 days of maternity leave are provided in accordance with labor standards.\"},{\"question\":\"Which of the following is classified as a Minor Penalty (\\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u0938\\u091c\\u093e\\u092f) under NEA Employee Bylaws?\",\"options\":[\"Censure (\\u0928\\u0938\\u093f\\u0939\\u0924) or withholding grade increment for up to 2 years\",\"Dismissal from service\",\"Demotion to lower rank\",\"Compulsory retirement\"],\"answer\":0,\"explanation\":\"Censure and withholding of annual increments\\/promotions are Minor Penalties.\"},{\"question\":\"What is the major difference between \\\"Removal from Service\\\" and \\\"Dismissal from Service\\\"?\",\"options\":[\"No difference\",\"Removal allows eligibility for future government employment, whereas Dismissal permanently disqualifies from future public service\",\"Dismissal pays full pension\",\"Removal has no formal notice\"],\"answer\":1,\"explanation\":\"Dismissal disqualifies the employee from all future public employment.\"},{\"question\":\"What festival allowance is provided to permanent NEA employees during Dashain?\",\"options\":[\"Rs. 5,000 flat\",\"One month basic salary\",\"Two months salary\",\"50% of basic pay\"],\"answer\":1,\"explanation\":\"One month basic salary is provided as Dashain\\/Festival allowance annually.\"},{\"question\":\"What is the mandatory retirement age for permanent employees in Nepal Electricity Authority?\",\"options\":[\"55 years\",\"58 years\",\"60 years\",\"65 years\"],\"answer\":1,\"explanation\":\"The standard compulsory retirement age is 58 years (or 30 years service rule as applicable).\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38');
INSERT INTO `lessons` (`id`, `module_id`, `chapter_id`, `title`, `slug`, `content`, `video_url`, `attachment_path`, `quiz_questions`, `type`, `order`, `duration_minutes`, `is_published`, `created_at`, `updated_at`) VALUES
(751, 150, 205, '5.3 NEA Financial Administration Bylaws', '53-nea-financial-administration-bylaws-205', '<h3>Core Provisions of NEA Financial Administration Bylaws (आर्थिक प्रशासन विनियमावली)</h3>\n\n<h4>1. Central Fund and Bank Accounts (केन्द्रीय कोष तथा खाता)</h4>\n<ul>\n    <li>Central Fund managed by Central Accounts Department at NEA Head Office.</li>\n    <li>Revenue collection accounts (No-frills deposit accounts where collection is automatically transferred to Central Pool Account).</li>\n    <li>Operating expenditure accounts operated jointly by Chief of Office (Account Head) and Finance Officer.</li>\n</ul>\n\n<h4>2. Budget Authorization & Expenditure Release</h4>\n<ul>\n    <li>Annual budget approved by NEA Board. Budget release occurs quarterly upon submission of expenditure statements and progress reports.</li>\n    <li>Re-appropriation (रकम फिर्ता/रकमान्तर): Permitted within stipulated limits and authorized by designated management authorities.</li>\n</ul>\n\n<h4>3. Advances Management (पेश्कीका प्रकार तथा फर्छौट)</h4>\n<ul>\n    <li>Types: Institutional / Operational advance, Employee personal traveling advance (TA/DA advance), Letter of Credit advance, Contractor mobilization advance.</li>\n    <li>Advance clearance (फर्छौट): Must be cleared within 15 to 30 days of activity completion; failure leads to deductions from salary with penal interest.</li>\n</ul>\n\n<h4>4. Audit Queries / Irregularities (बेरुजु र बेरुजु फर्छौट)</h4>\n<ul>\n    <li><strong>Beruju Classification:</strong> Regularizable (नियमित गर्ने), Recoverable (असुली गर्ने), and Advances Remaining (पेश्की बाँकी).</li>\n    <li>Settlement process: Submitting missing evidence/bills, depositing recovered sums into revenue accounts, seeking Board/Internal audit clearance.</li>\n</ul>', NULL, NULL, '[{\"question\":\"Who manages the Central Fund (\\u0915\\u0947\\u0928\\u094d\\u0926\\u094d\\u0930\\u0940\\u092f \\u0915\\u094b\\u0937) of Nepal Electricity Authority?\",\"options\":[\"Branch Manager alone\",\"Central Accounts Department at NEA Head Office\",\"Internal Audit\",\"Trade Union\"],\"answer\":1,\"explanation\":\"The Central Accounts Department manages the consolidated central revenue and treasury pool.\"},{\"question\":\"Within how many days of completion of the assigned official work or tour must an Advance (\\u092a\\u0947\\u0936\\u094d\\u0915\\u0940) be cleared?\",\"options\":[\"7 days\",\"15 to 30 days\",\"6 months\",\"End of fiscal year\"],\"answer\":1,\"explanation\":\"Advances must be settled within 15 to 30 days; overdue advances face deductions with penalties.\"},{\"question\":\"What are the three statutory categories of Audit Irregularities (\\u092c\\u0947\\u0930\\u0941\\u091c\\u0941)?\",\"options\":[\"Regularizable (\\u0928\\u093f\\u092f\\u092e\\u093f\\u0924 \\u0917\\u0930\\u094d\\u0928\\u0947), Recoverable (\\u0905\\u0938\\u0941\\u0932\\u0940 \\u0917\\u0930\\u094d\\u0928\\u0947), and Advances Remaining (\\u092a\\u0947\\u0936\\u094d\\u0915\\u0940 \\u092c\\u093e\\u0901\\u0915\\u0940)\",\"Cash, Bank, Ledger\",\"Small, Medium, Big\",\"Local, Provincial, Federal\"],\"answer\":0,\"explanation\":\"Beruju is categorized into Regularizable, Recoverable, and Unsettled Advances.\"},{\"question\":\"What is Re-appropriation (\\u0930\\u0915\\u092e\\u093e\\u0928\\u094d\\u0924\\u0930) in financial budget administration?\",\"options\":[\"Transferring unspent budget from one approved budget sub-head to another budget sub-head within authorized limits\",\"Stealing budget funds\",\"Cancelling total budget\",\"Opening a new bank account\"],\"answer\":0,\"explanation\":\"Re-appropriation transfers budget between authorized headings with proper sanction.\"},{\"question\":\"Who is responsible for the custody, record maintenance, and annual physical verification of assets in an NEA office?\",\"options\":[\"Storekeeper and Office Chief ( \\u091c\\u093f\\u0928\\u094d\\u0938\\u0940 \\u0938\\u0902\\u0930\\u0915\\u094d\\u0937\\u0923 \\u0924\\u0925\\u093e \\u092c\\u0930\\u092c\\u0941\\u091d\\u093e\\u0930\\u0925)\",\"Meter reader alone\",\"Bank teller\",\"Outside customer\"],\"answer\":0,\"explanation\":\"The Office Chief and Store In-charge ensure custody and asset physical verification.\"},{\"question\":\"What procedure is required when an employee holding custody of office assets\\/files is transferred to another station?\",\"options\":[\"Handover and Takeover (\\u092c\\u0930\\u092c\\u0941\\u091d\\u093e\\u0930\\u0925) with formal documentation\",\"Throwing old files\",\"Taking assets home\",\"Leaving without notice\"],\"answer\":0,\"explanation\":\"Formal Barbujharath (handover\\/takeover) is mandatory upon transfer.\"},{\"question\":\"What is the ceiling for direct procurement of goods without calling competitive quotations in public financial rules?\",\"options\":[\"Up to Rs. 25,000\",\"Up to Rs. 500,000 (as prescribed in Public Procurement Act\\/Rules)\",\"Up to Rs. 1 Crore\",\"Unlimited\"],\"answer\":1,\"explanation\":\"Procurement thresholds are governed by the Public Procurement Act and NEA bylaws.\"},{\"question\":\"What type of tender is mandatory for mega procurement works exceeding statutory thresholds?\",\"options\":[\"Direct purchase\",\"Open Competitive Bidding (National \\/ International Competitive Bidding - NCB \\/ ICB)\",\"Oral agreement\",\"Sealed quotations without publication\"],\"answer\":1,\"explanation\":\"Open competitive bidding with public notice is mandatory for major contracts.\"},{\"question\":\"What is the minimum publication notice period for a National Competitive Bidding (NCB) tender in national daily newspapers?\",\"options\":[\"7 days\",\"15 days\",\"30 days\",\"60 days\"],\"answer\":2,\"explanation\":\"NCB tenders generally require a minimum 30-day notice period in national daily newspapers.\"},{\"question\":\"What rate of earnest money deposit (Bid Security \\/ Bid Bond) is required from bidders in public procurement?\",\"options\":[\"0.5%\",\"2% to 3% of the estimated contract price\",\"10%\",\"25%\"],\"answer\":1,\"explanation\":\"Bid security is typically 2% to 3% of the estimated procurement cost.\"}]', 'text', 3, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(752, 150, 206, '5.4 Electricity Theft Control Rules, 2059 (2002)', '54-electricity-theft-control-rules-2059-2002-206', '<h3>Key Provisions of Electricity Leakage / Theft Control Rules, 2059 (विद्युत चोरी नियन्त्रण नियमावली)</h3>\n\n<h4>1. Acts Constituting Electricity Theft (विद्युत चोरी मानिने अवस्था)</h4>\n<ul>\n    <li>Direct tapping/hooking from distribution lines without a registered meter.</li>\n    <li>Tampering with meter seals, gear mechanisms, or CT/PT connections to slow down or bypass meter recording.</li>\n    <li>Using artificial magnets, electronic bypass gadgets, or reversing meter connections.</li>\n    <li>Supplying electricity to unauthorized third parties or using domestic category connection for commercial/industrial purposes without approval.</li>\n</ul>\n\n<h4>2. Loss Assessment and Unit Determination (युनिट निर्धारण प्रक्रिया)</h4>\n<ul>\n    <li>Assessed on the basis of connected load (KW) multiplied by operating hours per day over a period up to <strong>6 months to 1 year</strong>.</li>\n    <li>Assessment Formula: <code>Assessment Units = Total Connected Load (KW) * Daily Usage Hours * Days * Utilization Factor</code>.</li>\n</ul>\n\n<h4>3. Disconnection & Reconnection</h4>\n<ul>\n    <li>Power supply disconnected immediately upon detecting theft.</li>\n    <li>Reconnection permitted only after payment of total assessed electricity charges + <strong>100% fine/penalty (शतप्रतिशत जरिवाना)</strong> + reconnection fees.</li>\n</ul>\n\n<h4>4. Informant Rewards (पुरस्कार सम्बन्धी व्यवस्था)</h4>\n<ul>\n    <li>Individuals providing concrete information leading to detection and recovery of power theft are eligible for cash reward (up to 20% of recovered fine/amount as per regulations).</li>\n</ul>', NULL, NULL, '[{\"question\":\"Under Electricity Theft Control Rules 2059, which of the following constitutes electricity theft?\",\"options\":[\"Direct hooking \\/ tapping into distribution lines without an authorized meter\",\"Paying bills on time\",\"Requesting a meter test\",\"Using LED light bulbs\"],\"answer\":0,\"explanation\":\"Direct hooking or tampering with meter seals constitutes power theft.\"},{\"question\":\"What penalty is levied upon a consumer caught stealing electricity under Electricity Theft Control Rules 2059?\",\"options\":[\"Total assessed unmetered electricity charge plus 100% fine (\\u0936\\u0924\\u092a\\u094d\\u0930\\u0924\\u093f\\u0936\\u0924 \\u091c\\u0930\\u093f\\u0935\\u093e\\u0928\\u093e)\",\"25% fine\",\"Only written warning\",\"No penalty if bill is paid\"],\"answer\":0,\"explanation\":\"The full assessed consumption amount is recovered along with a 100% penalty (double amount).\"},{\"question\":\"How is the quantity of stolen electricity units assessed when tampering or direct tapping is detected?\",\"options\":[\"Total connected electrical load (KW) multiplied by standard operating hours over a 6-month to 1-year period\",\"Random guess\",\"Minimum 10 units\",\"Zero units\"],\"answer\":0,\"explanation\":\"Assessment is based on connected load capacity, daily hours, and period of unauthorized use.\"},{\"question\":\"What action is taken on the electrical power line immediately upon detecting power theft?\",\"options\":[\"Immediate line disconnection (\\u0932\\u093e\\u0907\\u0928 \\u0915\\u093e\\u091f\\u094d\\u0928\\u0947)\",\"Increasing voltage\",\"Giving free power\",\"Installing a bigger fuse\"],\"answer\":0,\"explanation\":\"The supply line is disconnected immediately to stop unauthorized usage.\"},{\"question\":\"When can a disconnected power line be reconnected after electricity theft is detected?\",\"options\":[\"Only after full payment of assessed loss units, 100% fine, and reconnection charges\",\"After 24 hours automatically\",\"Upon oral request\",\"Never\"],\"answer\":0,\"explanation\":\"Reconnection is granted only upon full clearance of assessed dues and penalties.\"},{\"question\":\"What reward is provided to informants providing actionable information leading to the apprehension of power theft?\",\"options\":[\"Up to 20% of the recovered penalty\\/fine amount\",\"Gold medal\",\"Free electricity for lifetime\",\"Government job\"],\"answer\":0,\"explanation\":\"The rules provide a cash incentive reward (up to 20% of recovered penalty) to informants.\"},{\"question\":\"Who has the authority to inspect premises and seize electrical equipment used for power theft?\",\"options\":[\"Authorized NEA Inspection Squad \\/ Officer and accompanying Police personnel\",\"Any neighbor\",\"Local school teacher\",\"Private contractor\"],\"answer\":0,\"explanation\":\"Authorized NEA inspection officers accompanied by police conduct enforcement raids.\"},{\"question\":\"Tampering with CT\\/PT meter seals and test links in industrial connections is classified as:\",\"options\":[\"Commercial innovation\",\"Severe electrical theft and fraud subject to criminal prosecution\",\"Routine maintenance\",\"Power saving technique\"],\"answer\":1,\"explanation\":\"CT\\/PT meter tampering is severe industrial power theft resulting in heavy penalties.\"},{\"question\":\"Supplying electricity to an unauthorized third party outside designated premises without NEA permission is:\",\"options\":[\"Permitted charity\",\"A violation of supply regulations subject to penalty and line cut\",\"Encouraged\",\"Tax exempt\"],\"answer\":1,\"explanation\":\"Unauthorized sub-distribution is strictly prohibited under distribution rules.\"},{\"question\":\"Under which Act are cases of electrical theft prosecuted?\",\"options\":[\"Electricity Theft Control Act, 2058 (2002) and Rules 2059\",\"Forest Act\",\"Land Reform Act\",\"Motor Vehicle Act\"],\"answer\":0,\"explanation\":\"Electricity Theft Control Act 2058 and Rules 2059 govern theft offenses and penalties.\"}]', 'text', 1, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(753, 150, 206, '5.5 Electricity Distribution Bylaws, 2078 & Tariff Regulations', '55-electricity-distribution-bylaws-2078-tariff-regulations-206', '<h3>Provisions of Electricity Distribution Bylaws, 2078 (विद्युत वितरण विनियमावली)</h3>\n\n<h4>1. New Customer Connection (नयाँ ग्राहक कायम गर्ने)</h4>\n<ul>\n    <li>Submission of application form, citizenship certificate, land ownership certificate (Lalpurja) or lease agreement, house completion certificate/recommendation.</li>\n    <li>Feasibility survey, deposit of security deposit (धरौटी) and service connection fee, installation of sealed meter.</li>\n</ul>\n\n<h4>2. Meter Reading and Testing (मिटर जाँच र रिडिङ्ग)</h4>\n<ul>\n    <li>Conducted by designated meter readers according to monthly fixed reading cycles (Group A, B, C, D).</li>\n    <li>Testing of defective or fast/slow meters upon customer application using calibrated test benches.</li>\n</ul>\n\n<h4>3. Billing During Locked Premises (तालाबन्दीमा हुने बिलिङ्ग)</h4>\n<ul>\n    <li>If meter premises are locked during reading cycle, minimum monthly service charge / average consumption bill is generated. Adjustment occurs on subsequent physical reading.</li>\n</ul>\n\n<h4>4. Tariff Collection & Rebate / Penalty Structure</h4>\n<ul>\n    <li>Payment within 1st week of bill generation: <strong>Rebate / Discount (e.g., 2-3% discount)</strong>.</li>\n    <li>Payment within due date (e.g., up to 22nd day): Net bill amount without penalty.</li>\n    <li>Delayed payment beyond due date: Graded fine/surcharge (5% penalty up to 30 days, 10% penalty up to 40 days, 25% penalty beyond 40 days).</li>\n    <li>Supply disconnected (Blacklisting & Line Cut) if unpaid beyond 60 days.</li>\n</ul>', NULL, NULL, '[{\"question\":\"Under Electricity Distribution Bylaws 2078, what documents are required for a new domestic customer connection?\",\"options\":[\"Application form, citizenship certificate, land ownership certificate (Lalpurja) or house completion certificate\",\"Passport only\",\"No documents needed\",\"Bank loan agreement only\"],\"answer\":0,\"explanation\":\"Citizenship and proof of land\\/house ownership or authorized tenancy are required.\"},{\"question\":\"How is billing handled when a customer meter premise is locked during the monthly reading cycle?\",\"options\":[\"Minimum monthly charge \\/ average historical consumption is billed, with adjustments made on subsequent actual reading\",\"Free power for that month\",\"Line cut immediately\",\"Account deleted\"],\"answer\":0,\"explanation\":\"Average\\/minimum billing is recorded during locked premises and adjusted later.\"},{\"question\":\"What rebate\\/discount is provided to electricity consumers who pay their bills within the first week of bill generation?\",\"options\":[\"2% to 3% rebate \\/ discount on energy charges\",\"50% discount\",\"No discount\",\"Rs. 1,000 cash back\"],\"answer\":0,\"explanation\":\"NEA offers an early payment rebate (e.g., 2% discount within first 7 days).\"},{\"question\":\"What happens if a consumer delays paying the electricity bill beyond the normal due date (e.g., beyond 22-30 days)?\",\"options\":[\"Graded surcharge\\/penalty (5%, 10%, 25%) is added to the bill\",\"The bill is waived\",\"Interest is paid to the consumer\",\"The bill amount decreases\"],\"answer\":0,\"explanation\":\"Progressive penalty surcharges (5% to 25%) are applied for delayed bill settlements.\"},{\"question\":\"After how many days of continuous non-payment of electricity bills is the consumer line subject to disconnection?\",\"options\":[\"15 days\",\"30 days\",\"60 days (2 months overdue)\",\"1 year\"],\"answer\":2,\"explanation\":\"Electricity lines are disconnected after 60 days of non-payment of dues.\"},{\"question\":\"What fee is deposited by a consumer as financial security before a new meter is energized?\",\"options\":[\"Security Deposit (\\u0927\\u0930\\u094c\\u091f\\u0940)\",\"Advance tax\",\"Donation\",\"Customs duty\"],\"answer\":0,\"explanation\":\"A refundable Security Deposit is collected from consumers upon new connection.\"},{\"question\":\"What device is installed by NEA to record electricity consumption at customer premises?\",\"options\":[\"Energy Meter (Single-phase \\/ Three-phase Smart \\/ Electronic Meter)\",\"Transformer\",\"Inverter\",\"Capacitor bank\"],\"answer\":0,\"explanation\":\"Electronic\\/Smart Energy Meters accurately record kilowatt-hour (kWh) units.\"},{\"question\":\"What is the standard unit of measurement of electrical energy consumption on consumer bills?\",\"options\":[\"Kilowatt-hour (kWh \\/ 1 Unit = 1,000 Watt-hours)\",\"Volt\",\"Ampere\",\"Horsepower\"],\"answer\":0,\"explanation\":\"1 Unit of electricity equals 1 Kilowatt-Hour (1 kWh).\"},{\"question\":\"What tariff system charges different electricity rates based on peak, off-peak, and normal hours of the day?\",\"options\":[\"Time of Day (TOD) Tariff\",\"Flat rate tariff\",\"Free tariff\",\"Emergency tariff\"],\"answer\":0,\"explanation\":\"TOD (Time-of-Day) metering charges higher rates during peak evening hours.\"},{\"question\":\"When is a customer electricity ledger record permanently cancelled (\\u0932\\u0917\\u0924 \\u0916\\u093e\\u0930\\u0947\\u091c)?\",\"options\":[\"Upon customer request, building demolition, or prolonged non-payment and non-reconnection after blacklisting\",\"Every year\",\"When meter reader changes\",\"During monsoon\"],\"answer\":0,\"explanation\":\"Customer registration is cancelled upon formal request or failure to settle blacklisted dues.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(754, 150, 207, '5.6 Retirement Funds: EPF and Citizen Investment Trust (CIT)', '56-retirement-funds-epf-and-citizen-investment-trust-cit-207', '<h3>1. Employees Provident Fund - EPF (कर्मचारी सञ्चय कोष)</h3>\n<ul>\n    <li><strong>Mandatory Contribution:</strong> 10% deducted from employee monthly basic salary + 10% matching contribution by NEA = <strong>Total 20%</strong> deposited monthly in EPF.</li>\n    <li><strong>Benefits:</strong> Annual compounding interest, special loan facilities (house loan, education loan), medical insurance support, funeral grants, and lump-sum payment upon retirement.</li>\n</ul>\n\n<h3>2. Citizen Investment Trust - CIT (नागरिक लगानी कोष)</h3>\n<ul>\n    <li>Voluntary / mandatory retirement schemes, gratuity fund management, and defined-benefit pension schemes.</li>\n    <li>Provides income tax deduction benefits up to prescribed statutory limits (e.g., 1/3 of taxable income or Rs. 300,000 / Rs. 500,000 as per prevailing Finance Act).</li>\n</ul>', NULL, NULL, '[{\"question\":\"What percentage is mandatorily deducted from an NEA permanent employee\'s monthly basic salary for the Employees Provident Fund (EPF)?\",\"options\":[\"5%\",\"10%\",\"15%\",\"20%\"],\"answer\":1,\"explanation\":\"10% is deducted from basic pay, matched by 10% from NEA, totaling 20% deposited monthly in EPF.\"},{\"question\":\"What matching contribution is made by Nepal Electricity Authority towards employee EPF monthly?\",\"options\":[\"5%\",\"10%\",\"15%\",\"20%\"],\"answer\":1,\"explanation\":\"NEA provides an equal 10% matching employer contribution.\"},{\"question\":\"What is the full form of CIT in Nepal\'s retirement financial institutions?\",\"options\":[\"Citizen Investment Trust (\\u0928\\u093e\\u0917\\u0930\\u093f\\u0915 \\u0932\\u0917\\u093e\\u0928\\u0940 \\u0915\\u094b\\u0937)\",\"Central Income Treasury\",\"Commercial Insurance Trust\",\"Credit Information Trade\"],\"answer\":0,\"explanation\":\"CIT stands for Citizen Investment Trust (Nagarik Lagani Kosh).\"},{\"question\":\"What is the maximum allowable income tax deduction for contributions to EPF \\/ CIT and Social Security under prevailing tax rules?\",\"options\":[\"Rs. 100,000\",\"Rs. 300,000 or 1\\/3rd of taxable income (whichever is lower, or up to 5 Lakhs for SSF)\",\"Rs. 1,000,000\",\"Unlimited\"],\"answer\":1,\"explanation\":\"Tax deductions apply up to 1\\/3rd of assessable income or statutory ceilings (Rs. 300,000 \\/ 500,000).\"},{\"question\":\"What lump-sum retirement benefit is paid to employees who do not qualify for pension based on their total service years?\",\"options\":[\"Gratuity (\\u0909\\u092a\\u0926\\u093e\\u0928)\",\"Overtime pay\",\"Leave encashment only\",\"Travel grant\"],\"answer\":0,\"explanation\":\"Gratuity is a lump-sum separation payment calculated based on service duration.\"},{\"question\":\"How many years of minimum permanent service in NEA is generally required to be eligible for regular monthly Pension?\",\"options\":[\"10 years\",\"15 years\",\"20 years\",\"25 years\"],\"answer\":2,\"explanation\":\"20 years of continuous permanent service is standard for defined-benefit pension eligibility.\"},{\"question\":\"What financial assistance loans are available to contributors from EPF and CIT?\",\"options\":[\"Special housing loans, education loans, and 80-90% contributor advance loans\",\"Stock market speculation loans\",\"Gambling loans\",\"Foreign visa loans\"],\"answer\":0,\"explanation\":\"Contributors can access subsidized housing, education, and special fund loans.\"},{\"question\":\"Under contributory pension systems, what happens to accumulated retirement fund balances upon retirement?\",\"options\":[\"Paid as monthly annuity or lump-sum withdrawal with interest\",\"Donated to government\",\"Forfeited\",\"Divided among coworkers\"],\"answer\":0,\"explanation\":\"Accumulated fund balances with interest are paid out or converted to monthly annuities.\"},{\"question\":\"Is interest earned on EPF and CIT deposits credited annually and compounded?\",\"options\":[\"Yes, credited annually and compounded into contributor principal accounts\",\"No interest is paid\",\"Interest is paid only in cash\",\"Interest is deducted\"],\"answer\":0,\"explanation\":\"EPF and CIT compound interest annually into the employee account.\"},{\"question\":\"What death insurance\\/funeral grant is provided by EPF to the families of deceased active contributors?\",\"options\":[\"Funeral and accidental term insurance grants as per EPF regulations\",\"No grant\",\"Salary for 10 years\",\"House handover\"],\"answer\":0,\"explanation\":\"EPF provides statutory accidental death insurance and funeral support grants.\"}]', 'text', 1, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(755, 150, 207, '5.7 Income Tax Act, 2058 & Tax Deducted at Source (TDS)', '57-income-tax-act-2058-tax-deducted-at-source-tds-207', '<h3>Essential Provisions of Income Tax Act, 2058 (आयकर ऐन)</h3>\n\n<h4>1. Taxation of Remuneration / Employment Income (Section 8)</h4>\n<ul>\n    <li>Includes basic salary, allowances, overtime pay, Dashain bonus, leave encashment, employer provident fund contributions, and perquisites.</li>\n    <li>Progressive slab rates for natural persons (Single vs Married couple slabs: 1% Social Security Tax on initial exemption limit, 10%, 20%, 30%, and 36%/39% super-tax for high brackets).</li>\n</ul>\n\n<h4>2. Tax Deductions at Source - TDS (कर कट्टी सम्बन्धी व्यवस्था)</h4>\n<table border=\"1\" cellpadding=\"8\" style=\"border-collapse: collapse; width: 100%;\">\n    <thead>\n        <tr style=\"background-color: #f1f5f9;\">\n            <th>Transaction Type</th>\n            <th>Applicable TDS Rate</th>\n            <th>Type of Withholding</th>\n        </tr>\n    </thead>\n    <tbody>\n        <tr>\n            <td><strong>House Rent Payment</strong> (Institutional/Office rental)</td>\n            <td>10%</td>\n            <td>Local level / Inland Revenue</td>\n        </tr>\n        <tr>\n            <td><strong>Interest on Bank Deposits</strong> (Institutional)</td>\n            <td>15%</td>\n            <td>Adjustable TDS</td>\n        </tr>\n        <tr>\n            <td><strong>Supply of Goods (Contract > Rs. 50 Lakhs)</strong></td>\n            <td>1.5%</td>\n            <td>Adjustable TDS</td>\n        </tr>\n        <tr>\n            <td><strong>Service Contract / Consultancy Fees</strong></td>\n            <td>15% (VAT bill: 1.5% on contract / 15% without PAN)</td>\n            <td>Adjustable TDS</td>\n        </tr>\n        <tr>\n            <td><strong>Meeting Allowance / Lecture Fees</strong></td>\n            <td>15%</td>\n            <td>Final Withholding Tax (अन्तिम कर)</td>\n        </tr>\n    </tbody>\n</table>\n\n<h4>3. Deposit and Reporting of TDS (Section 90)</h4>\n<p>All withheld tax must be deposited in the Government Treasury within <strong>25 days</strong> of the following Nepali month, accompanied by e-TDS returns filing via the IRD portal.</p>', NULL, NULL, '[{\"question\":\"Under which Act of Parliament is direct income taxation governed in Nepal?\",\"options\":[\"Customs Act 2064\",\"Income Tax Act, 2058 (2002)\",\"VAT Act 2052\",\"Excise Act 2058\"],\"answer\":1,\"explanation\":\"The Income Tax Act 2058 (2002 AD) governs all income and withholding taxes in Nepal.\"},{\"question\":\"What is the applicable TDS rate on House Rent paid to individuals or institutions for office leases?\",\"options\":[\"1.5%\",\"5%\",\"10%\",\"15%\"],\"answer\":2,\"explanation\":\"House rent TDS is 10% (collected by local governments or tax authorities).\"},{\"question\":\"What TDS rate applies on meeting allowances (\\u092c\\u0948\\u0920\\u0915 \\u092d\\u0924\\u094d\\u0924\\u093e) paid to board members or committee participants?\",\"options\":[\"5%\",\"10%\",\"15% (Final Withholding Tax)\",\"25%\"],\"answer\":2,\"explanation\":\"Meeting allowance TDS is 15% and is treated as Final Withholding Tax.\"},{\"question\":\"What is the TDS rate on payments made for supply of goods under contracts exceeding Rs. 50 Lakhs?\",\"options\":[\"1.5%\",\"5%\",\"10%\",\"13%\"],\"answer\":0,\"explanation\":\"TDS on procurement contracts exceeding Rs. 50 Lakhs is 1.5%.\"},{\"question\":\"Within how many days of the end of each Nepali month must withheld tax (TDS) be deposited into the Government Treasury?\",\"options\":[\"7 days\",\"15 days\",\"25 days (Section 90)\",\"30 days\"],\"answer\":2,\"explanation\":\"Under Section 90 of the Income Tax Act, TDS must be deposited within 25 days of the following month.\"},{\"question\":\"What electronic portal maintained by the Inland Revenue Department (IRD) is used to file monthly TDS returns?\",\"options\":[\"e-TDS System \\/ IRD Integrated Tax System\",\"Nagrik App only\",\"NEA internal website\",\"Nepal Post portal\"],\"answer\":0,\"explanation\":\"Withholding agents must submit monthly returns via the IRD e-TDS portal.\"},{\"question\":\"What rate of Social Security Tax (SST) is levied on the initial basic income exemption slab of natural persons?\",\"options\":[\"1%\",\"5%\",\"10%\",\"15%\"],\"answer\":0,\"explanation\":\"1% Social Security Tax is levied on the first income exemption slab of employment income.\"},{\"question\":\"What is the mandatory 9-digit tax identification number required for businesses, employees, and taxpayers in Nepal?\",\"options\":[\"PAN (Permanent Account Number)\",\"VAT number\",\"NIN\",\"Passport ID\"],\"answer\":0,\"explanation\":\"PAN is the unique 9-digit Permanent Account Number issued by IRD.\"},{\"question\":\"Which of the following is considered a Final Withholding Payment where no further income tax filing is needed?\",\"options\":[\"Bank interest on personal savings and meeting allowances\",\"Monthly basic salary\",\"Business profit\",\"Commercial house rent\"],\"answer\":0,\"explanation\":\"Interest on individual bank deposits and meeting allowances are final withholding taxes.\"},{\"question\":\"What is the consequence of failing to deduct and deposit TDS within the statutory 25-day deadline?\",\"options\":[\"Interest surcharge (15% per annum) and statutory late penalty under the Income Tax Act\",\"No consequence\",\"Income tax cancellation\",\"Free bonus\"],\"answer\":0,\"explanation\":\"Delays attract statutory penal interest and fines under Sections 117-119 of the Income Tax Act.\"}]', 'text', 2, 25, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(756, 150, 207, '5.8 Prevention of Corruption Act, 2059 & Public Integrity', '58-prevention-of-corruption-act-2059-public-integrity-207', '<h3>Key Provisions of Prevention of Corruption Act, 2059 (भ्रष्टाचार निवारण ऐन)</h3>\n\n<h4>1. Major Corruption Offenses (Section 3 - 17)</h4>\n<ul>\n    <li>Accepting or giving bribery/grafts (रिसवत/घुस लिने दिने).</li>\n    <li>Embezzlement, misappropriation, or damage of public property (सरकारी/सार्वजनिक सम्पत्तिको हिनामिना).</li>\n    <li>Preparing false official documents, bills, measurement books, or progress reports.</li>\n    <li>Illegal enrichment / Unaccounted wealth: Public servant possessing property disproportionate to lawful income sources.</li>\n    <li>Leaking confidential tenders, revenue leakage, or manipulating procurement bids.</li>\n</ul>\n\n<h4>2. Penal Provisions</h4>\n<ul>\n    <li>Imprisonment ranging from 3 months to 10+ years depending on the misappropriated amount, along with confiscation of property and equivalent fine.</li>\n    <li>Enhanced punishment (additional 3 years) for office chiefs, constitutional post holders, and senior public officials.</li>\n</ul>\n\n<h4>3. Surveillance & Reporting</h4>\n<ul>\n    <li>Mandatory annual submission of Property Declaration (सम्पत्ति विवरण) by every NEA employee within 60 days of fiscal year start (by Bhadra end).</li>\n    <li>Investigative powers vested in CIAA and National Vigilance Centre (NVC).</li>\n</ul>', NULL, NULL, '[{\"question\":\"Under which Act are corruption offenses and anti-graft enforcement governed in Nepal?\",\"options\":[\"Civil Service Act\",\"Prevention of Corruption Act, 2059 (2002)\",\"Police Act\",\"Good Governance Act\"],\"answer\":1,\"explanation\":\"The Prevention of Corruption Act 2059 governs corruption offenses and penalties.\"},{\"question\":\"Within how many days from the start of a fiscal year must every public servant submit their annual Property Declaration (\\u0938\\u092e\\u094d\\u092a\\u0924\\u094d\\u0924\\u093f \\u0935\\u093f\\u0935\\u0930\\u0923)?\",\"options\":[\"30 days\",\"60 days (by end of Bhadra)\",\"90 days\",\"180 days\"],\"answer\":1,\"explanation\":\"Property declarations must be submitted within 60 days of the start of the fiscal year.\"},{\"question\":\"To which specialized court does the CIAA file corruption and bribery cases for trial in Nepal?\",\"options\":[\"District Court\",\"Special Court (\\u0935\\u093f\\u0936\\u0947\\u0937 \\u0905\\u0926\\u093e\\u0932\\u0924)\",\"High Court\",\"Arbitration Tribunal\"],\"answer\":1,\"explanation\":\"Corruption cases are tried at the Special Court under the Special Court Act.\"},{\"question\":\"Which institution under the Office of the Prime Minister conducts administrative surveillance and vigilance to prevent corruption?\",\"options\":[\"National Vigilance Centre (NVC \\/ \\u0930\\u093e\\u0937\\u094d\\u091f\\u094d\\u0930\\u093f\\u092f \\u0938\\u0924\\u0930\\u094d\\u0915\\u0924\\u093e \\u0915\\u0947\\u0928\\u094d\\u0926\\u094d\\u0930)\",\"Election Commission\",\"Auditor General\",\"Supreme Court\"],\"answer\":0,\"explanation\":\"The National Vigilance Centre conducts anti-corruption vigilance in public offices.\"},{\"question\":\"What penalty is prescribed when a public official is convicted of acquiring disproportionate \\/ unaccounted illegal assets?\",\"options\":[\"Confiscation of illegal assets, fine of equivalent amount, and imprisonment\",\"Small oral reprimand\",\"Promotion transfer\",\"Salary bonus\"],\"answer\":0,\"explanation\":\"Illegal assets are confiscated in full, along with imprisonment and fines.\"},{\"question\":\"Under Section 15 of the Act, what penalty applies to public servants who prepare false government bills or fake measurement books?\",\"options\":[\"Imprisonment and fine based on severity of offense\",\"Reward\",\"No punishment\",\"Overtime allowance\"],\"answer\":0,\"explanation\":\"Falsifying official government documents or measurement books is a criminal offense.\"},{\"question\":\"Are both the bribe giver and the bribe taker held criminally liable under the Prevention of Corruption Act?\",\"options\":[\"Yes, both giving and accepting bribes are criminal offenses subject to imprisonment and fine\",\"Only the giver is guilty\",\"Only the taker is guilty\",\"Neither is guilty\"],\"answer\":0,\"explanation\":\"Both demanding\\/accepting and offering bribes are punishable offenses.\"},{\"question\":\"What enhanced punishment applies if corruption is committed by an Office Chief or senior executive?\",\"options\":[\"Additional imprisonment up to 3 years over standard penalty\",\"Penalty is halved\",\"No penalty\",\"Transferred to headquarters\"],\"answer\":0,\"explanation\":\"Office chiefs and senior officials face enhanced imprisonment sentences.\"},{\"question\":\"What happens to a public official against whom the CIAA files a formal corruption case in the Special Court?\",\"options\":[\"Automatically suspended from official position until court verdict\",\"Given a promotion\",\"Sent on foreign tour\",\"Made board director\"],\"answer\":0,\"explanation\":\"The public servant is placed under automatic suspension upon case filing in court.\"},{\"question\":\"What fundamental principle of public administration is promoted by the Good Governance Act 2064?\",\"options\":[\"Transparency, Accountability, Rule of Law, and Quality Public Service Delivery\",\"Bureaucratic secrecy\",\"Delaying customer service\",\"Eliminating records\"],\"answer\":0,\"explanation\":\"The Good Governance Act mandates transparency, accountability, and citizen-friendly service.\"}]', 'text', 3, 20, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(757, 150, 207, '5.9 NEA Legislation & Governance Assessment Quiz', '59-nea-legislation-governance-assessment-quiz-207', '[{\"question\":\"What is the primary statutory responsibility of Nepal Electricity Authority (NEA)?\",\"options\":[\"Generation, Transmission, and Distribution of electricity across Nepal\",\"Road construction\",\"Mining coal\",\"Operating domestic airlines\"],\"answer\":0,\"explanation\":\"NEA manages generation, transmission, and distribution of electricity throughout Nepal.\"},{\"question\":\"When was Nepal Electricity Authority (NEA) established in Bikram Sambat?\",\"options\":[\"2041 Poush 1\",\"2042 Bhadra 1\",\"2046 Baishakh 1\",\"2050 Chaitra 30\"],\"answer\":1,\"explanation\":\"NEA was formally founded on Bhadra 1, 2042 BS under the NEA Act 2041.\"},{\"question\":\"What is the full mark score of Phase 1 Written Examination for NEA Level 4?\",\"options\":[\"100 Marks\",\"200 Marks (Paper I: 100 + Paper II: 100)\",\"300 Marks\",\"50 Marks\"],\"answer\":1,\"explanation\":\"The written exam comprises 200 marks (Paper I 100 marks + Paper II 100 marks).\"},{\"question\":\"What is the pass mark percentage required in each paper of the written exam?\",\"options\":[\"32%\",\"40%\",\"50%\",\"60%\"],\"answer\":1,\"explanation\":\"40 marks out of 100 is the minimum pass mark for each paper.\"},{\"question\":\"Negative marking in Loksewa multiple choice objective questions is deducted at what rate for wrong answers?\",\"options\":[\"10%\",\"20% (0.2 marks per 1 mark question)\",\"33%\",\"50%\"],\"answer\":1,\"explanation\":\"20% marks are deducted for every incorrect MCQ answer.\"},{\"question\":\"What is the theoretical hydropower potential of Nepal?\",\"options\":[\"42,000 MW\",\"83,000 MW\",\"100,000 MW\",\"20,000 MW\"],\"answer\":1,\"explanation\":\"Theoretical hydropower potential is 83,000 MW (economically feasible ~42,000 MW).\"},{\"question\":\"Which constitutional organ conducts the recruitment exams for NEA Level 4 posts?\",\"options\":[\"Public Service Commission (Lok Sewa Aayog)\",\"Ministry of Energy\",\"Tribhuvan University\",\"Private Board\"],\"answer\":0,\"explanation\":\"The Public Service Commission conducts selection examinations for public enterprises.\"},{\"question\":\"What is the fundamental accounting equation?\",\"options\":[\"Assets = Liabilities + Capital\",\"Assets = Liabilities - Capital\",\"Capital = Liabilities + Revenues\",\"Profit = Assets + Cash\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Owner\'s Equity.\"},{\"question\":\"Under the Constitution of Nepal, how many fundamental rights are guaranteed in Part 3?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"31 Fundamental Rights are guaranteed from Article 16 to Article 46.\"},{\"question\":\"What penalty is levied on power theft under Electricity Theft Control Rules 2059?\",\"options\":[\"Assessed loss amount plus 100% fine (शतप्रतिशत जरिवाना)\",\"25% fine\",\"Written warning only\",\"No fine\"],\"answer\":0,\"explanation\":\"Assessed unmetered consumption is recovered along with a 100% fine.\"}]', NULL, NULL, '[{\"question\":\"What is the primary statutory responsibility of Nepal Electricity Authority (NEA)?\",\"options\":[\"Generation, Transmission, and Distribution of electricity across Nepal\",\"Road construction\",\"Mining coal\",\"Operating domestic airlines\"],\"answer\":0,\"explanation\":\"NEA manages generation, transmission, and distribution of electricity throughout Nepal.\"},{\"question\":\"When was Nepal Electricity Authority (NEA) established in Bikram Sambat?\",\"options\":[\"2041 Poush 1\",\"2042 Bhadra 1\",\"2046 Baishakh 1\",\"2050 Chaitra 30\"],\"answer\":1,\"explanation\":\"NEA was formally founded on Bhadra 1, 2042 BS under the NEA Act 2041.\"},{\"question\":\"What is the full mark score of Phase 1 Written Examination for NEA Level 4?\",\"options\":[\"100 Marks\",\"200 Marks (Paper I: 100 + Paper II: 100)\",\"300 Marks\",\"50 Marks\"],\"answer\":1,\"explanation\":\"The written exam comprises 200 marks (Paper I 100 marks + Paper II 100 marks).\"},{\"question\":\"What is the pass mark percentage required in each paper of the written exam?\",\"options\":[\"32%\",\"40%\",\"50%\",\"60%\"],\"answer\":1,\"explanation\":\"40 marks out of 100 is the minimum pass mark for each paper.\"},{\"question\":\"Negative marking in Loksewa multiple choice objective questions is deducted at what rate for wrong answers?\",\"options\":[\"10%\",\"20% (0.2 marks per 1 mark question)\",\"33%\",\"50%\"],\"answer\":1,\"explanation\":\"20% marks are deducted for every incorrect MCQ answer.\"},{\"question\":\"What is the theoretical hydropower potential of Nepal?\",\"options\":[\"42,000 MW\",\"83,000 MW\",\"100,000 MW\",\"20,000 MW\"],\"answer\":1,\"explanation\":\"Theoretical hydropower potential is 83,000 MW (economically feasible ~42,000 MW).\"},{\"question\":\"Which constitutional organ conducts the recruitment exams for NEA Level 4 posts?\",\"options\":[\"Public Service Commission (Lok Sewa Aayog)\",\"Ministry of Energy\",\"Tribhuvan University\",\"Private Board\"],\"answer\":0,\"explanation\":\"The Public Service Commission conducts selection examinations for public enterprises.\"},{\"question\":\"What is the fundamental accounting equation?\",\"options\":[\"Assets = Liabilities + Capital\",\"Assets = Liabilities - Capital\",\"Capital = Liabilities + Revenues\",\"Profit = Assets + Cash\"],\"answer\":0,\"explanation\":\"Assets = Liabilities + Owner\'s Equity.\"},{\"question\":\"Under the Constitution of Nepal, how many fundamental rights are guaranteed in Part 3?\",\"options\":[\"21\",\"25\",\"31\",\"35\"],\"answer\":2,\"explanation\":\"31 Fundamental Rights are guaranteed from Article 16 to Article 46.\"},{\"question\":\"What penalty is levied on power theft under Electricity Theft Control Rules 2059?\",\"options\":[\"Assessed loss amount plus 100% fine (\\u0936\\u0924\\u092a\\u094d\\u0930\\u0924\\u093f\\u0936\\u0924 \\u091c\\u0930\\u093f\\u0935\\u093e\\u0928\\u093e)\",\"25% fine\",\"Written warning only\",\"No fine\"],\"answer\":0,\"explanation\":\"Assessed unmetered consumption is recovered along with a 100% fine.\"}]', 'quiz', 4, 15, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38');

