INSERT INTO `modules` (`id`, `course_id`, `title`, `slug`, `description`, `pdf_file`, `notes`, `key_points`, `quiz_questions`, `order`, `is_published`, `created_at`, `updated_at`) VALUES
(1, 1, 'Samanya Gyan (General Knowledge)', 'samanya-gyan-general-knowledge-1', 'First Paper: Objective GK section covering Nepal geography, history, science, and current affairs.', NULL, 'यस मोड्युलमा लोकसेवा आयोगको पाठ्यक्रममा आधारित विस्तृत सैद्धान्तिक तथा व्यावहारिक ज्ञान समावेश गरिएको छ।\n\n१. विषयवस्तुको परिचय तथा पृष्ठभूमि\n२. मुख्य संवैधानिक तथा नीतिगत व्यवस्थाहरू\n३. परीक्षा तयारीका लागि ध्यान दिनुपर्ने प्रमुख बुँदाहरू\n४. नमूना प्रश्नोत्तर तथा उत्तर लेखन शैली\n\nविद्यार्थीहरूले माथि उपलब्ध अध्ययन सामग्री (PDF) डाउनलोड गरी नियमित अध्ययन र स्व-मूल्याङ्कन अभ्यास गर्न सक्नुहुन्छ।', '• परीक्षा दृष्टिकोणले अति महत्त्वपूर्ण परिभाषाहरू र कानुनी धाराहरू कण्ठ गर्नुहोस्।\n• विगत ५ वर्षका लोकसेवा प्रश्नपत्रहरूको गहन विश्लेषण र पुनरावलोकन गर्नुहोस्।\n• मुख्य तथ्याङ्क, मिति र संशोधनहरूलाई तालिका बनाएर नियमित अभ्यास गर्नुहोस्।\n• वस्तुगत प्रश्नहरूमा समय व्यवस्थापन (प्रति प्रश्न ४५ सेकेन्ड) पालना गर्नुहोस्।', '[]', 1, 1, '2026-08-29 08:42:03', '2026-09-02 12:19:38'),
(2, 1, 'Karyalaya Byawasthapan (Office Management)', 'karyalaya-byawasthapan-office-management-1', 'Second Paper: Office procedures, filing, record management, and correspondence.', NULL, NULL, NULL, '[]', 3, 1, '2026-08-29 08:42:03', '2026-09-02 12:19:38'),
(21, 1, 'IQ', 'iq', 'This module contains the information about the IQ and reasoning.', NULL, NULL, NULL, NULL, 2, 1, '2026-09-01 03:02:37', '2026-09-02 12:19:38'),
(58, 2, 'General Knowledge', 'nasu-general-knowledge', 'Comprehensive General Knowledge syllabus covering Nepal Geography, History, Culture, Universe, Science, and International Organizations.', NULL, 'Detailed syllabus study notes for Nayab Subba GK Paper.', '• Physical & Political Geography of Nepal\n• Historical Eras from Lichhavi to Republic\n• Science, Environment & UN / SAARC', '[]', 1, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(59, 2, 'GMAT(General Mental Ability Test)', 'nasu-gmat', 'Granular lessons for Verbal Analogy, Classification, Number Series, Letter Series, and Coding-Decoding.', NULL, 'Complete techniques, formulas and shortcuts for Nayab Subba IQ.', '• Step-by-Step Logic & Shortcuts\n• Pattern Recognition & Difference Trees\n• Direction Vectors, Alphabet Numbers & Syllogisms', NULL, 2, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(60, 2, 'Contemporary Studies and Public Service Management', 'nasu-cs-psm', 'Contains information about geographical, social, political and economic condition of Nepal', NULL, 'Complete office administration syllabus notes.', '• Office Operations & Record Preservation\n• Civil Service Act & Regulations\n• Citizen Charter, RTI & Accounting', NULL, 3, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(63, 4, 'Economics & Monetary Policy (NRB Module)', 'nrb-officer-economics', 'Demand, supply, price elasticity, market structures, national income accounting, inflation, IS-LM, and monetary economics.', NULL, 'Core macroeconomic theory and practical monetary policy execution by Nepal Rastra Bank.', '• Microeconomics: Consumer behavior, elasticity, production functions, and market pricing\n• Macroeconomics: National accounts, inflation dynamics, IS-LM framework, and BOP\n• Central Banking: Monetary instruments, open market operations, CRR, and SLR', NULL, 1, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(64, 5, 'Banking Laws & Regulations', 'nrb-ad-banking-laws', 'NRB Act 2058, BAFIA 2073, FERA 2019, Unified Directives, AML/CFT Act, and Basel III Standards.', NULL, 'Complete legal & statutory analysis for NRB Assistant Director.', '• NRB Act 2058 Objectives & Autonomy (Section 4)\n• BAFIA 2073 Licensing, Classification & Governance\n• Unified Directives: Capital Adequacy, NPL Classification & Loan Loss Provisioning', NULL, 1, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(65, 7, 'MS Office & Practical IT Applications', 'comp-ms-office-applications', 'Practical & theoretical computer syllabus covering Windows OS, Word, Excel, PowerPoint, Nepali Unicode, and Internet security.', NULL, 'Loksewa practical test patterns, shortcut keys, formulas, formatting rules, and typing speed accuracy guidelines.', '• Word Processing: Mail Merge, Tables, Header/Footer, Track Changes\n• Spreadsheets: VLOOKUP, INDEX-MATCH, PivotTables, Conditional Formatting, Logical Formulas\n• Presentation & DBMS: Slide Masters, Relational Tables, SQL Queries, and Data Security', NULL, 1, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(66, 9, 'Telecommunication Networks', 'ntc-networks-module', 'Telecommunication switching, GSM/LTE/5G mobile architectures, Optical FTTH, IP Routing, and Nepal Telecommunications Act 2053.', NULL, 'Complete technical and regulatory study notes for Nepal Telecom recruitment examinations.', '• Mobile Generations: 2G GSM, 3G UMTS, 4G LTE, 5G NR Architectures\n• Optical Fiber Transmission (WDM, GPON/FTTH)\n• Nepal Telecommunications Act 2053 & NTA Regulation', NULL, 1, 1, '2026-09-01 05:03:46', '2026-09-02 12:19:38'),
(67, 2, 'Service Group–Related', 'service-group-related', NULL, NULL, NULL, NULL, '[]', 4, 1, '2026-09-02 03:34:39', '2026-09-02 12:19:38'),
(70, 9, 'Telecommunication & Wireless Networks (NTC Technical)', 'ntc-telecom-networks', NULL, NULL, 'Core telecommunication network engineering, frequency spectrum allocation by NTA, modulation techniques, and optical transmission.', '• Mobile Cellular Standards: 2G (GSM), 3G (UMTS), 4G (LTE), and 5G NR architecture\n• Optical Fiber Communication, DWDM, and FTTH networks\n• TCP/IP routing, VLANs, MPLS, and packet switching', NULL, 1, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(71, 9, 'Telecom Acts, NTA Regulations & Management (NTC)', 'ntc-acts-management', NULL, NULL, 'Legal framework governing telecom operators in Nepal, spectrum licensing, frequency fees, and telecom consumer rights.', '• Telecommunications Act 2053 and Telecommunications Regulations 2054\n• Nepal Telecommunications Authority (NTA) regulatory mandates\n• Customer Care, Quality of Service (QoS), and Telecommunications Billing', NULL, 2, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(72, 4, 'Banking Laws, Regulations & Governance (NRB Module)', 'nrb-banking-laws', NULL, NULL, 'Statutory banking law, corporate governance, fit-and-proper test for directors, and prudential regulatory norms in Nepal.', '• Nepal Rastra Bank Act 2058 and central bank autonomy\n• Bank and Financial Institutions Act (BAFIA) 2073\n• Anti-Money Laundering (AML/CFT) Act 2064 and KYC compliance\n• NRB Unified Directives, CAMELS rating, and Basel III standards', NULL, 2, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(73, 5, 'Advanced Central Banking & International Finance', 'nrb-ad-central-banking', NULL, NULL, 'Advanced monetary economics, exchange rate regimes, international capital flows, and prudential financial regulation.', '• Balance of Payments (BOP) Accounting: Current Account, Financial Account, and Forex Reserves\n• Foreign Exchange Management: Pegged exchange rate system with INR, REER, and NEER\n• Monetary Transmission Channels and Financial Stability Analysis', NULL, 1, 1, '2026-09-02 04:02:18', '2026-09-02 12:19:38'),
(140, 3, 'Paper I: General Awareness (AAT Part A - 50 Marks)', 'paper-i-general-awareness-aat-part-a-50-marks-3', 'Comprehensive General Awareness covering World and Nepal Geography, World History, Nepalese History & Culture, Polity & Governance, Economic Development, Sustainable Development & Climate Change, Science & Technology, and International Affairs.', NULL, 'Covers all 8 dimensions of the General Awareness syllabus (Units 1.1 to 1.8) for the Administrative Aptitude Test (AAT).', '• Physical, Social & Economic Geography of Nepal and the World\n• Ancient, Medieval & Modern History and Democratic Movements of Nepal\n• Constitution, Governance System & Public Administration Evolution\n• Macroeconomic Planning, Periodic Plans, Sustainable Development & Climate Action\n• Science, Technology, SAARC & Multilateral International Institutions', NULL, 1, 1, '2026-09-02 11:54:52', '2026-09-02 12:19:38'),
(141, 3, 'Paper I: Aptitude Test & Reasoning (AAT Part B - 30 Marks)', 'paper-i-aptitude-test-reasoning-aat-part-b-30-marks-3', 'Comprehensive aptitude testing covering Verbal Reasoning, Analytical & Logical Ability, Non-Verbal/Spatial Reasoning, Quantitative Arithmetic, and Data Interpretation.', NULL, 'Detailed exam notes covering all 5 core sections of Part B for Section Officer.', '• Verbal Series, Analogies, Coding-Decoding & Direction Sense\n• Logical Inference, Statement-Assumption, Cause-Effect & Syllogisms\n• Visual & Spatial Non-Verbal Intelligence, Venn Diagrams & Figure Matrices\n• Quantitative Arithmetic, Averages, Ratios, Profit-Loss & Work-Time\n• Tables, Bar Graphs, Pie Charts & Data Sufficiency Problem Solving', NULL, 2, 1, '2026-09-02 11:54:52', '2026-09-02 12:19:38'),
(143, 3, 'Paper II: Governance Systems (Main Examination - 100 Marks)', 'paper-ii-governance-systems-main-examination-100-marks-3', 'Subjective analytical study of State & Governance, Constitutionalism, Federalism, Public Administration, Ethics, Integrity, E-Governance, and Public Policy.', NULL, 'Detailed study for Stage II Written Examination (10 Questions x 10 Marks = 100 Marks).', '• Constitutional Supremacy, Rule of Law & Separation of Powers\n• Federal Governance & Inter-Governmental Relations (Article 232)\n• Public Administration Principles & New Public Management (NPM)\n• Civil Service Ethics, Public Accountability, RTI & Anti-Corruption\n• E-Governance Infrastructure, Nagarik App & Public Policy Formulation', NULL, 3, 1, '2026-09-02 11:54:52', '2026-09-02 13:32:14'),
(144, 3, 'Paper III: Contemporary Issues (Main Examination - 100 Marks)', 'paper-iii-contemporary-issues-main-examination-100-marks-3', 'Subjective analytical study of Social Inclusion, Macroeconomic Management, Sectoral Growth, Climate & Disaster Resilience, National Security, and Foreign Policy.', NULL, 'Detailed study for Stage II Written Examination (10 Questions x 10 Marks = 100 Marks).', '• Proportional Inclusion, Social Justice & Demographic Dividend\n• Fiscal & Monetary Policy, Public Debt & Medium-Term Expenditure Framework (MTEF)\n• Commercial Agriculture, Tourism Branding & Green Hydropower Export\n• Disaster Risk Reduction (NDRRMA), Climate Adaptation & Build Back Better\n• Non-Aligned Foreign Policy, Panchasheel, Economic Diplomacy & UN Peacekeeping', NULL, 4, 1, '2026-09-02 11:54:52', '2026-09-02 13:32:22'),
(145, 3, 'Paper IV: Service Related Administration, Law & Management (Main Exam - 100 Marks)', 'paper-iv-service-related-administration-law-management-main-exam-100-marks-3', 'Detailed study of Civil Service Legislation, Administrative Law, Public Procurement, Financial Procedures, Fiscal Responsibility, and Official Office Management.', NULL, 'Detailed study for Stage II Written Examination (10 Questions x 10 Marks = 100 Marks).', '• Civil Service Act 2049, Appointments, Leaves, Promotions & Penalties\n• Administrative Law, Principles of Natural Justice & Ultra Vires Doctrine\n• Public Procurement Act 2063, e-GP, Bid Securities & Contract Management\n• Financial Procedures & Fiscal Responsibility Act 2076 and Beruju Settlement\n• Official Note (Tippani) Drafting, Darta/Chalani & Cabinet Proposals', NULL, 5, 1, '2026-09-02 11:54:52', '2026-09-02 13:32:33'),
(146, 13, 'General Knowledge (Paper I - 50 Marks)', 'general-knowledge-paper-i-50-marks-13', 'Comprehensive General Knowledge covering Nepal Geography, Climate, Natural Resources, Socio-Cultural Affairs, Periodic Planning, Economic Pillars, Hydropower & Energy, Environment & Climate Change, Current Affairs, Federalism, and Inclusive Governance.', NULL, NULL, NULL, NULL, 1, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(147, 13, 'Constitution of Nepal (Paper I - 40 Marks)', 'constitution-of-nepal-paper-i-40-marks-13', 'Detailed study of the Constitution of Nepal (2072 BS) covering Salient Features, Preliminary (Part-1), Fundamental Rights & Duties (Part-3), Directive Principles & State Policies (Part-4), Constitutional Organs (Parts 21, 22, 23, 24, 26), and Schedules 1-9.', NULL, NULL, NULL, NULL, 2, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(148, 13, 'General Mathematics & Computer Fundamentals (Paper I - 10 Marks)', 'general-mathematics-computer-fundamentals-paper-i-10-marks-13', 'Elementary mathematics, numerical problem solving (Unitary method, Percentage, Fraction, Average, Profit & Loss, Interest & Discount) and Computer literacy (Word, Excel, PowerPoint, Email & Internet).', NULL, NULL, NULL, NULL, 3, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(149, 13, 'Service Knowledge: Accounting, Reporting & Audit (Paper II - Section A - 50 Marks)', 'service-knowledge-accounting-reporting-audit-paper-ii-section-a-50-marks-13', 'Detailed Accounting Foundations, Double Entry System, Capital & Revenue Expenditure, Books of Accounts, Trial Balance, NEA Financial Reporting, Cost Accounting, Store Management, Internal Control, and Auditing.', NULL, NULL, NULL, NULL, 4, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38'),
(150, 13, 'Service Knowledge: NEA Acts, Bylaws & Legislation (Paper II - Section B - 50 Marks)', 'service-knowledge-nea-acts-bylaws-legislation-paper-ii-section-b-50-marks-13', 'Detailed statutory provisions: Nepal Electricity Authority Act 2041, NEA Employee Service Terms Bylaws, Financial Administration Bylaws, Electricity Theft Control Rules 2059, Retirement Funds (EPF/CIT), Electricity Distribution Bylaws 2078, Income Tax Act 2058 (TDS), and Prevention of Corruption Act 2059.', NULL, NULL, NULL, NULL, 5, 1, '2026-09-02 11:54:53', '2026-09-02 12:19:38');

